ClinicalChunks.register("data/templates-041.js",[{"id":"templates-b8408a9cc054ab325713","key":"v1-c9ccc21dfe2a3058|templates-b8408a9cc054ab325713","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"视神经萎缩","category":"门诊病历模板","raw":{"name":"视神经萎缩","category":"门诊病历模板","case":{"case_name":"门诊病历435","templates":{"主诉":"视力下降伴视野缺损1周","现病史":"患者1周前无明显诱因出现视神经萎缩相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以视力下降伴视野缺损1周为主诉就诊，病程中逐渐加重并伴轻度乏力，首先完善视力、眼压、裂隙灯检查与眼底检查，明确视盘色泽、杯盘比及有无视神经萎缩的形态学依据；完善视野检查了解视野缺损的范围与形态，评估视功能损害程度；查眼底照相记录视盘形态便于随访对比，完善 OCT 检查了解视网膜神经纤维层厚度，客观评估神经纤维层有无变薄；患者既往体健、无明确病因，需完善头颅CT明确颅内有无占位、出血等病变，必要时完善头颅MRI以明确视神经及颅内段有无脱髓鞘、肿瘤等病变，鉴别压迫性与炎性视神经病变；查颈动脉超声了解颈动脉有无斑块及狭窄，评估眼动脉供血情况，完善经颅多普勒了解颅内血流动力学改变；完善血常规排除感染、贫血所致视神经损害，完善生化全项与肝肾功能评估全身代谢状态及用药前基础情况，完善凝血功能排除高凝状态所致血管性病变，查血糖、血脂了解有无糖尿病及高脂血症等血管危险因素，查同型半胱氨酸排除高同型半胱氨酸血症所致血管内皮损伤；完善心电图排除心律失常及心肌缺血等心源性栓子来源，完善心脏超声（排查栓子来源）明确心内有无附壁血栓及瓣膜病变，鉴别心源性栓塞所致视神经供血障碍；如上述检查仍不能明确病因，必要时完善腰椎穿刺（必要时）检查脑脊液，明确有无颅内感染或脱髓鞘疾病，必要时请相关科室会诊协助诊治。\n\n（检查清单）\n【必做检查】\n血常规、生化全项、凝血功能、血糖、血脂、同型半胱氨酸\n\n【影像学检查】\n头颅CT/MRI、颈动脉超声、经颅多普勒\n\n【其他检查】\n心电图、心脏超声（排查栓子来源）、腰椎穿刺（必要时）","初步诊断":"1. 视神经萎缩\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 神经营养修复：甲钴胺片 0.5mg 每日3次口服，连用2～3个月；\n2. 改善视神经微循环：银杏叶提取物片（金纳多）40mg 每日3次口服，连用3个月；或羟苯磺酸钙胶囊 0.5g 每日3次口服；\n3. 补充维生素：维生素B1片 10mg 每日3次口服，复合维生素B片 2片 每日3次口服；\n4. 针对病因治疗：青光眼性视神经萎缩者联用降眼压药物（如拉坦前列素滴眼液 1滴 每晚1次）；炎症或缺血性病因明确者，在专科指导下短期规范使用糖皮质激素，并停用可疑致病药物（如乙胺丁醇、异烟肼等）。\n\n【一般治疗及生活指导】\n1. 戒烟限酒，避免熬夜，保证规律作息与充足睡眠，避免精神紧张及情绪激动；\n2. 避免长时间近距离用眼，每用眼30～40分钟远眺休息5～10分钟，避免强光刺激，强光下外出可佩戴太阳镜；\n3. 均衡饮食，多摄入富含B族维生素、维生素A及花青素的食物（如动物肝脏、胡萝卜、蓝莓、深绿色蔬菜），忌辛辣刺激及过度油腻饮食；\n4. 避免剧烈运动、头部外伤及用力屏气等动作，防跌倒碰撞，出现视力骤降或眼痛时立即就医。\n\n【随诊要求】\n1. 每1～3个月门诊复查视力、视野、眼底及OCT（视盘RNFL厚度），评估病情进展；\n2. 若出现视力进行性下降、视野缺损扩大或眼痛等症状，随时复诊；\n3. 病因未明者建议完善头颅及眶部MRI，必要时请神经内科、神经外科会诊，排除颅内占位性病变及脱髓鞘疾病等；\n4. 长期规律随访，坚持规范用药，不可自行停药或减量，注意监测血压、血糖及眼底情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":570,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c540f6da9b0e2452da0d67303ccf957e6ade3c050aa48ad1dbf47899d8cac094","pinyin":"shishenjingweisuo","initials":"ssjws","setting":"out","caseName":"门诊病历435","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历435",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-29e73a63c27af614c61e","key":"v1-c9ccc21dfe2a3058|templates-29e73a63c27af614c61e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"视盘水肿","category":"门诊病历模板","raw":{"name":"视盘水肿","category":"门诊病历模板","case":{"case_name":"门诊病历436","templates":{"主诉":"视力模糊伴头痛1周","现病史":"患者1周前无明显诱因出现视盘水肿相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以视力模糊伴头痛1周为主诉就诊，症状逐渐加重并伴轻度乏力，首先完善视力、眼压、裂隙灯检查及眼底检查，明确视盘水肿的程度、有无出血渗出及有无合并视神经萎缩；查眼底照相记录视盘形态便于动态随访，完善视野检查了解有无生理盲点扩大及视野缺损，评估视功能受损情况；患者头痛伴视盘水肿，需完善头颅CT明确颅内有无占位性病变、出血及脑室系统情况，必要时完善头颅MRI以明确颅内有无肿瘤、炎症及脱髓鞘病变，必要时加做头颅MRV排除颅内静脉窦血栓所致颅内压增高；完善腰椎穿刺并测定脑脊液压力，明确有无颅内压升高及其程度，同时完善脑脊液常规、生化及细胞学检查，鉴别颅内感染与占位性病变；完善血常规排除感染、贫血所致视盘水肿，完善尿常规与便常规排除泌尿系统及消化道慢性失血，完善肝肾功能评估肝肾代谢功能及用药前基础状态，查血糖、血脂了解有无糖尿病及高脂血症等血管性危险因素，完善电解质检查排除电解质紊乱；完善心电图排除心律失常及心肌缺血，完善胸部X线片排除肺部感染、结核及占位性病变，完善腹部超声排除腹部占位及肝肾疾病所致继发性改变；根据病情需要选择相应检查，必要时请相关科室会诊协助明确病因。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 视盘水肿\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 降颅压治疗（特发性颅内高压所致视盘水肿首选）：乙酰唑胺片0.25g，口服，每日2次，晨起及午后各1次，疗程4~8周，根据眼底水肿消退程度及耐受性调整剂量，定期复查电解质、肾功能。\n2. 辅助利尿脱水：呋塞米片20mg，口服，每日1次，晨服，连用3~5日，注意监测血钾，避免长期联用致低钾血症。\n3. 神经营养支持：甲钴胺片0.5mg，口服，每日3次，疗程1~3个月，减轻视神经轴索损伤。\n【一般治疗及生活指导】\n1. 视盘水肿多为颅内压增高所致（颅内占位、静脉窦血栓、特发性颅内高压等），病因治疗为根本：尽快完善头颅MRI+MRV、腰椎穿刺测压等检查，确诊后转神经内科/神经外科专科处理。\n2. 低盐低脂饮食，限制每日液体入量，避免一次性大量饮水或过快输液。\n3. 避免一切增高颅内压的行为：用力排便、剧烈咳嗽、打喷嚏、屏气、提重物、长时间低头弯腰均应避免，保持大便通畅，必要时辅助通便。\n4. 每日自测双眼视力，如出现视力明显下降、视野缺损或头痛加重，立即就医。\n【随诊要求】\n1. 每2~4周复诊1次，复查双眼视力、视野及眼底（视盘水肿程度、有无出血及渗出）。\n2. 每4~8周复查OCT视盘RNFL厚度及视觉诱发电位（VEP），动态评估视神经损伤程度。\n3. 病因治疗后继续随访至少3~6个月，监测有无继发性视神经萎缩；若出现视力急剧下降、视野缺损扩大或剧烈头痛伴恶心呕吐，需立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":571,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cb5453b0d4ba1b46e0474a5868379c0270ecf5db7b4b2a7f6d5de6c73bfd5ab0","pinyin":"shipanshuizhong","initials":"spsz","setting":"out","caseName":"门诊病历436","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历436",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-075cc71e01f5a714a8f5","key":"v1-c9ccc21dfe2a3058|templates-075cc71e01f5a714a8f5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"缺血性视神经病变","category":"门诊病历模板","raw":{"name":"缺血性视神经病变","category":"门诊病历模板","case":{"case_name":"门诊病历437","templates":{"主诉":"单眼突发视力下降伴视野缺损3天","现病史":"患者（前部缺血性视神经病变（AION），为视神经前段缺血所致，临床分型如下：①非动脉炎性（NAION，最常见，占90%以上，多见于中老年，常伴高血压、糖尿病、高脂血症、动脉硬化、睡眠呼吸暂停（夜间低血压致灌注下降）及小视盘拥挤（视盘小、杯盘比小，易发生缺血，为解剖易感因素））；②动脉炎性（巨细胞动脉炎、颞动脉炎，多见于50岁以上，为全身性血管炎，累及眼动脉及睫状后动脉，病情严重（有双侧失明风险，并可伴全身主动脉并发症，属急症，需全身激素急诊处理，重要，详见巨细胞动脉炎一节））。患者于1天前晨起睡醒时发现：视力下降（无痛性、突发、单眼（非动脉炎性者常于晨起睡醒时发现，为睡眠中发生；动脉炎性者可先出现一过性黑矇（眼型TIA，为警示症状），之后出现持久性下降））、视野缺损（下方弓形视野缺损常见，非动脉炎性者因视盘上方缺血所致）、视盘水肿（呈节段性或弥漫性，为眼底表现）。全身症状（动脉炎性者需重点询问：颞部头痛（新发头痛，重要）、颞动脉压痛或条索状改变、下颌间歇性跛行（咀嚼痛，重要）、发热、盗汗、体重下降、多肌痛（肩、髋近端肌痛、僵硬，可与风湿性多肌痛并存）、血沉显著升高）。动脉炎性者若未治疗，对侧眼可受累（数天至数周内可致双侧失明，属急症，重要）；非动脉炎性者对侧眼可在数年内受累（约10~15%）。另需询问睡眠呼吸暂停（打鼾、呼吸暂停、缺氧，需评估）、既往眼病史（前部缺血性视神经病变史）、血管病危险因素（高血压、糖尿病、血脂异常）。今日来我院眼科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP130/80mmHg。视力：患眼下降。眼底：视盘水肿（节段性，早期可见视盘周围苍白、出血），晚期（数周后）视神经萎缩、苍白。相对性传入性瞳孔障碍（RAPD）：患眼阳性，为单眼视神经病变的重要体征。视野：下方弓形缺损。眼压：正常，可排除青光眼。颞动脉：触诊无压痛及条索，搏动正常。全身：无发热，血沉待评估。对侧眼：视盘杯盘比小、拥挤，为非动脉炎性的解剖易感因素。","辅助检查":"【必做】视野检查（明确缺损类型并随访）、眼底检查（观察视盘水肿及苍白）；【关键鉴别】血沉/CRP（动脉炎性者显著升高（>50mm/h；但正常不能排除），用于筛查巨细胞动脉炎，重要）、血小板、颞动脉活检（动脉炎性确诊依据，血管壁巨细胞肉芽肿性炎为金标准；临床高度怀疑者应先予激素治疗再行活检，不等活检结果再治疗，属急症，重要）、彩色多普勒超声（颞动脉狭窄征象，辅助检查）；【影像】头颅MRI（排除颅内占位压迫视神经、脱髓鞘性视神经炎（年轻者可行MRI视神经增强扫描））、视神经OCT（观察视盘水肿及视网膜神经纤维层厚度，用于随访）、眼压、血糖血压血脂（血管危险因素评估）、睡眠呼吸暂停（疑诊者行多导睡眠图，见于非动脉炎性）。","初步诊断":"1. 缺血性视神经病变（非动脉炎性（NAION），单眼：视力下降、视野缺损、视盘水肿，需行血沉/CRP及颞动脉活检评估以排除动脉炎性，注意对侧眼受累风险）\n（注：治疗依分型而定，关键在动脉炎性属急症需激素治疗。①非动脉炎性：无特效治疗（视神经缺血不可逆，视力恢复有限，部分可自发改善）；控制血管危险因素（血压（注意夜间低血压，睡眠呼吸暂停者慎过度降压、夜间监测）、血糖、血脂，戒烟，重要，以防对侧眼受累）；睡眠呼吸暂停（疑诊者行多导睡眠图评估，治疗用CPAP，可降低对侧眼风险）；阿司匹林（抗血小板二级预防，证据有限，但多因心血管获益而使用）；随访（对侧眼视力变化需及时就医，OCT随访）。②动脉炎性/巨细胞动脉炎：属急症，立即予大剂量糖皮质激素（甲泼尼龙冲击或泼尼松60~80mg/d，立即开始，不等活检结果，重要，以防对侧眼失明及全身血管并发症（主动脉动脉瘤、夹层、卒中））；颞动脉活检（激素开始后1周内进行，组织学仍可阳性）；激素维持（6~12个月以上并逐渐减量，监测血沉以防复发）；激素副作用（监测骨质疏松、血糖、感染）；全身（风湿性多肌痛症状需一并治疗）。③视力康复（视力不可逆损失者予低视力辅助，并教育保护对侧眼）。④随访（视力/视野（恢复有限，记录基线并随访）、血沉（动脉炎性者治疗监测）、对侧眼（动脉炎性者用激素以防双侧失明，为关键）、危险因素（全身血管病随访））。眼科与风湿科协作：非动脉炎性者控制危险因素以防对侧眼受累；动脉炎性者急诊激素以防双侧失明，重要。）","处理方案":"【药物治疗】\n1. 糖皮质激素（首选，疑动脉炎性AION者必须尽早足量）：甲泼尼龙片40mg qd晨起顿服，视力改善或视盘水肿减轻后每5~7日减量（每次减5mg），总疗程4~6周；用药期间监测血压、血糖、血钾。\n2. 改善视神经微循环：复方樟柳碱注射液2ml，患侧颞浅动脉旁皮下注射，1次/日，连用14日为一疗程。\n3. 神经营养支持：甲钴胺片0.5mg tid口服，连用4~6周。\n4. 抗血小板（合并高血压、糖尿病、高脂血症等血管危险因素者）：阿司匹林肠溶片100mg qd口服长期服用；消化性溃疡活动期或出血倾向者禁用，可换用氯吡格雷75mg qd。\n\n【一般治疗及生活指导】\n1. 急性期减少眼球转动，避免剧烈运动、低头、屏气、用力排便等升高眶内压/颅内压的动作，保证充足睡眠，保持情绪平稳。\n2. 戒烟、限酒，低盐低脂饮食；严格控制血压、血糖、血脂达标，避免血压过低或波动过大（慎用硝酸酯类等扩血管药物），改变体位时动作宜缓慢。\n3. 避免一次性大量饮水及长时间热水浴，防止眼压波动；外出可佩戴太阳镜减轻畏光不适。\n4. 患眼避免揉搓及碰撞，眼部热敷、理疗等医师指导下进行。\n\n【随诊要求】\n1. 急性期每1~2周复诊1次，复查视力、视野、眼底（观察视盘水肿消退及视神经萎缩进展），视盘水肿消退后可改为每月1次，病情稳定后每3~6个月复查视力、视野及眼底OCT。\n2. 疑动脉炎性AION者应监测血沉、CRP；若出现颞侧头痛、咀嚼肌疼痛、头皮触痛或对侧眼一过性视力下降，立即急诊就诊，必要时行颞动脉活检。\n3. 出现视力进行性下降、视野缺损扩大或眼胀痛伴恶心呕吐者随时复诊；长期随访期间继续控制血压、血糖、血脂，预防对侧眼受累。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":572,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a207254f13f5087602f6d4ec1079a4658183494fbc09eb59dbab018b2520793d","pinyin":"quexuexingshishenjingbingbian","initials":"qxxssjbb","setting":"out","caseName":"门诊病历437","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历437",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e8aeed3a7e45ca35b19e","key":"v1-c9ccc21dfe2a3058|templates-e8aeed3a7e45ca35b19e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"屈光不正","category":"门诊病历模板","raw":{"name":"屈光不正","category":"门诊病历模板","case":{"case_name":"门诊病历438","templates":{"主诉":"视远模糊伴眼疲劳1年","现病史":"患者为近视（物像聚焦于视网膜前，看远模糊、看近清楚；因眼球轴长过长或角膜曲率过大所致）。各型屈光不正特点：远视（物像聚焦于视网膜后，看近模糊；年轻人可通过调节代偿而看清，但易疲劳）、散光（角膜或晶状体不规则，物像模糊、变形，各方向不同）。相关因素：年龄（儿童（近视发生发展，近视防控重要，增加户外活动可减少近视进展）、青少年（近视进展期）、成人（屈光稳定）、老视（40岁以上调节力下降，看近模糊，见老视一节））、遗传（父母近视者子女风险升高）、用眼（长时间近距离工作、看手机电脑为近视危险因素）、环境（户外活动少者近视风险升高）。患者于1年余前出现视力下降（以看远模糊为主，看近清楚）。症状表现为：远视力模糊（近视者看黑板、电视及远处时眯眼、眼疲劳）、近视力模糊（远视或老视者看书、看手机时需拿远）、视物变形或重影（散光）、眯眼或歪头（儿童借以改善视力的行为提示）、眼疲劳（调节性疲劳，可伴头痛，多见于远视、散光）、儿童表现（学习成绩下降、注意力不集中、揉眼、歪头，多由学校视力筛查发现）、复视（罕见）。另需询问：既往视力（良好或已戴镜）、戴镜史（旧镜需验光调整）、视力筛查史（儿童学校或幼儿园常规筛查）、外伤或手术史（可影响视力）、全身情况（糖尿病（血糖波动可致屈光变化）、药物（抗胆碱药可致调节麻痹）、白内障（老年视力模糊，不属单纯屈光问题，需检查鉴别））。今日来我院眼科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP120/80mmHg。视力：裸眼远、近视力（视力表检查，为核心项目）。矫正视力：验光后右眼1.0、左眼1.0（矫正视力达1.0为正常，提示屈光不正可矫正，重要；矫正不良需考虑其他眼病，如白内障、眼底病变）。验光：自动电脑验光加显然验光（主觉验光插片，确定度数，为核心配镜依据）；睫状肌麻痹验光（用于儿童及青少年（阿托品或环戊通散瞳麻痹睫状肌，可获准确屈光状态；儿童调节力强，不麻痹验光度数不准，重要））。裂隙灯：检查前节、角膜及晶状体（排除白内障）。眼底：检查视网膜、黄斑及视神经，排除眼底病变所致视力下降。眼位及眼球运动：检查有无斜视。角膜曲率及眼轴：用于近视评估及近视防控随访。","辅助检查":"【必做】视力检查（远、近视力）、验光（显然验光确定屈光度数，为核心）、睫状肌麻痹验光（儿童及青少年首次验光，可准确评估屈光状态，重要）；【其他】裂隙灯及眼底检查（排除器质性眼病（白内障、眼底病），矫正视力不佳时需进一步检查）、角膜地形图（评估散光及圆锥角膜）、眼轴测量（近视随访、评估进展）、双眼视功能（儿童斜视、弱视）、儿童视力筛查（早期发现弱视，治疗关键期，重要）。","初步诊断":"1. 屈光不正（近视（右-3.00D，左-3.50D），双眼；裸眼视力右0.2、左0.1，矫正视力1.0；需结合年龄及调节状态评估（儿童需睫状肌麻痹验光，老视另行评估））\n（注：治疗以矫正为主，包括配镜、隐形眼镜或手术，并重视近视防控。①框架眼镜：为矫正视力的核心手段（近视用凹透镜、远视用凸透镜、散光用柱镜；配镜应足度矫正（儿童需准确全矫以防弱视，重要）；远视儿童（视疲劳、斜视、内斜者需配镜）；定期复查（儿童每6~12个月验光，度数变化需调整，重要）。②隐形眼镜（角膜接触镜）：适用于美容、运动、屈光参差者，需注意护理与卫生，防角膜炎，重要；RGP（硬性透氧镜）适用于散光、高度近视；角膜塑形镜（OK镜，夜间佩戴，用于儿童近视防控，短期控制近视进展有效，需规范验配、护理及随访，防角膜感染，重要）。③近视防控（以儿童青少年为核心）：户外活动（每天≥2小时户外光照，可减少近视发生与进展，重要，证据充分）；减少近距离用眼（20-20-20法则：每20分钟看远20秒）；低浓度阿托品（0.01%滴眼液控制近视进展，临床常用，需监测眼压及调节）；角膜塑形镜、多焦软镜或离焦框架镜（均为近视防控选择）；定期随访（监测眼轴，评估近视进展，重要）。④手术：屈光手术包括激光角膜屈光手术（LASIK、SMILE全飞秒）、表层手术（PRK、LASEK）、眼内晶体植入（ICL，适用于高度近视（近视超过800度、角膜薄者选择））；适应证（成人18岁以上、屈光稳定（1~2年以上）、角膜厚度足够、无禁忌（圆锥角膜、活动性眼病、自身免疫病））；矫正目标（脱镜；但老视者（40岁以上）术后看近仍需老花镜，需告知）；手术风险（干眼、夜间眩光、感染、罕见角膜并发症）。⑤全身及其他：糖尿病（控制血糖，血糖波动可致屈光变化）、老视（40岁以上看近需加正镜，见老视一节）、白内障（老年视力模糊、晶状体浑浊，需手术评估，不属单纯屈光问题）。眼科处理要点：验光配镜，儿童需睫状肌麻痹验光以防弱视；近视防控强调户外活动；屈光手术需严格评估，重要。）","处理方案":"【药物治疗】\n1. 缓解视疲劳用药（营养角膜、改善调节）：七叶洋地黄双苷滴眼液，每日3次，每次1滴，双眼滴用，连用2周为一疗程，症状缓解后停药。\n2. 人工泪液（润滑眼表、缓解干涩）：0.1%玻璃酸钠滴眼液，每日3~4次，每次1滴，双眼滴用，症状明显者可增至每日6次，用至症状缓解；戴角膜接触镜者于摘镜后使用。\n3. 延缓近视进展（抗胆碱能药，适用于青少年近视）：0.01%硫酸阿托品滴眼液，每晚睡前1次，每次1滴，双眼滴用，滴后按压内眦泪囊区1~2分钟以减少全身吸收；每3~6个月复诊评估，遵医嘱长期用药，停药时逐渐减量。\n【一般治疗及生活指导】\n1. 光学矫正：屈光不正首选医学矫正，经规范验光（首次配镜及青少年行散瞳验光）后佩戴合适度数框架眼镜或角膜接触镜；屈光度稳定2年以上、符合适应证者可行角膜屈光手术。\n2. 用眼卫生：遵循\"20-20-20\"法则，近距离用眼每20分钟远眺6米以外至少20秒；读写保持一尺（约33cm）距离，光线充足，避免暗光、躺卧及晃动车厢内用眼。\n3. 户外活动：每日累计户外活动2小时以上，多看远处、多参加球类运动，有助于缓解调节疲劳、延缓近视进展。\n4. 禁忌：避免长时间连续使用电子屏幕及熬夜；不揉眼；佩戴角膜接触镜者须规范清洁护理，禁戴过夜（非日戴型）、禁使用过期镜片；高度近视者避免剧烈对抗性运动及头部撞击，警惕视网膜脱离。\n【随诊要求】\n成人一般每1~2年复查医学验光1次；出现视物模糊、视疲劳加重、眼胀痛、复视或眼前黑影飘动、闪光感等异常时及时复诊。青少年每3~6个月复查验光及眼轴长度，动态评估近视进展。佩戴角膜接触镜者每6~12个月行眼部健康检查（含角膜及眼表情况）；行屈光手术者按医嘱于术后1天、1周、1个月、3个月、6个月、1年定期复查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":573,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2656c64e3398e2fae56820270b32535977ec995d57a53692057fe3a03c986a3d","pinyin":"quguangbuzheng","initials":"qgbz","setting":"out","caseName":"门诊病历438","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历438",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-abecbc4d1f2995efc0d8","key":"v1-c9ccc21dfe2a3058|templates-abecbc4d1f2995efc0d8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"老视","category":"门诊病历模板","raw":{"name":"老视","category":"门诊病历模板","case":{"case_name":"门诊病历439","templates":{"主诉":"视近模糊伴眼疲劳1年","现病史":"患者（>40岁，老视为晶状体硬化、睫状肌调节力下降所致，40岁后调节幅度↓，看近困难，属生理性过程，人人都会发生）于2年前渐出现：看近模糊（看书/看手机报纸时字体小、需将物拿远才清楚）、阅读需更亮灯光（照明需求↑，为早期表现）、眼疲劳（调节不足致眼酸胀、疲劳、头痛）、视物模糊（由近看远调节转换迟缓，即近远调节变慢）。患者原有屈光状态（远视者看远也需调节，故40岁前即可出现老花；近视者老视后看近摘镜即可，即近视抵消老花）、职业用眼情况（是否从事精细近工作）已详细询问；需与远视（看近模糊但年轻时即有，一直看近疲劳）、近视未矫正、白内障（老年视力模糊、远近均下降、晶状体浑浊）、眼底病/糖尿病所致屈光变化相鉴别，症状与用眼距离相关；原有屈光（远视/近视/散光）、阅读习惯、年龄均已了解。老视为生理性、渐进性过程，40岁后逐渐出现并随年龄加重，至55岁左右趋于稳定，非疾病状态。今日来我院眼科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP120/80mmHg。视力：远视力（多正常或为原有屈光状态所致）、近视力下降（用标准近视力表于40cm阅读距离检查）；验光：远屈光加近附加（ADD，即老视度数，一般+0.75D（40~44岁）、+1.5D（45~49岁）、+2.0D（50~54岁）、+2.5D（55岁以上），可粗估，精确验光需插片试戴）；裂隙灯：检查晶状体（排除白内障早期）；眼底检查（排除眼底病）。","辅助检查":"【必做】视力/验光（远/近屈光加ADD，确定老视度数）、近视力表检查；【其他】裂隙灯（检查晶状体，与白内障鉴别）、眼底（排除眼底病）、睫状肌麻痹验光（老视不需要，成人显然验光即可）、角膜检查（手术评估、多焦晶体）。","初步诊断":"1. 老视（老花，调节力下降所致：双眼ADD+2.0D，年龄相关，原有屈光状态为远视或近视，已排除白内障及眼底病）\n（注：治疗以矫正为主，看近加正镜，需向患者说明老视为生理过程、无法治愈，仅能矫正：①框架眼镜：老花镜（单光看近专用；原有屈光不正者选双光/渐进多焦镜，即看远看近一副，上看远、下看近，渐进通道有适应期，周边变形、行走下楼需注意，适应期1~2周）、定制镜片（依阅读距离、职业习惯调整ADD）；②隐形眼镜：多焦隐形眼镜（可选）、单眼视（一眼看远、一眼看近，即monovision，酌情选择）；③手术：老视手术（激光（单眼视激光）、角膜植入物（Kamra角膜嵌环）、晶状体置换（屈光性晶状体置换、多焦/三焦人工晶状体，可摘白内障同时解决远中近视力；多焦晶体存在对比度下降、眩光，选择与评估重要）），手术矫正老视属新兴技术，需评估适合者；④其他：改善照明（阅读灯宜亮）、阅读材料字号加大（手机字号调大）、原有屈光（近视者看近摘镜，需告知；远视者老视出现早，配镜宜早）、白内障（发展至晶状体浑浊、视力进一步下降时评估手术）、定期复查（度数每1~2年复查，老视渐进展至55岁左右趋于稳定）；眼科验光配老花/渐进镜、多焦晶体手术评估、白内障鉴别均重要。","处理方案":"【药物治疗】\n1. 盐酸毛果芸香碱滴眼液（1%）1滴，双眼，每日1次，于近距离用眼前约30分钟滴入，通过缩瞳产生\"针孔效应\"提高景深、改善中近视力；按需长期使用，用药期间每3～6个月复查眼压及前房深度，浅前房、闭角型青光眼或有急性闭角发作史者禁用。\n2. 玻璃酸钠滴眼液（0.1%）1滴，双眼，每日3～4次，缓解老视患者常合并的干眼症状、改善视觉舒适度；疗程2～4周，症状反复时可按需重复使用，佩戴角膜接触镜者需在摘镜后滴用。\n\n【一般治疗及生活指导】\n1. 光学矫正为首选方案：视近困难者验配单光近用老花镜，需兼顾远、中、近视力者选用渐进多焦点眼镜，每1～2年或自觉视近模糊加重时重新验光调整度数。\n2. 改善照明与阅读条件：近距离用眼时保证充足、均匀的光线（建议台灯照度400 lux以上），避免在暗光或强眩光下阅读，可将字号适当放大。\n3. 注意用眼卫生：保持阅读距离33～40cm，连续近距离用眼每45分钟休息5～10分钟，眺望远处放松睫状肌；避免长时间低头用眼及揉搓双眼。\n4. 饮食与生活方式：均衡饮食，适当多食富含叶黄素、维生素C/E及β-胡萝卜素的深色蔬菜、水果和坚果，戒烟限酒；户外活动时佩戴防紫外线太阳镜，延缓晶状体及黄斑老化。\n\n【随诊要求】\n每6～12个月门诊复查裸眼及矫正视力、屈光状态，重新验光并调整近用眼镜处方；若出现视力突然下降、视物变形、眼前固定黑影增多、眼胀痛伴虹视或视野缺损等，应随时就诊，排查白内障、青光眼及年龄相关性黄斑变性等合并疾病；使用缩瞳剂者每3～6个月监测眼压、前房深度及眼底情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":574,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"47971f4f51a80215b802a3987c745049d1ffa547106752bcedcb7986b32c76c2","pinyin":"laoshi","initials":"ls","setting":"out","caseName":"门诊病历439","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历439",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4cdb25479035c6a75ef8","key":"v1-c9ccc21dfe2a3058|templates-4cdb25479035c6a75ef8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"弱视","category":"门诊病历模板","raw":{"name":"弱视","category":"门诊病历模板","case":{"case_name":"门诊病历440","templates":{"主诉":"发现视力不良3年","现病史":"患儿（6岁，处于弱视治疗敏感期0~12岁，关键期<7~8岁，越早治疗越好，成人基本不可逆）于1年前视力筛查发现视力不良（单眼，属屈光参差性（两眼屈光度差大，好眼清晰、患眼模糊，产生抑制）），伴眯眼、阅读凑近，遮盖患眼无反应、遮盖好眼哭闹（单眼弱视快速筛查法：捂患眼不哭、捂好眼哭），无明显斜视外观及歪头；家族中无弱视/斜视/屈光不正史；外院验光情况：外院散瞳验光示右眼+4.50D、左眼+1.00D。今日来我院眼科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视力（裸眼及矫正；弱视定义为最佳矫正视力低于同龄正常且无器质性病变，或器质病变不能解释）、屈光检查（散瞳验光、睫状肌麻痹（阿托品/环戊通），为准确屈光核心）、眼底（排除器质性病变，如先天性白内障/视网膜病/视神经病等形觉剥夺病因）、眼位（斜视检查，遮盖-去遮盖/三棱镜）、双眼视功能（立体视，弱视者受损）。","辅助检查":"【必做】散瞳验光（睫状肌麻痹验光，准确屈光度，为弱视诊断及治疗基础，关键）、眼底检查、眼位检查；【影像】形觉剥夺病因疑及白内障时行眼底/超声（必要时）；【其他】视觉诱发电位（不配合婴幼儿，客观视力评估，必要时）。","初步诊断":"1. 弱视（屈光参差性：右眼，中度）\n（注：治疗核心为年龄越小效果越好（<7~8岁敏感期，成人弱视基本不可逆，早筛早治）：①矫正屈光不正（基础，配镜足度矫正，弱视治疗第一步）；②遮盖疗法（治疗弱视核心，遮盖好眼，强制弱视眼使用，遮盖时间依年龄及弱视程度（2~6小时/日，年龄越小时间越短以防好眼弱视），定期复查双眼视力以防遮盖性弱视）；③压抑疗法（阿托品滴好眼，睫状肌麻痹，替代遮盖，儿童依从性好，适于年龄较大儿童）；④治疗病因（斜视矫正：屈光矫正后残留斜视可手术，时机为先治弱视后矫正斜视或同时；形觉剥夺：先天性白内障早期手术，术后配镜+遮盖，最紧急）；⑤视觉训练（双眼视功能/立体视训练，弱视眼恢复后行精细目力训练，如穿珠描画，辅助）；⑥定期随访（视力每1~3个月复查至稳定（12岁），防复发（弱视治疗后随访））；儿童眼科专科，家长教育（依从性决定疗效，重要）；筛查（学龄前视力筛查，幼儿园/社区早期发现，关键）。）","处理方案":"【药物治疗】\n1. 阿托品压抑疗法（首选）：1%硫酸阿托品眼用凝胶，每晚睡前滴健眼1滴，qd，用药后压迫泪囊区1~2分钟以减少全身吸收，疗程3~6个月，根据弱视眼视力恢复情况调整；青光眼、前房浅、对阿托品过敏者禁用。\n2. 左旋多巴/卡比多巴辅助治疗（遮盖压抑疗效欠佳时选用）：左旋多巴卡比多巴片（250mg/25mg）1片 po tid，4~8周为一疗程，可辅助提高弱视眼视力及对比敏感度，餐后服用减轻胃肠道反应。\n3. 神经营养辅助：甲钴胺片0.5mg po tid，连用4~8周，辅助视神经功能恢复，服药期间禁饮酒。\n\n【一般治疗及生活指导】\n1. 严格遮盖疗法：按医嘱每日遮盖健眼4~6小时，遮盖期间督促用弱视眼进行精细目力训练（串珠、穿针、描红、拼图、插板等），每日1~2小时，切忌遮盖不足或随意间断。\n2. 饮食与休息：均衡饮食，多食富含维生素A、叶黄素及花青素的食物（胡萝卜、南瓜、菠菜、蛋黄、蓝莓等）；保证充足睡眠，避免长时间近距离用眼及视疲劳，避免强光直射。\n3. 禁忌及注意事项：滴阿托品后如出现面部潮红、口干、发热、烦躁等全身反应，立即停药并就诊；保持眼部清洁，勿揉眼；弱视训练时坐姿端正、光线充足。\n\n【随诊要求】\n1. 遮盖及药物压抑治疗期间：6岁以下每1~2周复诊1次，6岁以上每月复诊1次，复查双眼视力、注视性质及眼压，防止遮盖性弱视及高眼压。\n2. 每3~6个月重新散瞳验光，复查屈光状态并及时调整眼镜度数。\n3. 视力恢复正常后继续巩固治疗1~2年，每3个月随访1次，随访至12岁，防止弱视复发；若出现视力下降、复视或眼部不适，随时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":575,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5cd9076b2bbb3c9c4f305caca36c2b8af54f48e9e9f1c9e7643b2f5258b22e61","pinyin":"ruoshi","initials":"rs","setting":"out","caseName":"门诊病历440","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历440",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6d5b5c44d1b9bda5f263","key":"v1-c9ccc21dfe2a3058|templates-6d5b5c44d1b9bda5f263","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"斜视","category":"门诊病历模板","raw":{"name":"斜视","category":"门诊病历模板","case":{"case_name":"门诊病历441","templates":{"主诉":"眼位偏斜1年","现病史":"患儿（儿童，属后天性间歇性外斜，为儿童常见类型，注意力不集中、疲劳、看远时出现外斜，可自行控制）于3年前出现眼位偏斜，为双眼交替、间歇性、外斜视，偏斜随注视距离变化（看远时明显），注视方向改变时亦有变化；无复视（儿童多无复视，因产生抑制以防复视，故有弱视风险），有代偿头位（歪头转面以正位注视）、眯眼、畏光（间歇性外斜者强光下喜闭一眼，常见）。该病需与先天性/婴幼儿期发病者（内斜，生后6个月内发病，为先天性内斜，需早治）及后天性者（屈光调节性内斜（2~3岁、远视，调节所致，戴镜后多可矫正）、外伤后、神经性（外展神经麻痹致内斜）、成人突发斜视伴复视（属神经眼科急症，需排查））相鉴别；家族无斜视史，围产期史无特殊。今日来我院眼科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视力及矫正视力（弱视评估）、眼位（角膜映光法/Hirschberg，判断偏斜方向及度数量化）、遮盖试验（交替遮盖/遮盖-去遮盖，鉴别隐斜与显斜、判断恒定或间歇）、三棱镜遮盖试验（斜视度数定量，用于手术设计）、眼球运动（各方向运动，麻痹性斜视的神经肌肉评估）、双眼视功能（立体视、Worth四点）、屈光（散瞳验光，调节性内斜与远视）、眼底（排除器质病变）、代偿头位测量、复视检查（成人，红玻片/同视机）。","辅助检查":"【必做】散瞳验光（睫状肌麻痹，调节性斜视诊断、远视，核心）、眼位及斜视度检查、眼球运动及双眼视功能评估；【影像】头颅MRI/CT（后天性麻痹性斜视、神经源性疾病（动眼/滑车/外展神经麻痹，血管性/肿瘤/外伤，需影像排查，尤其成人突发复视）、甲状腺相关眼病（眼肌受累致限制性斜视，需甲功评估））；【其他】神经科/内分泌科会诊（神经麻痹、甲状腺眼病，按病因）、围产期及发育评估（婴幼儿）。","初步诊断":"1. 斜视（外斜：后天性，间歇性，伴弱视）\n（注：治疗目的为恢复眼位正位、双眼视功能及美容，儿童早治防弱视：①屈光矫正（调节性内斜足度远视镜，多数戴镜后内斜消失或减少，为核心）；②弱视治疗（遮盖/压抑，合并弱视者先治弱视）；③手术（非调节性部分/斜视度数大/保守治疗无效者：眼外肌手术矫正内斜或外斜，儿童最佳时机（内斜宜2岁前，正值双眼视发育关键期，不宜过晚）；间歇性外斜手术时机（控制力下降/斜视度数增大/立体视受损时））；④肉毒毒素注射（婴幼儿内斜，可部分替代手术，近年患者）；⑤后天性麻痹性斜视治疗病因（神经源性请神经内科；甲状腺眼病请内分泌科，予激素/免疫治疗；外伤后观察6~12个月（有自愈可能）再手术）+复视对症（棱镜临时矫正）+急性斜视保守观察或遮盖单眼（防复视不适）；⑥双眼视功能训练（术后立体视恢复）；随访（术后眼位、视力、双眼视，防复发）；儿童眼科专科，家长教育（早期发现早期就诊，先天性内斜不治疗可致永久弱视及无双眼视，重要）。）","处理方案":"【药物治疗】\n1. 麻痹性斜视（神经源性损害）：甲钴胺片0.5mg tid po，联合维生素B1片10mg tid po，疗程2~4周。\n2. 糖尿病、高血压等微血管性急性麻痹性斜视：在上述神经营养治疗基础上严格控制血压血糖，可加用银杏叶提取物片40mg tid po×2周。\n3. 调节性内斜视（高AC/A或远视性调节性内斜视）：1%阿托品眼膏双眼各1次/日×3天行睫状肌麻痹后验光，配足矫远视眼镜；必要时短期联用1%毛果芸香碱滴眼液1滴 bid（缩瞳作用可致视物变暗，用药期间注意监测）。\n4. 急性麻痹性斜视保守治疗6~8周无好转者：A型肉毒毒素5U（0.1ml）行拮抗肌肌腹注射1次（需眼科专科操作），注射后4~8周评估斜视角变化。\n【一般治疗及生活指导】\n1. 病因排查：成人突发斜视伴复视须警惕脑血管病、颅内占位等，及时完善头颅MRI/MRA并请神经内科会诊，勿延误诊治。\n2. 复视处理：复视症状明显时暂时遮盖一眼（双眼交替遮盖，避免单眼遮盖过久）或配戴压贴三棱镜缓解症状；症状轻者可不遮盖，适应后定期复查。\n3. 生活规律，避免熬夜及长时间近距离用眼疲劳；戒烟限酒；积极控制血压、血糖、血脂，防治血管性眼肌麻痹复发。\n4. 斜视矫正术后：术后1周内避免剧烈运动、低头用力、揉眼及碰撞术眼，保持术眼清洁、按时点眼药防感染。\n【随诊要求】\n1. 用药2~4周后复诊：复查眼位、眼球运动、复视像及三棱镜度数，评估疗效并调整用药。\n2. 肉毒毒素注射后4~8周复诊评估斜视角及眼球运动，必要时重复注射或改行手术治疗。\n3. 调节性内斜视戴镜后每3~6个月复查屈光状态及眼位，及时调整眼镜度数。\n4. 保守治疗6个月斜视度数稳定且无好转者行手术评估，术后1周、1个月、3个月定期复查眼位及双眼视功能；期间若出现头痛、呕吐、眼球运动障碍加重或视力骤降，立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":576,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e40ba4991dceb47126c827cbaac3495dfbeba78b3dbc7555a0f24ed054183a8c","pinyin":"xieshi","initials":"xs","setting":"out","caseName":"门诊病历441","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历441",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-13e90f0056ed3a835834","key":"v1-c9ccc21dfe2a3058|templates-13e90f0056ed3a835834","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"眼球震颤","category":"门诊病历模板","raw":{"name":"眼球震颤","category":"门诊病历模板","case":{"case_name":"门诊病历442","templates":{"主诉":"眼球不自主摆动1周","现病史":"患者1周前无明显诱因出现眼球震颤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以眼球不自主摆动1周为主诉就诊，症状逐渐加重并伴轻度乏力，首先完善视力、眼压、裂隙灯检查及眼底检查，明确有无先天性白内障、视神经发育异常及视网膜病变等可致视力障碍性眼球震颤的眼部病因；完善眼底照相记录眼底形态便于随访对比，完善 OCT 检查了解黄斑及视网膜神经纤维层结构有无异常，完善视野检查了解视野缺损情况，评估视功能损害程度；患者眼球震颤需鉴别前庭性与中枢性病因，完善眼B超了解眼球及球后结构有无异常，完善视觉电生理检查了解视网膜与视神经传导功能，必要时完善荧光素眼底血管造影明确有无视网膜血管性病变；完善头颅CT明确颅内有无占位、出血及小脑病变，必要时完善头颅MRI明确小脑、脑干及前庭通路有无病变，鉴别中枢性眼球震颤；完善纯音测听与声导抗了解有无合并听力损害，完善前庭功能检查明确有无前庭系统功能障碍，评估有无前庭周围性病变；完善血常规排除感染、贫血所致神经系统症状，完善生化全项与肝肾功能、血糖、血脂、电解质检查，排除代谢性及电解质紊乱所致眼球震颤；完善心电图排除心律失常等心源性因素；必要时请神经内科与耳鼻喉科会诊协助明确病因。\n\n（检查清单）\n【必做检查】\n视力、眼压、裂隙灯检查、眼底检查\n\n【影像学检查】\n眼底照相、OCT、视野检查\n\n【其他检查】\n荧光素眼底血管造影、眼B超、视觉电生理","初步诊断":"1. 眼球震颤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 加巴喷丁胶囊 0.1g po tid，起始小剂量，每3-5天渐增至0.3g po tid（疗程4-8周），可减轻部分先天性及获得性眼球震颤振幅，注意头晕、嗜睡等不良反应，肾功能不全者减量；\n2. 美金刚片 5mg po qd，1周后加至5mg po bid，再1周后渐增至10mg po bid维持（疗程8-12周），用于获得性眼球震颤及伴视力下降者，注意幻觉、头晕等不良反应；\n3. 巴氯芬片 5mg po tid，必要时渐增至10mg po tid，用于周期性交替性眼球震颤，注意嗜睡、肌张力降低，肝肾功能不全者慎用；\n4. 4-氨基吡啶缓释片 10mg po bid，用于下跳性或上跳性眼球震颤，注意癫痫病史者禁用。\n（药物治疗仅能部分改善眼震振幅及视力，需在监测下个体化调整剂量。）\n\n【一般治疗及生活指导】\n1. 保证充足睡眠、避免视疲劳，连续近距离用眼（手机、电脑、阅读）不超过40分钟，休息时远眺放松调节，避免咖啡因、酒精及尼古丁等可能加重眼震的刺激物；\n2. 保持均衡饮食，适当补充维生素B族及叶黄素，多食深色蔬菜水果，避免暴饮暴食及辛辣刺激饮食；\n3. 利用代偿头位视物以获得最佳视力，必要时佩戴三棱镜或光学矫正眼镜，弱视者行遮盖及视觉训练；注意用眼安全，避免驾驶、高空作业及操作精密仪器等需精细视力活动；\n4. 保持情绪平稳、避免过度紧张焦虑及疲劳，可配合眼保健操及放松训练，缓解精神因素诱发的眼震加重。\n\n【随诊要求】\n1. 药物治疗期间每2-4周复诊一次，评估眼震振幅、频率及视力变化，监测不良反应并及时调整剂量；\n2. 每3-6个月复查视力、屈光、眼位及眼底，评估病情进展；\n3. 若出现视力突然下降、复视、眩晕、头痛、恶心或肢体麻木等新发症状，或震颤明显加重影响生活，应随时就诊；\n4. 儿童患者需定期复查屈光状态及双眼视功能，预防弱视及斜视；疑有中枢神经系统病变者转神经内科进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":577,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ed89e6126151554634b4de2e3728a1d75f2332256b83d5b533e6cb2fcb7a4f6e","pinyin":"yanqiuzhenchan","initials":"yqzc","setting":"out","caseName":"门诊病历442","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历442",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0cdb47906e0689cb4881","key":"v1-c9ccc21dfe2a3058|templates-0cdb47906e0689cb4881","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"眼眶蜂窝织炎","category":"门诊病历模板","raw":{"name":"眼眶蜂窝织炎","category":"门诊病历模板","case":{"case_name":"门诊病历443","templates":{"主诉":"眼睑红肿伴发热、眼球突出3天","现病史":"患者（儿童及成人均可发病，多继发于鼻窦炎（筛窦为最常见感染源，眶内壁纸样板薄弱），也可继发于眶周外伤/异物、面部/牙齿感染、泪囊炎、手术后、血行播散）于3天前出现眼睑红肿（进行性加重），由眶周蜂窝织炎（隔前：眼睑红肿，无眼球突出及视力障碍）发展为眶蜂窝织炎（隔后：眼球突出、眼球运动受限、视力下降、球结膜水肿，属急症，可致盲及颅内感染），伴发热（体温最高38.9℃）、畏寒、头痛、眼眶胀痛，伴视力下降/丧失（视神经受压/缺血，严重）、复视（眼外肌受累）、脓涕（鼻窦炎来源）；无意识改变（无海绵窦血栓/颅内蔓延（脑膜炎/脑脓肿）等最严重并发症表现）；有鼻窦炎/感冒前驱史，无外伤史。今日来我院急诊眼科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.9℃，P96次/分，R20次/分，BP120/80mmHg。全身（发热、精神差，有中毒表现）。眼部：眼睑红肿热痛（眶周蜂窝织炎征，隔前）、眼球突出（突眼度Hertel法，较对侧突出3mm）、球结膜水肿（+++）、眼球运动受限伴疼痛（各方向）、视力下降（0.3，为视神经受累警示）、相对性传入性瞳孔障碍（RAPD，提示视神经压迫/缺血，严重）、眼底（视乳头水肿/视网膜静脉淤血，见于眶尖综合征，晚期）、角膜（暴露，因眼球突出）、鼻部（脓涕/鼻窦压痛）、区域淋巴结肿大。","辅助检查":"【必做】血常规（白细胞显著升高）、CRP/降钙素原、血培养（发热者，用抗生素前）、鼻窦X线/超声（眶周脓肿初步筛查）；【影像】眼眶及鼻窦CT（增强，首选，判断隔前/隔后受累、眶内脓肿（骨膜下脓肿，位于内直肌旁，呈梭形）、鼻窦炎、异物并定位，为手术决策核心）；【影像】MRI（CT不能确定或评估颅内并发症时，如脑膜脑炎/海绵窦血栓，增强）；【其他】脓肿穿刺培养（手术时）、腰椎穿刺（疑颅内感染，查脑脊液）。","初步诊断":"1. 眼眶蜂窝织炎（右眼：眶隔后（眶内），伴骨膜下脓肿）\n（注：眼眶蜂窝织炎为眼科急症（可致盲（视神经炎/缺血）及颅内感染（海绵窦血栓、脑膜炎，有死亡风险），应即急诊住院治疗：①静脉广谱抗生素（经验性，覆盖鼻窦菌（肺炎链球菌、流感嗜血杆菌、金黄色葡萄球菌，考虑MRSA、厌氧菌）：头孢曲松2g q12h+万古霉素（MRSA高危）±甲硝唑（覆盖厌氧菌，鼻窦/牙源）；儿童需覆盖流感嗜血杆菌（头孢曲松）；疗程为静脉用药至症状明显好转后改口服，总疗程2~3周）；②脓肿（骨膜下脓肿：药物治疗24~48小时无好转、脓肿大、视力下降或出现颅内并发症时手术引流（鼻内镜下眶减压/外路切开引流））；③视力监测（每4~6小时查视力/瞳孔，视神经受累为急症手术指征）；④处理感染源（鼻窦炎行鼻内镜手术引流（可同步）、拔除病灶牙、取出异物）；⑤并发症处理（海绵窦血栓：抗凝+广谱抗生素+考虑抗真菌，进ICU；脑膜炎/脓肿：神经外科处理颅内病变）；⑥眶隔前蜂窝织炎（轻症、无全身症状者可口服抗生素门诊治疗（阿莫西林克拉维酸），密切随访，但需警惕进展，影像区分隔前隔后是关键）；耳鼻喉+眼科+（颅内病变加神经科）多学科协作急诊处理。）","处理方案":"【药物治疗】\n1. 头孢呋辛酯片 0.5g bid×10~14天（口服前先静脉抗感染治疗病情稳定后序贯，门诊轻症可全程口服）。\n2. 阿莫西林克拉维酸钾片 0.625g tid×10~14天（覆盖金黄色葡萄球菌及链球菌，伴鼻窦炎者尤宜）。\n3. 甲硝唑片 0.4g tid×7~10天（眼眶蜂窝织炎常合并厌氧菌感染，需联合使用）。\n4. 布洛芬缓释胶囊 0.3g bid（或对乙酰氨基酚片0.5g tid）按需退热镇痛，症状缓解后停药。\n【一般治疗及生活指导】\n1. 急性期卧床休息、减少用眼及视屏时间；患眼可予局部冷敷减轻红肿，切忌热敷及挤压、揉搓眼部。\n2. 严格禁止挤压面部\"危险三角区\"及鼻部病灶，防止感染经静脉逆行入颅。\n3. 清淡饮食，多饮水，忌辛辣刺激性食物及烟酒；保持鼻腔通畅，必要时生理盐水洗鼻。\n4. 每日自我监测双眼视力及眼球突出程度，发现视力下降、复视、眼球活动受限须立即就医。\n【随诊要求】\n1. 用药3~5天后复诊评估疗效（复查血常规、CRP），必要时调整抗感染方案。\n2. 用药期间出现视力下降、眼球突出加重、眼痛加剧、高热、剧烈头痛、恶心呕吐或神志改变者，立即急诊就诊，排除颅内并发症。\n3. 抗生素需足量足疗程（10~14天）服用，切勿自行减量或提前停药；疗程结束后复查血常规及炎症指标确认感染控制。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":578,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cca395c8568a6b3b1403ebbbc8603ccfd20380a7a67bfae218cede9d181c1cd7","pinyin":"yankuangfengwozhiyan","initials":"ykfwzy","setting":"out","caseName":"门诊病历443","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历443",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1774d7db0ab2805a902b","key":"v1-c9ccc21dfe2a3058|templates-1774d7db0ab2805a902b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"眼眶肿瘤","category":"门诊病历模板","raw":{"name":"眼眶肿瘤","category":"门诊病历模板","case":{"case_name":"门诊病历444","templates":{"主诉":"眼球突出伴眼眶肿物1周","现病史":"患者1周前无明显诱因出现眼眶肿瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以眼球突出伴眼眶肿物1周为主诉就诊，症状逐渐加重并伴轻度乏力，首先完善视力、眼压、裂隙灯检查及眼底检查，明确有无视神经受压、视盘水肿及眼压升高，评估肿瘤对视功能的影响；完善眼底照相记录眼底情况便于随访对比，完善 OCT 检查了解视网膜神经纤维层有无受压变薄，完善视野检查了解有无与肿瘤位置相符的视野缺损；患者眼球突出伴眼眶肿物，需完善眼眶CT明确肿物位置、大小、边界及与眶壁、视神经的关系，必要时完善眼眶MRI以明确肿物性质及有无颅内蔓延，鉴别海绵状血管瘤、淋巴瘤及炎性假瘤等病变；完善眼B超了解球后占位及血流情况，必要时完善荧光素眼底血管造影了解眼底血循环情况；完善视觉电生理检查了解视神经传导功能受损程度；完善血常规排除感染、贫血所致全身症状，完善生化全项与肝肾功能评估全身代谢状态及手术前基础情况，查血糖、血脂、电解质了解有无代谢异常，完善凝血功能为可能的手术治疗做准备；完善心电图与胸部X线片评估心肺功能，完善腹部超声排除腹部原发肿瘤转移；必要时请眼科、影像科及肿瘤科会诊，必要时行肿物穿刺活检明确病理性质。\n\n（检查清单）\n【必做检查】\n视力、眼压、裂隙灯检查、眼底检查\n\n【影像学检查】\n眼底照相、OCT、视野检查\n\n【其他检查】\n荧光素眼底血管造影、眼B超、视觉电生理","初步诊断":"1. 眼眶肿瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.糖皮质激素类（用于炎性假瘤、淋巴增殖性病变的诊断性治疗及控制肿瘤周围组织水肿）：泼尼松片 30-60mg 每日晨起顿服，连用1-2周后视疗效每1-2周递减5mg，总疗程4-8周；服药期间监测血压、血糖，并加服奥美拉唑肠溶胶囊20mg qd 保护胃黏膜。\n2.神经营养类（保护视神经功能，适用于肿瘤压迫视神经、存在视力下降或视野缺损者）：甲钴胺片 0.5mg tid，联合维生素B1片 10mg tid，连用1-3个月。\n3.抗生素类（肿瘤破溃继发感染、穿刺活检或术后预防感染）：头孢呋辛酯片 0.25g bid×5-7天；对青霉素及头孢过敏者改用左氧氟沙星片 0.5g qd×5天（18岁以下、孕妇禁用）。\n\n【一般治疗及生活指导】\n1.休息与活动：保证充足睡眠，避免剧烈运动、提重物、用力排便、长时间低头等使眶内压骤增的动作；避免揉眼、按压或热敷肿块区域，防止肿瘤破裂或播散。\n2.饮食：均衡高蛋白、富含维生素饮食（瘦肉、蛋、鱼类、新鲜蔬果），戒烟戒酒，避免辛辣刺激及腌制食品；拟行放疗或化疗者注意加强营养支持。\n3.眼部保护：眼球突出致眼睑闭合不全者，白天予玻璃酸钠滴眼液滴眼，睡前涂红霉素眼膏并佩戴眼罩覆盖，防止暴露性角膜炎和角膜溃疡。\n4.病情观察：每日自行观察眼球突出度、视力、复视及眼痛变化，如出现视力骤降、眼球突出进行性加重或剧烈眶痛，立即就医。\n\n【随诊要求】\n1.良性肿瘤（如海绵状血管瘤）且视神经未受压者，每3-6个月门诊复查一次（视力、眼压、眼球突出度、眼底及眼眶MRI/CT），动态评估肿瘤大小变化。\n2.怀疑或确诊恶性病变（淋巴瘤、横纹肌肉瘤、泪腺腺样囊性癌等）者，转肿瘤专科联合制定治疗方案，按方案定期随访：治疗期每1-3个月复查影像学，缓解后每6-12个月复查并评估全身情况。\n3.接受糖皮质激素治疗者，每1-2周复诊评估疗效并监测血糖、血压、电解质等不良反应，遵医嘱阶梯减量，不可自行停药。\n4.出现视力进行性下降、剧烈头痛眼痛、眼球突出突然加重、发热或恶心呕吐等颅内压增高表现时，随时急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":579,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3fc5dee8a1d235841f1ce81ae1d33429c4eaf759705f468b8f652ae2e30e2d3d","pinyin":"yankuangzhongliu","initials":"ykzl","setting":"out","caseName":"门诊病历444","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历444",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c27628751bb13bc0a762","key":"v1-c9ccc21dfe2a3058|templates-c27628751bb13bc0a762","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"外耳道炎","category":"门诊病历模板","raw":{"name":"外耳道炎","category":"门诊病历模板","case":{"case_name":"门诊病历445","templates":{"主诉":"耳痛、耳痒伴耳道分泌物3天","现病史":"患者于3天前因游泳耳道进水（外耳道潮湿，即“游泳耳”，为最常见诱因；病原以细菌为主（铜绿假单胞菌/金葡菌/真菌））出现：耳痛（牵拉耳廓/按压耳屏时明显加重，为特征，可与中耳炎鉴别（中耳炎鼓膜牵拉不痛））、耳痒（早期，见于湿疹/真菌）、耳道分泌物（脓性，量中等，有恶臭（铜绿假单胞菌所致，呈绿色脓性，为特征））、耳闷（因肿胀、堵塞致听力下降（传导性，轻度））、咀嚼痛（颞下颌关节邻近炎症所致）；无发热（一般无发热，深部感染/恶性外耳道炎可有），无耳廓/耳患者肿（无蜂窝织炎蔓延），无糖尿病及免疫低下史（恶性外耳道炎风险不高），无真菌性外耳道炎及湿疹史；有游泳/挖耳诱因（不当掏耳可损伤外耳道皮肤致感染，重要；耳道感染也可继发于助听器/耳机佩戴所致摩擦、潮湿，或外耳道湿疹（过敏））。糖尿病及免疫低下者需警惕恶性外耳道炎（坏死性），该病呈进行性加重，可累及深部组织及颞骨致骨髓炎，表现为剧烈耳痛、耳漏、面瘫，属急症，需住院治疗；本例无上述危险因素。今日来我院耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P80次/分，R18次/分，BP118/76mmHg。耳：耳廓牵拉痛（外耳道炎牵拉耳廓/按压耳屏即痛，为特征）、外耳道皮肤红肿（弥漫肿胀、堵塞致狭窄）、分泌物（脓性，量中等）、鼓膜窥不清（因肿胀堵塞，清理后见鼓膜完整、无穿孔，排除中耳炎）、耳周淋巴结肿大、耳廓无红肿（无蜂窝织炎蔓延）、颞颌关节无咀嚼痛、无糖尿病相关深部肉芽及恶臭（不支持恶性外耳道炎）。","辅助检查":"【必做】耳内镜检查（核心，评估外耳道及鼓膜）；【其他】分泌物培养（反复发作/特殊感染/治疗无效时，查铜绿假单胞菌/真菌并做药敏）、血常规/血糖（筛查糖尿病，警惕恶性外耳道炎，重要）、CT（疑恶性外耳道炎时（糖尿病者深部受累、颞骨骨质破坏）评估并住院）、真菌镜检（疑真菌时查菌丝）、听力检查（中耳受累时必要时）。","初步诊断":"1. 外耳道炎（急性弥漫性：外耳道肿胀程度中度，已排除恶性外耳道炎（无糖尿病/免疫低下））\n（注：治疗以清洁+局部抗感染、保持干燥为核心：①耳道清洁（关键，专业清理（耳内镜下用吸引/拭子）清除分泌物及脱屑（重要，使药物直达创面、防堵塞）；保持干燥（洗头游泳时用耳塞/棉球防进水，痊愈前禁游泳，重要））；②局部用药（抗生素滴耳液：急性细菌性用左氧氟沙星/氧氟沙星滴耳液（耳用喹诺酮，安全），含激素者（氧氟沙星+地塞米松）可抗炎消肿，用于早期，每日3~4次滴耳，行耳浴（侧卧滴入后保持5~10分钟），疗程7~10天；真菌性用抗真菌滴耳液（水杨酸/克霉唑）或抗真菌药膏（咪康唑）涂耳道，并停用抗生素（抗生素会加重真菌，重要）；湿疹性用激素软膏（氢化可的松）+口服抗组胺药（过敏）；肿胀明显者用耳道棉条（浸药后塞入，引流、消肿、促药物渗入））；③全身抗生素（指征为蜂窝织炎蔓延（耳患者肿）、发热、糖尿病/免疫低下者，口服抗铜绿药物（环丙沙星，覆盖铜绿假单胞菌，重要））；④恶性外耳道炎（坏死性，属急症：糖尿病者出现剧烈耳痛、耳漏、肉芽、颅神经受累（面瘫）需住院，静脉抗铜绿抗金葡（环丙沙星+头孢他啶/哌拉西林他唑巴坦），长程（6~8周）治疗，清创（手术清除坏死组织），CT随访（观察骨质破坏恢复），控制血糖，重要）；⑤预防（保持耳道干燥（游泳用耳塞，洗后吹干、侧头控水）、勿挖耳（棉签/挖耳勺易损伤致感染，重要）、糖尿病者控糖并及早治疗耳道感染（防恶性））；⑥随访（治疗3~5天应好转，未好转/加重需复诊（分泌物培养、调整用药），真菌感染疗程长（2~4周）需随访）；耳鼻喉科清洁+局部滴耳、保持干燥，糖尿病者警惕恶性外耳道炎，均重要。","处理方案":"【药物治疗】\n1. 局部抗感染（首选）：氧氟沙星滴耳液（0.3%）滴耳，每次6~10滴，每日2~3次，滴药后患耳向上侧卧保持10分钟使药液充分浸入外耳道，疗程5~7天；对铜绿假单胞菌感染或滴耳液不耐受者，可换用环丙沙星滴耳液（0.3%），用法用量同前。\n2. 镇痛抗炎：疼痛明显者予布洛芬缓释胶囊0.3g口服，每日2次（或对乙酰氨基酚片0.5g口服，每日3次），疗程3~5天，餐后服用。\n3. 口服抗生素：外耳道明显肿胀、弥漫性炎症或伴耳周蜂窝织炎、发热等全身症状者，加用阿莫西林克拉维酸钾片0.625g口服，每日2次，疗程7天；青霉素过敏者改用头孢呋辛酯片0.25g口服，每日2次，疗程7天。\n\n【一般治疗及生活指导】\n1. 保持外耳道干燥清洁：洗头、洗澡时用无菌棉球蘸凡士林堵塞患耳外耳道口，避免污水入耳；治疗期间禁止游泳、潜水、泡温泉。\n2. 严禁挖耳、掏耳及用棉签反复清理外耳道，避免进一步损伤外耳道皮肤加重感染；耳内分泌物较多时由医师在耳内镜下清理后再滴药。\n3. 清淡饮食，忌辛辣刺激及海鲜、烟酒，规律作息，避免熬夜、劳累，注意休息。\n4. 减少佩戴入耳式耳机及不透气耳塞，避免长时间压迫刺激外耳道，保持耳部通风。\n\n【随诊要求】\n1. 用药3天后症状无缓解或耳痛加重、耳道流脓、出现听力下降或发热者，及时复诊。\n2. 完成5~7天疗程后复诊，由医师检查外耳道炎症消退情况，评估是否需要调整或延长治疗。\n3. 外耳道炎反复发作或迁延不愈者，复诊时需排查真菌性外耳道炎、外耳道胆脂瘤及糖尿病等基础疾病。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":580,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"69c3ef90820249df95251c75d9c85c246667a74ad50960b7e6799eb42769976f","pinyin":"waierdaoyan","initials":"wedy","setting":"out","caseName":"门诊病历445","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历445",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5bb3ca1cd4c7900a4f63","key":"v1-c9ccc21dfe2a3058|templates-5bb3ca1cd4c7900a4f63","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"外耳道疖","category":"门诊病历模板","raw":{"name":"外耳道疖","category":"门诊病历模板","case":{"case_name":"门诊病历446","templates":{"主诉":"耳痛伴耳道红肿1周","现病史":"患者1周前无明显诱因出现外耳道疖相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以耳痛伴耳道红肿1周为主诉就诊，症状逐渐加重并伴轻度乏力，首先完善耳镜检查明确外耳道有无局限性红肿隆起、疖肿成熟情况及有无分泌物，评估鼓膜是否完整；患者耳痛需与中耳炎、外耳道炎及耳部带状疱疹鉴别，完善血常规排除细菌感染及评估炎症程度，指导抗生素使用；完善鼻内镜检查排除鼻部及鼻咽部病变所致咽鼓管功能障碍，完善喉镜检查排除咽喉部病变所致耳部牵涉痛；完善纯音测听与声导抗了解听力有无下降及中耳功能状态，必要时完善前庭功能检查排除前庭系统受累；患者耳道红肿需排除邻近结构病变，完善颞骨CT明确外耳道及中耳乳突有无骨质破坏及胆脂瘤，必要时完善鼻窦CT排除鼻窦炎所致牵涉性耳痛，完善颈部超声了解颈部淋巴结有无肿大；完善尿常规与便常规排除泌尿系统及消化道疾病，完善肝肾功能评估肝肾代谢功能及用药前基础情况，查血糖了解有无糖尿病等易感染因素，查血脂、电解质评估全身代谢状态；完善心电图与胸部X线片、腹部超声评估心肺及腹部基础情况；如疖肿反复发作或伴发热，必要时完善分泌物培养及药敏试验，指导抗感染方案。\n\n（检查清单）\n【必做检查】\n血常规、耳镜检查、鼻内镜检查、喉镜检查\n\n【影像学检查】\n鼻窦CT、颞骨CT、颈部超声\n\n【其他检查】\n纯音测听、声导抗、前庭功能检查","初步诊断":"1. 外耳道疖\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗感染治疗：阿莫西林胶囊0.5g tid×5～7天（青霉素过敏者改用患者霉素片0.15g bid×5～7天），或头孢呋辛酯片0.25g bid×5～7天。\n2. 局部用药：10%鱼石脂甘油纱条敷于疖肿处，每日更换1次，促其成熟破溃；或用氧氟沙星滴耳液滴耳，每次3～5滴，每日3次，滴后患耳朝上保持10分钟。\n3. 止痛治疗：疼痛明显者予布洛芬缓释胶囊0.3g bid，或对乙酰氨基酚片0.5g prn，每日不超过4次，饭后服用。\n4. 疖肿早期未化脓者：可加用2%酚甘油滴耳剂滴耳，每次3滴，每日3次，以消炎止痛。\n\n【一般治疗及生活指导】\n1. 保持外耳道干燥清洁，洗头、洗澡时用干棉球堵塞耳道口防止进水；彻底戒除挖耳、掏耳习惯，避免损伤外耳道皮肤。\n2. 清淡饮食，多饮水，忌辛辣、油腻及海鲜等刺激性食物，戒烟限酒。\n3. 避免患耳受压，侧卧时勿压患侧耳廓；避免游泳及剧烈运动，防止污水入耳或挤压疖肿。\n4. 疖肿未成熟时勿自行挤压、搔抓，防止感染扩散至耳周软组织及颅内。\n\n【随诊要求】\n1. 用药后3～5天复诊，评估疖肿消退及疼痛缓解情况；若3天内症状无缓解或出现耳患者肿加重、发热、张口困难、耳后肿痛，须立即复诊。\n2. 疖肿成熟化脓者，复诊行切开引流，并按医嘱定期换药至创口愈合。\n3. 反复发作或迁延不愈者，复诊时检查空腹血糖及糖化血红蛋白，排除糖尿病等基础疾病，必要时转耳鼻喉专科进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":581,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"77e31174bfe41592d77d3c0af71bb27d8328bc62938575964ba62816580b7e57","pinyin":"waierdaojie","initials":"wedj","setting":"out","caseName":"门诊病历446","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历446",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e16f021deed9390c160b","key":"v1-c9ccc21dfe2a3058|templates-e16f021deed9390c160b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"耵聍栓塞","category":"门诊病历模板","raw":{"name":"耵聍栓塞","category":"门诊病历模板","case":{"case_name":"门诊病历447","templates":{"主诉":"耳闷、听力下降1周","现病史":"患者于1周前挖耳并进水后渐出现：耳闷胀感（堵塞感）、听力下降（传导性，轻度，耵聍完全堵塞所致）、耳鸣（低调）、耳痛（耵聍进水膨胀后压迫鼓膜/外耳道，游泳/洗头后常见）、耳痒，无眩晕（偶有，系压迫所致）、咳嗽（外耳道刺激迷走神经耳支致反射性咳嗽）。诱因为耵聍（正常分泌，外耳道自洁、上皮移行排出，多数不需清理）堵塞（耳道狭窄/弯曲、耵聍分泌多、不当挖耳（用棉签将耵聍推入深部，越推越深致栓塞，为最常见原因，重要，应勿挖耳）、老年人（耵聍干硬致栓塞）、助听器/耳塞使用者），既往无鼓膜穿孔（冲洗禁忌，重要，已询问中耳炎/手术史），无耳溢（除非继发感染致外耳道炎则有脓、痛），有挖耳习惯及游泳进水诱因；既往有耵聍栓塞史（反复，需定期清理）。今日来我院耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP120/78mmHg。耳：外耳道耵聍（位于外段近鼓膜处，性质为湿性（黏稠、棕褐），完全堵塞形成栓塞）、外耳道充血（继发外耳道炎，有痛）、鼓膜窥不清（被耵聍遮挡，取出后检查完整性、评估有无穿孔）、听力（音叉检查提示传导性听力下降，耵聍栓塞所致，轻度）、耳周无压痛。","辅助检查":"【必做】耳内镜（核心，评估耵聍，取出后检查鼓膜）；【其他】取出后听力复查（耵聍取出后听力多恢复，若仍差需进一步纯音测听评估中耳/内耳）、疑感染（外耳道炎）时行分泌物培养（必要时）、疑鼓膜穿孔（有中耳炎史）时行声导抗（中耳评估）。","初步诊断":"1. 耵聍栓塞（外耳道耵聍堵塞，右侧，完全堵塞，未继发外耳道炎）\n（注：治疗以取出耵聍、安全操作、防损伤鼓膜为原则：①取出方法：耳道冲洗（用温水以注射器/专用冲洗器冲入外耳道将耵聍冲出，适用于软性耵聍，禁忌为鼓膜穿孔史/中耳炎史（冲洗液可入中耳致感染，重要），穿孔者禁用冲洗，改用器械/吸引）；耵聍钩/耳匙（器械取出，适用于硬性/部分栓塞，需专业操作，在直视（耳内镜）下进行，防损伤外耳道/鼓膜）；吸引（适用于软性耵聍，负压吸引）；滴耳液软化（硬性耵聍用碳酸氢钠滴耳液/耵聍水软化，每日3~4次×2~3天后再冲洗/吸引，滴后耳胀为正常现象，软化后易取出，重要）；继发感染时先抗感染（滴耳液，左氧氟沙星），待炎症消退后再取；②取出后检查鼓膜（完整性，有无穿孔并处理）、复查听力（评估恢复）、处理外耳道炎症；③预防教育（关键：勿挖耳（棉签/挖耳勺会将耵聍推入深部致栓塞，并损伤外耳道/鼓膜，重要；耵聍多数可自洁（经咀嚼/说话及上皮移行自行排出），不需清理，仅在栓塞/有症状时清理）；耵聍多者定期（每6~12个月）到耳科清理，勿自行掏挖；助听器/耳塞使用者定期耳科检查）；④随访（取出后观察症状（听力/耳闷）是否缓解；反复栓塞者评估外耳道狭窄/炎症/皮脂腺功能）；耳鼻喉科安全取出、保护鼓膜、勿挖耳宣教，均重要。","处理方案":"【药物治疗】\n1.碳酸氢钠滴耳液（5%）：滴耳，每次4～5滴，每日3～4次，连用3天软化耵聍后复诊行外耳道冲洗或负压吸引取出；鼓膜穿孔者禁用。\n2.3%过氧化氢溶液：外耳道冲洗前滴入，每次3～5滴，静置1～2分钟后侧头倾倒流出，清洁外耳道，每日1次。\n3.合并外耳道炎者：氧氟沙星滴耳液，滴耳每次3～5滴，每日3次，疗程5～7天，同时保持耳内干燥。\n4.耵聍坚硬、软化困难或伴耳痛者：苯酚甘油滴耳液滴耳，每次3～4滴，每日3次，润滑、消炎、止痛后再行取出。\n【一般治疗及生活指导】\n1.避免用棉签、挖耳勺、发卡等自行掏挖外耳道，以免将耵聍推向深部形成嵌顿或损伤外耳道皮肤及鼓膜。\n2.洗头、沐浴、游泳时用棉球或耳塞堵塞外耳道口，防止水液进入；滴耳软化期间侧头让药液及耵聍碎屑自行流出，保持外耳道干燥。\n3.清淡饮食，忌辛辣刺激性食物及饮酒；合并感染时避免剧烈运动及用力擤鼻。\n4.减少佩戴入耳式耳机时间，避免噪声刺激加重耳闷、听力下降等不适。\n【随诊要求】\n1.滴药软化3天后及时复诊行外耳道冲洗或负压吸引取出耵聍；一次未能取净者，间隔1周再次复诊。\n2.取出后复查听力，若听力改善不明显或伴耳闷、耳鸣、眩晕，需进一步行纯音测听、声导抗及耳内镜检查，排除中耳及内耳病变。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":582,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2737109ec05d25553856b99047e77949384c09ea6c4457e30979113fb2fa4d3b","pinyin":"dingningshuanse","initials":"dnss","setting":"out","caseName":"门诊病历447","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历447",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1439a47e6a1414da0b02","key":"v1-c9ccc21dfe2a3058|templates-1439a47e6a1414da0b02","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"大疱性鼓膜炎","category":"门诊病历模板","raw":{"name":"大疱性鼓膜炎","category":"门诊病历模板","case":{"case_name":"门诊病历448","templates":{"主诉":"耳痛伴耳闷1周","现病史":"患者1周前无明显诱因出现大疱性鼓膜炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以耳痛伴耳闷1周为主诉就诊，症状逐渐加重并伴轻度乏力，首先完善耳镜检查明确鼓膜有无充血、大疱形成及有无鼓膜穿孔流脓，评估病变范围；完善纯音测听与声导抗了解听力下降程度及中耳功能状态，鉴别分泌性中耳炎与急性中耳炎；完善血常规排除细菌或病毒感染并评估炎症程度，完善尿常规与便常规排除泌尿系统及消化道慢性疾病，完善肝肾功能评估肝肾代谢功能及用药前基础情况，查血糖了解有无糖尿病等易感染因素，查血脂、电解质评估全身代谢状态；患者耳痛耳闷需排除邻近部位病变，完善颞骨CT明确中耳乳突有无积液及骨质破坏，必要时完善鼻内镜检查排除鼻咽部病变所致咽鼓管功能障碍；完善心电图排除心律失常及心肌缺血，完善胸部X线片排除肺部感染及结核，完善腹部超声排除腹部疾病；根据病情需要选择相应检查，如耳部症状持续加重或出现面瘫、眩晕，必要时完善头颅MRI明确有无颅内并发症，必要时请耳鼻喉科与感染科会诊协助诊治。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 大疱性鼓膜炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗感染治疗：若伴流感样全身症状，考虑病毒感染为主，予磷酸奥司他韦胶囊 75mg 口服 bid×5天；若鼓膜充血明显、耳流脓或合并急性中耳炎表现，考虑细菌感染或混合感染，予阿莫西林克拉维酸钾片 0.457g（阿莫西林0.4g/克拉维酸57mg）口服 tid×5-7天，青霉素过敏者改用阿奇霉素片 0.5g 口服 qd×3天。\n2. 局部治疗：氧氟沙星滴耳液 6-10滴 滴耳 tid×5-7天，滴耳时患耳向上侧卧，保持10分钟使药液充分浸泡外耳道及鼓膜，滴耳前先清除外耳道分泌物。\n3. 对症止痛：耳痛剧烈者予布洛芬缓释胶囊 0.3g 口服 bid，或对乙酰氨基酚片 0.5g 口服，必要时每6小时1次，疼痛缓解后即停用；耳痛持续不减且大疱张力高者，可由医师在无菌操作下行鼓膜表面大疱挑破引流以缓解疼痛。\n\n【一般治疗及生活指导】\n1. 注意休息，避免劳累、熬夜及受凉，多饮水，清淡易消化饮食，保证充足睡眠以增强抵抗力。\n2. 保持外耳道清洁干燥，洗头、洗澡时用干棉球塞住外耳道口，避免污水入耳；禁止用力擤鼻，应单侧交替轻擤，防止中耳压力骤变加重鼓膜损伤。\n3. 禁忌掏耳、用力按压耳屏或使用耳勺等刺激耳道，避免大疱过早破裂及继发感染；大疱破裂流液时用无菌棉签轻轻拭去外耳道口分泌物，勿向耳道深部填塞。\n4. 戒烟酒，忌辛辣刺激及过烫饮食，避免剧烈运动及游泳、潜水等使耳道压力急剧变化的活动。\n\n【随诊要求】\n1. 用药后3-5天复诊，复查耳内镜，观察大疱消退、鼓膜愈合及外耳道渗出情况，必要时调整用药。\n2. 若出现耳痛持续加重、耳流脓增多、听力明显下降、发热、眩晕或面瘫等表现，应及时复诊或急诊就诊。\n3. 症状缓解、鼓膜愈合后1-2周建议复查纯音测听及声导抗，评估听力及中耳功能恢复情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":583,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c832635a6c0c5532a75b0b126821a7243bfd1911bc1bba9de62d43b7bd070347","pinyin":"dapaoxinggumoyan","initials":"dpxgmy","setting":"out","caseName":"门诊病历448","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历448",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7c159039f2e6b222021f","key":"v1-c9ccc21dfe2a3058|templates-7c159039f2e6b222021f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"分泌性中耳炎","category":"门诊病历模板","raw":{"name":"分泌性中耳炎","category":"门诊病历模板","case":{"case_name":"门诊病历449","templates":{"主诉":"耳闷、听力下降伴耳内回声1月","现病史":"患者为儿童，2~6岁高发，因咽鼓管短平宽、功能不成熟，于上呼吸道感染后出现咽鼓管功能障碍，中耳负压致积液（渗出性、非感染性，鼓膜完整、无急性炎症，区别于急性中耳炎化脓）；成人多因咽鼓管功能障碍或鼻咽部病变（鼻咽癌：成人单侧分泌性中耳炎的重要警示，单侧积液应排除鼻咽部肿瘤，尤其伴血涕、颈部包块、耳闷者；我国鼻咽癌高发，成人单侧分泌性中耳炎必查鼻咽）、腺样体肥大（儿童，压迫咽鼓管咽口）、腭裂（咽鼓管功能差）、过敏（变应性鼻炎）、气压伤（飞行/潜水）所致。本次于感冒后渐进出现：听力下降（传导性、轻中度；儿童可无主诉，多由老师或家长发现上课注意力不集中、看电视声音过大、反应迟钝，此为重要学习影响，儿童听力筛查可发现）、耳闷胀感（耳内堵塞感）、耳内回声（自听过强、说话有回声，为中耳积液的特征）、耳鸣（低调）、耳痛（多无，区别于急性中耳炎）、眩晕（少）；儿童可表现为抓耳、烦躁、语言发育迟缓（长期双耳听力下降可致语言发育迟缓，重要）。起病以来：有无感冒鼻塞流涕（诱因，儿童）、打鼾与张口呼吸（腺样体肥大）、耳流脓（无，鼓膜完整）、鼻咽症状（成人单侧者注意血涕、颈部包块等鼻咽癌警示）、气压伤史（飞行、潜水）；病程：急性（<3周）/亚急性（3周~3月）/慢性（>3月，需干预）。今日来我院耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P100次/分，R24次/分，BP96/60mmHg。耳：鼓膜内陷（光锥消失）、活动度差（鼓气耳镜/耳内镜观察）、色泽呈琥珀色/灰蓝色（积液透见、液平面、气泡，均为鼓膜后积液征象）、鼓膜增厚（慢性）；鼓膜完整、无穿孔；听力：音叉检查Rinne阴性（传导性聋，气导短于骨导）；儿童需查鼻咽部（腺样体肥大，间接鼻咽镜/内镜，检查重要）、鼻（鼻炎/鼻窦炎）；成人单侧者必查鼻咽镜（鼻咽癌排查，重要）、纤维鼻咽镜（观察鼻咽部有无肿物）。","辅助检查":"【必做】耳内镜/鼓气耳镜（核心，观察鼓膜内陷、活动差、液平，判断积液）、声导抗（鼓室图：B型即平坦型为中耳积液的特征性表现，可诊断；C型提示负压，为咽鼓管功能障碍早期）、听力检查（纯音测听示传导性听力下降，有气骨导差，须记录程度；儿童可用行为测听，不配合者需客观听力检查）、腺样体（儿童：内镜或鼻咽侧位X线，判断腺样体肥大所致病因）；【其他】鼻咽镜（成人单侧者排查鼻咽癌，重要）、过敏原（过敏者，即变应性鼻炎）、腭裂（儿童评估）、中耳穿刺（诊断性穿刺抽液，用于诊断不明确者，诊断明确时一般不需）。","初步诊断":"1. 分泌性中耳炎（中耳积液，病程分型：急性/慢性（>3月）；儿童多因腺样体肥大，成人多因鼻咽部病变；单侧者须鼻咽癌排查；传导性听力下降30dB）\n（注：治疗原则为解除咽鼓管功能障碍加引流积液，依病因及病程选择：①观察及保守治疗，适用于急性/轻中度者（约50~80%可自愈，观察3个月，尤其儿童感冒后）：治疗诱因：鼻炎鼻窦炎予鼻用糖皮质激素（糠酸莫米松喷鼻，改善咽鼓管通气引流）、减充血剂（短期用羟甲唑啉，≤5天）、抗组胺药（过敏者）、咽鼓管功能锻炼（捏鼻鼓气即Valsalva动作；儿童可吹气球训练，促进咽鼓管开放）、治疗腺样体肥大；②手术，指征为慢性（>3个月）伴持续性听力下降（影响语言、学习，儿童尤为重要）、积液反复发作（>3次/6月）、保守治疗无效、鼓膜内陷有中耳黏连/胆脂瘤风险（慢性中耳负压致内陷袋，可发展为胆脂瘤，晚期危害大，重在预防）、成人病因处理后仍持续者：手术方式：鼓膜置管术（鼓膜切开加通气管，引流积液、平衡中耳压、改善听力，即时见效；通气管留置6~12个月，可自行脱落或取出）、腺样体切除（儿童腺样体肥大、反复分泌性中耳炎者，切除腺样体加置管，可减少复发，重要联合手术）；③随访：观察期每1~3个月复查声导抗/听力，观察积液消退与恢复；置管后注意通气管在位（留置6~12个月，防感染，耳勿进水，游泳戴耳塞）、脱管后观察鼓膜愈合与听力、监测复发；慢性反复者评估腺样体、腭裂、免疫因素；成人单侧者定期鼻咽镜检查排除肿瘤（重要，利于鼻咽癌早诊）；耳鼻喉科随诊：儿童关注学习与语言，成人单侧必查鼻咽，慢性者置管加腺样体处理，随访重要。）","处理方案":"【药物治疗】\n1. 鼻用糖皮质激素：糠酸莫米松鼻喷雾剂（内舒拿）每次每侧鼻孔2喷，每日1次，晨起使用，疗程4周，减轻鼻咽部及咽鼓管咽口黏膜水肿，促进咽鼓管开放引流。\n2. 黏液促排剂：桉柠蒎肠溶软胶囊（切诺）0.3g，每日3次，饭前半小时凉开水整粒吞服，疗程2周，稀释中耳及咽鼓管分泌物，促进排出。\n3. 抗菌药物：阿莫西林克拉维酸钾片0.457g，每日3次，口服7天，适用于急性期伴上呼吸道感染或脓性积液者；青霉素过敏者改用阿奇霉素胶囊0.5g，每日1次，口服5天。\n4. 咽鼓管功能训练：行捏鼻鼓气法（Valsalva法），每日3-5次，每次鼓气持续2-3秒后吞咽，配合鼓膜按摩，促进咽鼓管开放及中耳气体交换。\n\n【一般治疗及生活指导】\n1. 避免双侧同时用力擤鼻，应单侧交替轻擤，防止鼻咽部压力骤增将分泌物压入中耳腔。\n2. 积极预防上呼吸道感染，感冒流行季节减少出入人群密集场所；避免乘飞机、潜水、快速升降电梯等气压急剧变化环境。\n3. 戒烟并远离二手烟，减少粉尘及刺激性气体暴露；洗头、洗澡时防止污水入耳，保持外耳道干燥。\n4. 注意休息，避免熬夜劳累，保证充足睡眠，增强机体抵抗力；清淡饮食，忌辛辣刺激性食物。\n\n【随诊要求】\n1. 用药2-4周后复诊，复查耳内镜、纯音听阈及声导抗（鼓室图），评估中耳积液吸收及咽鼓管功能恢复情况，据情调整治疗方案。\n2. 保守治疗3个月症状无改善或鼓室积液持续存在者，应转诊耳鼻喉专科评估鼓膜穿刺抽液、鼓膜置管或咽鼓管球囊扩张术等进一步处理。\n3. 治疗期间如出现耳痛加重、耳流脓、发热等急性化脓性中耳炎表现，应及时复诊或急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":584,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3085dbc1115dea7fdcbd1d313f0e16c30be54b5d24cb9c6b8477a9ba8a3af313","pinyin":"fenmixingzhongeryan","initials":"fmxzey","setting":"out","caseName":"门诊病历449","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历449",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8a9bb2020bf20ffc80f6","key":"v1-c9ccc21dfe2a3058|templates-8a9bb2020bf20ffc80f6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"化脓性中耳炎","category":"门诊病历模板","raw":{"name":"化脓性中耳炎","category":"门诊病历模板","case":{"case_name":"门诊病历450","templates":{"主诉":"耳痛、耳流脓伴听力下降5天","现病史":"患者（儿童多见，因咽鼓管短平、上感后易发；成人多因鼻咽部感染/游泳进水）于3天前（上呼吸道感染后）出现耳深部疼痛（胀痛/跳痛，夜间加重）、耳闷、听力下降，继之发热（体温最高38.5℃），1天前鼓膜穿孔后耳流脓（开始为血性，后为黏脓性，量多）、耳痛减轻（穿孔引流后减压，为典型过程）、流脓持续2天，伴耳后红肿压痛（乳突炎，并发症）、无眩晕（无迷路炎）、无面瘫（无面神经受累）、无头痛发热加重（无颅内并发症如脑膜炎/脑脓肿，罕见但严重）、无耳周肿胀，感冒鼻塞流涕情况、有无反复发作中耳炎史及鼓膜穿孔史、耳内进水/掏耳史：无明确耳内进水及掏耳史。今日来我院耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.5℃，P96次/分，R20次/分，BP110/70mmHg。外耳道见脓性分泌物（清理后见鼓膜）、鼓膜充血膨隆、标志不清（急性期）；穿孔后见紧张部中央性穿孔（记录大小、位置）、搏动性溢脓（灯塔征，提示活动性感染）、残余鼓膜充血；乳突区压痛阳性（乳突炎警示，注意耳后红肿、脓肿）、听力：音叉/纯音检查示传导性听力下降、鼻咽部未见腺样体肥大（儿童）、颈部淋巴结未及肿大。","辅助检查":"【必做】耳内镜（清理脓液后详细检查鼓膜及外耳道）、听力检查（纯音测听，判断传导性听力下降程度）、脓液细菌培养加药敏（取引流物，明确病原，指导治疗调整）；【影像】颞骨CT（疑并发症如乳突炎/胆脂瘤/颅内病变、反复发作或治疗无效时，评估病变范围）；【其他】血常规（白细胞计数，评估感染）、鼻咽镜（检查腺样体/鼻咽，明确儿童病因）。","初步诊断":"1. 急性化脓性中耳炎（左耳，穿孔后引流期）\n（注：治疗以抗感染为主：①抗生素（核心，须覆盖肺炎链球菌、流感嗜血杆菌、卡他莫拉菌：阿莫西林克拉维酸（儿童按体重给药；成人0.625g tid）或头孢类，疗程7~10天，穿孔流脓者需足疗程，以防并发症）；②局部：清理耳道脓液（吸引或棉签，保持引流通畅，关键）、抗生素滴耳液（穿孔后可用左氧氟沙星滴耳液（耳用喹诺酮，安全性好）滴耳，疗程7~10天）；③对症：解热镇痛（布洛芬/对乙酰氨基酚，退热止痛）、鼻用减充血剂（羟甲唑啉，改善咽鼓管引流，儿童≤5天）；④鼓膜切开（鼓膜膨隆剧痛或引流不畅者，切开引流、减压）；⑤并发症处理（乳突炎：耳后红肿压痛，予静脉抗生素加乳突切开引流术；面瘫/眩晕/颅内症状者急诊住院，由耳神经外科处理）；⑥随访：治疗后复查，观察鼓膜愈合（穿孔多自行愈合，4~6周）与听力恢复；穿孔不愈者按慢性中耳炎处理，评估手术修补；⑦预防复发：治疗鼻窦炎/腺样体肥大、正确擤鼻、避免耳内进水、接种肺炎球菌疫苗；儿童反复发作者转耳鼻喉专科评估（鼓膜置管，用于分泌性/反复感染）。）","处理方案":"【药物治疗】\n1. 抗菌药物：首选青霉素类，阿莫西林胶囊0.5g tid（每8小时1次）×7天；青霉素过敏者改用大环内酯类，阿奇霉素片0.5g qd×3天，或头孢呋辛酯片0.25g bid×7天（头孢过敏者禁用）。用药期间若耳痛加重或持续发热需及时复诊调整。\n2. 局部滴耳：0.3%氧氟沙星滴耳液，每次6-10滴，tid，滴药前先以3%过氧化氢溶液清洗外耳道脓液并擦干，滴药后患耳向上侧卧10分钟，疗程7-10天；鼓膜穿孔流脓明显者，滴耳液需经体温加温至接近体温后再滴，以免刺激内耳引起眩晕。\n3. 改善咽鼓管引流：1%麻黄碱滴鼻液（或盐酸羟甲唑啉鼻喷剂）双侧鼻腔各1-2滴（喷），tid，连用不超过7天，以减轻咽鼓管口黏膜肿胀、利于中耳引流。\n4. 对症止痛：鼓膜穿孔前耳痛剧烈者，予布洛芬缓释胶囊0.3g bid×3天口服止痛；发热时根据患者具体情况制定个体化方案物理降温，必要时加用解热镇痛药。\n\n【一般治疗及生活指导】\n1. 保持外耳道干燥清洁：洗头、洗澡、游泳时用干棉球或专用耳塞堵塞外耳道，避免污水入耳；禁止自行挖耳掏脓或频繁清理外耳道，以免加重感染或损伤鼓膜。\n2. 正确擤鼻及用药：擤鼻时一侧一侧交替进行，切勿捏住双侧鼻孔用力擤，避免将鼻腔分泌物经咽鼓管压入中耳；滴鼻、滴耳药严格按说明操作，滴耳后保持患耳向上体位至少10分钟。\n3. 注意休息与饮食：急性期适当休息、保证睡眠，避免熬夜、劳累及剧烈运动；清淡饮食，忌辛辣刺激性食物、戒烟戒酒，多饮水。\n4. 避免气压骤变环境：近期避免乘坐飞机、潜水、快速升降电梯等气压骤变场合，防止鼓膜损伤和中耳压力骤变加重病情；积极治疗感冒、鼻炎、鼻窦炎、扁桃体炎等上呼吸道感染诱因。\n\n【随诊要求】\n1. 用药后3-5天复诊，评估耳痛、耳流脓、听力及全身症状改善情况，必要时调整抗生素方案。\n2. 完成疗程后复查耳内镜（耳镜）检查，确认外耳道、鼓膜及中耳黏膜恢复情况；若鼓膜穿孔持续不愈或流脓超过2周，转耳鼻喉专科进一步检查（纯音测听、声导抗、颞骨CT等），评估是否需鼓膜修补及排除中耳胆脂瘤等并发症。\n3. 治疗期间如出现耳后红肿压痛、乳突区压痛、剧烈头痛、眩晕、恶心呕吐、面瘫或高热不退等，提示可能并发急性乳突炎或颅内并发症，应立即就医急诊处理，不可延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":585,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ad2ae9b6407e865d55801b3cd8c2d9b71b660dd6eb6c9a1a5fe0d3c51ca67803","pinyin":"huanongxingzhongeryan","initials":"hnxzey","setting":"out","caseName":"门诊病历450","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历450",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6503f9ce5fcb7ffb6024","key":"v1-c9ccc21dfe2a3058|templates-6503f9ce5fcb7ffb6024","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"乳突炎","category":"门诊病历模板","raw":{"name":"乳突炎","category":"门诊病历模板","case":{"case_name":"门诊病历451","templates":{"主诉":"耳后红肿疼痛伴发热5天","现病史":"患者（急性化脓性中耳炎治疗不当或引流不畅，儿童多见）于中耳炎后5天出现耳后红肿、疼痛（乳突区胀痛，进行性加重）、耳廓向前外耸立（耳后脓肿即骨膜下脓肿的特征体征）、发热（体温最高39.2℃，持续或复发）、耳流脓增多，伴面瘫（面神经管受累）、无眩晕恶心（无迷路炎、无内耳受累）、无头痛呕吐嗜睡（无颅内并发症如乙状窦血栓/脑膜炎/脑脓肿；该组症状最严重，出现意识改变需急诊）、耳后波动感（提示脓肿形成），中耳炎治疗史（抗生素未足量）：曾口服抗生素3天，未足疗程。今日来我院急诊耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T39.2℃，P104次/分，R22次/分，BP112/70mmHg。耳后乳突区红肿、压痛（++）、波动感阳性（骨膜下脓肿）、耳廓向前外耸立（移位）、外耳道及鼓膜见脓性分泌物（鼓膜穿孔，引流通畅）、听力传导性下降、颈部淋巴结肿大、无颈强直（无脑膜刺激征，未提示颅内感染）、神经系统：左侧面瘫（示齿口角歪斜）、意识清楚（颅内并发症筛查未见异常）。","辅助检查":"【必做】血常规（白细胞显著升高）、CRP、血培养（发热明显者，评估脓毒症）；【影像】颞骨CT（首选，可见乳突气房模糊/骨质破坏（融合性乳突炎）、骨膜下脓肿、乙状窦周围脓肿及颅内并发症，评估关键）；【影像】头颅MRI+MRV（疑颅内并发症如乙状窦血栓/脑膜炎/脑脓肿者，增强扫描）；【其他】脓液培养（耳道或手术取材）、腰椎穿刺（疑脑膜炎者，查脑脊液）。","初步诊断":"1. 急性乳突炎（左，融合性乳突炎伴骨膜下脓肿；并发症为周围性面瘫）\n（注：急性乳突炎为中耳炎的严重并发症，可致颅内感染、危及生命，需急诊住院治疗：①静脉广谱抗生素（立即使用，须覆盖肺炎链球菌、金葡菌（考虑MRSA）、流感嗜血杆菌、厌氧菌：头孢曲松加万古霉素，必要时加甲硝唑；疗程2~3患者脉用药，继以口服）；②手术（核心：融合性乳突炎/脓肿者急诊行乳突切开术，开放引流乳突气房、清除病变；骨膜下脓肿者切开引流；反复或慢性者行乳突根治术）；③并发症处理（面瘫：激素加抗生素，并行手术减压（乳突开放）；迷路炎：眩晕者予抗生素加前庭抑制剂，防止并发脑膜炎；乙状窦血栓：抗凝（低分子肝素→华法林）加抗生素；脑膜炎/脑脓肿：神经外科加ICU处理，腰穿/开颅引流，多学科协作）；④对症（退热、镇痛、补液）；⑤随访（术后完成抗感染疗程，复查听力，观察鼓膜及乳突愈合，防慢性化）；儿童中耳炎应规范治疗以预防（足疗程抗生素，重要，防进展为乳突炎）；耳鼻喉科联合神经科多学科急诊处理，勿延误。）","处理方案":"【药物治疗】\n1. 阿莫西林克拉维酸钾片（0.625g）1片 po bid×7天（首选覆盖肺炎链球菌、流感嗜血杆菌及产酶金葡菌；青霉素过敏者改用头孢呋辛酯片0.25g bid或克拉霉素片0.5g bid）\n2. 桉柠蒎肠溶软胶囊0.3g po tid×7天（促进中耳及乳突气房分泌物引流，利于炎症消退）\n3. 有耳漏者：3%过氧化氢溶液清洗外耳道后，氧氟沙星滴耳液3～5滴滴耳 tid×7天；耳痛明显时加布洛芬缓释胶囊0.3g po bid（按需，疗程≤5天）\n\n【一般治疗及生活指导】\n1. 保持鼻腔通畅、改善咽鼓管引流：呋麻滴鼻液滴鼻2滴 tid×5天；避免用力擤鼻，应单侧交替擤鼻，防止感染经咽鼓管逆行扩散\n2. 注意休息，避免劳累熬夜，清淡饮食、多饮水，戒烟酒；洗头洗澡时用棉球塞耳，保持外耳道干燥，禁止游泳及耳内进水\n3. 耳后红肿区可温热敷，每次15～20分钟、每日2～3次，促进炎症吸收；勿按压、搔抓或自行清理耳内分泌物，以免损伤鼓膜\n\n【随诊要求】\n用药3～5天复诊复查耳内镜，评估耳痛、耳后红肿及耳漏变化，必要时调整抗菌药物；抗生素足疗程（7～10天）后复查。若治疗48小时症状无缓解，或出现持续高热、耳后红肿疼痛加剧、剧烈头痛、恶心呕吐、意识改变等颅内并发症征象，需立即到耳鼻喉科或急诊就诊；反复发作者建议行颞骨CT检查明确有无骨质破坏及胆脂瘤形成，必要时转专科手术治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":586,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f26501666faef5809dc0e101a440475ed1451585f8642a8f6918451b88c4aef9","pinyin":"rutuyan","initials":"rty","setting":"out","caseName":"门诊病历451","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历451",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d8bd4e663dce1f14017b","key":"v1-c9ccc21dfe2a3058|templates-d8bd4e663dce1f14017b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"耳硬化症","category":"门诊病历模板","raw":{"name":"耳硬化症","category":"门诊病历模板","case":{"case_name":"门诊病历452","templates":{"主诉":"进行性听力下降伴耳鸣5年","现病史":"患者（青年，20~40岁起病，女性多见，白种人高发，我国较少）于5年前开始进行性听力下降（传导性聋，早期低频听力下降，听人说话听得到听不清，骨导好气导差；在嘈杂环境中听力反而改善，即Willis误听，为特征性表现，提示非耳蜗性；渐进加重并累及高频）、伴耳鸣（持续性嗡嗡声），无眩晕（耳硬化累及内耳即耳蜗性耳硬化时可有眩晕，呈混合性聋，晚期出现）、妊娠/哺乳期加重（女性受激素影响，常见）、家族史（常染色体显性遗传，约50%有家族史，支持诊断）、无外伤/噪声史（已排除）、无鼓膜及中耳手术史，佩戴助听器尝试及效果：佩戴助听器后交流改善。今日来我院耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP118/76mmHg。外耳道及鼓膜正常（完整、标志清，重要：传导性聋而鼓膜正常提示耳硬化或听骨链问题；Schwartz征为鼓膜后下方透见粉红色，提示活动期病灶充血）、音叉试验（Rinne：骨导>气导，即阴性，提示传导性聋；Weber：偏向患侧，传导性聋表现）、纯音测听（气骨导差，为传导性聋的特征）、声导抗（鼓室图正常即A型，但镫骨肌反射消失，为耳硬化特征，提示听骨链固定）。","辅助检查":"【必做】纯音测听（气导/骨导，示传导性聋及气骨导差即空气骨导间距，判断程度并随访）、声导抗（镫骨肌反射消失、鼓室图正常，支持镫骨固定）；【影像】颞骨高分辨率CT（可见镫骨底板增厚/前庭窗狭窄、耳蜗周围低密度（耳蜗性耳硬化，内耳CT），并排除其他中耳病变，为重要鉴别手段，如听骨链畸形/慢性中耳炎后遗）；【鉴别】鼓膜正常伴传导性聋者需鉴别（耳硬化/听骨链固定/畸形，依靠CT及手术探查）。","初步诊断":"1. 耳硬化症（左耳，镫骨性，传导性聋中度）\n（注：治疗根据听力程度及患者需求，有两种选择：①助听器（不愿手术/轻度/对侧耳者，气导助听器改善听力，无创，为选择之一）；②手术（镫骨手术：镫骨足板小孔技术/镫骨置换术（活塞，人工镫骨），为根治核心，可恢复听力（成功率90%以上，气骨导差明显缩小）；风险包括感音神经性聋（内耳损伤约1%，罕见但剧烈眩晕/耳鸣需警惕；术后即现重度感音神经性聋者，立即予激素/高压氧处理，属手术并发症）、面神经损伤（罕见，解剖异常时）、鼓膜穿孔、眩晕（多短暂）、味觉改变（鼓索神经牵拉，多可恢复））；③氟化钠（用于耳蜗性耳硬化，延缓进展，证据有限，不常规推荐）；④随访（术后1~2个月听力稳定，复查纯音测听评价；远期双侧者对侧手术时机与助听器/手术选择；耳鸣部分术后改善）；耳鼻喉科专科处理，手术需有经验的耳科医生，与患者充分沟通手术预期及风险。）","处理方案":"【药物治疗】\n1. 氟化钠片（Sodium Fluoride）25mg po tid，疗程3～6个月（活动期/耳海绵化期），抑制镫骨足板及耳蜗周围海绵化病变进展；用药期间每3个月监测血氟、尿氟，出现关节痛、恶心、食欲减退等氟中毒表现即停药。\n2. 碳酸钙D3片（钙尔奇D）600mg po qd，与氟化钠联用维持钙磷代谢平衡，减轻长期服氟对骨代谢的影响。\n3. 合并眩晕者：甲磺酸倍他司汀片（敏使朗）6mg po tid，疗程14天，改善内耳微循环、缓解眩晕。\n4. 合并耳鸣明显者：银杏叶提取物片（金纳多）40mg po tid，疗程1个月，改善耳蜗血供。\n\n【一般治疗及生活指导】\n1. 避免噪声暴露：远离强声环境、避免长时间佩戴耳机，必要时佩戴防噪耳塞，防止噪声叠加损害残余听力。\n2. 禁用耳毒性药物：避免氨基糖苷类抗生素、袢利尿剂（呋塞米）、大剂量水杨酸类（阿司匹林）及奎宁等，戒烟限酒。\n3. 均衡饮食，适量补充钙质及维生素D：多食牛奶、豆制品、绿叶蔬菜，适当户外日晒；育龄期女性注意妊娠可能加重听力下降，备孕前应评估听力状况。\n4. 避免剧烈运动、头部快速晃动及用力擤鼻、憋气等动作，防止眩晕发作及跌倒致头部外伤。\n\n【随诊要求】\n1. 每3～6个月门诊复查纯音测听及声导抗（鼓室导抗图），动态评估听力曲线及镫骨活动度变化。\n2. 服用氟化钠期间每3个月复查血氟、尿氟，出现氟斑牙、关节疼痛、消化道症状等及时停药复诊。\n3. 若出现听力进行性下降（较前下降≥10dB）、眩晕反复发作或耳鸣明显加重，随时复诊。\n4. 听力损失达中度及以上者，建议行助听器验配评估；符合手术适应证者转诊耳外科，评估镫骨手术（镫骨足板切除术/人工镫骨植入术）治疗时机。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":587,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b14ee499ddeb43b206019e9670d360803b5a02736719b09629bc7f9947d7e200","pinyin":"eryinghuazheng","initials":"eyhz","setting":"out","caseName":"门诊病历452","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历452",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6960f4faef21257888bb","key":"v1-c9ccc21dfe2a3058|templates-6960f4faef21257888bb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"良性阵发性位置性眩晕","category":"门诊病历模板","raw":{"name":"良性阵发性位置性眩晕","category":"门诊病历模板","case":{"case_name":"门诊病历453","templates":{"主诉":"体位变动诱发旋转性眩晕伴恶心3天","现病史":"患者于3天前开始（晨起起床或夜间翻身时突发）旋转性眩晕（视物旋转、天旋地转，持续数秒至<1分钟，通常<60秒，体位变动诱发、保持头位静止后缓解）、伴恶心呕吐（剧烈，为自主神经症状）、心慌出汗，无耳鸣/听力下降（无，可与梅尼埃病区别，重要）、无头痛、无肢体无力言语不清（无，排除中枢性眩晕，如后循环缺血/小脑病变所致中枢性位置性眩晕，需鉴别）、无头外伤/颈椎病/近期卧床/病毒感染/内耳手术（未找到耳石脱落诱因），眩晕后头晕不适可持续数小时（残余感，但旋转感短暂，为特征），反复发作（每日多次，体位触发），平卧及行走正常（发作间期无症状）。今日来我院耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P76次/分，R18次/分，BP120/78mmHg。神经系统正常：发作间期无眼震、无共济失调、听力粗测无下降、Romberg征稳定（排除中枢病变）；体位试验（关键，可确诊）：Dix-Hallpike试验（检查后半规管/前半规管：患者坐位头转45°，快速仰卧头悬垂30°，观察眼震（潜伏期数秒，旋转性眼震，向上向地，提示后管，持续<1分钟，具疲劳性即重复后减弱，为典型表现），可诱发眩晕及眼震，阳性即可诊断）；滚转试验（检查水平半规管：仰卧头转向两侧，观察水平眼震（向地/离地），提示水平管耳石）。","辅助检查":"【必做】Dix-Hallpike试验/滚转试验（位置试验，可确诊并定侧，明确受累半规管，为核心检查）；【鉴别影像】头颅MRI/CT（用于症状不典型者：眼震持续、垂直向下、无疲劳性，或伴中枢体征（共济失调、构音障碍、复视），疑中枢性位置性眩晕（小脑/脑干病变，血管性或肿瘤）时；位置试验眼震不符合外周特征（持续>1分钟、方向改变、纯垂直性、不疲劳）者需影像排除，重要）；【其他】纯音测听（听力正常，可排除梅尼埃病，但需基线值）、前庭功能（复位后评估，必要时）。","初步诊断":"1. 良性阵发性位置性眩晕（右后半规管耳石症）\n（注：治疗以耳石复位为核心，多数一次即愈，成功率高：①耳石复位（根据受累半规管选择：后半规管用Epley手法（CRP，经典复位，步骤为坐位→向患侧转45°仰卧头悬垂→转头对侧→继续转身侧卧→坐起，每步停留30~60秒至眼震消失）；水平半规管用Barbecue翻滚/Gufoni手法）；②复位后指导（复位后24~48小时避免剧烈头动、仰头（理发洗头暂缓），高枕卧位（睡眠时头抬高30~45°），以防耳石再移位，1周内避免患侧卧位）；③药物（辅助：复位前后恶心眩晕重者，予前庭抑制剂（茶苯海明/倍他司汀），短期使用，不替代复位）；④复发（常见，约50%，复发后再复位效果仍好；复位后残余头晕可持续数天~数周，与耳石碎片/前庭适应有关，可自行缓解，辅以前庭康复训练）；⑤家庭复位（复发且不能及时就医者，教会Epley自复位，谨慎指导）；⑥预防（避免快速转头/长时间低头、防头部外伤、治疗颈椎病）；耳鼻喉科/神经科门诊随诊，复位操作专业，多数预后极好（自限但易复发，复位可立即缓解）。）","处理方案":"【药物治疗】\n1. 前庭抑制剂（急性发作期剧烈眩晕时短期使用）：苯海拉明片25mg po，发作时临时服用，每日不超过3次，连用不超过3天。\n2. 改善内耳微循环：甲磺酸倍他司汀片6mg po tid×7天。\n3. 中枢性止晕药：盐酸氟桂利嗪胶囊5mg po qn×7天，老年人根据患者具体情况制定个体化方案减量至2.5mg qn，嗜睡者慎用。\n4. 降低复发风险（伴维生素D缺乏或骨量减少者）：维生素D3滴剂400-800IU po qd，碳酸钙D3片0.6g po qd，长期服用并定期复查。\n\n【一般治疗及生活指导】\n1. 尽快行耳石复位治疗（Epley手法或管石复位术），复位后48小时内保持头部相对固定，避免剧烈转头、低头仰头，睡眠时垫高枕头或取半卧位。\n2. 急性期卧床休息，避免快速转身、弯腰捡物、猛然起身等动作；缓解期动作宜缓慢，逐步恢复日常活动。\n3. 低盐清淡饮食，戒烟限酒，避免浓茶、咖啡等刺激性饮品。\n4. 眩晕未完全缓解期间禁忌驾车、高空作业、操作机械设备及游泳，避免独自上下楼梯。\n\n【随诊要求】\n1. 耳石复位后3-7天复诊，评估复位效果及残余头昏症状，必要时再次行耳石复位。\n2. 若复位后眩晕反复发作或持续加重，2周内复诊，行前庭功能检查及头颅MRI排除中枢性病变。\n3. 出现新发听力下降、耳鸣加重或言语不清、肢体无力、复视等神经系统症状时，立即就诊。\n4. 曾有复发史或复位后症状反复者，建议定期门诊随访（每3-6个月），监测复发并及时干预。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":588,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"91a544757d28b12298490fc061fc987b501d9d3b28953428fd7cbc607a19f1ba","pinyin":"liangxingzhenfaxingweizhixingxuanyun","initials":"lxzfxwzxxy","setting":"out","caseName":"门诊病历453","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历453",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-814c845e50c3004a6625","key":"v1-c9ccc21dfe2a3058|templates-814c845e50c3004a6625","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"前庭神经炎","category":"门诊病历模板","raw":{"name":"前庭神经炎","category":"门诊病历模板","case":{"case_name":"门诊病历454","templates":{"主诉":"突发旋转性眩晕伴恶心呕吐3天","现病史":"患者为青中年，多于病毒感染后（上呼吸道感染/感冒后1~2周，前庭神经炎为病毒性炎症，前庭上神经多见）于3天前突发剧烈旋转性眩晕（持续，非体位性，不因静止缓解，与耳石症区别）、恶心呕吐（剧烈，持续数小时至数天，渐减轻）、平衡障碍（行走不稳，向患侧倾倒）、心慌出汗，无听力下降/耳鸣（无，为关键鉴别点，可与梅尼埃病及迷路炎区别，提示前庭神经炎为纯前庭受累）、无耳痛流脓（无，排除中耳炎/迷路炎）、无头痛/复视/肢体无力/言语不清（无，排除中枢性眩晕如脑干小脑卒中（后循环），需警惕，尤其老年/有血管病危险因素者）、无意识改变，数天后眩晕渐减，遗留残余平衡不稳/头晕（可持续数周~数月，为前庭代偿过程）。今日来我院耳鼻喉科/神经科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P88次/分，R18次/分，BP124/80mmHg。自发性眼震（向健侧，水平旋转性，快相向健侧，为前庭神经炎特征）、Romberg征（向患侧倾倒，闭眼加重）、原地踏步试验（偏向患侧）、甩头试验（头脉冲试验：向患侧快速转头时出现矫正性扫视，提示患侧前庭眼反射减弱，为重要体征）、听力粗测正常、神经系统无中枢体征（共济、构音、复视均正常，排除卒中）、耳部正常（无中耳炎）。","辅助检查":"【必做】床旁前庭检查（眼震观察、甩头试验，为诊断核心，可发现单侧前庭功能减退证据）；【听力】纯音测听（正常，用于排除梅尼埃/迷路炎，为诊断必需）；【影像】头颅MRI（疑中枢性者：老年、有血管病危险因素、有中枢体征、眼震不典型（纯垂直、持续>数天不缓解），用于排除脑干小脑卒中/肿瘤，重要）；【其他】前庭功能检查（冷热试验：患侧反应减弱，可确诊，急性期后可做）、前庭诱发肌源电位（用于受累神经定位，必要时）。","初步诊断":"1. 前庭神经炎（左，前庭上神经炎）\n（注：治疗：①急性期剧烈眩晕者予前庭抑制剂短期使用（不超过3天，过度使用会延迟前庭代偿，重要）：茶苯海明50mg q6h或苯海拉明/地西泮；止吐用甲氧氯普胺/昂丹司琼；②糖皮质激素（急性期用甲泼尼龙，可改善恢复（证据支持，减轻神经炎症），发病72小时内开始，疗程渐减）；③前庭康复训练（核心，恢复期即眩晕减轻后开始：Brandt-Daroff习服/前庭适应训练、凝视稳定与平衡训练，促进中枢代偿、缩短病程，为关键治疗）；④对症（补液（呕吐脱水者）、休息（急性期避免驾车/高空作业）、防跌倒）；⑤病因处理（病毒感染多为自限性，不常规抗病毒；若为细菌性迷路炎（中耳炎伴耳流脓、眩晕）则予抗生素加耳科处理，注意鉴别）；⑥随访（眩晕多数数天~数周渐缓解（严重者可数周）；平衡不稳的前庭代偿需数周~数月，老年代偿慢，需坚持康复训练；复发少见，前庭神经炎多单次发作，反复眩晕者需重新评估其他病因）；耳鼻喉/神经科随诊，区分中枢性（卒中）是关键（注意时间窗，及时溶栓/取栓）。）","处理方案":"【药物治疗】\n1.糖皮质激素（首选、核心治疗）：甲泼尼龙片（美卓乐）32mg 每日晨起顿服，连用3天后每3天减量（24mg→16mg→8mg），总疗程约2周；或醋酸泼尼松片1mg/kg/d 晨顿服，每3～5天减量，2～3周内逐渐停用。用药前排除活动性感染、消化性溃疡、血糖控制不佳的糖尿病、严重高血压等禁忌，用药期间监测血糖、血压。\n2.前庭抑制剂（仅急性期眩晕呕吐剧烈时短期使用，总疗程不超过72小时，症状缓解即停，以免延迟前庭代偿）：茶苯海明片（晕海宁）25～50mg 口服 tid；或盐酸苯海拉明片25mg 口服 bid～tid；呕吐不能口服时可予盐酸异丙嗪25mg 肌注 st。\n3.止吐药：甲氧氯普胺片10mg 口服 tid 或昂丹司琼片8mg 口服 bid，用于恶心呕吐明显者（与异丙嗪二选一，避免镇静作用叠加）。\n4.辅助治疗：甲钴胺片0.5mg 口服 tid×2周营养神经；甲磺酸倍他司汀片6mg 口服 tid×2周（急性期后配合患者，促进前庭功能恢复）。\n【一般治疗及生活指导】\n1.休息：急性期卧床休息，保持环境安静、光线柔和，避免快速转头、猛然起身及剧烈体位变动；呕吐明显时注意补水，必要时静脉补液维持水电解质平衡。\n2.饮食：清淡易消化饮食，少食多餐，避免油腻、辛辣刺激性食物，忌咖啡、浓茶及酒精。\n3.活动与康复：眩晕减轻后（一般发病1周内）尽早开始前庭康复训练（如Cawthorne-Cooksey眼动、头部转动及体位平衡训练），每日2～3次、每次10～15分钟，循序渐进，促进前庭代偿、缩短病程；恢复期避免驾车、操作机械、登高及游泳，防止跌倒。\n4.禁忌：发病及恢复期避免乘坐颠簸交通工具、长时间注视手机或快速移动画面；激素治疗期间监测血压血糖，注意有无黑便、呕血等消化道出血征象。\n【随诊要求】\n1.治疗3～5天复诊，评估眩晕、平衡功能改善情况及药物耐受性；若眩晕持续超过1周不缓解或进行性加重，或出现耳鸣、听力下降、耳闷胀感、剧烈头痛、发热、肢体无力、言语不清等新发症状，立即复诊或急诊就诊。\n2.激素减量期间遵医嘱随访，监测血压、血糖；疗程结束后1～2周复诊，行位置试验、纯音测听等评估前庭及听力功能，必要时转诊耳鼻喉科或神经内科进一步诊治。\n3.症状缓解后如遗留慢性头晕、行走不稳感，门诊随访接受前庭康复指导，多数患者3～6个月内恢复；少数遗留持续性失衡者需长期随访并评估跌倒风险。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":589,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1a43433da468a14d493f704bfe09cf508c8bf875ae63a360f2ce3f88ad396fe5","pinyin":"qiantingshenjingyan","initials":"qtsjy","setting":"out","caseName":"门诊病历454","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历454",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-88b0b90e7b89246ff895","key":"v1-c9ccc21dfe2a3058|templates-88b0b90e7b89246ff895","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"噪声性耳聋","category":"门诊病历模板","raw":{"name":"噪声性耳聋","category":"门诊病历模板","case":{"case_name":"门诊病历455","templates":{"主诉":"听力下降伴耳鸣1周","现病史":"患者1周前无明显诱因出现噪声性耳聋相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以听力下降伴耳鸣1周为主诉就诊，症状逐渐加重并伴轻度乏力，首先完善耳镜检查明确外耳道及鼓膜有无异常，排除耵聍栓塞、鼓膜穿孔等传导性听力下降因素；完善纯音测听明确听力下降的程度与类型，典型表现为双侧高频听力损失，为噪声性耳聋的诊断提供客观依据；完善声导抗了解中耳功能状态，鉴别中耳病变所致传导性耳聋，必要时完善前庭功能检查排除前庭系统受累；完善血常规排除感染、贫血所致耳鸣及听力下降，完善鼻内镜检查排除鼻咽部病变所致咽鼓管功能障碍，完善喉镜检查排除咽喉部病变；完善颞骨CT明确内耳及中耳结构有无异常，必要时完善头颅MRI明确桥小脑角及听神经有无占位性病变，鉴别听神经瘤所致单侧听力下降；完善鼻窦CT排除鼻窦病变所致耳部牵涉症状，完善颈部超声了解颈部血管及淋巴结情况；完善心电图排除心律失常及心肌缺血，必要时完善经颅多普勒了解椎基底动脉供血情况；同时建议完善职业噪声暴露史采集及佩戴防护用品，定期复查纯音测听评估听力变化，必要时请耳鼻喉科及职业病科会诊协助诊断。\n\n（检查清单）\n【必做检查】\n血常规、耳镜检查、鼻内镜检查、喉镜检查\n\n【影像学检查】\n鼻窦CT、颞骨CT、颈部超声\n\n【其他检查】\n纯音测听、声导抗、前庭功能检查","初步诊断":"1. 噪声性耳聋\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 改善内耳微循环：银杏叶提取物片（金纳多）40mg，口服，每日3次，疗程4周。\n2. 营养神经：甲钴胺片0.5mg，口服，每日3次，疗程4周；可联合维生素B1片10mg，口服，每日3次。\n3. 抗氧化及代谢促进：维生素E软胶囊100mg，口服，每日2次，疗程4周；可联合辅酶Q10胶囊10mg，口服，每日3次。\n4. 若为急性声损伤（如爆震性聋、突发性听力下降72小时内），可短期患者糖皮质激素：醋酸泼尼松片1mg/kg/d，晨起顿服，连用5天后逐日递减（每日减量5mg），总疗程不超过10天，用药期间监测血糖、血压。\n【一般治疗及生活指导】\n1. 立即脱离噪声环境：避免接触85dB以上强噪声，工作或必要接触时佩戴防噪耳塞/耳罩（降噪值SNR≥20dB），坚持规范佩戴。\n2. 合理用耳：减少耳机使用时间，音量控制在最大音量的60%以内，每次连续佩戴不超过60分钟，避免在嘈杂环境中使用耳机。\n3. 规律作息，保证充足睡眠，避免熬夜及精神紧张、焦虑；戒烟限酒，清淡低盐低脂饮食。\n4. 避免使用耳毒性药物（如氨基糖苷类抗生素、袢利尿剂、顺铂等），如确需用药医师耳聋病史。\n【随诊要求】\n1. 用药4周后复诊，复查纯音听阈测听及声导抗，对比治疗前后听力阈值变化，评估疗效并调整用药。\n2. 建议每6~12个月复查纯音听力1次，动态监测听力波动及进展。\n3. 治疗期间若出现耳鸣明显加重、突发听力骤降或伴眩晕、耳闷胀感，应立即就诊耳鼻喉科。\n4. 从事噪声作业者应按国家规定每年进行职业健康检查（纯音听力检查），必要时完善职业病诊断及听力伤残鉴定。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":590,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"888ac021eb44924f8d2a43924ca8fb0b86def814db3c357f6db55b1b9ca3f034","pinyin":"zaoshengxingerlong","initials":"zsxel","setting":"out","caseName":"门诊病历455","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历455",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d091d1e6317431ee718f","key":"v1-c9ccc21dfe2a3058|templates-d091d1e6317431ee718f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"药物性耳聋","category":"门诊病历模板","raw":{"name":"药物性耳聋","category":"门诊病历模板","case":{"case_name":"门诊病历456","templates":{"主诉":"用药后听力下降1周","现病史":"患者1周前无明显诱因出现药物性耳聋相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以用药后听力下降1周为主诉就诊，症状逐渐加重并伴轻度乏力，首先详细追问耳毒性药物用药史，完善耳镜检查明确外耳道及鼓膜有无异常，排除耵聍栓塞及中耳病变所致听力下降；完善纯音测听明确听力下降程度与类型，典型表现为双侧对称性感音神经性听力损失，为药物性耳聋的诊断及分级提供依据；完善声导抗了解中耳功能状态，必要时完善前庭功能检查排除耳毒性药物所致前庭功能损害，完善耳声发射了解耳蜗外毛细胞功能；完善血常规排除感染、贫血所致听力下降，完善肝肾功能评估肝肾代谢功能，为停用或调整耳毒性药物提供依据，查血糖、血脂、电解质了解有无代谢异常及电解质紊乱；完善颞骨CT明确内耳及中耳结构有无异常，完善鼻窦CT排除鼻窦炎等鼻部病变所致耳部牵涉症状，必要时完善头颅MRI明确桥小脑角及听神经有无占位性病变，鉴别听神经瘤等所致听力下降；完善鼻内镜检查排除鼻咽部病变所致咽鼓管功能障碍，完善喉镜检查排除咽喉部病变，完善颈部超声了解颈部血管及淋巴结有无异常；完善心电图与胸部X线片评估心肺基础情况；建议立即停用可疑耳毒性药物，避免使用氨基糖苷类等耳毒性药物，定期复查纯音测听评估听力恢复情况，必要时请耳鼻喉科与临床药学室会诊协助诊治。\n\n（检查清单）\n【必做检查】\n血常规、耳镜检查、鼻内镜检查、喉镜检查\n\n【影像学检查】\n鼻窦CT、颞骨CT、颈部超声\n\n【其他检查】\n纯音测听、声导抗、前庭功能检查","初步诊断":"1. 药物性耳聋\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 立即停用并终身避免耳毒性药物（氨基糖苷类抗生素、袢利尿剂、铂类抗肿瘤药、万古霉素、水杨酸类等），此为治疗前提；确需抗感染时改用无耳毒性药物。\n2. 神经营养药：甲钴胺片0.5mg，口服，每日3次，连用4周。\n3. 改善内耳微循环药：银杏叶提取物片（金纳多）40mg，口服，每日3次，连用4周；或甲磺酸倍他司汀片6mg，口服，每日3次，连用4周。\n4. 急性期（停药后2周内）短期糖皮质激素：醋酸泼尼松片30mg，晨起顿服，每日1次，连用7天后每3天减5mg直至停用，总疗程不超过2周（用药期间监测血压、血糖，有高血压、糖尿病者慎用并相应调整）。\n\n【一般治疗及生活指导】\n1. 休息：保证充足睡眠，避免劳累、熬夜及精神紧张；急性期适当卧床休息，避免剧烈运动和噪声刺激。\n2. 环境：远离噪声环境，避免长时间佩戴耳机，保持居住环境安静，保护残余听力。\n3. 饮食：低盐清淡饮食，多饮水，忌浓茶、咖啡及酒精，戒烟。\n4. 禁忌：禁用一切耳毒性药物；日后就医时务必主动告知既往药物性耳聋病史，避免再次使用同类药物；不自行购买服用任何抗生素及利尿剂。\n\n【随诊要求】\n1. 停药及治疗后1~2周复查纯音测听、声导抗及耳声发射，评估听力恢复情况。\n2. 治疗期间听力进行性下降，或出现眩晕、耳鸣明显加重者，随时复诊或转耳鼻喉科住院进一步诊治。\n3. 使用糖皮质激素者监测血压、血糖；疗程结束后1个月再复查听力，评估远期恢复，必要时行助听器或人工耳蜗评估。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":591,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2f48352b2ed12ba8c9efaba7223f1422d998b97b343b0d207c1c32305a38ab27","pinyin":"yaowuxingerlong","initials":"ywxel","setting":"out","caseName":"门诊病历456","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历456",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b037d1868d7637adb67a","key":"v1-c9ccc21dfe2a3058|templates-b037d1868d7637adb67a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"老年性耳聋","category":"门诊病历模板","raw":{"name":"老年性耳聋","category":"门诊病历模板","case":{"case_name":"门诊病历457","templates":{"主诉":"双耳听力下降1周","现病史":"患者1周前无明显诱因出现老年性耳聋相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者双耳听力下降1周，无明显诱因且逐渐加重，完善纯音测听检查明确听力损失程度与类型，为老年性耳聋的诊断与助听器验配提供依据；查声导抗检查了解中耳传音功能、排除中耳积液等传导性因素；患者双耳听力下降虽考虑老年性聋，仍需完善耳镜检查了解外耳道及鼓膜情况、排除耵聍栓塞与鼓膜穿孔所致听力下降；患者发病以来伴轻度乏力，完善血常规检查排除感染、贫血所致；患者听力下降需除外咽鼓管功能障碍及鼻咽部病变所致，完善鼻内镜检查了解鼻腔、鼻咽部及咽鼓管咽口情况、排除鼻咽部占位；患者听力下降呈进行性加重，需警惕邻近部位病变累及，完善喉镜检查排除喉咽部病变；患者听力下降需警惕鼻咽癌、听神经瘤等所致，完善鼻窦CT检查了解鼻腔鼻窦有无占位、排除鼻窦病变；完善颞骨CT检查了解中耳乳突及内耳结构、明确有无中耳胆脂瘤或内耳畸形；患者高龄，需排除椎基底动脉供血不足等血管因素所致听力下降，完善颈部超声检查了解颈部血管情况；患者为感音神经性听力下降，为排除内耳前庭系统伴随损害，完善前庭功能检查明确前庭功能状态。\n\n（检查清单）\n【必做检查】\n血常规、耳镜检查、鼻内镜检查、喉镜检查\n\n【影像学检查】\n鼻窦CT、颞骨CT、颈部超声\n\n【其他检查】\n纯音测听、声导抗、前庭功能检查","初步诊断":"1. 老年性耳聋\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 改善内耳微循环：银杏叶提取物片（金纳多）40mg po tid×4周；\n2. 神经营养：甲钴胺片 0.5mg po tid×4周；\n3. 补充维生素及代谢支持：维生素B1片 10mg po tid×4周；复合维生素B片 2片 po tid×4周。\n（如伴明显高脂血症、血液黏稠度增高者，可加用尼麦角林片 10mg po tid×4周。）\n\n【一般治疗及生活指导】\n1. 避免噪声刺激：远离强噪声环境，必要时佩戴防噪耳塞，避免长时间使用耳机，音量不超过最大音量的60%。\n2. 饮食清淡：低盐低脂饮食，多食富含维生素及锌、镁等微量元素的食物（如坚果、深海鱼、新鲜蔬果），戒烟限酒，控制好血压、血糖、血脂。\n3. 慎用耳毒性药物：避免使用氨基糖苷类抗生素（庆大霉素、链霉素等）、袢利尿剂（呋塞米）等耳毒性药物，确需使用时医师耳聋病史。\n4. 适当活动：适度体育锻炼（如散步、太极拳），保证充足睡眠，避免精神紧张与过度劳累。\n\n【随诊要求】\n1. 服药2～4周后复诊，复查纯音听阈测定评估疗效，必要时调整用药；\n2. 建议每年门诊复查纯音听阈测定1次，动态监测听力变化；\n3. 听力损失影响日常交流者，建议尽早验配助听器并定期调试；\n4. 如出现听力突然明显下降、耳内胀闷、眩晕或耳鸣骤然加重，应立即就诊，排除突发性耳聋及其他内耳疾病。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":592,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"671acd6aaaf1f80354bc001626b8eb66b947f765542b4298dbb0ff1f8a57368a","pinyin":"laonianxingerlong","initials":"lnxel","setting":"out","caseName":"门诊病历457","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历457",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-451d51f1bac4aad0c0bf","key":"v1-c9ccc21dfe2a3058|templates-451d51f1bac4aad0c0bf","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"鼻前庭炎","category":"门诊病历模板","raw":{"name":"鼻前庭炎","category":"门诊病历模板","case":{"case_name":"门诊病历458","templates":{"主诉":"鼻孔处红肿、疼痛1周","现病史":"患者1周前无明显诱因出现鼻前庭炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者鼻孔处红肿、疼痛1周，逐渐加重，完善鼻内镜检查直接观察鼻前庭及鼻腔黏膜病变范围、明确有无疖肿、皲裂及分泌物；患者局部红肿疼痛需判断有无细菌感染及炎症反应程度，完善血常规检查了解白细胞及中性粒细胞水平、排除全身感染与贫血；患者鼻前庭炎症可波及中耳与咽部，完善耳镜检查了解鼓膜有无充血、排除中耳炎性病变；完善喉镜检查排除喉咽部合并感染；患者鼻部症状需与鼻窦炎、鼻窦囊肿鉴别，完善鼻窦CT检查明确鼻窦有无炎症或占位；完善颞骨CT检查了解中耳乳突情况、排除中耳乳突炎；患者鼻前庭及鼻周炎症可致颈部淋巴结反应性增生，完善颈部超声检查了解颈部淋巴结及软组织情况；患者主诉鼻部症状而无明显听力下降，为基线评估听功能，完善纯音测听检查了解听力水平；完善声导抗检查了解中耳传音功能；患者发病以来伴轻度乏力，完善前庭功能检查排除前庭功能障碍所致平衡异常。\n\n（检查清单）\n【必做检查】\n血常规、耳镜检查、鼻内镜检查、喉镜检查\n\n【影像学检查】\n鼻窦CT、颞骨CT、颈部超声\n\n【其他检查】\n纯音测听、声导抗、前庭功能检查","初步诊断":"1. 鼻前庭炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 局部外用抗生素软膏：莫匹罗星软膏（百多邦）涂于双侧鼻前庭，每日2～3次，连用5～7天；对莫匹罗星过敏者改用夫西地酸乳膏或红霉素软膏，用法同上。\n2. 渗出、糜烂明显者：先以3%硼酸溶液或生理盐水局部湿敷，每日2～3次，每次15～20分钟，待渗液减少后再外涂抗生素软膏。\n3. 局部红肿、疼痛明显或伴蜂窝织炎倾向者，加用口服抗生素：头孢呋辛酯片0.25g bid×5～7天；青霉素不过敏者亦可选阿莫西林胶囊0.5g tid×5～7天。\n4. 瘙痒或结痂明显者，可短期外用糖皮质激素软膏（如氢化可的松乳膏，每日1～2次，不超过3～5天），与抗生素软膏交替使用，避免长期患者。\n\n【一般治疗及生活指导】\n1. 戒除挖鼻、拔鼻毛等不良习惯，避免用手指反复搔抓、摩擦鼻前庭皮肤。\n2. 保持鼻前庭清洁干燥，有痂皮时勿强行撕扯，可用温水或生理盐水湿润软化后轻轻拭除；洗脸、沐浴时避免肥皂水等刺激物反复进入前鼻孔。\n3. 清淡饮食，忌辛辣、油炸及烟酒等刺激性食物；保持大便通畅，规律作息，避免熬夜、过度劳累。\n4. 糖尿病患者及血糖异常者应积极控制血糖，反复发作者建议进一步检查，排除糖尿病、免疫功能低下等基础疾病；避免使用油性化妆品或粉质遮盖鼻前庭区域。\n\n【随诊要求】\n1. 用药3～5天后症状无缓解或加重，或红肿范围扩大、疼痛加剧、出现发热等全身症状者，应及时复诊。\n2. 反复发作或迁延不愈者，建议2周内复诊评估，完善血糖等相关检查，排查基础疾病；经久不愈者需警惕鼻前庭湿疹、真菌感染或鼻腔肿瘤等，必要时行鼻内镜检查。\n3. 症状消退、局部皮肤恢复正常后，仍需保持局部清洁及良好习惯1～2周，以防复发；复发者再次就诊时需告知既往用药史。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":593,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c3000b0ed54db4c5ac46a157a6ebcf32c4f8d6c04f239c6a38b328a24c8d41d8","pinyin":"biqiantingyan","initials":"bqty","setting":"out","caseName":"门诊病历458","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历458",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-824129efe32c9ede84ec","key":"v1-c9ccc21dfe2a3058|templates-824129efe32c9ede84ec","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"鼻疖","category":"门诊病历模板","raw":{"name":"鼻疖","category":"门诊病历模板","case":{"case_name":"门诊病历459","templates":{"主诉":"反复鼻疖相关不适1周，加重1天。","现病史":"患者1周前无明显诱因出现鼻疖相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者反复鼻疖相关不适1周、加重1天，鼻疖多为鼻前庭毛囊及皮脂腺的急性化脓性感染，完善血常规检查了解白细胞及中性粒细胞水平、排除全身感染与脓毒症；患者鼻疖挤压后感染可沿面静脉蔓延至海绵窦，完善鼻窦CT检查明确炎症有无波及鼻窦及眶内、排除眶内并发症；完善鼻内镜检查直接观察鼻前庭疖肿及鼻腔黏膜情况、明确病变部位与有无脓肿形成；患者鼻部感染可经咽鼓管波及中耳，完善耳镜检查了解鼓膜情况、排除中耳炎；完善喉镜检查排除喉咽部合并感染；完善颞骨CT检查了解中耳乳突有无受累；患者鼻周及面颊部感染可致颈部淋巴结肿大，完善颈部超声检查了解颈部淋巴结情况；患者鼻疖反复发作，需排查糖尿病等全身诱因，完善血糖检查明确有无糖代谢异常；为基线评估听功能，完善纯音测听检查了解听力水平；完善声导抗检查了解中耳传音功能；患者发病以来伴轻度乏力，为排除前庭及全身因素所致平衡障碍，完善前庭功能检查明确前庭功能状态。\n\n（检查清单）\n【必做检查】\n血常规、耳镜检查、鼻内镜检查、喉镜检查\n\n【影像学检查】\n鼻窦CT、颞骨CT、颈部超声\n\n【其他检查】\n纯音测听、声导抗、前庭功能检查","初步诊断":"1. 鼻疖\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 局部抗感染：10%鱼石脂软膏适量涂于患处，bid，连用3-5天，以促其化脓成熟；亦可用莫匹罗星软膏适量涂于患处，tid，连用5天。\n2. 全身抗生素（红肿明显、有发热或邻近淋巴结肿大时）：阿莫西林克拉维酸钾片0.457g po bid×5-7天；青霉素过敏者改用头孢呋辛酯片0.25g po bid×5-7天，服药期间禁饮酒。\n3. 对症镇痛：布洛芬缓释胶囊0.3g po bid，疼痛明显时服用，疗程不超过3天。\n\n【一般治疗及生活指导】\n1. 严禁挤压、挑刺疖肿或用力擤鼻：鼻周属\"危险三角区\"，挤压可使感染沿面静脉逆行扩散至海绵窦，引发海绵窦血栓性静脉炎、败血症等颅内严重并发症。\n2. 保持鼻部清洁干燥，早期可用温热毛巾局部热敷（每次15-20分钟，每日3次），促进炎症消散；避免挖鼻、拔鼻毛等不良习惯，防止反复感染。\n3. 清淡饮食，多饮水，忌辛辣刺激性食物及烟酒；注意休息、避免熬夜，保持大便通畅，增强机体抵抗力。\n\n【随诊要求】\n1. 用药3天后复诊评估疗效；若红肿疼痛无缓解或加重，或出现发热、剧烈头痛、寒战、眼睑及球结膜水肿、视力模糊等海绵窦受累征象，须立即返院急诊就诊。\n2. 治疗1周后复诊，确认疖肿消退及炎症控制情况；反复发作者建议检查空腹血糖，排除糖尿病等基础疾病。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":594,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2a41c4da39c14c3b1b4bb769953f90868cfee5a66d5d00f39ee71ed527ed531d","pinyin":"bijie","initials":"bj","setting":"out","caseName":"门诊病历459","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历459",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-cc8f4394430fbe19f6d2","key":"v1-c9ccc21dfe2a3058|templates-cc8f4394430fbe19f6d2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性鼻炎","category":"门诊病历模板","raw":{"name":"急性鼻炎","category":"门诊病历模板","case":{"case_name":"门诊病历460","templates":{"主诉":"鼻塞、流涕伴打喷嚏3天","现病史":"患者于3天前受凉或接触感冒病人后出现鼻塞（交替性或持续性，夜间加重）、流涕（初期为清水样，3～4天后转为黏脓性，量多）、打喷嚏（阵发性）、鼻痒（可伴眼痒）、咽部不适（咽干、咽痛，伴发咽炎）及全身症状（低热、乏力、轻度头痛）。伴嗅觉减退，为黏膜肿胀所致，多属暂时性，可逐渐恢复。病程中需注意有无发热（体温>38.5℃需考虑流感或其他感染）、脓涕持续超过10天或双相加重（好转后再次加重，提示继发细菌性鼻窦炎，应警惕）、耳闷（经咽鼓管引起分泌性中耳炎）、咳嗽（提示下气道受累）；婴幼儿可表现为吃奶困难、鼻塞、哭闹、张口呼吸及发热，需监测中耳炎、肺炎等并发症；有哮喘或过敏史者需与变应性鼻炎鉴别（后者打喷嚏多、清水样涕明显，常有过敏原接触史）。本病程多呈自限性，5～7天可缓解，多为病毒性。今日来我院耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP120/80mmHg。鼻黏膜充血肿胀（双侧），鼻腔可见分泌物（清水样或黏脓性，量中等），下鼻甲肿大，鼻道通畅度尚可，咽部充血，耳部鼓膜完整（用于中耳炎评估，儿童尤需注意），扁桃体无肿大，颈部淋巴结无肿大（病毒感染时可肿大），肺部呼吸音清。","辅助检查":"【必做】以临床诊断为主，典型病史即可诊断；【其他】血常规、CRP（用于发热明显或疑细菌感染者鉴别）、流感及呼吸道病毒检测（流行季节、发热及全身症状重者用于鉴别）、鼻内镜（病程迁延或疑鼻窦炎者，观察窦口情况）、过敏原检测（疑变应性鼻炎者）。","初步诊断":"1. 急性鼻炎（普通感冒，由鼻病毒等引起；轻度，评估有无并发症）\n（注：本病自限性，以对症治疗为主，多无需药物：①对症治疗：鼻塞可用鼻用减充血剂（羟甲唑啉，短程使用，疗程≤5～7天，以防药物性鼻炎，重要，儿童禁用）；生理盐水喷鼻或冲洗（安全，儿童适用）；打喷嚏、流涕明显者可用抗组胺药（扑尔敏或西替利嗪，尤其伴过敏者）；发热、头痛者可用解热镇痛药（对乙酰氨基酚或布洛芬，儿童病毒性感染不用阿司匹林，以防Reye综合征）；咽痛可用含片；多饮水、注意休息。②抗生素：不常规使用，病毒性感染无效，以防滥用；除非继发细菌感染（脓涕>10天、双相加重或发热，提示鼻窦炎、中耳炎），按细菌性感染选用阿莫西林克拉维酸。③儿童：鼻塞可用生理盐水滴鼻加吸鼻器，吃奶前清理鼻腔，保证进食，防并发症（中耳炎表现为耳痛哭闹、下呼吸道感染表现为咳嗽气促，出现时应就诊）；退热（体温≥38.5℃可用布洛芬或对乙酰氨基酚，按体重给药）。④病程：一般5～7天好转；若迁延或加重（脓涕>10天提示鼻窦炎）应复诊。⑤卫生：洗手、纸巾、防传播、通风。建议耳鼻喉科或儿科就诊；本病自限，以对症治疗为主、防滥用抗生素、注意并发症识别，均属重要。","处理方案":"【药物治疗】\n1. 抗组胺药：氯雷他定片10mg qd×5天，或西替利嗪片10mg qd×5天，用于缓解喷嚏、流涕、鼻痒。\n2. 鼻用糖皮质激素：布地奈德鼻喷雾剂64μg/喷，每侧鼻孔各1喷 bid×5-7天，用于减轻鼻黏膜炎症及鼻塞。\n3. 鼻用减充血剂：盐酸羟甲唑啉鼻喷雾剂，每侧鼻孔各1-2喷 bid，连用不超过5天（症状缓解即停，避免药物性鼻炎）。\n4. 对症治疗：对乙酰氨基酚片0.5g，发热或头痛时口服，q4-6h，24小时不超过2g。\n\n【一般治疗及生活指导】\n1. 充分休息，保证充足睡眠，避免劳累及熬夜，病程约7天，勿带病剧烈运动。\n2. 多饮温水，清淡易消化饮食，忌辛辣、烟酒及过冷过热食物。\n3. 生理盐水或海盐水鼻腔冲洗，每次每侧20-50ml，bid，清洁鼻腔、减轻鼻塞。\n4. 保持室内通风、湿度适宜，注意保暖，避免冷空气及粉尘刺激，减少外出聚集。\n\n【随诊要求】\n1. 用药5-7天后鼻塞、流涕等症状无明显缓解或加重者，及时复诊。\n2. 出现高热不退（>38.5℃持续3天）、黄脓涕增多、头痛加剧、耳痛、面部胀痛等提示并发症（鼻窦炎、中耳炎）时，随时就诊。\n3. 若症状缓解但10天后仍反复，需复诊排除其他鼻腔疾病并调整方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":595,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"80db470b6a404af4fbc9c314be403ca3acb90363ef231d69b4bc45ab725fad97","pinyin":"jixingbiyan","initials":"jxby","setting":"out","caseName":"门诊病历460","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历460",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-52aadc46cc82c6d1f407","key":"v1-c9ccc21dfe2a3058|templates-52aadc46cc82c6d1f407","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性鼻炎","category":"门诊病历模板","raw":{"name":"慢性鼻炎","category":"门诊病历模板","case":{"case_name":"门诊病历461","templates":{"主诉":"鼻塞、流涕1年","现病史":"患者于数月至数年前（慢性起病，可因先天发育或外伤后渐进）出现鼻塞（呈交替性，侧卧时下方鼻塞明显，为单纯性特征；或呈持续性，见于肥厚性，两侧渐进，可致张口呼吸；均以夜间加重）、流涕（黏涕见于单纯性或肥厚性，清水样涕见于变应性，即过敏性鼻炎，常伴打喷嚏、鼻痒）、嗅觉减退（因鼻塞所致，多可逆）、头痛头昏（鼻塞缺氧引起）、耳鸣耳闷（影响咽鼓管）、咽部不适（后鼻滴漏所致，常清嗓）、睡眠受影响（打鼾、张口呼吸）。分型特点：单纯性者黏膜充血肿胀，可逆，对减充血剂收缩良好；肥厚性者黏膜及鼻甲增生肥厚，不可逆，持续性堵塞，对减充血剂反应差，需手术；变应性者有过敏原接触史，打喷嚏、清水涕、鼻痒、眼痒，呈季节性或常年性；药物性者长期使用鼻用减充血剂（如鼻喷羟甲唑啉超过7天），可致反跳性鼻塞（药物性鼻炎，重要，须询问用药史）；萎缩性者鼻黏膜萎缩、鼻腔宽大、有干痂、恶臭（臭鼻症），少见，多见于老年女性；另有职业性或环境因素（粉尘、化学物）、吸烟、妊娠（激素变化致鼻塞，多见于孕后期）、糖尿病或甲状腺功能减退（黏膜改变）等。需了解用药史（鼻喷剂中减充血剂是否长期使用、激素喷鼻剂使用情况）、全身疾病史及吸烟与环境接触史。今日来我院耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP120/80mmHg。鼻：鼻黏膜检查，单纯性者充血肿胀、表面光滑，用减充血剂后黏膜可收缩（可逆，符合单纯性）；肥厚性者黏膜肥厚，下鼻甲肥大，呈桑葚样或结节状，不可逆，用减充血剂后不收缩（符合肥厚性）；变应性者黏膜苍白水肿，伴清水样涕。鼻腔可见分泌物（黏涕或清涕，量不等），鼻道堵塞程度不一，可并见鼻中隔偏曲，鼻底可见干痂（提示萎缩性），嗅觉检查可有减退。咽部可见后鼻滴漏，耳部注意有无中耳（分泌性）病变，肺部注意有无哮喘（与变应性相关）。","辅助检查":"【必做】鼻内镜（核心，用于评估黏膜及鼻甲情况、鼻道与窦口）；【其他】过敏原检测（疑变应性者，皮肤点刺或血清特异性IgE）、鼻分泌物涂片（查嗜酸性粒细胞，用于变应性与非变应性嗜酸细胞增多的鉴别）、鼻甲收缩试验（1%麻黄碱，收缩者为单纯性，不收缩者为肥厚性，为手术指征）、鼻窦CT（疑鼻窦炎并见者，或鼻甲肥厚性评估及手术前）、嗅觉测试。","初步诊断":"1. 慢性鼻炎（单纯性、肥厚性、变应性或药物性、萎缩性；需评估鼻甲肥大程度，有无合并鼻窦炎或鼻中隔偏曲）\n（注：治疗依分型而定，包括药物与手术：①单纯性：鼻用糖皮质激素（糠酸莫米松或氟替卡松，一线用药，抗炎、改善鼻塞流涕，疗程数周，长期维持安全）、生理盐水冲洗、减充血剂（仅用于严重者短期使用，≤5～7天，以防药物性鼻炎，重要）、避免诱因。②肥厚性：药物治疗同单纯性，但因不可逆肥大效果差，收缩剂不收缩，应手术，可行下鼻甲部分切除术或低温等离子消融、激光（缩小鼻甲、改善通气，微创，注意保留黏膜以防萎缩性鼻炎及空鼻综合征，重要，切除应适度）。③变应性：参见过敏性鼻炎，鼻用激素加抗组胺药加脱敏治疗。④药物性：停用减充血剂是关键，停用后反跳性鼻塞可加重1～2周，应坚持，辅以鼻用激素（糠酸莫米松减轻反跳）、口服激素（短期用于严重、顽固者）及鼻腔冲洗至恢复；同时教育患者勿长期使用减充血剂。⑤萎缩性：鼻腔冲洗（生理盐水或碳酸氢钠，清除干痂）、润滑（薄荷油或石蜡油滴鼻）、抗生素软膏、局部补充维生素A或D；严重者少见，可手术缩小鼻腔。⑥随访：鼻内镜评估治疗反应；药物减量（控制后激素喷鼻维持最小量，长期使用）；手术后冲洗、复查、注意复发。建议耳鼻喉科就诊；强调分型治疗、激素喷鼻为基础、防药物性鼻炎、肥厚性手术及防过度切除，均属重要。","处理方案":"【药物治疗】\n1. 鼻用糖皮质激素：糠酸莫米松鼻喷雾剂（内舒拿）每侧鼻腔1-2喷 bid，晨起使用，疗程4-8周，为一线首选药物，可显著减轻鼻塞、流涕及打喷嚏症状。\n2. 口服第二代抗组胺药：氯雷他定片10mg qd，睡前口服，疗程2-4周；伴明显打喷嚏、鼻痒者首选。\n3. 鼻用减充血剂（短期患者）：盐酸羟甲唑啉鼻喷雾剂每侧1-2喷 bid，连用不超过7天，仅用于鼻塞严重时短期缓解，避免长期使用以防药物性鼻炎。\n4. 黏液促排剂：桉柠蒎肠溶软胶囊0.3g tid，餐前半小时凉开水送服，疗程1-2周，用于黏液分泌增多、涕多黏稠者。\n\n【一般治疗及生活指导】\n1. 每日用生理盐水或海盐水行鼻腔冲洗1-2次，清除鼻腔分泌物及过敏原，保持鼻黏膜清洁湿润。\n2. 避免接触粉尘、烟雾、刺激性气体及已知过敏原，保持居室通风、温湿度适宜（湿度40%-60%）。\n3. 戒烟限酒，忌辛辣刺激性食物；加强营养，适当运动锻炼，增强体质，预防感冒。\n4. 注意保暖，避免受凉及反复呼吸道感染；感冒迁延可诱发或加重慢性鼻炎，急性发作时及时规范治疗。\n\n【随诊要求】\n1. 用药2周后复诊，评估症状改善情况并调整治疗方案；症状缓解后需在医师指导下逐渐减量或维持治疗，不可自行停药。\n2. 若症状持续超过3个月无缓解，或出现鼻出血、嗅觉减退、持续性头痛、面部胀痛等表现，应及时复诊，必要时行鼻内镜检查及影像学检查排除鼻息肉、鼻窦炎等其他病变。\n3. 使用鼻用减充血剂连续不超过7天，长期使用需遵医嘱定期复查，警惕药物性鼻炎。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":596,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6f19e3f1221e0bf6eb7fe6976ae6b4065e5009e24720d0f29ed146811f537f33","pinyin":"manxingbiyan","initials":"mxby","setting":"out","caseName":"门诊病历461","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历461",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-813d60dc2c2b10ebf772","key":"v1-c9ccc21dfe2a3058|templates-813d60dc2c2b10ebf772","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"萎缩性鼻炎","category":"门诊病历模板","raw":{"name":"萎缩性鼻炎","category":"门诊病历模板","case":{"case_name":"门诊病历462","templates":{"主诉":"鼻干、鼻塞伴嗅觉减退1周","现病史":"患者1周前无明显诱因出现萎缩性鼻炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者鼻干、鼻塞伴嗅觉减退1周，完善鼻内镜检查直接观察鼻黏膜萎缩程度、鼻腔宽大及干痂形成情况、明确有无臭鼻症表现；患者鼻塞、嗅觉减退需与鼻窦炎、鼻窦囊肿及鼻腔占位鉴别，完善鼻窦CT检查明确鼻窦有无炎症或占位性病变；患者发病以来伴轻度乏力，完善血常规检查排除感染、贫血所致；患者鼻黏膜病变需与特殊性感染鉴别，完善耳镜检查了解鼻咽部及鼓膜情况、排除中耳病变；完善喉镜检查排除喉部病变；完善颞骨CT检查了解中耳乳突及内耳结构情况；萎缩性鼻炎常合并鼻腔宽大、气流异常，可影响咽鼓管功能，完善声导抗检查了解中耳传音功能；为基线评估听功能，完善纯音测听检查了解听力水平；患者鼻腔鼻窦慢性炎症可致颈部淋巴结反应性增生，完善颈部超声检查了解颈部淋巴结及软组织情况；患者鼻腔宽大、通气异常可累及内耳前庭，完善前庭功能检查排除前庭功能障碍所致平衡异常。\n\n（检查清单）\n【必做检查】\n血常规、耳镜检查、鼻内镜检查、喉镜检查\n\n【影像学检查】\n鼻窦CT、颞骨CT、颈部超声\n\n【其他检查】\n纯音测听、声导抗、前庭功能检查","初步诊断":"1. 萎缩性鼻炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.鼻腔冲洗及润滑剂：生理盐水鼻腔冲洗，bid；复方薄荷油滴鼻液每次2-3滴，tid，以湿润黏膜、软化并清除脓痂。\n2.局部抗生素滴鼻：1%链霉素滴鼻液（或0.5%新霉素滴鼻液）每次2-3滴，tid，抑制鼻腔细菌生长，减轻恶臭。\n3.维生素及营养支持：维生素A 50000U，qd，口服；维生素B2 10mg，tid，口服，连用2-4周，促进黏膜上皮修复。\n4.局部激素及扩张血管治疗：0.5%雌二醇软膏或5%鱼肝油软膏涂布鼻黏膜，qd，睡前使用，刺激腺体分泌、改善黏膜血液循环。\n\n【一般治疗及生活指导】\n1.保持鼻腔湿润：室内湿度维持在50%-60%，干燥季节可用加湿器或鼻腔生理盐水喷雾，避免空调、暖气直吹及干燥粉尘环境，外出可佩戴口罩。\n2.禁忌挖鼻、用力擤鼻：避免损伤萎缩的鼻黏膜引起出血，清除痂皮时先用油剂软化后再轻轻擤出或冲洗，忌强行剥离。\n3.加强营养：多食富含维生素A、B2及优质蛋白的食物（动物肝脏、胡萝卜、蛋黄、牛奶、豆制品），忌辛辣刺激、烟酒，减少黏膜刺激。\n4.适度活动与增强体质：规律作息、避免熬夜，适当体育锻炼，注意保暖，积极防治上呼吸道感染以防病情加重。\n\n【随诊要求】\n1.用药后2-4周复诊，评估鼻干燥、脓痂及恶臭等症状改善情况，必要时调整用药。\n2.每1-3个月复查鼻腔黏膜状态，观察黏膜萎缩及脓痂变化，长期用药者定期评估肝功能（维生素A大剂量时）。\n3.若出现反复鼻出血、脓性分泌物增多伴臭味加重、头痛或嗅觉持续丧失，或疑有合并感染、恶变可能时，应及时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":597,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c40f15004973c70d0717d375f8e5b7285897463dbd00936cceee3aa8e92aaff0","pinyin":"weisuoxingbiyan","initials":"wsxby","setting":"out","caseName":"门诊病历462","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历462",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ed38618418f7b7cf9bbb","key":"v1-c9ccc21dfe2a3058|templates-ed38618418f7b7cf9bbb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"干酪性鼻炎","category":"门诊病历模板","raw":{"name":"干酪性鼻炎","category":"门诊病历模板","case":{"case_name":"门诊病历463","templates":{"主诉":"鼻塞、脓涕伴恶臭1周","现病史":"患者1周前无明显诱因出现干酪性鼻炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者鼻塞、脓涕伴恶臭1周，干酪性鼻炎以鼻腔鼻窦内干酪样物质潴留为特征，完善鼻窦CT检查明确病变范围、骨质破坏程度及有无鼻窦占位、排除鼻腔鼻窦肿瘤；完善鼻内镜检查直接观察鼻腔内干酪样物及黏膜情况、必要时取组织活检明确性质；患者脓涕伴恶臭提示感染，完善血常规检查了解白细胞及中性粒细胞水平、排除全身感染与贫血；患者病程中需与结核等特殊性感染鉴别，完善喉镜检查排除喉部及下咽部病变；完善耳镜检查了解鼻咽部及鼓膜情况、排除中耳病变；完善颞骨CT检查了解中耳乳突有无受累及骨质破坏；患者鼻腔鼻窦长期病变可致颈部淋巴结肿大，完善颈部超声检查了解颈部淋巴结情况、必要时鉴别淋巴结性质；患者鼻塞、脓涕可经咽鼓管影响中耳，完善声导抗检查了解中耳传音功能；为基线评估听功能，完善纯音测听检查了解听力水平；患者鼻腔鼻窦病变可累及内耳前庭，完善前庭功能检查明确前庭功能状态。\n\n（检查清单）\n【必做检查】\n血常规、耳镜检查、鼻内镜检查、喉镜检查\n\n【影像学检查】\n鼻窦CT、颞骨CT、颈部超声\n\n【其他检查】\n纯音测听、声导抗、前庭功能检查","初步诊断":"1. 干酪性鼻炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 阿莫西林克拉维酸钾片（阿莫西林0.4g/克拉维酸57mg）1片口服 tid，疗程7天：控制干酪样物继发的需氧菌与厌氧菌混合感染；青霉素过敏者改用克林霉素胶囊0.3g口服 qid。\n2. 甲硝唑片0.4g口服 tid，疗程7天，与上述药物联用加强抗厌氧菌覆盖（干酪样物及脓性分泌物中厌氧菌检出率高）。\n3. 0.9%氯化钠溶液鼻腔冲洗，每次每侧100ml，bid，清除干酪样物、脓涕及干痂；冲洗后滴入复方薄荷油滴鼻液，每侧2~3滴，tid，润滑鼻黏膜、防止干痂形成。\n4. 若伴喷嚏、大量清涕等变应性症状，加用氯雷他定片10mg口服 qd，疗程7天。\n\n【一般治疗及生活指导】\n1. 保证充足睡眠与休息，避免劳累，增强机体抵抗力，预防感冒。\n2. 饮食清淡、营养均衡，多摄入优质蛋白与新鲜蔬果，忌辛辣、过烫饮食，戒烟限酒。\n3. 保持鼻腔清洁，勿用力擤鼻、抠鼻，按医嘱坚持每日鼻腔冲洗。\n4. 粉尘或有害气体环境工作者应佩戴口罩做好防护，减少鼻黏膜刺激。\n\n【随诊要求】\n1. 用药1周后复诊，评估鼻塞、脓涕、恶臭、头痛等症状变化及药物耐受情况。\n2. 本病以手术彻底清除干酪样物为主、药物治疗为辅：应尽快完善鼻内镜检查及鼻窦CT明确病变范围，择期行鼻内镜下病灶清除术。\n3. 术后2周、1个月、3个月定期行鼻内镜复查，观察术腔愈合及有无复发；此后每3~6个月随访1次，持续随访2年以上。\n4. 若出现剧烈头痛、发热、眼球突出、视力下降或面部明显肿胀，提示病变向眶内、颅内发展，需立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":598,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"427bfff286ae684cd9a6731a8239f2423066c4418419eab18c064b2421b0dac3","pinyin":"ganlaoxingbiyan","initials":"glxby","setting":"out","caseName":"门诊病历463","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历463",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8b40335d9d6139f3ceb0","key":"v1-c9ccc21dfe2a3058|templates-8b40335d9d6139f3ceb0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"鼻中隔偏曲","category":"门诊病历模板","raw":{"name":"鼻中隔偏曲","category":"门诊病历模板","case":{"case_name":"门诊病历464","templates":{"主诉":"鼻塞、反复鼻出血1年","现病史":"患者于先天发育或外伤后（鼻外伤可致骨折、偏曲）逐渐出现鼻塞，以单侧为主（偏曲凸侧堵塞，对侧鼻甲代偿肥大时两侧可交替，呈进行性，重者张口呼吸）；伴反复鼻出血，因偏曲凸面黏膜干燥、血管（利特尔区）受偏曲刺激所致，为常见症状；伴头痛，可因鼻中隔偏曲压迫鼻甲引起反射性头痛，或影响鼻窦引流致鼻窦炎；另有打鼾、嗅觉减退（鼻塞所致）、流涕（合并鼻窦炎时为脓涕）、反复鼻窦炎（偏曲使鼻窦引流受阻、窦口堵塞）、耳鸣耳闷（影响咽鼓管）。需了解有无鼻出血（频率、量、是否需止血）、外伤史（鼻骨骨折）、反复鼻窦炎、过敏（可并见变应性鼻炎）、睡眠情况（打鼾、呼吸暂停）、外鼻畸形（歪鼻，可并见，出于美容考虑）等；多数轻度偏曲者无症状，不需治疗，此点重要。今日来我院耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP120/80mmHg。鼻：前鼻镜及鼻内镜检查（核心），可见鼻中隔偏曲，需描述方向（C形、S形或棘突，其中骨嵴刺入鼻甲可致头痛、出血，重要）及程度；偏曲凸侧黏膜干燥、糜烂、血管显露（出血点位于利特尔区）；对侧鼻甲代偿肥大（可致两侧堵塞）；鼻道通畅度下降；鼻窦口引流受影响；可并见外鼻歪鼻；鼻腔可见活动性出血或干痂。","辅助检查":"【必做】鼻内镜（核心）；【影像】鼻窦CT（手术前评估偏曲程度、有无并见鼻窦炎及骨质情况）、X线（鼻骨，用于外伤、骨折评估）；【其他】鼻出血者行出血点定位（内镜下电凝或激光处理）、睡眠呼吸评估（打鼾者疑阻塞性睡眠呼吸暂停，必要时）。","初步诊断":"1. 鼻中隔偏曲（C形或S形、棘突；偏左或偏右；伴鼻甲代偿肥大、慢性鼻窦炎或鼻出血）\n（注：治疗原则为无症状者不需治疗（轻度者多数观察即可，重要），有症状者手术：①保守及对症治疗：无症状或轻者观察随访；鼻塞可用鼻用糖皮质激素（减轻黏膜肿胀、改善通气，但不能纠正偏曲，对骨性偏曲效果有限）、生理盐水冲洗（清洁、防干痂）；鼻出血可局部处理（出血点电凝或化学烧灼如硝酸银、凡士林纱条填塞用于活动性出血、湿润剂如红霉素软膏或薄荷油以防干燥再出血，重要）；反复或量大者行手术矫正。②手术：鼻中隔矫正术，即黏膜下鼻中隔成形术（SMR），切除偏曲的软骨及骨、保留黏膜、矫正并恢复中隔，为标准术式，可内镜下微创完成；适应证为明显鼻塞（保守无效、影响呼吸睡眠及生活）、反复鼻出血（偏曲凸面血管所致、保守无效）、反复鼻窦炎（偏曲致引流受阻）、头痛（偏曲压迫）以及准备行鼻窦或鼻甲手术者（同时矫正以改善术后效果）；术前应行鼻窦CT排除鼻窦炎并同时处理；术后填塞（1～2天取出，防出血）、冲洗（术后恢复、防黏连）、复查（观察愈合及通气改善）。③并发症：鼻中隔血肿（术后胀痛，需引流，防脓肿及软骨坏死、鼻中隔穿孔、鞍鼻，重要，须处理）、穿孔（黏膜双侧破损所致，术后少见，可有干痂，需处理）、黏连（术后中隔与鼻甲之间，需分离）。④随访：术后1周及1个月评估恢复及通气改善；无症状者随访，出现出血、头痛时再评估。建议耳鼻喉科就诊；有症状者行手术矫正，注意防术后并发症，无症状者观察，均属重要。","处理方案":"【药物治疗】\n1. 鼻用糖皮质激素喷雾剂（首选一线，减轻鼻黏膜水肿、改善鼻塞）：糠酸莫米松鼻喷雾剂 每次每侧鼻孔1-2喷，qd~bid，连用4~8周，症状缓解后维持最小有效剂量。\n2. 生理性海盐水鼻腔冲洗：0.9%氯化钠溶液或等渗海盐水喷雾 每次每侧2-3喷，bid~tid，可长期使用，保持鼻腔湿润、清除分泌物及干痂。\n3. 黏液促排剂（分泌物黏稠增多时）：桉柠蒎肠溶软胶囊 0.3g po tid，连用7~14天。\n4. 短期鼻用减充血剂（严重鼻塞应急缓解，仅短期使用）：盐酸羟甲唑啉鼻喷雾剂 每次每侧1喷，tid，连续使用不超过7天，切忌长期患者以免引起药物性鼻炎。\n\n【一般治疗及生活指导】\n1. 避免外伤及用力擤鼻、挖鼻、抠鼻，防止鼻出血及鼻中隔血肿形成；出血时避免仰头，采用指压鼻翼法压迫止血。\n2. 保持居住环境通风、湿润，避免干燥、粉尘及烟雾刺激，可配合加湿器；戒烟限酒，减少冷空气及刺激性气体直接刺激鼻腔。\n3. 清淡饮食，忌辛辣、过烫食物，多饮水，保持大便通畅，避免用力排便增加鼻腔出血风险。\n4. 避免剧烈运动及对抗性、碰撞性运动；若拟行鼻中隔矫正术，术前遵医嘱停用阿司匹林等抗凝药物，并避免感冒。\n\n【随诊要求】\n1. 保守治疗4~8周后复诊，评估鼻塞、头痛等症状改善情况，必要时调整用药方案。\n2. 若鼻塞持续不缓解或进行性加重，或反复鼻出血、头痛、嗅觉减退，或出现打鼾加重、睡眠呼吸暂停表现，应及时复诊，行鼻内镜检查并评估鼻中隔矫正术手术指征。\n3. 术前评估者需遵医嘱完善鼻内镜、鼻窦CT等检查后专科复诊确定手术方案；术后按医嘱定期复查至术腔上皮化。","手术记录":"手术记录\n\n手术日期：请术者据实际填写\n术前诊断：鼻中隔偏曲（偏曲方向及类型：C形或S形、棘突；伴或不伴鼻甲代偿肥大、慢性鼻窦炎、鼻出血）\n术后诊断：同术前诊断\n手术名称：经鼻内镜下鼻中隔黏膜下矫正术（鼻中隔成形术，SMR）（门诊病历处理方案记载标准术式为黏膜下鼻中隔成形术；实际术式及是否联合鼻甲手术、鼻窦手术请术者据实补充）\n术者（签名）：____________　　助手（签名）：____________\n麻醉方法（签名）：____________（常规可采用局部浸润麻醉加表面麻醉，或全身麻醉，以麻醉科方案为准，由麻醉医师据实填写）\n体位：仰卧位，头稍后仰（常规，请据实际填写）\n手术经过（要点，具体步骤请术者据实际操作补充）：麻醉成功后取仰卧位，常规消毒铺巾，以含肾上腺素棉片收敛双侧鼻腔黏膜。于左侧鼻中隔皮肤黏膜交界处（或偏曲凸侧）做L形或Killian切口，切开黏膜及黏软骨膜，以剥离子沿软骨表面向后分离黏软骨膜及黏骨膜，形成黏膜下隧道，充分暴露偏曲的鼻中隔软骨及骨部。以鼻中隔刀在黏膜下切除偏曲的方形软骨（保留足够L形支撑支架，防止术后鞍鼻），咬除偏曲的筛骨垂直板及犁骨骨嵴、棘突，矫正中隔至中线位。检查双侧鼻腔通气改善，中隔形态平直，黏膜无撕裂。复位黏膜瓣，间断缝合切口，双侧鼻腔以凡士林纱条及膨胀海绵填塞，必要时置鼻中隔夹板固定。术中出血少，术毕安返病房（是否联合下鼻甲部分切除或鼻窦开放术，请术者据实补充）。\n术中出血量：约30ml（常规范围20～50ml，请据实际填写）　　输血量：0ml，未输血\n切除标本：切除的鼻中隔软骨及骨组织一般不作病理检查（若术中黏膜可疑病变，应送病理，请据实填写）\n术中意外及处理：无（如出现黏软骨膜撕裂、鼻中隔血肿、出血较多等，请据实补充记录及处理措施）\n术后情况：麻醉清醒后安返病房，生命体征平稳，双侧鼻腔填塞在位。术后取半卧位，予抗感染及止血治疗，观察鼻腔渗血及咽部有无血液流下。填塞物计划于术后24～48小时取出，取出后予生理盐水冲洗、鼻腔湿润剂（薄荷油或红霉素软膏）及鼻用糖皮质激素喷鼻，避免用力擤鼻、挖鼻及外伤，1周及1个月门诊复查，观察有无鼻中隔血肿、穿孔、黏连及通气改善情况。\n签名：术者________　　记录者________","手术知情同意书":"手术知情同意书\n\n患者姓名：（病历未记载，请补充）　　性别：（病历未记载）　　年龄：（病历未记载）\n科别：耳鼻咽喉科　　住院号（门诊号）：门诊病历464　　就诊日期：（病历未记载，请补充）\n术前诊断：鼻中隔偏曲\n拟定手术名称：经鼻内镜下鼻中隔黏膜下矫正术（鼻中隔成形术）\n拟定手术日期：（病历未记载，请补充）\n麻醉方式：局部浸润麻醉+表面麻醉，或全身麻醉（以麻醉科实际方案为准）\n\n一、手术目的：矫正偏曲的鼻中隔软骨及骨性结构，恢复鼻腔正常通气与引流，解除鼻塞（单侧为主、进行性）、反复鼻出血、反射性头痛等症状，并为鼻窦引流及后续鼻腔手术创造条件。\n\n二、替代治疗方案（各有适应证与利弊）：\n1. 保守治疗：鼻用糖皮质激素喷雾剂（如糠酸莫米松）减轻黏膜水肿、生理性海盐水鼻腔冲洗、黏液促排剂、短期鼻用减充血剂。可缓解黏膜肿胀所致鼻塞，但不能纠正骨性偏曲，对结构性阻塞效果有限，且减充血剂连续使用不超过7天以免发生药物性鼻炎。\n2. 鼻出血出血点的局部处理：硝酸银化学烧灼、电凝、凡士林纱条填塞等，仅处理出血症状，不解决偏曲本身。\n3. 单纯鼻甲手术（如下鼻甲部分切除/消融）：可改善通气，但对偏曲侧无效，且可能造成空鼻综合征。\n4. 不做手术：轻度偏曲、无症状者可观察随访；但症状明显者鼻塞、头痛、反复鼻出血、鼻窦炎可长期存在或逐渐加重，并可能影响睡眠与生活质量。\n\n三、手术风险与并发症：\n1. 麻醉意外及心脑血管意外；\n2. 术中、术后鼻出血，严重者需再次填塞或手术止血、输血；\n3. 鼻中隔血肿，继发感染可形成鼻中隔脓肿，导致软骨坏死；\n4. 鼻中隔穿孔，术后出现鼻腔干痂、哨音，必要时需二次修补；\n5. 鼻中隔支撑不足致鼻梁塌陷（鞍鼻）、鼻尖变形等外观改变；\n6. 鼻腔黏连（中隔与下鼻甲之间），需术后分离处理；\n7. 鼻中隔矫正不彻底或过度矫正，症状改善不满意，需再次手术；\n8. 嗅觉减退、鼻腔干燥感、头痛；\n9. 术后感染、发热，填塞期耳闷、溢泪、吞咽不适；\n10. 其他不可预知的并发症。\n\n四、麻醉风险：麻醉药物过敏、呼吸循环抑制、心律失常、误吸、喉痉挛、术后苏醒延迟等；局部麻醉可能出现局麻药中毒、鼻黏膜损伤，由麻醉医师另行详细交代并签署麻醉知情同意书。\n\n五、输血及血制品：鼻中隔手术出血一般较少，但若术中或术后大出血仍需输血；输血可能传播肝炎、艾滋病等血源性疾病并可能发生输血反应。已另行签署输血知情同意书。\n\n六、术中改变术式的可能：若术中发现偏曲程度超出术前评估、合并鼻甲肥大或鼻窦病变，可能同时加行下鼻甲手术、鼻窦开放术；若黏软骨膜撕裂严重或出血难以控制，可能缩小手术范围或分期手术，术者将与患者及家属沟通后决定。\n\n七、术后注意事项：术后24～48小时内取出鼻腔填塞物，取出前避免用力擤鼻、打喷嚏时张口；取出后坚持生理盐水鼻腔冲洗、鼻腔湿润，勿挖鼻、抠鼻及用力擤鼻；1个月内避免鼻部外伤及剧烈运动、对抗性运动；遵医嘱使用鼻用糖皮质激素；术后1周、1个月门诊复查，出现大量鼻出血、鼻部胀痛加重、发热、鼻梁塌陷等及时就诊。\n\n八、其他：诊疗费用按医保政策结算，具体以实际发生为准；患者及家属有权了解病情并可随时提出疑问。\n\n医师签名：____________　　日期：____年__月__日\n患者（或家属）签名：____________与患者关系：______　　日期：____年__月__日"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":599,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8f8a8ac7f0fa8b25b15e5e7f732c8ad93264481154b19315873dfc50b2f753c9","pinyin":"bizhonggepianqu","initials":"bzgpq","setting":"mixed","caseName":"门诊病历464","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案","手术记录","手术知情同意书"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历464",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案 手术记录 手术知情同意书",30],["主要诊断编码","",30]]},{"id":"templates-683599c8c1fe3c5d2649","key":"v1-c9ccc21dfe2a3058|templates-683599c8c1fe3c5d2649","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"鼻中隔血肿","category":"门诊病历模板","raw":{"name":"鼻中隔血肿","category":"门诊病历模板","case":{"case_name":"门诊病历465","templates":{"主诉":"鼻塞、鼻痛1周","现病史":"患者1周前无明显诱因出现鼻中隔血肿相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者鼻塞、鼻痛1周，鼻中隔血肿多与外伤或凝血功能异常有关，完善血常规检查了解血红蛋白及血小板水平、评估出血程度并排除感染与贫血；患者既往否认手术外伤史，需除外凝血机制异常所致自发性鼻中隔血肿，完善凝血功能检查明确凝血状态；完善鼻内镜检查直接观察鼻中隔黏膜膨隆及色泽、明确血肿范围及有无继发感染；患者鼻中隔血肿可继发脓肿并破坏鼻中隔软骨，完善鼻窦CT检查明确病变范围、排除鼻窦病变及鼻中隔脓肿形成；完善颞骨CT检查了解中耳乳突情况、排除中耳病变；患者鼻塞明显、需评估鼻咽部及咽鼓管情况，完善耳镜检查了解鼓膜有无充血、排除中耳积液；完善喉镜检查排除喉部病变；患者鼻中隔血肿可致鼻塞而影响中耳通气，完善声导抗检查了解中耳传音功能；患者鼻塞可伴听力下降主诉，完善纯音测听检查了解听力水平；患者鼻部病变可致颈部淋巴结反应性增生，完善颈部超声检查了解颈部淋巴结情况；患者发病以来伴轻度乏力，完善前庭功能检查排除前庭功能障碍。\n\n（检查清单）\n【必做检查】\n血常规、耳镜检查、鼻内镜检查、喉镜检查\n\n【影像学检查】\n鼻窦CT、颞骨CT、颈部超声\n\n【其他检查】\n纯音测听、声导抗、前庭功能检查","初步诊断":"1. 鼻中隔血肿\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.预防感染：阿莫西林克拉维酸钾片（0.457g/片，含阿莫西林0.4g）1片 po bid，连用5～7天；青霉素过敏者改用头孢呋辛酯片0.25g po bid×5天，或阿奇霉素片0.5g po qd×3天。\n2.镇痛：布洛芬缓释胶囊0.3g po bid，疼痛明显时服用，连用不超过3天；或对乙酰氨基酚片0.5g po，每日不超过4次。\n3.辅助止血：云南白药胶囊0.25g po tid×3天，适用于有明显出血倾向或穿刺抽吸后渗血者。\n\n【一般治疗及生活指导】\n1.鼻中隔血肿应尽早行穿刺抽吸或切开引流，置引流条者24～48小时内保持引流通畅，勿自行拔除，避免血肿机化、继发感染。\n2.伤后48小时内鼻部间断冷敷（每次15～20分钟，每日3～4次）以减轻肿胀疼痛；48小时后改为温热敷，促进血肿吸收。\n3.避免用力擤鼻、打喷嚏时张口、抠挖鼻腔，避免剧烈运动、长时间低头弯腰及重体力劳动，防止血肿扩大或再出血。\n4.饮食宜温凉软食，忌过热、辛辣刺激食物及烟酒，避免热水浴、桑拿等致血管扩张的行为。\n\n【随诊要求】\n处理后24～48小时复诊，由医师检查引流情况并按时拔除引流条；期间若出现鼻部胀痛加剧、发热、脓性分泌物、鼻出血或鼻塞加重，应立即就诊。术后1周复诊行鼻内镜检查，评估血肿吸收与愈合情况，观察有无中隔脓肿、软骨坏死及穿孔等并发症，必要时择期行鼻中隔成形术。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":600,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"839b6b8c9295c8e130d888dce1c9bd8ad062d17a377b12387093fe83445eed22","pinyin":"bizhonggexuezhong","initials":"bzgxz","setting":"out","caseName":"门诊病历465","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历465",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-da25db340f0fd91b7315","key":"v1-c9ccc21dfe2a3058|templates-da25db340f0fd91b7315","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"鼻中隔脓肿","category":"门诊病历模板","raw":{"name":"鼻中隔脓肿","category":"门诊病历模板","case":{"case_name":"门诊病历466","templates":{"主诉":"鼻塞、鼻痛伴发热1周","现病史":"患者1周前无明显诱因出现鼻中隔脓肿相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者鼻塞、鼻痛伴发热1周，需高度警惕鼻中隔脓肿，完善血常规检查了解白细胞、中性粒细胞及炎症指标水平、明确感染程度并排除全身感染；完善鼻内镜检查直接观察鼻中隔黏膜充血膨隆及有无波动感、明确脓肿范围；鼻中隔脓肿可破坏鼻中隔软骨并继发颅内感染，完善鼻窦CT检查明确病变范围、排除鼻窦炎及眶内、颅内并发症；完善颞骨CT检查了解中耳乳突情况、排除中耳乳突炎；患者发热伴鼻部感染，需除外合并中耳及咽部感染，完善耳镜检查了解鼓膜情况、排除中耳炎；完善喉镜检查排除喉咽部感染；患者鼻中隔脓肿致鼻塞可影响咽鼓管通气，完善声导抗检查了解中耳传音功能；为基线评估听功能，完善纯音测听检查了解听力水平；患者鼻部感染可致颈部淋巴结肿大，完善颈部超声检查了解颈部淋巴结情况、必要时鉴别有无脓肿形成；患者发病以来伴轻度乏力，完善前庭功能检查排除前庭功能障碍。\n\n（检查清单）\n【必做检查】\n血常规、耳镜检查、鼻内镜检查、喉镜检查\n\n【影像学检查】\n鼻窦CT、颞骨CT、颈部超声\n\n【其他检查】\n纯音测听、声导抗、前庭功能检查","初步诊断":"1. 鼻中隔脓肿\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗感染：阿莫西林克拉维酸钾片 0.625g（含阿莫西林0.5g）口服 bid×7天，覆盖金黄色葡萄球菌、链球菌等常见致病菌；青霉素过敏者改用头孢呋辛酯片 0.25g bid×7天，头孢菌素类亦过敏者改用左氧氟沙星片 0.5g qd×7天。\n2. 抗厌氧菌：甲硝唑片 0.4g tid×7天，口服，覆盖口腔及鼻腔常见厌氧菌混合感染。\n3. 对症镇痛：布洛芬缓释胶囊 0.3g bid 口服，疼痛明显时服用，疗程≤3天；或对乙酰氨基酚片 0.5g prn，每日总量不超过2g。\n\n【一般治疗及生活指导】\n1. 脓肿未切开引流者应尽快行切开引流；已切开者保持引流口通畅，每日以生理盐水冲洗鼻腔2次，严禁自行挤压、搔抓鼻部脓腔。\n2. 避免用力擤鼻、挖鼻及剧烈喷嚏，减少黏膜损伤，防止感染扩散或导致鼻中隔穿孔。\n3. 清淡易消化饮食，多饮水，忌辛辣刺激食物及烟酒；注意休息，避免熬夜与剧烈运动。\n4. 密切观察病情变化，若出现剧烈头痛、高热不退、眼球突出、视力下降或意识改变，提示眶内或颅内并发症可能，须立即急诊就医。\n\n【随诊要求】\n1. 用药后3～5天复诊，评估鼻部红肿、疼痛、引流情况及全身症状，必要时复查血常规、CRP。\n2. 切开引流者每2～3天复诊换药，保持引流通畅，直至脓腔闭合。\n3. 抗生素疗程结束后1周复诊，行鼻内镜检查评估鼻中隔黏膜愈合情况，排查鼻中隔穿孔、软骨坏死等并发症。\n4. 治疗期间若鼻塞加重、发热持续不退，或出现眼部、神经系统症状，随时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":601,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d4b7bf42ab8ff4a0e06023163f3a46c7835851830ccc440cd4217b7e12726f2f","pinyin":"bizhonggenongzhong","initials":"bzgnz","setting":"out","caseName":"门诊病历466","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历466",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1dbe36c9454b46aa4bf4","key":"v1-c9ccc21dfe2a3058|templates-1dbe36c9454b46aa4bf4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"鼻腔异物","category":"门诊病历模板","raw":{"name":"鼻腔异物","category":"门诊病历模板","case":{"case_name":"门诊病历467","templates":{"主诉":"单侧鼻塞、脓涕伴鼻臭3天","现病史":"患儿为儿童（1～5岁最常见，多因好奇将豆类、珠子、纽扣、纸团、玩具零件、瓜子、果核等小物塞入鼻腔）；成人少见，异物可为鼻内医源性（如棉片遗留）、外伤（石子、弹片）所致，或为鼻石（长期异物钙化形成鼻石症，慢性病程，伴臭味）。多于1天前（塞入时间可由家长目击或不明）出现单侧鼻塞（异物堵塞，以一侧为主，此点重要，单侧症状提示异物）、单侧脓涕（异物继发感染，呈黏脓涕，单侧为其特征）、鼻臭（异物腐烂或感染所致，为重要线索，幼儿出现单侧臭味应先考虑异物）、鼻出血（异物损伤黏膜）、打喷嚏（刺激所致）。儿童可表现为哭闹、烦躁、抠鼻，家长可发现不明原因的单侧脓涕及臭味，应注意查异物，此点重要。需了解有无发热（继发感染或鼻窦炎）、异物性质（是否具腐蚀性或为电池，其中纽扣电池在鼻腔内形成碱液、腐蚀黏膜，可致穿孔，属急症，需紧急取出，重要；豆类吸水膨胀可加重堵塞；尖锐物可刺入；若异物吸入进入气道可致呛咳，应警惕，取出时须防坠入气道）、单侧脓涕臭味持续时间及自行取出的尝试（家长勿挖取，以免推入更深或造成损伤）。今日来我院耳鼻喉科或急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P120次/分，R28次/分，BP90/60mmHg。鼻：前鼻镜及鼻内镜检查（核心），可见鼻腔异物，需记录位置（下鼻道、总鼻道或后鼻孔）、性质（观察形态、颜色以鉴别），周围黏膜充血、肿胀，可见脓涕包裹，长期异物可形成肉芽，可伴出血，注意鼻中隔有无损伤；对侧鼻腔亦应检查，以排除另侧异物；咽部注意有无异物脱入；耳部未见异常；颈部未见异常。呼吸情况需评估，警惕异物脱入气道引起呛咳、呼吸困难。","辅助检查":"【必做】前鼻镜及鼻内镜（核心，可直视，多数异物可见）；【影像】X线或CT，用于不透X线异物（金属、骨性）的定位，或疑后鼻孔及深部异物（鼻内镜未见于前部者行CT）；透光异物（如豆类）不显影，须靠鼻内镜检查；【其他】电池异物属紧急情况（纽扣电池可腐蚀黏膜，需急诊取出，不必依赖影像）；疑异物吸入者行胸片以评估气道。","初步诊断":"1. 鼻腔异物（左侧鼻腔异物，以纽扣电池可能性大，属急症；伴继发感染及鼻窦炎评估）\n（注：治疗以取出异物为主，方法依位置及性质而定，儿童需配合：①取出：应由耳鼻喉科或急诊专业处理，宜内镜直视下进行，用鼻腔异物钩或吸引器，圆滑异物经异物钩绕过钩出，避免用镊子夹取（圆滑异物易被推入更深或坠入气道，重要；圆异物患者钩或吸引器，不用镊子），光滑异物可用负压吸出，鼻内镜下直视操作较安全；后鼻孔异物可推至咽部后吐出或取出。②纽扣电池：属紧急情况，电池电解腐蚀鼻黏膜，数小时内即可致穿孔及瘢痕狭窄，需急诊取出（24小时内，重要），取出后以大量生理盐水冲洗，并随访黏膜愈合及穿孔情况。③豆类：吸水膨胀，应尽早取出，以防膨胀后堵塞加重。④儿童配合：需固定（家长抱扶或约束），可予表面麻醉（利多卡因喷鼻）减痛，操作应轻柔，防出血及损伤。⑤术后：继发感染、脓涕者予抗生素（口服或局部，头孢或阿莫西林克拉维酸）、鼻用激素（减轻黏膜肿胀）、鼻腔冲洗，并随访黏膜愈合及鼻窦炎消散情况，定期复查。⑥预防：宣教家长使小物远离幼儿（豆类、珠子、纽扣等应收纳，重要）；儿童塞入异物后应立即就医（勿自行挖取，以防推深及损伤）；注意玩具安全（小零件按年龄管理）。建议耳鼻喉科就诊；强调内镜取出、电池属急诊、防坠入气道及健康教育，均属重要。","处理方案":"【药物治疗】\n1. 抗菌药物（异物取出后伴黏膜损伤或污染者）：阿莫西林胶囊0.5g，口服，每日3次，连用3～5天（青霉素过敏者改用阿奇霉素片0.5g，每日1次，连用3天）。\n2. 鼻用减充血剂（缓解鼻塞）：盐酸羟甲唑啉鼻喷剂（如达芬霖），每侧鼻腔1喷，每日2次，连续使用不超过7天。\n3. 局部抗菌软膏（鼻腔黏膜擦伤、糜烂者）：莫匹罗星软膏（百多邦），以棉签涂于鼻前庭及损伤处，每日2次，连用3～5天。\n4. 黏液促排剂（分泌物黏稠量多者）：桉柠蒎肠溶软胶囊0.3g，口服，每日3次，连用5～7天。\n\n【一般治疗及生活指导】\n1. 异物取出后24小时内避免用力擤鼻、挖鼻及用力喷嚏，防止鼻腔出血和感染扩散；保持鼻腔清洁，可用生理盐水冲洗，每日1～2次。\n2. 观察鼻腔出血情况：少量血性分泌物多可自行停止；若出血持续不止或出血量较大，应立即就医。\n3. 饮食：忌辛辣、过热及过硬饮食，减少对鼻腔黏膜的刺激；适量多饮水，保持鼻黏膜湿润。\n4. 活动与看护：避免剧烈运动、游泳及潜水；儿童勿将豆类、纽扣、玩具零件等小物件塞入鼻腔，家长加强看护并进行安全教育。\n\n【随诊要求】\n1. 异物取出后1～2天复诊，复查鼻腔，确认异物完全取出、无残留及黏膜损伤情况。\n2. 若出现发热、脓性涕伴臭味、鼻塞加重、反复鼻出血或呼吸不畅，应及时复诊。\n3. 异物存留时间较长、已并发鼻窦炎或肉芽组织形成者，按医嘱每3～7天定期复诊，直至炎症消退。\n4. 幼儿或怀疑有异物残留者，建议3～5天内行鼻内镜检查复查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":602,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3be21283bd52a9f6c12265964b1f8d604c9a48876b5032696b5ba92e9a062aad","pinyin":"biqiangyiwu","initials":"bqyw","setting":"out","caseName":"门诊病历467","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历467",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-525cacd36fc89a5e2922","key":"v1-c9ccc21dfe2a3058|templates-525cacd36fc89a5e2922","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"鼻息肉","category":"门诊病历模板","raw":{"name":"鼻息肉","category":"门诊病历模板","case":{"case_name":"门诊病历468","templates":{"主诉":"进行性鼻塞伴嗅觉减退3年","现病史":"患者于____（慢性鼻窦炎基础（鼻息肉常与慢性鼻窦炎并存；慢性鼻窦炎伴鼻息肉（CRSwNP），嗜酸性粒细胞型（我国部分）、哮喘（阿司匹林耐受不良（阿司匹林加重性呼吸疾病，AERD，鼻息肉+哮喘+阿司匹林过敏，Widal三联征，我国少见但存在）、变应性鼻炎、囊性纤维化（西方，儿童，全身）、纤毛不动（卡塔格纳综合征，儿童）），渐进，数年）出现：____（鼻塞（进行性，双侧，越来越重，鼻息肉堵塞，张口呼吸，打鼾）、嗅觉减退/丧失（嗅裂堵塞/炎症，重要，鼻息肉常见，嗅觉下降）、流涕（黏液/黏脓涕，后鼻滴漏）、头痛面部胀痛（鼻窦炎并见）、打鼾/睡眠呼吸暂停（堵塞）、咽喉（分泌物倒流，咳嗽）、____（有无单侧鼻息肉（重要，单侧，警惕，内翻性乳头状瘤（鼻窦，单侧肿物，易出血，瘤，需手术，病理，与鼻息肉鉴别，重要）、后鼻孔息肉（儿童青少年，单侧，源于上颌窦，长蒂，脱至后鼻孔，鼻咽堵塞）、出血（多无，鼻息肉少出血，若出血，其他）、哮喘（并存，控制）、阿司匹林（过敏史，Widal）、过敏（变应性鼻炎）、儿童（囊性纤维化，全身），手术史（既往鼻息肉手术，复发，常见，重要））。今日来我院耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP120/76mmHg。鼻（行前鼻镜或鼻内镜检查（为检查核心，可观察鼻腔息肉（呈灰白色、半透明、表面光滑、荔枝肉样、质软、活动度好、无压痛、触碰不易出血，可堵塞鼻道（需记录数量、大小、位置），常为双侧）、嗅裂（可见息肉堵塞）、鼻道（可见分泌物、息肉堵塞，影响鼻窦引流）、黏膜（可见水肿，提示过敏）、鼻中隔（可见偏曲））、咽（需检查后鼻孔有无息肉）、耳（注意有无分泌性中耳炎，咽鼓管功能可受鼻息肉影响）、肺（注意有无哮喘，听诊有无哮鸣音）。","辅助检查":"【必做】鼻内镜（核心：确诊及评估）；【影像】鼻窦CT（冠状位，鼻窦（密度增高，软组织影，息肉（双侧窦腔占位）、骨质（单侧膨胀/破坏，内翻性乳头状瘤/肿瘤，警示）、窦口复合体（堵塞，评估），手术前，评估范围，重要）；【过敏/哮喘】过敏原检测（变应性鼻炎并见）、肺功能（哮喘，评估）、阿司匹林激发（疑Widal，专科，谨慎）；【病理】（手术切除，组织病理（息肉，炎性，排除内翻性乳头状瘤（单侧，上皮内翻，复发及恶变，鳞癌，风险，病理，重要，切除送检）；儿童囊性纤维化：汗液试验）。","初步诊断":"1. 慢性鼻窦炎伴鼻息肉（CRSwNP，双侧，嗜酸性，伴哮喘、变应性鼻炎或阿司匹林耐受不良，需评估复发风险）\n（注：治疗以药物与手术结合、防复发为核心，属慢性病综合管理：①药物治疗（为一线，可控制炎症、缩小息肉）：鼻用糖皮质激素（如糠酸莫米松或氟替卡松鼻喷剂，长期患者，为抗炎核心，能缩小息肉、控制症状、防复发，术后维持尤为重要）、口服糖皮质激素（短程用于大息肉或急性加重，泼尼松30~40mg/d×7~14天，可缩小息肉，为手术准备或术后防复发，须注意副作用，仅短程使用）、生理盐水冲洗（每日清洁鼻腔、促进引流，为辅助治疗）、白三烯受体拮抗剂（如孟鲁司特，用于伴哮喘或过敏者）、抗组胺药（用于伴变应性鼻炎者）、生物制剂（度普利尤单抗（抗IL-4/13，用于重度难治性CRSwNP，近年获批，可缩小息肉、改善嗅觉，疗效显著，为新进展，用于手术后复发或重度者，需专科评估，重要）、奥马珠单抗（抗IgE，用于重度并伴哮喘者）、美泊利单抗（抗IL-5，用于嗜酸性者））；②手术（指征为药物控制不佳、大息肉堵塞、嗅觉丧失影响生活、出现并发症（鼻窦炎引流受阻）、疑内翻性乳头状瘤或肿瘤（需手术加病理）；术式为功能性鼻内镜手术（FESS），切除息肉并开放鼻窦、引流、改善症状，嗅觉可部分恢复，早期手术效果好；手术不能根治，因属慢性病、复发率高，术后需药物维持（激素喷鼻，长期患者，重要，防复发））；③合并症处理（哮喘需规范治疗（吸入激素控制）、阿司匹林不耐受（Widal三联征）者应避免阿司匹林及NSAIDs以防加重，急性发作时及时处理、变应性鼻炎可行脱敏治疗）；④随访（术后鼻腔冲洗加激素喷鼻，定期内镜检查、监测息肉复发，复发者依范围再治疗（激素、生物制剂或再次手术）、评估嗅觉恢复、单侧病变者需病理随访，警惕乳头状瘤复发及恶变，需监测）；本病由耳鼻喉科诊治，以药物为核心、手术为手段，术后长期用药，重度者可用生物制剂，防复发与长期管理很重要。","处理方案":"【药物治疗】\n1. 鼻用糖皮质激素（一线首选）：糠酸莫米松鼻喷雾剂（内舒拿）每次每侧鼻腔2喷（每喷50μg），每日1次晨起喷鼻，总量200μg/日，症状控制后减为每侧1喷维持，疗程至少3个月。\n2. 口服糖皮质激素（中重度或保守治疗2周无效者）：泼尼松片30-40mg（或0.5mg/kg）晨起顿服，连用5-7天，后每3-5天减量5mg，总疗程不超过2周，用药期间监测血压、血糖。\n3. 白三烯受体拮抗剂（合并哮喘或阿司匹林耐受不良者）：孟鲁司特钠片10mg，每晚睡前口服，疗程4-8周。\n4. 鼻腔冲洗及黏液促排：生理盐水鼻腔冲洗，每次每侧约200ml，每日1-2次，疗程至少4周；可联合桉柠蒎肠溶软胶囊0.3g tid，餐前半小时口服，连用2周。\n【一般治疗及生活指导】\n1. 保持鼻腔清洁湿润：每日生理盐水冲洗鼻腔，勿用力擤鼻、挖鼻、拔鼻毛，避免损伤黏膜诱发出血或继发感染。\n2. 避免过敏原与刺激物：远离粉尘、花粉、尘螨、动物皮毛等过敏原，戒烟限酒，避免二手烟及刺激性气体，空调环境注意通风加湿。\n3. 预防感冒：注意保暖、规律作息、适当锻炼增强体质；感冒或急性鼻炎发作时及时规范治疗，避免反复上呼吸道感染诱发息肉复发。\n4. 合理饮食：清淡饮食、多饮水，忌辛辣刺激及过烫食物；超重者建议减重，肥胖是鼻息肉复发的重要危险因素。\n【随诊要求】\n1. 用药2周后复诊，评估鼻塞、嗅觉、流涕等症状改善情况，必要时行鼻内镜检查评估息肉大小及鼻窦情况。\n2. 治疗期间每1-3个月复查鼻内镜，评估疗效及有无复发；鼻用激素至少规律使用3个月，不可自行停药。\n3. 如出现单侧鼻塞进行性加重、反复鼻出血、面部胀痛、脓涕增多伴发热等，应及时复诊；保守治疗3个月无效或息肉巨大阻塞明显者，转诊耳鼻喉科评估鼻内镜下息肉切除手术。\n4. 合并哮喘或阿司匹林耐受不良者，每3-6个月行肺功能及专科随访，控制合并症以降低复发率。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":603,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"176bd6fb959d5ae4790b9f35dac4432f047059bd9965e7d0cd7633b293bbc83d","pinyin":"bixirou","initials":"bxr","setting":"out","caseName":"门诊病历468","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历468",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4e5872627589f9620a93","key":"v1-c9ccc21dfe2a3058|templates-4e5872627589f9620a93","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"鼻窦囊肿","category":"门诊病历模板","raw":{"name":"鼻窦囊肿","category":"门诊病历模板","case":{"case_name":"门诊病历469","templates":{"主诉":"鼻塞伴面部胀痛1周","现病史":"患者1周前无明显诱因出现鼻窦囊肿相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者鼻塞伴面部胀痛1周，完善鼻窦CT检查明确囊肿部位、大小及与鼻窦引流通道的关系、了解有无骨质压迫吸收；完善鼻内镜检查了解中鼻道及鼻窦自然开口引流情况、必要时经鼻内镜观察囊液性质；患者面部胀痛伴鼻塞，完善血常规检查了解白细胞及中性粒细胞水平、排除感染与贫血；完善耳镜检查了解鼻咽部及鼓膜情况、排除中耳病变；完善喉镜检查排除喉部病变；完善颞骨CT检查了解中耳乳突及内耳结构、排除中耳病变；患者鼻窦囊肿可压迫咽鼓管导致中耳功能障碍，完善声导抗检查了解中耳传音功能；为基线评估听功能，完善纯音测听检查了解听力水平；患者鼻窦病变可致颈部淋巴结反应性增生，完善颈部超声检查了解颈部淋巴结及软组织情况；患者发病以来伴轻度乏力，完善前庭功能检查排除前庭功能障碍。\n\n（检查清单）\n【必做检查】\n血常规、耳镜检查、鼻内镜检查、喉镜检查\n\n【影像学检查】\n鼻窦CT、颞骨CT、颈部超声\n\n【其他检查】\n纯音测听、声导抗、前庭功能检查","初步诊断":"1. 鼻窦囊肿\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.黏液促排剂：桉柠蒎肠溶软胶囊（切诺）0.3g，口服，每日3次，餐前半小时用凉开水整粒吞服，疗程2周；亦可选用标准桃金娘油肠溶胶囊（吉诺通）300mg，口服，每日3次。\n2.糖皮质激素鼻喷剂：糠酸莫米松鼻喷雾剂（内舒拿）每侧鼻孔2喷（每喷50μg），每日1次，晨起使用，连续4周；或布地奈德鼻喷雾剂，每侧128μg，每日1次。\n3.合并感染时加用抗菌药物：阿莫西林克拉维酸钾片0.457g（按阿莫西林计0.4g），口服，每日3次，疗程7天；或头孢呋辛酯片0.25g，口服，每日2次，疗程7天。\n4.伴变应性鼻炎症状者：氯雷他定片10mg，口服，每日1次，疗程2周。\n\n【一般治疗及生活指导】\n1.注意休息，避免熬夜与过度劳累，加强营养，增强机体抵抗力。\n2.清淡饮食，多饮水，忌辛辣刺激、煎炸过烫食物，戒烟戒酒。\n3.正确擤鼻：单侧交替轻擤，避免用力擤鼻及抠挖鼻腔；每日用生理性海盐水鼻腔冲洗1-2次，保持鼻腔清洁通畅。\n4.避免受凉感冒及长时间处于粉尘、烟雾等污染环境；囊肿较大或出现面部胀痛、眼球突出、复视等症状时及时就诊。\n\n【随诊要求】\n1.用药2周后门诊复诊，复查鼻内镜及鼻窦CT，评估囊肿大小与症状改善情况。\n2.保守治疗无效、囊肿持续增大或出现面部畸形、眼胀、复视、视力下降等压迫症状者，建议转耳鼻喉科评估行鼻内镜下囊肿切除术。\n3.治疗期间如出现发热、剧烈头痛、眼部胀痛或视力骤降等，需立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":604,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3cb1bd79e36c380527fd3db6818f6e635376054628b6077f9f54202cfc355a5b","pinyin":"bidounangzhong","initials":"bdnz","setting":"out","caseName":"门诊病历469","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历469",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-087dc18e2d1658021121","key":"v1-c9ccc21dfe2a3058|templates-087dc18e2d1658021121","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"鼻腔鼻窦肿瘤","category":"门诊病历模板","raw":{"name":"鼻腔鼻窦肿瘤","category":"门诊病历模板","case":{"case_name":"门诊病历470","templates":{"主诉":"单侧鼻塞伴血性鼻涕1周","现病史":"患者1周前无明显诱因出现鼻腔鼻窦肿瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以单侧鼻塞伴血性鼻涕1周为主诉，单侧鼻塞进行性加重并反复血性分泌物是鼻腔鼻窦肿瘤的重要警示征象，入院后完善血常规检查排除感染、贫血及血液系统疾病所致出血；查耳镜检查以了解鼓膜及外耳道情况，排除肿瘤经咽鼓管累及中耳所致耳部症状；行鼻内镜检查以直观了解鼻腔鼻窦内新生物的部位、范围、表面形态及出血情况，必要时取活检明确病理性质；查喉镜检查以明确喉部有无受累，排除肿瘤向下侵犯所致声嘶、吞咽不适；完善鼻窦CT检查以明确肿瘤累及鼻窦范围及骨质破坏情况，评估手术可切除性；查颞骨CT了解颞骨及中耳有无受累，为手术方案提供依据；行颈部超声检查了解颈部淋巴结有无肿大转移，评估临床分期；查纯音测听以了解听力受损程度，评估肿瘤或积液对听力的影响；行声导抗检查了解鼓室压及中耳积液情况，鉴别分泌性中耳炎所致听力下降；完善前庭功能检查以评估前庭功能状态，鉴别头晕是否由前庭受累所致。\n\n（检查清单）\n【必做检查】\n血常规、耳镜检查、鼻内镜检查、喉镜检查\n\n【影像学检查】\n鼻窦CT、颞骨CT、颈部超声\n\n【其他检查】\n纯音测听、声导抗、前庭功能检查","初步诊断":"1. 鼻腔鼻窦肿瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 预防感染（活检/术后）：阿莫西林克拉维酸钾片0.375g po tid×5天；青霉素过敏者改用头孢呋辛酯片0.25g po bid×5天。\n2. 止血及创面保护：氨甲环酸片0.5g po tid×3~5天，配合云南白药胶囊0.5g po tid×3天；出血明显时加用酚磺乙胺片0.5g po tid。\n3. 减轻术腔水肿、控制局部炎症：布地奈德鼻喷雾剂（64μg/喷）每侧鼻腔1喷 bid，连用4周；鼻腔干燥结痂者加用生理性海水鼻腔喷雾剂喷鼻 tid。\n4. 黏液促排、改善引流：桉柠蒎肠溶软胶囊0.3g po tid×2周，餐前半小时凉开水送服。\n【一般治疗及生活指导】\n1. 休息：活检或术后1周内避免剧烈运动、重体力劳动及长时间低头，避免用力擤鼻、剧烈咳嗽，打喷嚏时张口，以防创面出血。\n2. 饮食：清淡、温凉、易消化软食为主，忌过热、过硬及辛辣刺激食物，戒烟戒酒，多饮水保持鼻腔湿润。\n3. 活动与环境：避免高温、干燥及粉尘烟雾环境，避免热水浴、桑拿，外出可戴口罩减少刺激。\n4. 禁忌：禁止抠鼻、挖鼻及自行拔除鼻腔痂皮，避免反复用力吸气，防止鼻出血及创面感染。\n【随诊要求】\n1. 活检或术后1~2周复诊，查看病理结果并行鼻内镜检查、评估创面愈合情况。\n2. 术后第1年每1~3个月复查鼻内镜及鼻窦CT/MRI，第2年每3~6个月复查，此后每6~12个月复查，连续随访至少5年。\n3. 出现鼻出血、鼻塞进行性加重、患侧疼痛、面部肿胀、复视或视力下降、颈部肿块等异常，随时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":605,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"38f466a9da5a66f91a41198636a9028748b6eb7e7bc23dd61bc48f26b2fa5fb6","pinyin":"biqiangbidouzhongliu","initials":"bqbdzl","setting":"out","caseName":"门诊病历470","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历470",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f1bf9f843cedd9abbca1","key":"v1-c9ccc21dfe2a3058|templates-f1bf9f843cedd9abbca1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腺样体肥大","category":"门诊病历模板","raw":{"name":"腺样体肥大","category":"门诊病历模板","case":{"case_name":"门诊病历471","templates":{"主诉":"夜间打鼾、张口呼吸1年","现病史":"患儿（儿童（3~7岁高发，腺样体（咽扁桃体，生理性肥大，6~7岁达峰，后萎缩），病理性肥大（反复感染/过敏，增生，堵塞后鼻孔及咽鼓管咽口））于____出现：____（鼻塞/张口呼吸（夜间，明显，打鼾（响亮，持续）、张口呼吸（睡眠及清醒，唇干，腺样体面容（长期，张口，上唇短翘，腭弓高，牙列不齐，表情呆滞，腺样体面容，长期，颌面发育影响，重要）、睡眠呼吸暂停（睡眠中，呼吸暂停，憋气，惊醒，睡眠不安，夜间缺氧，白天，嗜睡/注意力不集中/多动（影响学习，行为，重要）、打鼾）、分泌性中耳炎（咽鼓管咽口堵塞，中耳积液，听力下降，反复中耳炎，影响听力语言）、鼻窦炎（后鼻孔堵塞，引流不畅，反复鼻塞脓涕）、反复上呼吸道感染、咳嗽（夜咳，分泌物倒流）、生长发育（缺氧，生长激素，影响身高，体重，重要）、注意力，学习，行为（缺氧，多动，成绩下降，重要），扁桃体（常并见肥大（扁桃体+腺样体，共同堵塞）），病史（反复鼻炎扁桃体炎、过敏（变应性鼻炎）、打鼾持续时间、张口呼吸日夜、中耳炎发作次数、注意力学习）。今日来我院耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P100次/分，R22次/分，BP96/60mmHg。鼻咽部（行间接鼻咽镜或纤维鼻内镜检查（为检查核心，重点评估腺样体（大小（堵塞后鼻孔约3/4，属重度）、表面（光滑、色淡红）））、鼻（检查后鼻孔有无堵塞，鼻黏膜有无充血）、咽（扁桃体（大小为Ⅱ度）、软腭（观察抬高及活动，可因腺样体堵塞而受限））、耳（鼓膜（注意分泌性中耳炎、中耳积液、鼓膜内陷）、听力（粗测））、口腔（观察张口呼吸、腭弓、牙列，评估有无腺样体面容）、全身（评估生长发育（身高体重及百分位）、注意力（评估）、心肺（注意有无肺动脉高压，严重者少见，多因慢性缺氧）。","辅助检查":"【必做】纤维鼻咽镜（为检查核心，用于腺样体堵塞评估）；【影像】鼻咽侧位X线（评估腺样体（大小、堵塞后鼻孔比例、腺样体/鼻咽腔比率））、睡眠呼吸监测（多导睡眠图，用于打鼾憋气者，可诊断阻塞性睡眠呼吸暂停（OSA），儿童需观察呼吸暂停低通气指数，判断严重度，为手术指征，重要）；【其他】声导抗及听力检查（评估分泌性中耳炎、中耳积液）、过敏原检测（评估变应性鼻炎等过敏因素）、腺样体面容评估（颌面情况，需正畸评估，注意远期影响）。","初步诊断":"1. 腺样体肥大（儿童，堵塞后鼻孔重度，伴扁桃体肥大、分泌性中耳炎及OSA（睡眠呼吸暂停低通气指数升高），需评估腺样体面容及发育影响）\n（注：治疗（保守或手术，依堵塞程度、症状及OSA情况而定，儿童）：①保守治疗（适用于轻中度、无OSA及无并发症者）：治疗鼻部炎症（鼻用糖皮质激素（如糠酸莫米松喷鼻，可减轻腺样体及鼻黏膜炎症，部分患儿腺样体可缩小、症状改善，疗程1~3个月，有效者可先试用，重要）、抗组胺药（用于过敏者）、生理盐水冲洗）；观察（腺样体肥大属生理性，可随年龄增长而萎缩（青春期缩小），轻度者可随访观察）；②手术（腺样体切除术（适应证为重度堵塞（后鼻孔完全或近完全堵塞，张口呼吸、打鼾明显）、阻塞性睡眠呼吸暂停（已确诊OSA，呼吸暂停低通气指数高，存在缺氧，重要，为明确手术指征，可防发育、学习及心肺功能受影响）、反复分泌性中耳炎（因腺样体影响咽鼓管，可切除加鼓膜置管（联合手术，可减少中耳炎复发，重要）、反复鼻窦炎、疑腺样体肥大已影响发育（如腺样体面容进行性加重、颌面改变））；手术方式为腺样体切除，可用低温等离子微创、内镜直视下彻底切除，并同期评估扁桃体（肥大者同时切除，需评估堵塞情况）、术后注意出血（观察）、饮食（温凉）、打鼾改善（术后张口呼吸可逐渐改善，长期张口者面容部分可逆，颌面异常必要时正畸）；③随访（术后评估打鼾、张口呼吸及OSA改善情况（术后1~3个月复查）、中耳炎需复查听力、复发（腺样体再生少见，需再次评估）、未手术者需观察腺样体大小及症状变化（每年复查））；本病由耳鼻喉科及儿科共同管理，OSA者应明确手术指征，以防发育受影响，扁桃体与腺样体可联合处理，强调个体化与随访，重要。","处理方案":"【药物治疗】\n1. 鼻用糖皮质激素：丙酸氟替卡松鼻喷雾剂（辅舒良），每侧鼻孔各1喷（50μg），每日2次，疗程4~8周，可减轻腺样体及周围淋巴组织炎性水肿。\n2. 白三烯受体拮抗剂：孟鲁司特钠片10mg，睡前口服，每日1次，疗程4~8周，适用于合并过敏性鼻炎或腺样体炎性增生的患者。\n3. 黏液促排剂：桉柠蒎肠溶软胶囊0.3g，餐前半小时口服，每日3次，疗程2~4周，促进鼻腔及鼻咽部分泌物排出、减轻鼻塞。\n4. 若合并变应性鼻炎症状（喷嚏、清涕、眼痒），加用氯雷他定片10mg，每日1次口服，疗程2~4周。\n\n【一般治疗及生活指导】\n1. 保持鼻腔清洁：每日生理性海盐水鼻腔冲洗1~2次，减少分泌物潴留及反复感染刺激。\n2. 生活规律、保证充足睡眠，适度有氧运动（如快走、游泳）以增强体质，避免劳累及熬夜，减少上呼吸道感染诱发腺样体急性炎症。\n3. 饮食清淡，忌辛辣、油炸及过冷过热食物，戒烟戒酒，避免刺激性气体及二手烟、雾霾等空气污染环境。\n4. 注意保暖，预防感冒；反复感冒、鼻窦炎是腺样体肥大的主要诱因，应积极规范治疗急性感染。\n\n【随诊要求】\n1. 用药4周后复诊，评估鼻塞、打鼾、张口呼吸等症状改善情况；症状缓解不理想者复查鼻内镜或鼻咽侧位X线片，评估腺样体大小变化。\n2. 保守治疗8周仍无明显改善，或出现睡眠呼吸暂停（憋醒、呼吸暂停、白天嗜睡）、分泌性中耳炎、反复发作的鼻窦炎或听力下降等并发症时，及时复诊评估手术指征（腺样体切除术）。\n3. 治疗期间如出现鼻出血、严重头痛、耳痛或症状进行性加重，应立即就诊，不可自行延长用药时间。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":606,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7a3c5de6cf107caf6b15ce622236b52f6df8756f78041320fa3de5b73cc05f16","pinyin":"xianyangtifeida","initials":"xytfd","setting":"out","caseName":"门诊病历471","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历471",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8697d8823611d9398ed2","key":"v1-c9ccc21dfe2a3058|templates-8697d8823611d9398ed2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性扁桃体炎","category":"门诊病历模板","raw":{"name":"慢性扁桃体炎","category":"门诊病历模板","case":{"case_name":"门诊病历472","templates":{"主诉":"反复咽痛伴咽部异物感3年","现病史":"患者于3年来反复急性扁桃体炎发作（每年7次，均有咽痛、发热、化脓，每次需抗生素治疗）、咽部不适（异物感、干痒、晨起清嗓）、口臭（由扁桃体隐窝内分泌物及干酪样物所致（隐窝内可见白色小点，可挤出，有臭味））、咳嗽（咽部刺激所致）、吞咽不适、打鼾（扁桃体肥大者可堵塞咽腔，儿童严重时出现睡眠呼吸暂停、张口呼吸，重要）、低热乏力（慢性感染所致全身表现）；并发症方面：无扁桃体周围脓肿病史（该病属急症）、无风湿热病史（既往链球菌感染可累及心瓣膜及关节，即风湿性心脏病，我国仍可见）、无链球菌感染后肾小球肾炎（无血尿、水肿），睡眠呼吸暂停需进一步评估（儿童肥大者缺氧可影响生长发育及注意力，为切除指征，重要）；反复发作已影响学习、工作及生活；既往抗生素使用频繁，需评估耐药情况。今日来我院耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.2℃，P88次/分，R19次/分，BP112/70mmHg。咽部：扁桃体（慢性充血（呈暗红色）、肿大（Ⅲ度，已近中线，属肥大，儿童尤需注意）、隐窝（可见分泌物及干酪样栓，挤压时溢脓或排出干酪样物，为口臭来源）、表面（可见瘢痕、凹凸不平，符合慢性炎症改变）、腭弓（充血，部分粘连）、下颌角淋巴结（可肿大））；儿童需注意是否合并腺样体肥大（可有张口呼吸，应同时评估扁桃体及增殖体肥大）；心肺（注意风湿热相关心脏杂音，需评估）。","辅助检查":"【必做】以临床检查为主（隐窝脓栓为慢性扁桃体炎的体征）；【其他】急性发作时查血常规、CRP、咽拭子培养（链球菌，急性期）、抗链球菌溶血素O（疑风湿热者，于发作后检测）、尿常规（筛查链球菌感染后肾炎，适用于反复链球菌感染者）、睡眠呼吸监测（儿童肥大伴打鼾、呼吸暂停者行OSA评估，儿童多用多导睡眠图）、扁桃体肥大影像（较少用，怀疑堵塞时可拍X线，必要时）；【鉴别】需与扁桃体角化症、肿瘤相鉴别（单侧扁桃体肿大、质硬、溃疡者应警惕淋巴瘤或鳞癌，不对称者重要，成人单侧肿大需活检）。","初步诊断":"1. 慢性扁桃体炎（反复急性发作型：每年≥7次，或连续2年每年≥5次；伴扁桃体Ⅲ度肥大，需评估睡眠呼吸暂停及并发症）\n（注：治疗（非急性期以保守治疗加评估切除指征为主）：①保守治疗（注意口腔卫生（漱口，可用氯己定或盐水，减少隐窝积存，改善口臭）、咽部不适（含片或漱口对症）、增强免疫（锻炼、营养，减少发作）；急性发作时规范抗感染（见急性扁桃体炎，针对链球菌，足疗程，如青霉素10天，以防风湿热，重要，勿反复短程用药））；②扁桃体切除（手术指征：反复急性发作（≥7次/年，或连续2年≥5次/年，或3年≥3次/年，为标准，已影响生活）、有扁桃体周围脓肿史（发作后应切除，防再发）、扁桃体肥大导致睡眠呼吸暂停或呼吸困难（儿童重要，打鼾憋气、缺氧可影响生长发育及认知，切除可改善，为明确指征）、疑肿瘤（单侧肿大者活检或切除，送病理）、病灶性扁桃体炎（疑与风湿热、肾炎相关者可切除，以减少发作，但证据需评估）、口臭顽固（隐窝因素所致者可切除）；手术方式为扁桃体切除，可用等离子或低温微创，恢复快；儿童手术时机一般在4岁以上，需结合反复感染及影响程度评估；③腺样体（儿童合并腺样体肥大者，若并见呼吸障碍或分泌性中耳炎，可同时行腺样体切除（与扁桃体同做，解除堵塞））；④随访（保守治疗者记录发作频率，达到标准即行手术评估；术后注意出血（术后需观察）、疼痛（1~2周逐渐恢复）、饮食（温凉流质））；本病由耳鼻喉科诊治，反复发作或肥大堵塞者考虑手术，需个体化处理，并防并发症（如风湿热），重要。","处理方案":"【药物治疗】\n1. 青霉素类（首选）：阿莫西林胶囊 0.5g 口服 tid×5~7天（用药前须青霉素皮试，过敏者禁用）。\n2. 头孢菌素类：头孢呋辛酯片 0.25g 口服 bid×5~7天（青霉素过敏者慎用）；青霉素及头孢均过敏者选用大环内酯类：阿奇霉素片 0.5g 口服 qd×3天。\n3. 局部用药：复方硼砂溶液（或温生理盐水）含漱 每日3~4次；西地碘含片（华素片）1片 含服 每4~6小时1次，每日不超过5片。\n4. 对症处理：发热或咽痛明显时，布洛芬缓释胶囊 0.3g 口服 bid（按需，餐后服用）。\n\n【一般治疗及生活指导】\n1. 急性发作期注意休息，多饮水，进温凉流质或半流质饮食，忌辛辣、过烫、过硬及煎炸食物，避免刺激咽部。\n2. 保持口腔清洁，饭后用淡盐水或含漱液漱口；戒烟限酒，避免被动吸烟及粉尘、刺激性气体环境。\n3. 加强体育锻炼，增强体质，规律作息，避免受凉、劳累、熬夜，预防感冒及上呼吸道感染，季节交替时注意保暖。\n4. 保持居室通风、温湿度适宜，避免长时间用嗓及过度喊叫。\n\n【随诊要求】\n1. 用药3~5天后复诊评估疗效；若咽痛、发热无缓解或加重，及时复诊调整治疗方案。\n2. 出现张口受限、一侧咽痛加剧、言语含糊、呼吸不畅等扁桃体周围脓肿表现，或高热持续不退，须立即急诊就诊。\n3. 反复急性发作（每年≥5次，或连续2年每年≥3次）者，建议至耳鼻喉科就诊，评估扁桃体切除术指征。\n4. 出现低热、关节疼痛、心悸气短、眼睑及下肢浮肿、血尿等表现时，需及时就诊排查风湿热、急性肾小球肾炎等全身并发症。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":607,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b8a74113aa34ab58509067478a58fa26e627d574d8393d8523433b05c11401f8","pinyin":"manxingbiantaotiyan","initials":"mxbtty","setting":"out","caseName":"门诊病历472","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历472",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c38f14b6604f5c8e3af9","key":"v1-c9ccc21dfe2a3058|templates-c38f14b6604f5c8e3af9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"扁桃体周围脓肿","category":"门诊病历模板","raw":{"name":"扁桃体周围脓肿","category":"门诊病历模板","case":{"case_name":"门诊病历473","templates":{"主诉":"一侧咽痛剧烈伴张口受限3天","现病史":"患者（青壮年多见）于5天前患急性扁桃体炎（咽痛、发热），治疗后未缓解并加重，3天前出现右侧咽痛剧烈（呈持续性，吞咽时尤甚）、张口受限（呈牙关紧闭样，张口度减小，为翼内肌受刺激所致）、语音含糊（呈口中含物样，即“热土豆”语音）、流涎（吞咽困难，不能进食饮水）、同侧耳痛（放射痛），伴发热（体温最高39.2℃，持续不退）、畏寒、乏力；无呼吸困难及喘鸣（罕见者可因脓肿向下蔓延致上气道梗阻，属严重情况）、无颈部肿胀压痛、无声音嘶哑；既往反复扁桃体炎史：反复发作3年，每年4~5次。今日来我院急诊耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.9℃，P104次/分，R22次/分，BP118/74mmHg。张口度约1.5cm（受限，2指以内）、咽部检查（一侧扁桃体及腭舌弓明显红肿膨隆（向中线推移，悬雍垂偏向对侧，为脓肿侧特征）、软腭红肿膨隆、扁桃体表面可见脓性渗出（或有扁桃体炎表现））、穿刺（在膨隆最明显处穿刺抽脓，抽得脓液即可确诊兼治疗，为关键操作）、颈部（颌下及颈深淋巴结肿大压痛）、呼吸（注意有无喘鸣或喉鸣，需评估气道）。","辅助检查":"【必做】诊断性穿刺（于膨隆处穿刺抽脓，证实脓液即可确诊，同时送培养）；【影像】穿刺阴性而高度疑诊或诊断不明时行颈部CT（增强，可定位脓肿（扁桃体周围、咽旁或咽后）、明确范围及与血管关系）或颈部超声；【其他】血常规（白细胞升高）、CRP、脓液细菌培养加药敏（多为链球菌及厌氧菌混合感染，培养可指导用药）、血糖（糖尿病为脓肿高危因素并影响愈合）。","初步诊断":"1. 扁桃体周围脓肿（右侧，为扁桃体炎并发症）\n（注：治疗（脓肿形成后需引流，单用抗生素难以治愈）：①穿刺抽脓（诊断兼初步治疗，于膨隆处穿刺，抽出脓液以减压）；②切开引流（穿刺后仍积脓或脓液黏稠者，行扁桃体周围脓肿切开（局部麻醉下于膨隆处切开，钝性分离进入脓腔，充分引流，每日扩创至无脓）），即时抽脓后多数症状可显著缓解；③抗生素（静脉广谱，覆盖链球菌及厌氧菌：青霉素或头孢曲松加甲硝唑（覆盖厌氧菌，关键），疗程7~10天（先静脉，症状缓解后改口服））；④对症（补液（吞咽困难致脱水者静脉补液）、镇痛（布洛芬）、退热）；⑤气道监护（脓肿增大致呼吸困难者需急诊处理，必要时行气管切开（极少数，存在气道梗阻风险））；⑥扁桃体切除（预防复发，反复扁桃体炎或有脓肿史者，于炎症消退后4~6周择期行扁桃体切除（尚有争议，单次脓肿可保守加随访，反复发作者则切除））；⑦并发症监测（脓肿向咽旁或咽后间隙蔓延时颈部肿胀疼痛加重、张口受限加重，需CT评估，深部感染应住院静脉用药加引流；败血症可出现高热寒战）；本病由耳鼻喉科急诊处理，多数引流后快速缓解，需随访以防复发及并发症。）","处理方案":"【药物治疗】\n1. 阿莫西林克拉维酸钾片（0.457g/片，按阿莫西林计）1片 po bid，共7天（覆盖β-内酰胺酶阳性菌群；青霉素过敏者改头孢呋辛酯片0.25g po bid或阿奇霉素片0.5g po qd）。\n2. 甲硝唑片0.4g po tid，共5～7天（覆盖厌氧菌，与主抗生素联用）。\n3. 布洛芬缓释胶囊0.3g po bid，退热止痛，体温正常、疼痛缓解后停用，一般3～5天（消化道溃疡、肾功能不全者禁用）。\n4. 复方氯己定含漱液含漱，每次10ml含漱2～3分钟，bid～tid，共7天（维持口腔清洁、减轻局部炎症）。\n【一般治疗及生活指导】\n1. 适当休息，保证充足睡眠，多饮温水，保持室内空气湿润；避免劳累及熬夜。\n2. 饮食以温凉流质、半流质为主（如粥、烂面条、藕粉），少量多餐，忌过热、过硬、辛辣、油炸及刺激性食物，以免刺激咽部诱发疼痛及出血。\n3. 严禁用力咳嗽、剧烈擤鼻、大声喊叫及强行吞咽，防止脓肿破裂引起窒息或脓液吸入；戒烟酒。\n4. 保持口腔卫生，餐后及睡前用温盐水或复方氯己定含漱液漱口，勿用手或棉签自行挤压咽部肿物。\n【随诊要求】\n1. 用药后48～72小时复诊，评估疼痛、发热、张口受限及咽部红肿情况；如症状无缓解或加重，需行咽部B超或穿刺检查，必要时行脓肿切开引流，并考虑住院静脉抗感染治疗。\n2. 治疗期间若出现一侧咽痛加剧、张口困难加重、言语含混、流涎、呼吸困难或颈部肿胀，立即急诊就诊，以防脓肿破入咽旁间隙或发生上气道梗阻。\n3. 若脓肿自行破溃或经穿刺排脓，须于1～2日内复诊评估引流是否充分，必要时复查血常规、CRP。\n4. 疗程结束后复查评估局部体征及炎症指标；既往有反复发作史者，建议炎症消退3～6周后专科门诊评估是否行扁桃体切除术，以预防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":608,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8975f970ac58d0d1fd2d06e3678a74c5c378472acf45c3d533b0aabdb29d383e","pinyin":"biantaotizhouweinongzhong","initials":"bttzwnz","setting":"out","caseName":"门诊病历473","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历473",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2066498ad2e203d61fcc","key":"v1-c9ccc21dfe2a3058|templates-2066498ad2e203d61fcc","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"咽后壁脓肿","category":"门诊病历模板","raw":{"name":"咽后壁脓肿","category":"门诊病历模板","case":{"case_name":"门诊病历474","templates":{"主诉":"发热、咽痛伴吞咽困难3天","现病史":"患儿（幼儿及儿童多见，因咽后间隙淋巴结丰富，感染后可化脓形成脓肿，3岁以下常见；3岁以上淋巴结渐萎缩，较少见；成人少见，多为结核性、外伤或异物所致（如鱼刺刺伤咽后壁、内镜损伤、椎体骨髓炎或结核（寒性脓肿）继发），亦可由邻近感染（鼻咽部、扁桃体、腺样体、中耳、乳突感染）引流所致）于3天前（上呼吸道感染后）出现：发热（多为高热）、咽痛（吞咽痛，患儿哭闹、拒食）、吞咽困难、流涎（因吞咽疼痛所致）、呼吸不畅（表现为鼻塞样呼吸声（鼾样），严重者因脓肿压迫气道出现呼吸困难，属急症，有窒息风险，重要）、颈部僵直（颈强直、头后仰过伸位以缓解气道受压，可闻及鸣声）、声音改变（呈含物声）；需注意有无气道急症（窒息、呼吸困难、发绀）、脓肿破溃（脓液流入气道致窒息、呛咳，属急症）、纵隔蔓延（向下蔓延致纵隔炎，出现胸痛、发热）、败血症；成人需注意结核（慢性低热、盗汗、寒性脓肿、颈椎结核）、异物（鱼刺及外伤史）。今日来我院耳鼻喉科及儿科急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T39.0℃，P120次/分，R28次/分，BP90/60mmHg。咽（检查时压舌板需轻，勿过度刺激以防脓肿破溃窒息，重要，操作应轻柔）、咽后壁（一侧隆起、红肿、有波动感（脓肿））、张口呼吸及流涎、颈部（淋巴结肿大、颈强直（头后仰））、呼吸（喘鸣或鼾样呼吸困难（需评估气道，重要）、发绀）、声音（含物声）、全身（发热、脱水、拒食）。","辅助检查":"【必做】颈部X线侧位（咽后间隙增宽（超过正常，即颈椎体前软组织影增宽，提示脓肿，儿童重要，可初筛）、椎前软组织影、气液平）、颈部CT（为核心，咽后脓肿呈低密度脓腔、环形强化，可定位、判断大小及范围、评估纵隔蔓延，为急症诊断金标准）、超声（可定位脓肿，儿童辅助）、血常规（白细胞升高）、CRP、血培养（疑败血症）；【确诊】穿刺（经口腔内咽后壁穿刺抽脓，可确诊兼引流，由耳鼻喉科操作，需备吸引器以防窒息，脓液送培养（病原需氧加厌氧））、结核相关（成人疑结核者查胸片及γ-干扰素释放试验）；【其他】气道评估（呼吸困难者请麻醉科及耳鼻喉科会诊，评估脓肿破溃及插管风险，宜在手术室内处理以保证安全）、异物（疑鱼刺者行CT评估）、纵隔（向下蔓延者行CT明确范围（胸内））。","初步诊断":"1. 咽后壁脓肿（咽后间隙感染，急性化脓性（儿童），需评估脓肿大小及气道压迫、纵隔蔓延及脓毒症，为急症处理）\n（注：治疗（属急症，气道优先，以引流加抗生素为原则）：①气道管理（首要措施：呼吸困难者经口腔内操作有破溃窒息风险，重要；怀疑脓肿者不可用压舌板乱戳，以防破溃后脓液流入气道；需请麻醉科及耳鼻喉科在手术室内行气管插管（备困难气道方案，若脓肿破溃，插管后需处理流入的脓液）；严重呼吸困难者先行气管切开，以保障气道安全）；②引流（经口引流（儿童多用：经口腔内切开引流，切开脓肿壁并吸引脓液（取头低位以防误吸），脓液送培养），必要时再次引流；或经颈部引流（适用于成人、复杂或延伸至纵隔者：经颈侧切口引流，纵隔受累时请胸外科处理））；③抗生素（静脉广谱，覆盖链球菌、金黄色葡萄球菌及厌氧菌（儿童常见混合菌），可用阿莫西林克拉维酸或头孢曲松加甲硝唑（覆盖厌氧菌），依培养结果调整，疗程7~14天）；④病因处理（结核性者行抗结核治疗（可穿刺或引流，寒性脓肿勿切开，以免形成瘘管），合并颈椎结核需骨科处理；异物所致者应取出异物（如鱼刺，经喉镜或内镜））；⑤并发症（防窒息（重点防脓肿破溃）、纵隔炎或纵隔脓肿（出现胸部症状时行CT，请胸外科引流）、败血症（查血培养并支持治疗）、肺炎（误吸所致））；⑥随访（退热情况（引流加抗生素后48小时评估）、吞咽功能恢复、复查CT（观察脓肿消退，大脓肿或复杂者）、复发（引流不充分时需评估，并查找病因如结核、异物）、气道稳定后拔管）；本病由耳鼻喉科及儿科急诊处理，以气道安全、引流及广谱抗生素为核心，重点防窒息及纵隔感染，重要。","处理方案":"【药物治疗】\n1.抗感染（首选，覆盖革兰阳性球菌及厌氧菌）：阿莫西林克拉维酸钾片（0.625g）0.625g 口服 tid，疗程7～10天；或头孢呋辛酯片0.25g bid，疗程7～10天。\n2.青霉素过敏者：克林霉素胶囊0.3g 口服 qid，疗程7～10天；或莫西沙星片0.4g qd，疗程7～10天。\n3.对症退热镇痛：布洛芬缓释胶囊0.3g 口服 bid，体温正常或疼痛缓解后停用。\n4.局部含漱：复方氯己定含漱液10ml 含漱 bid～tid，含漱后30分钟内不饮水、不进食。\n\n【一般治疗及生活指导】\n1.卧床休息，减少说话，避免剧烈咳嗽及用力吞咽；进食温凉流质或半流质（如米粥、蛋羹、藕粉），忌辛辣、过热、粗糙食物及烟酒。\n2.密切观察呼吸及吞咽情况：若出现呼吸困难、喘鸣、张口受限、颈部肿胀加重或高热不退，立即急诊就诊（脓肿增大可压迫气道）。\n3.多饮水，保持口腔清洁；禁止挤压、按摩颈前部及咽周区域，防止感染扩散。\n4.体温≥38.5℃时予物理降温，出汗多者注意补充水分与电解质。\n\n【随诊要求】\n1.用药后48～72小时复诊，评估咽痛、发热、吞咽困难改善情况；症状无缓解或加重者，行颈部CT/MRI明确脓肿范围，必要时住院行切开引流。\n2.疗程结束后复查血常规、CRP，评估炎症消退情况；症状持续者复查颈部影像学确认脓肿是否吸收。\n3.治疗期间一旦出现呼吸困难、声音嘶哑、流涎、端坐呼吸等气道梗阻征象，立即急诊处理，切勿延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":609,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cb5e876e5c599476ffda02537ebecb38dc4e71f0b7877b5bf00de89dd9442617","pinyin":"yanhoubinongzhong","initials":"yhbnz","setting":"out","caseName":"门诊病历474","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历474",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2408f389cfbd7cb574ef","key":"v1-c9ccc21dfe2a3058|templates-2408f389cfbd7cb574ef","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"咽异感症","category":"门诊病历模板","raw":{"name":"咽异感症","category":"门诊病历模板","case":{"case_name":"门诊病历475","templates":{"主诉":"咽部异物感3月","现病史":"患者于6个月前（间歇发作，与情绪相关：紧张、焦虑时加重，注意力分散时减轻，为典型的功能性与情绪相关表现；精神压力（生活工作压力、焦虑抑郁）为常见诱因；渐进起病）出现：咽部异物感（即梅核气，咽部如有物梗阻，吞之不下、吐之不出，为核心主诉，多数不影响吞咽，吞咽食物时反而减轻，重要，与器质性病变所致进行性吞咽困难不同）、咽部（堵塞、压迫、贴叶、虫爬或烧灼感，感觉多样）、空咽加重（咽唾液时明显，进食时减轻乃至消失，为功能性特征，重要）、吞咽（正常，无困难；若为器质性病变则可出现吞咽困难，需警惕）；需注意排除器质性病因（重要）：反流性咽喉炎（胃食管反流，烧心反酸、喉咽反流，为最常见器质性病因之一，可行PPI试验，重要）、慢性咽炎（咽干痒、清嗓）、鼻后滴漏（鼻炎、鼻涕倒流）、扁桃体（肥大或结石）、茎突过长（少见）、颈椎病（骨赘压迫）、甲状腺肿大（压迫）、食管（肿瘤可致吞咽困难、消瘦，年龄大、吸烟饮酒者需警惕，必须排除，重要，咽异感症诊断前应排除器质性病变，尤其食管肿瘤）、肿瘤（咽、喉或食管肿瘤，老年人出现渐进性吞咽困难时必须行喉镜及胃镜排除，关键）；精神心理（焦虑、抑郁、疑病（恐癌，反复就诊，重要，心理因素）、更年期、癔球症（功能性））、全身（贫血、甲减、缺铁，少见）、用药情况。今日来我院耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P76次/分，R18次/分，BP118/76mmHg。咽部（黏膜（慢性充血，提示咽炎）、扁桃体（大小及隐窝有无结石）、咽后壁（淋巴滤泡））、喉（行间接喉镜或电子喉镜检查（为检查核心，观察喉黏膜、声带、会厌、梨状窝（有无异物或肿瘤，为必查项目，重要，以排除喉咽病变）、下咽（梨状窝有无潴留或肿瘤））、鼻（后鼻孔，注意有无鼻后滴漏）、颈部（甲状腺、淋巴结及有无肿块，行触诊）、食管（观察吞咽情况）、全身（有无贫血、消瘦等器质性表现，需评估）。","辅助检查":"【必做】电子喉镜或间接喉镜（为核心，用于排除喉咽器质性病变，必查，重要；年龄大于40岁、吸烟饮酒者更应行喉镜加胃镜检查，以排除肿瘤，关键）；【其他】疑反流者行PPI试验（质子泵抑制剂，奥美拉唑20mg bid×4~8周，症状改善支持反流性诊断，重要）或24小时pH监测、胃镜（疑食管或胃病变，有吞咽困难、消瘦、年龄大等高危因素者必查，以排除食管癌，重要）、颈椎X线（疑颈椎病或茎突过长者，可观察茎突）、甲状腺超声（甲状腺肿大或结节者）、血常规、铁蛋白及甲状腺功能（筛查贫血、甲减）、焦虑抑郁量表（心理评估）、鼻内镜（鼻后滴漏者）。","初步诊断":"1. 咽异感症（癔球症，功能性（与精神心理相关），器质性病因已排除（反流、鼻后滴漏、喉咽肿瘤），诊断依赖排除）\n（注：治疗（排除器质性病变后按功能性处理，以心理治疗加对症为主，综合管理）：①排除器质（首要，行喉镜及胃镜（高危者），排除肿瘤，既可使患者安心，本身即为治疗措施，重要，恐癌者喉镜正常可解除焦虑、缓解症状）；②反流治疗（合并反流者用PPI（奥美拉唑或埃索美拉唑，疗程4~8周，症状改善后维持）、调整生活方式（睡前3小时不进食、抬高床头、戒烟酒及咖啡、减重，重要，反流是常见且可治的病因））；③鼻后滴漏（治疗鼻炎（鼻用激素或鼻腔冲洗））；④心理治疗（为功能性核心：解释病情良性（非肿瘤，使患者安心）、减轻压力（放松、正念、运动）、抗焦虑（焦虑明显者用SSRI或苯二氮卓类，短期使用，请心理科评估，重要）、认知行为治疗（纠正疑病观念））；⑤对症（中成药（咽炎片或金嗓利咽丸，部分有效）、含片等安慰治疗，适用于轻度者；避免过度清嗓（可刺激并加重症状））；⑥随访（症状于4~8周评估，缓解者支持功能性诊断；持续不缓解或加重者复诊再评估（复查喉镜、胃镜，排除新发器质性病变，重要，尤其出现吞咽困难、消瘦、进行性加重时需警惕肿瘤）、心理症状持续者转专科）；本病由耳鼻喉科诊治，排除器质是前提，针对反流及心理因素对症处理，做好患者教育（说明良性），随访中需警惕进行性吞咽困难，必要时再查，重要。","处理方案":"【药物治疗】\n1. 奥美拉唑肠溶胶囊20mg qd，晨起空腹口服，疗程4-8周（合并反酸、烧心等胃食管反流表现时首选抑酸治疗）。\n2. 多潘立酮片10mg tid，餐前15-30分钟口服，疗程2-4周（促胃动力，减少反流刺激咽喉）。\n3. 西地碘含片（华素片）1.5mg tid 含服，含服后半小时内勿饮水进食（局部消肿抗炎）；或复方硼砂含漱液漱口，tid。\n4. 谷维素片10mg tid（调节自主神经功能，改善咽部异物感伴情绪紧张、焦虑者）。\n\n【一般治疗及生活指导】\n1. 忌烟酒、辛辣刺激、过烫过硬及油炸食物，少饮浓茶、咖啡、碳酸饮料，避免睡前加餐。\n2. 细嚼慢咽、少食多餐，餐后2小时内勿平卧，睡前3小时禁食，夜间可适当垫高床头15-20cm。\n3. 保持心情舒畅，避免紧张焦虑与过度劳累；勿频繁用力清嗓、反复吞咽，可少量多次饮温水湿润咽喉。\n4. 避免长时间大声说话及用嗓过度，注意口腔卫生。\n\n【随诊要求】\n用药2周后复诊评估症状缓解情况；若症状无缓解或加重，或出现吞咽困难、进食梗阻感、声嘶、颈部包块、消瘦等报警症状，应及时复诊，行电子喉镜、胃镜等检查排除器质性病变；完成4-8周疗程后复查评估疗效，症状持续不缓解者建议耳鼻喉科、消化科及心理科进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":610,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"30cfc8e6d300f96ba43c30774e0315373b526d5837852f843633c527238ebd1a","pinyin":"yanyiganzheng","initials":"yygz","setting":"out","caseName":"门诊病历475","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历475",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-cb8745e38b619982d5c2","key":"v1-c9ccc21dfe2a3058|templates-cb8745e38b619982d5c2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性喉炎","category":"门诊病历模板","raw":{"name":"慢性喉炎","category":"门诊病历模板","case":{"case_name":"门诊病历476","templates":{"主诉":"声音嘶哑伴喉干6月","现病史":"患者（职业用声（教师、销售、歌手等长期过度或不当用声者）、吸烟（慢性刺激，最重要，吸烟者喉炎常见）、饮酒、粉尘或化学物暴露、反流性咽喉炎（胃食管反流，喉后部受累，为最常见慢性喉炎原因之一，夜间反流，晨起声嘶，重要）、鼻后滴漏（慢性刺激）、慢性咳嗽（清嗓冲击））于1年余前（慢性、渐进，病程数月数年）出现：声音嘶哑（持续超过3周，属慢性，区别于急性（小于3周）；呈波动性（用声后加重，休息后减轻）、音质（粗糙、沙哑）、喉干及异物感（清嗓、干咳）、痰（少而黏）、用声（疲劳、费力，音域变窄）；需注意有无急性发作（感染致急性喉炎，在慢性基础上加重）、反流（烧心反酸，夜间及晨起声嘶或咽痛）、吸烟（量）、职业用声（强度及时间）、声嘶渐进加重（年龄大、吸烟者需警惕肿瘤，持续超过3周必须行喉镜检查，重要，喉癌早期可仅表现为声嘶，勿漏诊）、呼吸困难（喉梗阻，少见，多见于肿瘤晚期）、咯血。今日来我院耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P78次/分，R18次/分，BP116/72mmHg。喉（行电子喉镜或间接喉镜检查（为检查核心，可观察喉黏膜（弥漫性充血（慢性者呈暗红色）、声带（充血、肿胀、边缘圆钝，符合慢性喉炎改变、闭合（不全，可见声门裂隙）、表面（干燥、覆黏稠分泌物、可见声带小结或息肉（用声过度者并见，见专项））、喉后部（杓间区红肿、增生，为反流性喉炎特征）、黏膜（肥厚者提示慢性增生性喉炎，属癌前病变，需密切随访）、运动（声带活动正常）、下咽（梨状窝）、室带（有无代偿）），喉镜为必查项目，以排除新生物，重要）。","辅助检查":"【必做】电子喉镜（核心：诊断及排除肿瘤）；【其他】（疑反流，PPI试验（奥美拉唑，8周，反流性喉炎，改善）、24小时pH/喉咽反流监测（难治）、动态喉镜（声带振动，闭合）、嗓音分析（客观，随访）、喉黏膜活检（慢性增生性喉炎/白斑（癌前病变，喉镜下，活检，病理，排除癌变，重要，喉白斑/喉角化，喉癌前，随访）、疑肿瘤（活检）、胸片（肺）。","初步诊断":"1. 慢性喉炎（反流性：喉后部杓间区红肿，病因为用声过度、吸烟及反流，需喉镜排除新生物）\n（注：治疗（去除病因加声带休息为核心，防止增生及癌前病变进展）：①去除病因（戒烟（最重要，吸烟为持续刺激，慢性喉炎不戒烟难以痊愈，关键）、戒酒、避免粉尘、治疗反流（反流性者用PPI（奥美拉唑或埃索美拉唑，疗程8~12周，睡前抬高床头、睡前3小时不进食、减重，重要，属可治病因）、治疗鼻后滴漏（鼻用激素）、避免清嗓（可用吞咽动作替代）））；②声带休息（减少用声（并非完全禁声，慢性者应减少说话，避免大声及长时间讲话）、职业用声者科学用声（嗓音训练，呼吸支持、放松发声，减少声带撞击，防复发，重要）、避免耳语（更伤声带））；③对症（雾化（生理盐水或布地奈德，抗炎消肿，短期）、咽喉含片或漱口（润喉，安慰）、多饮水（润滑）、保持室内湿度）；④随访（喉镜（3~6个月复查，评估黏膜及声带恢复）、慢性增生性喉炎及喉白斑（属癌前病变，需密切随访（每3~6个月行喉镜加活检，若癌变应早期手术，重要，勿漏）、声嘶持续超过3个月者复查喉镜，排除肿瘤，重要）、嗓音训练（职业用声者需长期坚持，防复发））；本病由耳鼻喉科诊治，以戒烟、声休及反流治疗为主，需喉镜随访，增生性病变需防癌变，重要。","处理方案":"【药物治疗】\n1. 吸入用布地奈德混悬液1mg（2ml）＋0.9%氯化钠注射液2ml，雾化吸入，每次15分钟，一日2次，共7天。\n2. 黄氏响声丸（浓缩丸，每10丸重0.2g）20丸，口服，一日3次，共14天。\n3. 合并咽喉反流（反酸、烧心、晨起声嘶明显）者：奥美拉唑肠溶胶囊20mg，早餐前30分钟空腹口服，一日1次，共4周。\n4. 喉部分泌物黏稠、干咳痰黏者：桉柠蒎肠溶软胶囊0.3g，餐前半小时凉开水整粒吞服，一日3次，共7天。\n\n【一般治疗及生活指导】\n1. 声休：急性发作期少语或禁声3～5天，避免大声喊叫、长时间连续讲话及频繁清嗓；职业用声者（教师、主播等）注意科学发声、适当降低音量。\n2. 戒烟限酒，避免辛辣、过烫、过冷及油炸刺激性饮食；饭后2～3小时内勿平卧，睡前2小时禁食，减少胃酸反流刺激喉部。\n3. 每日少量多次饮水（1500～2000ml），保持咽喉湿润；避免粉尘、油烟、二手烟等刺激环境，必要时佩戴口罩。\n4. 规律作息，保证充足睡眠，避免熬夜及精神紧张；感冒及上呼吸道感染期间注意休息，减少用声。\n\n【随诊要求】\n1. 用药1～2周后复诊，评估声音嘶哑及喉部不适改善情况，由医师调整后续用药。\n2. 声音嘶哑持续超过4周无缓解，或症状反复发作，建议行电子喉镜（或频闪喉镜）检查，排除声带息肉、声带小结、喉白斑等病变。\n3. 出现进行性声嘶加重、喉痛、吞咽痛、痰中带血或呼吸困难者，随时立即就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":611,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3dbd2ad0512608b11f3b1cd17989240f34f9960aaeae5d955ea4baa3a824a47e","pinyin":"manxinghouyan","initials":"mxhy","setting":"out","caseName":"门诊病历476","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历476",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4e77e1eed08c7b1b78e5","key":"v1-c9ccc21dfe2a3058|templates-4e77e1eed08c7b1b78e5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"喉水肿","category":"门诊病历模板","raw":{"name":"喉水肿","category":"门诊病历模板","case":{"case_name":"门诊病历477","templates":{"主诉":"声音嘶哑伴呼吸困难1周","现病史":"患者1周前无明显诱因出现喉水肿相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以声音嘶哑伴呼吸困难1周为主诉，声嘶伴呼吸困难提示喉部黏膜水肿可能累及声门区，有气道梗阻风险，入院即刻完善血常规检查排除感染、贫血所致黏膜水肿及全身状态异常；查耳镜检查了解外耳道及鼓膜情况，排除耳部原发病变所致反射性喉部症状；行鼻内镜检查明确鼻腔、鼻咽部有无炎症、新生物或分泌物后漏刺激喉部，排除鼻源性因素所致喉水肿；查喉镜检查以直观了解喉黏膜水肿的范围、程度及声门开放情况，评估气道梗阻风险；完善鼻窦CT检查明确有无鼻窦炎性病变作为喉水肿的诱因，排除鼻窦感染所致；查颞骨CT了解中耳乳突有无病变，排除耳源性感染蔓延所致喉部水肿；行颈部超声检查了解颈部软组织及淋巴结情况，明确有无颈部占位、脓肿压迫所致喉水肿，必要时行颈部增强CT进一步明确；查纯音测听了解听力有无受损，评估有无合并感音神经性听力下降；行声导抗检查了解中耳功能状态，鉴别中耳病变；完善前庭功能检查评估前庭功能，明确眩晕与前庭受累的关系。\n\n（检查清单）\n【必做检查】\n血常规、耳镜检查、鼻内镜检查、喉镜检查\n\n【影像学检查】\n鼻窦CT、颞骨CT、颈部超声\n\n【其他检查】\n纯音测听、声导抗、前庭功能检查","初步诊断":"1. 喉水肿\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 糖皮质激素（首选，抗炎消肿）：地塞米松磷酸钠注射液5～10mg 静脉注射或肌内注射，即刻给予，必要时6～8小时后重复1次；病情缓解后改醋酸泼尼松片30～40mg 每日晨起顿服，渐减量至停药，总疗程3～5天。重度水肿可予甲泼尼龙40～80mg 静脉滴注 q12h。\n2. 抗组胺药（过敏所致者）：氯雷他定片10mg qd×3～5天，或西替利嗪片10mg qd×3～5天，与激素联合控制过敏反应。\n3. 抗感染（合并感染或喉部炎症者）：阿莫西林胶囊0.5g tid×5～7天（青霉素过敏者改用头孢呋辛酯片0.25g bid×5～7天；用药前皮试）。\n4. 局部雾化吸入：布地奈德混悬液2mg 加入生理盐水2ml 雾化吸入 bid×3～5天，直接作用于喉黏膜减轻水肿。\n\n【一般治疗及生活指导】\n1. 休息与体位：绝对减少说话、避免用力咳嗽及剧烈活动，取坐位或半卧位保持呼吸道通畅，密切观察呼吸、声音嘶哑及喘鸣变化。\n2. 饮食：进温凉流质或半流质饮食，禁食过热、辛辣刺激性食物及酒精，避免刺激加重喉部水肿。\n3. 禁忌：立即停用可疑致敏药物及食物，避免接触花粉、尘螨等过敏原；严格戒烟；禁用镇静催眠类药物，以免掩盖呼吸困难症状。\n4. 环境：保持室内空气湿润（湿度50%～60%），避免干燥及刺激性气体刺激咽喉。\n\n【随诊要求】\n1. 喉水肿属急症，用药后患者急诊留观1～2小时，若出现进行性呼吸困难、喘鸣加重、口唇发绀、三凹征或烦躁不安，须立即急诊就诊，必要时行气管插管或气管切开。\n2. 症状缓解后2～3天门诊复诊，复查喉部情况（必要时喉镜检查）评估黏膜水肿消退程度。\n3. 明确并规避诱因（过敏原、药物、感染等），必要时行过敏原检测及病因治疗，防止复发；复发性喉水肿建议转耳鼻喉科进一步评估有无喉部占位或血管神经性水肿。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":612,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b85dd5c15e998af641aedf7f5cb3da5e74be38f68c1505973b5d5efb0111830f","pinyin":"houshuizhong","initials":"hsz","setting":"out","caseName":"门诊病历477","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历477",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f7e335575a1f404fbd20","key":"v1-c9ccc21dfe2a3058|templates-f7e335575a1f404fbd20","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"声带小结","category":"门诊病历模板","raw":{"name":"声带小结","category":"门诊病历模板","case":{"case_name":"门诊病历478","templates":{"主诉":"声音嘶哑伴发声费力6月","现病史":"患者（职业用声（教师、播音、销售、歌唱等，为最常见原因，长期过度或不当用声）、儿童（大喊大叫，男孩多见，多可自限）、用声习惯（大声喊叫、长时间讲话、清嗓、吸烟、粉尘、反流性咽喉炎（胃食管反流，声带后部受刺激，为重要合并因素））于1年前（渐进，病程数月至数年）出现：声音嘶哑（由轻渐重，用声后加重、休息后减轻，初期为间歇性，后转为持续性）、发声费力（疲劳）、音域变窄（高音上不去，唱歌受影响）、音质（粗糙、嘶哑、有气息声）、咽喉不适（干痒、异物感）；需注意有无急性喉炎（感染所致，属急性，需区别）、声带息肉（单侧，较大小结，出血后形成声带任克水肿，需鉴别）、喉肿瘤（老年、单侧、渐进性嘶哑、吸烟者需警惕，重要，嘶哑超过3周必须行喉镜检查）、反流（烧心、反酸及喉部症状）、甲状腺或颈部手术史（可致喉返神经损伤、声带麻痹，需区别）、声带麻痹（单侧者嘶哑伴呛咳，为神经因素，需区别）；病程（数周至数月，渐进）；用声情况（每日用声时间，与职业相关）。今日来我院耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP114/72mmHg。喉部检查（行间接喉镜或电子喉镜（为检查核心，观察声带（双侧声带前中1/3交界处（为声带小结好发部位，即振动最剧处）可见对称性小结（双侧、小隆起、呈白色、表面光滑，为声带小结特征，可与息肉（多为单侧）鉴别）、声带（充血水肿，符合慢性改变）、闭合（因小结致声门闭合不全，为嘶哑原因）、喉黏膜（反流性者喉后部杓间区红肿）、运动（声带活动正常，可排除麻痹）），必要时行纤维喉镜或动态喉镜（评估声带振动及闭合）；【其他】反流评估（疑反流性咽喉炎者行喉镜检查加PPI试验，必要时行24小时pH监测）、用声评估（可行嗓音分析，客观评价）。","辅助检查":"【必做】电子喉镜或纤维喉镜（为确诊核心，可见双侧声带小结（位于前中1/3，对称分布））、动态喉镜（评估声带振动及闭合）；【其他】声带息肉或囊肿（多为单侧，喉镜下鉴别，需手术）、反流（喉反流者行PPI试验，反流性咽喉炎经治疗反流后小结可消退，重要，反流性咽喉炎表现为喉后部红肿）、可疑肿瘤（单侧、不典型、老年吸烟者需活检，排除肿瘤，重要）；【嗓音评估】嗓音障碍指数（主观评价）、声学分析（客观评价，用于随访）。","初步诊断":"1. 声带小结（双侧，位于声带前中1/3，与职业用声相关，属早期（软性、水肿性），需评估是否合并反流性咽喉炎）\n（注：治疗（以保守为主，即声带休息加嗓音训练，成熟小结可手术）：①声带休息（为核心，早期应减少用声（需禁声，但不用耳语（耳语更伤声带，重要），可轻声正常说话或少说，短期1~2周，初期小结（水肿性）可消退））；②嗓音训练（为关键，长期坚持可根治：科学用声（放松发声、腹式呼吸支持、减少声带撞击、调整音调）、请言语治疗师行嗓音治疗（纠正用声习惯，防复发，为核心，职业用声者）、注意用声卫生（避免大喊及长时间讲话、避免清嗓（可用吞咽代替，减少声带撞击，重要）、多饮水（润滑声带）、避免烟酒辛辣及粉尘））；③反流治疗（合并反流性咽喉炎者用质子泵抑制剂（奥美拉唑20mg bid×8~12周，减少声带后部刺激，小结可改善，重要）、睡前3小时不进食、抬高床头）；④药物（非甾体抗炎药或激素（用于早期炎症性者，短期雾化（布地奈德）可辅助，急性炎症期使用，不宜长期））；⑤手术（指征为成熟小结（纤维化、质硬，保守3~6个月无效，持续嘶哑并影响职业）、声带息肉（单侧，手术指征明确，可行喉显微手术（喉镜下切除，保留正常声带，微创，术后声带休息1~2周加嗓音训练，防复发，重要））；⑥随访（保守治疗者1~3个月复查喉镜（观察小结变化）、评估嗓音训练效果、预防复发（关键在于用声习惯，职业用声者需长期训练，重要））；本病由耳鼻喉科及嗓音门诊诊治，以保守为核心，嗓音训练为关键，反流需同治，成熟小结可手术，防复发重要。","处理方案":"【药物治疗】\n1. 短期糖皮质激素雾化吸入消肿（适用于声带急性充血水肿期）：吸入用布地奈德混悬液1mg加入生理盐水2ml，雾化吸入，每日2次，连用5~7天，每次用后清水漱口，面部清水擦洗。\n2. 中成药清热利咽、利喉开音：黄氏响声丸（糖衣丸）一次20丸，每日3次，饭后口服，疗程7~14天。\n3. 合并咽喉反流、胃酸刺激明显者加用抑酸治疗：奥美拉唑肠溶胶囊20mg，早餐前30分钟空腹口服，每日1次，疗程4周。\n4. 咽干不适明显者局部含化润喉：西瓜霜润喉片1~2片，含化，每日3~4次。\n\n【一般治疗及生活指导】\n1. 声带休息：急性充血水肿期严格禁声3~5天，避免说话及耳语（耳语可加重声带摩擦损伤），恢复期减少说话时间与强度，避免大声喊叫及长时间连续用声。\n2. 科学用声：放慢语速，用腹式呼吸支撑发声，避免频繁清嗓、用力咳嗽等不良习惯；职业用声者（教师、销售、主播等）可借助扩音设备辅助发音。\n3. 饮食：忌辛辣、过烫、过冷及油炸刺激食物，忌烟酒、咖啡、浓茶，多饮温开水保持咽喉湿润；睡前3小时避免进食以防胃酸反流刺激喉部。\n4. 环境与作息：避免粉尘、油烟、二手烟等刺激性环境，外出可佩戴口罩；规律作息，保证充足睡眠，避免熬夜及劳累。\n\n【随诊要求】\n1. 治疗2~4周后复诊，复查电子喉镜评估声带小结及声带充血水肿消退情况。\n2. 声音嘶哑持续2~3周无改善或进行性加重，或出现呼吸困难、咳血、颈部包块等表现，应立即复诊。\n3. 双侧声带小结较大、保守治疗3个月以上无效者，转耳鼻喉科评估支撑喉镜下声带小结切除术，术后遵医嘱定期喉镜复查并坚持声带休息及发声训练。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":613,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"69597a259089bafab7833a208caf34d12ac93120fa66813f7c3ea1517af7b408","pinyin":"shengdaixiaojie","initials":"sdxj","setting":"out","caseName":"门诊病历478","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历478",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7f20f4ce6a082332c569","key":"v1-c9ccc21dfe2a3058|templates-7f20f4ce6a082332c569","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"声带麻痹","category":"门诊病历模板","raw":{"name":"声带麻痹","category":"门诊病历模板","case":{"case_name":"门诊病历479","templates":{"主诉":"声音嘶哑伴饮水呛咳1月","现病史":"患者（单侧声带麻痹（喉返神经损伤：左侧喉返神经走行较长，经胸腔绕主动脉弓下方，易受累，故左侧麻痹多于右侧；病因包括医源性（甲状腺手术（最常见，甲状腺切除术可损伤喉返神经）、颈部或胸部手术（颈清扫、食管手术、纵隔手术））、肿瘤（甲状腺癌、肺癌、食管癌或纵隔肿瘤及淋巴结转移压迫喉返神经（左侧肺癌纵隔转移致声带麻痹是老年吸烟者声嘶的常见病因，需行胸片或CT排查肺癌，重要）、颈部转移）、神经性（特发性（病毒感染后，多可自限）、中枢性（卒中，延髓核上或核下病变）、外伤、气管插管或拔管损伤）、双侧声带麻痹（甲状腺手术双侧损伤（可致呼吸困难，属急症，需气道管理）、神经退行性变））于1个月前（渐进出现）出现：声音嘶哑（单侧者声带固定于内收位，发音时声门有裂隙，声门闭合不全，故声嘶、有气息声、发声费力）、呛咳（声门闭合不全致吞咽时误吸、呛咳，饮水时呛咳明显，重要，有肺炎风险）、吞咽困难、呼吸（单侧者多无呼吸困难（健侧可代偿），双侧声带内收麻痹者可出现吸气性呼吸困难及喘鸣，属急症，必要时气管切开）；需注意有无手术史（甲状腺、颈部或胸部手术及时间）、肿瘤史（甲状腺、肺、食管肿瘤及颈部放疗）、吸烟（肺癌风险）、呛咳误吸（可致肺炎、发热、咳嗽）、声带运动（需喉镜检查）、中枢病变（卒中及颅神经异常）、发音及吞咽影响。今日来我院耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.4℃，P80次/分，R18次/分，BP122/78mmHg。喉（行纤维喉镜或间接喉镜检查（为检查核心，观察声带运动（患侧声带麻痹、固定（呈旁正中位）、杓状软骨（活动情况）、声门（发音时闭合有裂隙）、黏膜、对侧（代偿性内收））、喉（检查有无肿瘤）、颈部（甲状腺（有无术后瘢痕、结节）、淋巴结）、胸部（肺部听诊，评估肿瘤）、神经（中枢及颅神经（迷走、舌下神经）、吞咽（评估误吸））、呼吸（双侧麻痹者注意喘鸣及呼吸困难，需评估）。","辅助检查":"【必做】喉镜或动态喉镜（为核心，用于评估声带运动障碍及麻痹时声带位置）；【病因排查】胸部X线或CT（排查肺癌、纵隔肿瘤及淋巴结（老年、吸烟、声嘶者必查胸片或CT，以排除肺癌，重要））、甲状腺超声（甲状腺结节或术后）、颈部CT或MRI（颈部肿瘤及淋巴结）、食管（有吞咽困难者评估食管肿瘤）；【其他】肌电图（喉肌电图，可定位神经损伤并评估预后（神经断裂或失用））、声学分析（嗓音评价）、神经（疑卒中或颅神经病变者评估，可行头颅MRI，以排查中枢性病因）、特发性（排除器质性病变后诊断，需观察6个月，部分患者可恢复）。","初步诊断":"1. 声带麻痹（单侧（左侧），特发性（需先排除医源性、肿瘤及中枢性病因），声带固定于旁正中位，声门闭合不全，需评估呛咳误吸及呼吸情况，病因待查）\n（注：治疗（以病因治疗加发声、吞咽及呼吸管理为主）：①病因处理（肿瘤（肺癌、甲状腺等压迫者，依原发灶行手术、放疗或化疗）、甲状腺术后（神经损伤轻者多为牵拉，3~6个月多可自行恢复，可行观察；永久性麻痹者行发声治疗或手术）、特发性（可观察6~12个月，部分患者可自发恢复（约30%~50%），同时行语言康复治疗））；②发声治疗及康复（嗓音训练（由语言治疗师指导，通过声带代偿性内收训练改善发声、气息声），单侧者行发声训练多有效，可改善轻度嘶哑）；③手术（单侧者可行声带注射填充（声带旁注射透明质酸、脂肪或胶原，使声带内移，改善声门闭合，利于发声并减少呛咳，重要，属微创）、甲状成形术（Ⅰ型，植入物使声带内移，可永久改善）、杓状软骨内收术（改善发声），呛咳者经声门闭合改善可减少误吸，降低肺炎风险，重要；双侧者出现呼吸困难时需行气道管理（气管切开，急症处理）或声带外展手术（杓状软骨切除或声带外移，改善通气，但发声功能下降，需权衡评估））；④吞咽管理（呛咳者行吞咽评估（饮水呛咳者需防误吸）、食物以糊状软食为主以减少呛咳、行吞咽康复训练；严重误吸、反复肺炎者可行胃造瘘或气管切开以保护气道）；⑤随访（病因随访（肿瘤治疗后的情况）、恢复情况（3~6个月复查喉镜，观察声带运动）、发声（评估训练效果）、吞咽（监测误吸及肺炎）、双侧麻痹者需教育其出现呼吸喘鸣时急诊就医）；本病由耳鼻喉科诊治，喉镜可确诊，需排查病因（胸片、肺），行发声训练、注射或成形术，双侧者注意气道，重要。","处理方案":"【药物治疗】\n1. 营养神经：甲钴胺片0.5mg tid，口服×4周；维生素B1片20mg tid，口服×4周。\n2. 急性期（发病2周内、排除感染及激素禁忌证）短程抗炎消肿：醋酸泼尼松片30mg qd，晨起顿服×5-7天。\n3. 改善循环、促进神经修复：银杏叶提取物片40mg tid，口服×4周；或地巴唑片10mg tid，口服×4周。\n4. 针对病因治疗（如甲状腺术后、颈部外伤、病毒感染所致者），必要时予抗病毒及扩血管药物，遵专科医嘱调整。\n【一般治疗及生活指导】\n1. 禁声休息：急性期绝对禁声1-2周，少说话、禁止耳语及用力清嗓，恢复期控制用声强度与时长，避免高声及长时间交谈。\n2. 防止误吸：进食宜细软、小口慢咽、细嚼，饮水时低头吞咽，吞咽困难明显者可将液体调稠或加增稠剂；餐后保持坐位30分钟。\n3. 饮食禁忌：忌辛辣、过烫、过冷及刺激性食物，戒烟戒酒，避免刺激性气体及粉尘环境，多饮温水润喉。\n4. 注意休息、避免劳累与受凉，避免剧烈咳嗽、用力屏气及突然用力，防止声带再损伤。\n【随诊要求】\n1. 用药期间每周复诊1次，评估声嘶程度、吞咽功能及有无呼吸困难、喘鸣。\n2. 治疗2-4周复查电子喉镜，必要时行喉肌电图，评估声带运动及恢复情况；未恢复者继续营养神经治疗并2-4周后复查。\n3. 病因未明者完善头颈影像学（颈部CT/MRI）、甲状腺及神经相关检查，转诊相应专科（神经内科、头颈外科、内分泌科）明确病因并随访。\n4. 若出现进行性加重的呼吸困难、喘鸣、憋气，警惕双侧声带麻痹，须立即急诊就诊，必要时行气管切开评估。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":614,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"347b615ad031b53e420877526149602dead4946ac6a1a9a083a794b9e3a36100","pinyin":"shengdaimabi","initials":"sdmb","setting":"out","caseName":"门诊病历479","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历479",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-81ec6f15dde1faa27bf1","key":"v1-c9ccc21dfe2a3058|templates-81ec6f15dde1faa27bf1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"喉梗阻","category":"门诊病历模板","raw":{"name":"喉梗阻","category":"门诊病历模板","case":{"case_name":"门诊病历480","templates":{"主诉":"吸气性呼吸困难伴喉鸣6小时","现病史":"患者（常见病因：急性喉炎或喉水肿（过敏所致血管神经性水肿、感染所致急性会厌炎或喉炎，儿童多为急性喉气管支气管炎（哮吼））、喉异物（小儿呛咳后）、喉肿瘤（喉癌，呈进行性加重）、喉外伤、双侧声带麻痹、甲状腺术后血肿或颈部手术后、瘢痕狭窄（气管插管后））于6小时前（突发（异物、过敏者可在数分钟内发生，属急症）或渐进（肿瘤者数周至数月加重））出现吸气性呼吸困难、吸气性喉鸣（喘鸣，响亮，位于吸气相，为喉梗阻特征，呼气相相对通畅）、声嘶或失声、犬吠样咳嗽（儿童哮吼）；需注意有无发绀（口唇、甲床，提示缺氧，属晚期）、烦躁不安（早期缺氧影响脑）、三凹征（吸气性，表现为胸骨上窝、锁骨上窝及肋间隙凹陷，提示吸气费力，儿童明显）、大汗、意识改变（嗜睡提示严重缺氧，属濒危）、流涎及吞咽困难（会厌炎或异物）、过敏表现（荨麻疹、血管神经性水肿）；病情进展速度为进行性加重。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.2℃，P104次/分，R24次/分（增快），BP118/74mmHg，SpO2 95%（下降，严重者更低）。神志清楚（提示缺氧程度尚可）。口唇无发绀。吸气性喉鸣明显（可闻及，远距离亦可闻及）、三凹征（吸气性凹陷，累及胸骨上窝、锁骨上窝、肋间及上腹部）、呼吸（吸气相延长，呼吸困难，呼吸频率增快，晚期可减慢（濒危））、声嘶（+）、颈部无肿胀、无肿块、无手术瘢痕（提示病因）、咽部及喉镜（注意会厌及声门有无急性会厌炎所致充血水肿；异物者视情况，气道稳定后再检查）。","辅助检查":"【必做】血氧饱和度监测（SpO2，持续监测，观察趋势）；【影像】病情允许且气道稳定后行颈部X线侧位（会厌炎可见拇指征；喉异物可表现为不透X线）、或行颈部CT（用于肿瘤、脓肿及狭窄定位，患者气道稳定后进行）；注意：重度梗阻应先处理气道，不做搬动检查（检查途中有窒息风险，需权衡，患者有抢救条件时进行）；【血气分析】（评估低氧血症及高碳酸血症，判断呼吸衰竭）；【其他】病因相关检查（过敏者查过敏原；感染者查血常规及CRP）。","初步诊断":"1. 喉梗阻（Ⅱ度：安静时即有喉鸣及轻度凹陷；Ⅰ度为安静时无呼吸困难、活动时出现吸气性喉鸣，Ⅲ度为明显呼吸困难加三凹征、烦躁及发绀，Ⅳ度为呼吸衰竭、昏迷，属濒危。病因：急性喉炎）\n（注：喉梗阻为急症（可窒息死亡，处理原则为争分夺秒，依梗阻程度及病因决定）：①Ⅰ~Ⅱ度（尚可代偿）：病因治疗加密切监护（感染性者用抗生素加糖皮质激素（地塞米松0.3~0.5mg/kg或氢化可的松，减轻水肿）加雾化（布地奈德加肾上腺素，适用于急性喉炎、会厌炎，减轻水肿）；过敏者立即肌注肾上腺素0.3~0.5mg（血管神经性水肿，关键）加抗组胺药及激素）；②Ⅲ度（明显缺氧）：紧急气道处理（气管插管（由有经验者操作，喉水肿者插管困难风险大，需备气管切开）或气管切开、环甲膜穿刺（紧急情况，插管失败者，适用于Ⅲ~Ⅳ度），必要时先雾化肾上腺素争取时间）；③Ⅳ度（濒危）：立即气管切开（紧急，争分夺秒，不等待）；④异物：直接喉镜或支气管镜取出（硬管支气管镜，在急诊手术室进行）；⑤病因根治（喉肿瘤者术后择期手术；双侧声带麻痹者行气管切开或杓状软骨手术）；⑥监护（解除梗阻后入ICU，监测呼吸、SpO2及意识，防治并发症（缺氧性脑病、肺水肿））；本病由耳鼻喉科、急诊、麻醉（插管）及ICU多学科紧急处理，分秒必争。）","处理方案":"【药物治疗】\n1. 糖皮质激素（首选抗炎消肿）：地塞米松磷酸钠注射液10mg静脉注射，或醋酸泼尼松片30mg qd口服，病情缓解后2～3天内渐减量，总疗程3～5天。\n2. 雾化吸入（快速缓解喉水肿）：吸入用布地塞米松混悬液2mg+盐酸肾上腺素注射液1mg（1ml），加入0.9%氯化钠注射液至总量4ml，雾化吸入bid，连用2～3天，急性加重时即刻加用1次。\n3. 抗感染治疗（伴感染或发热者）：阿莫西林克拉维酸钾片（0.457g）1片tid×5～7天；青霉素过敏者改用头孢呋辛酯片0.25g bid×5～7天。\n4. 氧疗：血氧饱和度下降或呼吸困难明显时鼻导管吸氧2～4L/min，监测血氧饱和度；必要时面罩给氧。\n【一般治疗及生活指导】\n1. 卧床休息，取半卧位，尽量安静少语、减少吞咽动作，避免剧烈活动及情绪激动诱发喉痉挛。\n2. 进温凉流质或半流质饮食，少量多餐，忌辛辣、过烫、粗糙食物及烟酒，防止呛咳加重喉水肿。\n3. 保持居室空气湿润通风，避免冷空气、烟雾、粉尘及过敏原刺激，外出可佩戴口罩。\n4. 密切观察呼吸频率、喘鸣音、口唇颜色及三凹征，嘱家属掌握急诊就医指征。\n【随诊要求】\n1. 若出现呼吸困难进行性加重、喘鸣、口唇发绀、烦躁不安或意识改变，立即急诊就诊，必要时行气管切开或气管插管。\n2. 用药后2～3天门诊复诊评估喉部水肿消退及喘鸣缓解情况，疗程结束后复查血常规、CRP等感染指标。\n3. 症状反复或病因不明者，建议耳鼻喉科专科门诊行电子喉镜检查明确病因（炎症、异物、肿瘤、过敏等），针对病因进一步处理。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":615,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"864ce67b88db44042f0f514c1f3d8a3417bf83522d686b3d24e67ce2977be154","pinyin":"hougengzu","initials":"hgz","setting":"out","caseName":"门诊病历480","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历480",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2d9f7ab8d6005668a94a","key":"v1-c9ccc21dfe2a3058|templates-2d9f7ab8d6005668a94a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"食管异物","category":"门诊病历模板","raw":{"name":"食管异物","category":"门诊病历模板","case":{"case_name":"门诊病历481","templates":{"主诉":"吞咽痛伴吞咽困难1周","现病史":"患者1周前无明显诱因出现食管异物相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以吞咽痛伴吞咽困难1周为主诉，进食后吞咽疼痛进行性加重提示食管异物嵌顿或食管黏膜损伤可能，急诊完善血常规检查排除感染、贫血，评估有无继发感染及出血倾向；查便常规加潜血试验以了解消化道有无出血，排除异物损伤黏膜所致隐性失血及消化道肿瘤；完善肝功能检查以评估肝脏合成功能及手术耐受性，为可能的内镜下取物或外科手术做准备；查淀粉酶以排除胰腺炎所致上腹痛及消化道症状；行脂肪酶检查进一步排除胰腺病变，鉴别腹痛原因；完善凝血功能检查以评估凝血状态，为内镜下取异物等有创操作的安全性提供保障；行腹部超声检查了解腹腔脏器情况，排除肝胆胰病变；查胃镜以直观了解食管内异物性质、位置及黏膜损伤程度，必要时行内镜下异物取出，肠镜必要时完善以排除下消化道病变；行腹部CT检查明确异物位置、有无穿孔及纵隔气肿等并发症；完善幽门螺杆菌检测（C13或C14呼气试验）以了解有无幽门螺杆菌感染，指导后续抑酸及根除治疗方案。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 食管异物\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 预防感染：阿莫西林胶囊0.5g tid×5天（青霉素过敏者改用头孢呋辛酯片0.25g bid×5天），覆盖口腔及食管菌群，防止继发感染。\n2. 抑酸护胃：奥美拉唑肠溶胶囊20mg qd，晨起空腹口服×7天，抑制胃酸反流、促进食管黏膜糜烂修复。\n3. 黏膜保护：铝碳酸镁咀嚼片0.5g tid，餐后嚼服×5天；或硫糖铝混悬液10ml tid×5天，覆盖创面、减轻局部刺激。\n（异物已取出且黏膜损伤轻微者，可仅予第2、3项；存在明显黏膜损伤或可疑穿孔者应住院观察）\n\n【一般治疗及生活指导】\n1. 异物取出后24小时内予温凉流质饮食，24小时后逐步过渡至半流质、软食；1周内避免粗糙、坚硬、过热及带刺、带骨食物，防止损伤创面或再发嵌顿。\n2. 进食细嚼慢咽，避免边进食边说笑、嬉闹；老年患者注意检查及固定义齿，避免误吞枣核、鱼刺、骨片等。\n3. 戒烟酒，避免辛辣刺激食物及咖啡、浓茶，减少对食管黏膜的物理和化学刺激。\n4. 密切观察有无胸骨后疼痛、吞咽疼痛、呕血、黑便等，出现异常立即就诊。\n\n【随诊要求】\n1. 治疗后1周门诊复诊，评估吞咽症状恢复情况；症状持续或加重者复查胃镜，明确食管黏膜愈合及有无瘢痕狭窄。\n2. 若出现发热、剧烈胸骨后疼痛、呕血、黑便等穿孔或出血征象，立即急诊就医，切勿延误。\n3. 合并食管狭窄、贲门失弛缓症或长期异物嵌顿史者，建议定期胃镜随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":616,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6344ccb00c18cba37b4f54c288466201ac58a1793514e5b30e2b10d73c8afc37","pinyin":"shiguanyiwu","initials":"sgyw","setting":"out","caseName":"门诊病历481","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历481",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f8e113b2f4c53d467cb2","key":"v1-c9ccc21dfe2a3058|templates-f8e113b2f4c53d467cb2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"气管支气管异物","category":"门诊病历模板","raw":{"name":"气管支气管异物","category":"门诊病历模板","case":{"case_name":"门诊病历482","templates":{"主诉":"进食后突发剧烈呛咳6小时","现病史":"患儿（6月~3岁儿童最常见，多有口中含物（花生米、瓜子、豆类、小玩具、硬币）并在奔跑哭闹时误吸）于6小时前（进食坚果时突发呛咳（剧烈阵咳，为异物进入气道所致）），呛咳后症状依异物位置不同：喉或气管异物表现为剧烈呛咳、喘鸣、呼吸困难、声嘶、发绀（大异物可立即窒息）；支气管异物（右侧多见，因右主支气管粗而直）呛咳后可有一段时间缓解（异物进入支气管后症状减轻，即安静期，之后出现反复咳嗽、喘鸣及肺部感染，易误诊为哮喘或肺炎，重要，有呛咳史并反复右下肺感染者需警惕异物）；需注意有无面色发绀、意识改变（完全梗阻可致窒息，数分钟内危及生命）、发热（继发感染，异物存留数天至数周可致肺炎或肺脓肿）、咳嗽痰多（感染期）。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.8℃，P130次/分，R32次/分，BP86/54mmHg，SpO2 94%。神志清楚。口唇无发绀。呼吸急促（呼吸困难，可见三凹征及喘鸣）。肺部听诊（为关键：异物侧（右侧）呼吸音减低、吸气性喘鸣（气管异物者）、呼气性哮鸣及局部固定啰音（支气管异物者），患侧呼吸音减弱，与哮喘鉴别：哮喘为双侧对称性哮鸣，异物为单侧或局部、不对称，为重要线索）、拍击音（活动性异物）、咽喉（检查有无异物，必要时视诊）、全身（有无缺氧表现）。","辅助检查":"检查计划：患儿于进食坚果时突发剧烈呛咳6小时，有明确异物吸入史，属儿科急症，可迅速导致窒息，急诊即刻完善胸部X线正侧位检查，直接征象为金属、骨等不透X线异物显影，间接征象为花生等透X线异物所致阻塞性肺气肿（患侧肺过度充气，呼气相纵隔向健侧移位、吸气相正常，为活瓣作用，属关键间接征象）及肺不张（完全阻塞时患侧密度增高），并了解有无反复肺部感染征象；若X线阴性而临床仍高度怀疑异物，完善胸部CT薄层扫描以直接显示异物部位、大小及与气道的关系，敏感性高，明确异物性质及嵌顿情况；完善支气管镜检查，此为诊断金标准且诊断兼治疗，可在直视下明确异物位置并取出，同时了解气道黏膜损伤及肉芽组织形成情况，评估有无继发肺不张、肺炎；必要时完善血常规及CRP检查排除继发细菌感染，为抗感染治疗提供依据；病情稳定后复查胸部X线或CT以评估异物取出后肺复张情况及有无残留病变。\n\n（检查清单）\n【必做】胸部X线（正侧位，直接征象为不透X线异物（金属、骨）显影，间接征象为透X线异物（花生等，占多数，不显影）所致阻塞性肺气肿（患侧肺过度充气，呼气相纵隔向健侧移位，吸气相正常，为活瓣作用，属关键间接征象）、肺不张（完全阻塞，患侧密度增高）、反复肺部感染征象）；【影像】胸部CT（X线阴性而高度疑异物者行薄层CT，可直接显示异物，敏感性高）；【确诊】支气管镜检查（为金标准，诊断兼治疗，可在可视下取出）。","初步诊断":"1. 气管支气管异物（右侧支气管，异物性质为坚果类，呛咳史明确）\n（注：气管支气管异物为急症（可窒息死亡，是儿童意外死亡的重要原因）：①现场急救（完全梗阻（不能咳嗽、发声，发绀）时立即处理：儿童用海姆立克法（1岁以上行腹部冲击；婴儿用背部拍击加胸部冲击交替），无效者行心肺复苏）；②支气管镜异物取出（确诊即取，属急诊，用硬质支气管镜，儿童在全麻下操作，以专用器械钳取，同时做好呼吸道管理（麻醉加通气）；异物大或嵌顿者必要时开胸取出，极少数）；③术后处理（观察（术后气道水肿，予雾化（布地奈德加肾上腺素），监护喉痉挛及水肿，多留观24小时）、抗感染（异物存留时间久或继发感染者用抗生素（阿莫西林克拉维酸），促进肺不张恢复））；④并发症处理（气道梗阻窒息者急救；肺炎、肺脓肿者抗感染加引流（支气管镜吸痰））；⑤预防（为核心，做好宣教：5岁以下儿童勿进食坚果、花生、瓜子（可磨碎后喂），小玩具远离幼儿，进食时勿跑闹哭啼，口中含物时勿逗笑或惊吓，家长教育，重要）；本病由耳鼻喉科及儿科急诊处理，异物取出率高，及时处理者预后好、并发症少，延误可致肺损伤，需警惕隐性异物（反复单侧肺炎者应询问呛咳史）。）","处理方案":"【药物治疗】\n1. 抗感染治疗：异物取出术后预防及控制气道继发感染，首选阿莫西林克拉维酸钾片（0.4g/57mg）1片 tid×5天；青霉素过敏者选用头孢呋辛酯片0.25g bid×5天。\n2. 糖皮质激素：减轻异物刺激所致气道黏膜水肿及炎症，布地奈德混悬液1mg雾化吸入 bid×5~7天；黏膜水肿明显者短期口服醋酸泼尼松片10mg qd×3天。\n3. 祛痰治疗：促进气道分泌物排出、保持气道清洁，盐酸氨溴索片30mg tid×5天。\n\n【一般治疗及生活指导】\n1. 体位与休息：异物未取出或取出后1周内取半卧位或坐位卧床休息，避免剧烈活动及用力屏气、剧烈咳嗽，防止异物移位加重嵌顿。\n2. 饮食：给予温凉流质或半流质饮食，禁食坚果、豆类、带骨刺及粗糙坚硬食物；进食时细嚼慢咽、避免说话嬉笑，防止再次误吸。\n3. 禁忌：严禁自行拍背、抠咽催吐或手指掏取异物，以免异物移位导致窒息；戒烟戒酒，避免烟雾、粉尘等刺激性气体及粉尘环境。\n4. 观察要点：若出现突发剧烈呛咳、吸气性呼吸困难、喘鸣或口唇发绀，立即急诊行支气管镜异物取出。\n\n【随诊要求】\n1. 异物取出术后1周门诊复诊，复查胸部X线或CT，评估异物是否完全取出及气道黏膜恢复情况。\n2. 术后出现发热、咳嗽咳痰加重、咳脓臭痰或呼吸困难者，应及时复诊，复查血常规及胸部CT，警惕继发感染或异物残留。\n3. 异物存留时间较长或术中见气道黏膜明显损伤、肉芽组织增生者，建议4周后复查支气管镜，评估气道狭窄及肉芽消退情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":617,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5d886c549f16efde220164b82c93e8f750de359af055b657e1e5b2f6d43071f6","pinyin":"qiguanzhiqiguanyiwu","initials":"qgzqgyw","setting":"out","caseName":"门诊病历482","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历482",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4016948a6c5fb2d64e65","key":"v1-c9ccc21dfe2a3058|templates-4016948a6c5fb2d64e65","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"颈部淋巴结炎","category":"门诊病历模板","raw":{"name":"颈部淋巴结炎","category":"门诊病历模板","case":{"case_name":"门诊病历483","templates":{"主诉":"颈部肿块伴疼痛5天","现病史":"患者于3天前（急性起病，多因感染（口腔、咽部、扁桃体、牙源性、头皮、耳部感染）致引流区淋巴结肿大；慢性者表现为无痛、渐进性肿大，需查因（结核或肿瘤））出现：颈部肿块及淋巴结肿大（本例为右侧颌下，右侧颌下淋巴结多引流牙及口腔感染；其他部位如颏下、颈深（引流咽及扁桃体）、颈后、锁骨上（重要，左锁骨上淋巴结即Virchow淋巴结，提示腹部或胸部肿瘤转移，需警惕）、枕后（引流头皮），可为单侧或双侧，需记录数量）、疼痛（急性者局部红肿热痛，压痛明显）、发热（急性者伴全身发热）；需注意病史：感染源（咽痛（扁桃体炎）、牙痛（牙源性）、口腔溃疡、头皮感染（疖）、耳痛（中耳炎））、结核（低热盗汗，颈部无痛性肿大，呈串珠样、可融合，即淋巴结核，我国重要）、肿瘤（无痛、质硬、固定、进行性增大，锁骨上者提示转移，如肺癌、胃癌，属警告信号）、淋巴瘤（全身多发、无痛、质韧如橡胶感，伴发热、盗汗、瘙痒及体重下降）、EB病毒（传染性单核细胞增多症，青少年多见，咽痛发热伴淋巴结肿大及肝脾肿大）、HIV、猫抓病（猫抓后由巴尔通体所致局部淋巴结肿大）、免疫反应性；既往史（近期感染、结核接触、肿瘤史、HIV高危）、全身症状（发热、盗汗、消瘦，属警告）、大小变化（急性者经治疗可消退；慢性或无痛性增大者需查因，必要时活检，重要）。今日来我院普外科及耳鼻喉科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.2℃，P92次/分，R20次/分，BP120/76mmHg。颈部（淋巴结（位置及大小（记录直径cm）：右侧颌下可及肿大淋巴结，质地（软（急性炎症）、中等（反应性、结核）、硬（肿瘤，如石样，提示转移癌）、活动度（活动（炎症）、固定（肿瘤浸润））、压痛（急性者有）、表面（红肿、皮温升高（急性化脓）、波动感（脓肿）、串珠样（结核）、多发或融合）、甲状腺（触诊）、涎腺（腮腺、颌下腺有无肿大）、口腔、咽及扁桃体（查找感染灶）、锁骨上（触诊，注意Virchow淋巴结）、腋窝及腹股沟（评估全身淋巴结，注意淋巴瘤）、肝脾（肿大提示淋巴瘤或传染性单核细胞增多症）、全身（皮疹、发热、消瘦）。","辅助检查":"【必做】血常规（白细胞：急性细菌，升高）、CRP（炎症）；【超声】颈部超声（淋巴结（大小/形态（皮髓质分界（清晰：良性；消失，肿瘤）、血流（淋巴门）、脓肿（液性：化脓）、钙化），无创、首选影像）；【其他】（急性，寻找感染源：咽拭子、牙科X线（牙源性）、EBV抗体（青少年、单核）、结核（结核菌素试验/γ-干扰素释放试验/胸片：淋巴结核，我国考虑）、细针穿刺（抽吸化脓、引流/培养；细胞学：结核/肿瘤，初步、重要）、淋巴结活检（切除活检完整淋巴结，病理：金标准，指征（无痛增大（>2~3周不消退）、质硬固定、锁骨上、抗感染无效，排除淋巴瘤/结核/转移癌，重要，勿延误，可疑，活检）、肿瘤原发灶寻找（胸片/CT、鼻咽镜，鼻咽癌：颈部转移：首发；我国鼻咽癌颈部无痛淋巴结，重要，查鼻咽）；血培养（高热）；HIV（高危，发热淋巴结）。","初步诊断":"1. 颈部淋巴结炎（急性细菌性，需评估有无化脓；位置为右侧颌下，引流来源为口腔及牙源性感染，需评估活检指征）\n（注：治疗（依病因）：①急性细菌性（抗感染（经验性覆盖链球菌及金黄色葡萄球菌（口腔咽部来源），可用阿莫西林克拉维酸或头孢，疗程7~10天）、止痛退热、脓肿（有波动感者行穿刺或切开引流（送培养））、一般处理（休息、多饮水）；观察消退情况（抗感染后2~3天开始消退，1~2周消退））；②慢性反应性（查因（治疗感染源，如牙、扁桃体、耳部病变）、观察（感染控制后消退；若持续增大或不消退（超过2~3周）需进一步检查（超声、细针穿刺或活检，排除肿瘤，重要）））；③结核性（淋巴结核，行抗结核治疗（四联方案，6~9个月，参见淋巴结结核，经穿刺或活检确诊）、脓肿形成者抽脓并抗结核）；④肿瘤（活检确诊（淋巴瘤行化疗（如R-CHOP方案）、转移癌需寻找原发灶（如鼻咽癌致颈部转移，需放疗），请肿瘤科会诊，转专科）；⑤随访（急性者治疗后1~2周评估消退情况，未消退或增大者活检；慢性者随访2~3个月，观察变化，有活检指征（持续、增大、质硬、锁骨上）者活检，勿延误，重要）；本病由普外科及耳鼻喉科诊治，急性者抗感染，慢性者查因，无痛、质硬、固定及锁骨上淋巴结者应活检，以排除肿瘤及结核，重要。","处理方案":"【药物治疗】\n1. 首选口服抗菌药物覆盖链球菌及金黄色葡萄球菌：阿莫西林胶囊 0.5g tid×7天（空腹或餐后均可，与食物同服可减少胃肠道反应）。\n2. 青霉素过敏者换用：克林霉素胶囊 0.3g tid×7天；或阿奇霉素片 0.5g qd×5天（首日 0.5g，第2-5天 0.25g qd亦可）。\n3. 疼痛明显或伴发热者：布洛芬缓释胶囊 0.3g bid，体温正常、疼痛缓解后停药（一般不超过3-5天）。\n4. 局部治疗：鱼石脂软膏外敷肿大淋巴结处，每日1-2次，连续3-5天；红肿热痛明显时改用10%硫酸镁溶液湿敷，每日2-3次。\n\n【一般治疗及生活指导】\n1. 注意休息，避免熬夜、劳累及剧烈运动，保证充足睡眠，提高机体免疫力；发热期间适当卧床休息。\n2. 清淡饮食，多饮水，多食富含维生素的新鲜蔬菜水果；忌辛辣刺激、油炸及过烫食物，戒烟酒。\n3. 保持口腔及咽部卫生，积极治疗龋齿、牙周炎、扁桃体炎、上呼吸道感染等原发感染灶（本病多由头颈部感染继发所致）；切忌反复触摸、按压、挤压肿大淋巴结。\n4. 局部可予以温热敷促进炎症吸收，每日2-3次，每次15-20分钟；若局部出现波动感（已成脓）则禁热敷，禁止自行挤压排脓。\n\n【随诊要求】\n1. 用药3天后复诊评估疗效；若48-72小时体温不退或持续≥38.5℃、疼痛加剧、淋巴结迅速增大、局部皮肤发红发热明显，应随时复诊。\n2. 疗程结束后复查颈部触诊，淋巴结应明显缩小、压痛消失；若抗生素足疗程治疗后淋巴结无缩小或持续肿大超过2-4周，需行血常规、ESR/CRP、颈部彩超检查，必要时淋巴结穿刺或活检，以排除结核性淋巴结炎、淋巴瘤等疾病。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":618,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2250ce2fa59eed60a4468e490b3770aabe511c5220f2a82815ef95126f3d9bdf","pinyin":"jingbulinbajieyan","initials":"jblbjy","setting":"out","caseName":"门诊病历483","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历483",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-91d952a2e866ef242b07","key":"v1-c9ccc21dfe2a3058|templates-91d952a2e866ef242b07","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"颈部脓肿","category":"门诊病历模板","raw":{"name":"颈部脓肿","category":"门诊病历模板","case":{"case_name":"门诊病历484","templates":{"主诉":"颈部红肿疼痛伴发热1周","现病史":"患者1周前无明显诱因出现颈部脓肿相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以颈部红肿疼痛伴发热1周为主诉，局部红肿热痛伴全身症状提示颈部化脓性感染可能，需评估感染程度及有无脓肿形成，急诊完善血常规检查排除感染程度及贫血，了解白细胞及中性粒细胞水平以指导抗感染治疗；查凝血功能以评估凝血状态，为可能的切开引流手术提供安全保障；完善肝肾功能检查以评估肝肾代谢能力，指导抗生素选择及剂量调整，排除肝肾功能不全所致药物蓄积；查电解质以了解有无因发热、进食减少所致水电解质紊乱；查血糖以排除糖尿病所致感染迁延不愈及免疫功能低下；行血型检查为可能的输血及手术做好准备；完善颈部超声检查以明确脓肿的部位、大小、范围、液化程度及与周围血管神经的关系，为穿刺或切开引流定位；行颈部CT检查了解脓肿深部范围、有无累及纵隔及气道受压情况，必要时增强扫描明确脓肿壁及血供；完善颈部MRI检查以更清晰显示软组织受累范围及有无骨髓炎、椎前间隙感染，鉴别肿瘤性病变；查心电图以了解心脏基础状态，评估手术及麻醉耐受性；行胸部X线片检查排除纵隔感染、肺部并发症及异物所致；必要时完善肿瘤标志物检查以排除颈部转移性肿瘤所致淋巴结坏死液化，明确病变性质。\n\n（检查清单）\n【必做检查】\n血常规、凝血功能、肝肾功能、电解质、血糖、血型\n\n【影像学检查】\nX线片、CT、MRI、超声\n\n【其他检查】\n心电图、胸部X线片、肿瘤标志物（必要时）","初步诊断":"1. 颈部脓肿\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗感染：颈部脓肿多为口腔厌氧菌与链球菌等混合感染，首选阿莫西林克拉维酸钾片0.625g口服bid（或头孢呋辛酯片0.25g口服bid），联合甲硝唑片0.4g口服tid抗厌氧菌，疗程5～7天；青霉素或头孢过敏者改用莫西沙星片0.4g口服qd＋甲硝唑片0.4g tid。\n2. 对症镇痛：布洛芬缓释胶囊0.3g口服bid（餐后服），或对乙酰氨基酚片0.5g口服prn，每日不超过4次。\n3. 局部处理：脓腔形成、波动感明显者应转耳鼻喉科行穿刺或切开引流，避免自行挤压。\n\n【一般治疗及生活指导】\n1. 休息：急性期注意休息、保证充足睡眠，避免劳累及熬夜。\n2. 饮食：进食温凉流质或半流质软食，多饮水，忌辛辣、过烫及坚硬粗糙食物，戒烟戒酒。\n3. 口腔卫生：加强口腔清洁，每日刷牙并配合漱口液含漱，积极治疗龋齿、牙周炎等原发感染灶。\n4. 禁忌：脓肿未充分引流前勿热敷、勿自行挤压，以防感染扩散；密切观察有无呼吸困难、吞咽困难、张口受限等压迫症状。\n\n【随诊要求】\n1. 用药后2～3天复诊，评估肿痛消退情况与药物疗效，必要时复查血常规、C反应蛋白。\n2. 若48～72小时症状无缓解或加重（持续高热、颈部肿胀进行性增大、出现声嘶/吞咽困难/呼吸困难），应立即就诊，行颈部超声或CT检查并请耳鼻喉科评估是否需手术引流。\n3. 脓肿引流术后遵医嘱定期换药直至脓腔闭合；原发龋齿、牙周病需同步规范治疗，防止复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":619,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"81f925de9de11a40ac5d8691f04a7d50e934bbf1ed04067b3d3f89aad914632c","pinyin":"jingbunongzhong","initials":"jbnz","setting":"out","caseName":"门诊病历484","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历484",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-31ce350d64bf18af5dd2","key":"v1-c9ccc21dfe2a3058|templates-31ce350d64bf18af5dd2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲状腺炎","category":"门诊病历模板","raw":{"name":"甲状腺炎","category":"门诊病历模板","case":{"case_name":"门诊病历485","templates":{"主诉":"颈前肿痛伴发热2周","现病史":"患者于1周前出现：颈前肿痛（按分型表现如下：亚急性甲状腺炎（病毒性，最常见，女性及中青年多见，起病前常有上呼吸道感染前驱症状，表现为颈痛（甲状腺区疼痛，可放射至耳部及下颌，吞咽时加重）、发热（低热至中高热）、甲状腺肿大（有压痛、质硬）、甲功波动（早期因甲状腺破坏、激素释放而出现甲亢，表现为怕热、心悸、手抖；后期转为甲减，表现为畏寒、乏力；之后恢复））、急性化脓性甲状腺炎（细菌所致，少见，颈前红热痛，可形成脓肿，出现吞咽及呼吸困难，发热高）、桥本甲状腺炎（自身免疫性，为最常见甲状腺炎及甲减主要原因，呈慢性，甲状腺肿（无痛、质韧），早期可因破坏释放出现一过性甲亢，之后多数逐渐出现甲减，抗甲状腺过氧化物酶抗体阳性，我国女性及中年多见）、无痛性（静息型）甲状腺炎（产后甲状腺炎，多于产后1年内发生，甲亢与甲减交替波动，呈自限性）、放射性甲状腺炎（碘131治疗后，少见））；表现（颈痛、发热、甲亢或甲减症状、甲状腺肿及压痛）；甲功（需查游离三碘甲状腺原氨酸、游离甲状腺素及促甲状腺激素，可见波动，亚急性者先呈甲亢（促甲状腺激素降低），后期甲减）；既往史（上呼吸道感染（亚急性）、产后（无痛性）、自身免疫病及家族史（桥本）、碘摄入情况、甲状腺药物（甲亢治疗、碘131或抗甲状腺药可致破坏性甲状腺炎））。今日来我院内分泌科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.8℃，P96次/分（甲亢期偏快），R20次/分，BP126/78mmHg。甲状腺（肿大（程度Ⅰ~Ⅲ度）、质地（亚急性者质硬、压痛（++），触痛明显，为特征；桥本者质韧如橡皮样，无痛或轻压痛；化脓者局部红肿热，可有波动感（脓肿））、表面（光滑，桥本者可有结节）、活动（随吞咽上下移动）、血管杂音（无，甲状腺炎无杂音，可与Graves甲亢鉴别））、颈部（淋巴结，化脓者可见肿大）、甲亢体征（手抖、眼（无突眼，甲状腺炎所致甲亢无眼征，Graves病则有，可鉴别）、心率）、甲减体征（黏液性水肿、反射迟滞，见于后期）、局部（颈前有无红热，见于化脓者）。","辅助检查":"【必做】甲状腺功能（游离三碘甲状腺原氨酸、游离甲状腺素及促甲状腺激素，用于分期（甲亢期游离甲状腺素高、促甲状腺激素低，见于亚急性、无痛性及桥本早期；甲减期游离甲状腺素低、促甲状腺激素高；之后恢复）、甲状腺过氧化物酶抗体及甲状腺球蛋白抗体（桥本者显著升高，为诊断核心）、促甲状腺激素受体抗体（用于与Graves病鉴别，甲状腺炎者阴性）、血沉（亚急性者显著增快（大于50~100mm/h，为特征，支持诊断）、CRP、血常规（化脓者白细胞升高）、甲状腺摄碘率（亚急性者极低（因甲状腺破坏致摄碘下降，出现分离现象，即甲状腺炎所致甲亢摄碘低，而Graves病摄碘高，为鉴别关键）、甲状腺核素显像（摄碘低）、甲状腺超声（甲状腺弥漫性回声减低（亚急性者可见低回声区，与压痛处一致；桥本者弥漫低回声、呈网格样，血流可增多）、化脓者可见脓肿）；【确诊】化脓者行穿刺（抽脓并送培养）、亚急性者依临床表现加血沉及摄碘率诊断，多不需活检、桥本者依抗体加超声诊断、细针穿刺（诊断不明或有结节者，用于排除肿瘤，桥本者并发淋巴瘤风险极低，结节需评估恶性可能）；【其他】血钙（必要时检测）、肝肾功能（治疗前评估）。","初步诊断":"1. 甲状腺炎（亚急性肉芽肿性（De Quervain），甲功分期为甲亢期，需评估摄碘率及抗体）\n（注：治疗（依分型及甲功而定，多数呈自限性）：①亚急性甲状腺炎（核心为止痛抗炎：非甾体抗炎药（布洛芬或萘普生，用于轻中度颈痛，为首选）、糖皮质激素（泼尼松30~40mg/d，用于症状重或非甾体抗炎药无效者，可显著缓解（24~48小时颈痛及发热缓解，为特征，支持诊断），需逐渐减量（4~8周，血沉正常后减量，勿骤停，以免复发））、甲亢期（为一过性，可用β受体阻滞剂（普萘洛尔，缓解心悸），不用抗甲状腺药（因非甲状腺毒症，属破坏性，不用，重要）、甲减期（多为一过性，多数可自行恢复，明显者用左甲状腺素（短期使用，甲功恢复后停药））、随访（甲功，1~2个月复查恢复情况））；②桥本甲状腺炎（甲功正常者观察随访（每年查甲功及促甲状腺激素，监测是否进展为甲减）、甲减者用左甲状腺素替代（终身服用，目标为使促甲状腺激素正常，参见甲减）、甲状腺肿（明显压迫者可用左甲状腺素缩小，部分有效，或手术（用于压迫或疑恶性者））、定期超声（观察结节，排除甲状腺癌（桥本者乳头状癌风险轻度升高，需评估并随访）））；③无痛性及产后甲状腺炎（观察（自限性）、甲亢期用β受体阻滞剂（一过性）、甲减期用左甲状腺素（恢复后停药，产后6~12个月随访甲功）、产后哺乳者需注意用药安全）；④急性化脓性（抗生素（静脉广谱）、脓肿行切开引流（外科处理），少见）；⑤随访（甲功（亚急性者每2~4周复查，初期密切，恢复后延长间隔；桥本者每6~12个月复查）、血沉（亚急性者用于治疗监测）、超声（桥本者有结节者每年复查）、症状（观察颈痛、发热消退及甲功变化，识别各期并相应处理）；本病由内分泌科诊治，先分型，亚急性者用激素，桥本者行替代治疗，需长期随访，重要。","处理方案":"【药物治疗】\n1. 轻中度亚急性甲状腺炎（甲状腺肿痛、低热，无高热）：布洛芬缓释胶囊0.3g po bid，饭后服，连用7-14天；或双氯芬酸钠缓释片75mg po qd。\n2. 中重度亚急性甲状腺炎（持续高热、甲状腺明显肿痛或NSAIDs疗效不佳）：泼尼松片30mg（约0.5mg/kg）po qd晨起顿服，症状缓解后（一般1-2周）每周减量5mg，总疗程4-8周，不可骤停或自行减量。\n3. 甲状腺毒症症状明显（心悸、手抖、多汗）：普萘洛尔片10mg po tid，连用2-4周，使静息心率控制在70-90次/分（哮喘、严重心衰、Ⅱ度以上房室传导阻滞者禁用）。\n4. 桥本甲状腺炎并临床甲减（TSH升高、FT4降低）：左甲状腺素钠片（优甲乐）25-50μg po qd晨起空腹服，服药后至少间隔30-60分钟再进食，每4-6周复查TSH调整剂量，直至TSH达标后维持。\n\n【一般治疗及生活指导】\n1. 休息与活动：发热、甲状腺明显肿痛或甲亢症状明显期应卧床休息或减少活动，避免剧烈运动和过度劳累，待症状缓解后再逐步恢复日常活动。\n2. 饮食：保持正常碘摄入即可，避免长期大量进食海带、紫菜、海鱼等高碘食物，忌用含碘药物（如胺碘酮）；少食辛辣刺激性食物，戒烟限酒。\n3. 生活起居：规律作息，避免熬夜、精神紧张和情绪波动，因应激、劳累、感染可诱发亚急性甲状腺炎复发或加重病情。\n4. 用药注意事项：NSAIDs饭后服用以减轻胃黏膜刺激，必要时联用质子泵抑制剂护胃；服用泼尼松期间注意监测血糖、血压，不得自行停药；左甲状腺素应与铁剂、钙剂、铝碳酸镁等间隔4小时以上服用。\n\n【随诊要求】\n1. 亚急性甲状腺炎：治疗期间每1-2周复诊1次，监测体温、甲状腺肿痛程度及血沉（ESR）、CRP变化；疗程结束后每月复查甲状腺功能1次，共随访6-12个月，因部分患者病程中可出现一过性甲减甚至永久性甲减，需评估是否加用左甲状腺素替代治疗。\n2. 桥本甲状腺炎：服用左甲状腺素者每4-6周复查甲状腺功能调整剂量，达标后每6-12个月复查甲功及甲状腺抗体（TPOAb、TgAb）；甲状腺功能正常未用药者每6-12个月复查1次甲功。\n3. 出现高热不退、甲状腺肿痛进行性加重、声音嘶哑、吞咽困难或呼吸困难时，应立即就诊，警惕甲状腺脓肿或压迫症状。\n4. 育龄期女性备孕及妊娠期间应将TSH控制在2.5mIU/L以下（孕早期<2.5mIU/L），孕前及孕期均应至内分泌专科门诊就诊调整用药，产后注意随访监测。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":620,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8705e071b70b5af03012004750e7d562a095202c25bcaae7321f8410de44e7aa","pinyin":"jiazhuangxianyan","initials":"jzxy","setting":"out","caseName":"门诊病历485","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历485",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e8d9efc01a06c1478afa","key":"v1-c9ccc21dfe2a3058|templates-e8d9efc01a06c1478afa","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲状腺肿瘤","category":"门诊病历模板","raw":{"name":"甲状腺肿瘤","category":"门诊病历模板","case":{"case_name":"门诊病历486","templates":{"主诉":"发现颈部肿块6月","现病史":"患者于1周前（体检行超声发现甲状腺结节（检出率极高，超声检查约50%人群有结节，多数为良性，重要，不必恐慌；亦可自行触及颈部肿块，可随吞咽上下活动））发现：甲状腺结节（单发、大小依超声测量（以毫米计）并分类、质地依体检判断、多数无症状，以良性为主）、压迫症状（结节较大（大于4cm或位于胸骨后）时可致吞咽困难、呼吸不畅、声嘶（因压迫或侵犯喉返神经，属恶性警告））、疼痛（结节出血或囊内出血时可突然增大并疼痛，多为良性（囊性变））、颈部淋巴结（肿大提示转移，属恶性警告）；甲状腺癌（分化型中乳头状癌最常见（占85%以上，预后极好，10年生存率大于90%，年轻女性多见，淋巴结转移早但预后好）、滤泡状癌（经血行转移至肺、骨）、髓样癌（源于甲状腺滤泡旁细胞，分泌降钙素，可有家族性（多发性内分泌腺瘤2型），可伴腹泻、面部潮红）、未分化癌（老年多见，罕见，预后极差，迅速增大并侵犯周围）、淋巴瘤（多伴桥本甲状腺炎，老年，少见）；甲状腺恶性肿瘤多数为分化型，预后好，早期手术可治愈，重要）；甲状腺结节评估（TI-RADS分类（超声甲状腺影像报告和数据系统，分1~5级，级别越高恶性风险越高，4~5类需细针穿刺评估，重要））；既往史（放射线暴露（头颈部，儿童期照射可增加甲状腺癌风险，重要）、家族史（甲状腺癌、多发性内分泌腺瘤2型及髓样癌、降钙素相关）、桥本甲状腺炎、碘摄入情况）。今日来我院内分泌科及甲状腺外科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P76次/分，R18次/分，BP118/74mmHg。甲状腺（触诊（结节（大小、数目、质地（硬（提示恶性或钙化）；软或囊性（提示良性）、活动度（固定提示恶性）、边界（清或不清）、压痛（出血囊变时可疼痛）、甲状腺（弥漫性肿大，见于桥本）、吞咽（随吞咽上下活动）、颈部淋巴结（肿大、质硬提示转移）、声音（嘶哑提示喉返神经受侵犯，属恶性警告）、呼吸（有无压迫）、远处（转移少见）、多发性内分泌腺瘤体征（黏膜神经瘤、嗜铬细胞瘤所致高血压）。","辅助检查":"【必做】甲状腺超声（为核心：结节（大小、形态、边界（不规则提示恶性）、回声（低回声提示恶性）、钙化（微小钙化提示恶性，重要）、血流（丰富提示恶性）、纵横比（大于1提示恶性）、TI-RADS分级（1~5级，级别越高恶性风险越高，为穿刺指征，重要）、淋巴结（评估颈部转移）、甲状腺功能（促甲状腺激素正常或异常（升高提示桥本；降低提示高功能结节即热结节，多为良性，少见）、甲状腺过氧化物酶抗体（桥本者升高））；【确诊】细针穿刺抽吸活检（FNA，为核心：TI-RADS 4~5类、结节大于1~1.5cm或有高危因素（超声可疑（钙化、低回声、边界不清）、生长迅速、淋巴结可疑、有家族史或放射线暴露史）者行穿刺，细胞学按Bethesda分类（Ⅰ~Ⅵ类，恶性或可疑者手术；良性者随访，重要），不典型或滤泡性病变者手术或行分子检测）；【其他】降钙素（疑髓样癌者升高，用于筛查及多发性内分泌腺瘤家族筛查）、甲状腺球蛋白（术后随访的肿瘤标志物）、颈部CT（大结节、胸骨后或疑淋巴结侵犯者，术前评估）、甲状腺核素显像（热结节（高功能，多为良性，可致甲状腺毒症，处理不同）、声带（声嘶者行喉镜检查喉返神经）。","初步诊断":"1. 甲状腺结节/肿瘤（TI-RADS 4类，单发，细针穿刺Bethesda Ⅴ类（可疑恶性），考虑可疑恶性（待病理，需排除甲状腺乳头状癌），需评估淋巴结转移）\n（注：治疗（依结节评估决定，多数良性者随访，恶性者手术）：①良性结节（细针穿刺为良性且TI-RADS低危者随访（每6~12个月复查超声，观察大小变化（增长超过20%或2mm需再次穿刺）、甲状腺功能正常者不需特殊处理）、大结节（有压迫症状（吞咽困难、呼吸不畅、声嘶）者手术切除（甲状腺叶切除）、胸骨后者手术、出于美容考虑者可评估手术）、甲状腺功能异常（高功能热结节致甲亢者，依情况用抗甲状腺药、碘131或手术））；②可疑或恶性（手术（甲状腺切除术，乳头状癌及滤泡状癌可行甲状腺叶切除或全切（依肿瘤大小、多灶、淋巴结及高危因素决定；分化型甲状腺癌可行全切加中央区淋巴结清扫，低危者可行叶切，需与患者讨论）、术后用左甲状腺素（抑制促甲状腺激素，即TSH抑制，防复发，适用于分化型，需设定目标值）、放射性碘治疗（碘131，术后用于高危者（残余或转移，清除甲状腺床）、甲状腺球蛋白（用于监测复发，全切后甲状腺球蛋白应测不出，升高提示复发）、髓样癌（全切加颈清扫，监测降钙素；多发性内分泌腺瘤者若合并嗜铬细胞瘤，术前需排除，并先处理嗜铬细胞瘤，重要）、未分化癌（预后差，综合治疗，以姑息为主））；③预后（分化型中乳头状癌预后极好（手术治愈率大于95%），早期发现重要，超声普及使检出增多，勿过度治疗（良性占多数，行穿刺明确，避免不必要手术，重要））；④随访（良性者每年超声复查；术后每6~12个月查甲状腺球蛋白或降钙素及超声，监测复发、调整甲状腺素剂量（使促甲状腺激素达标）；有放射史或家族史的高危者定期复查）；本病由内分泌科及甲状腺外科诊治，超声加细针穿刺评估，良性者随访，恶性者手术，分化型预后好，重要。","处理方案":"【药物治疗】\n1. 左甲状腺素钠片（优甲乐）50μg po qd，晨起空腹顿服，服后半小时再进食；分化型甲状腺癌术后行TSH抑制治疗，高危组目标TSH<0.1mIU/L、中危组0.1~0.5mIU/L，每4~6周复查甲功调整剂量，疗程依据复发风险分层持续3~10年；良性结节伴TSH升高者予25μg qd起始，维持TSH在正常范围即可。\n2. 碳酸钙D3片（钙尔奇D）600mg po qd，联合骨化三醇胶丸（罗盖全）0.25μg po bid，用于甲状腺全切术后低钙血症预防，连用2~4周，根据血钙及PTH水平调整后减停。\n3. 颈部淋巴结清扫术后如合并甲状旁腺功能减退、持续低钙者，改予葡萄糖酸钙口服液10ml tid，按血钙监测值个体化调整，血钙稳定正常后逐渐减量。\n【一般治疗及生活指导】\n1. 饮食：均衡营养，避免长期大量摄入海带、紫菜、海鱼等高碘食物，无需严格忌碘；拟行放射性碘131治疗者须于治疗前严格低碘饮食2周。\n2. 休息与活动：术后1个月内避免剧烈运动、重体力劳动及颈部过度后仰、提举重物，可正常散步；避免颈部碰撞和外伤。\n3. 禁忌：戒烟限酒，避免颈部反复接受不必要的X线、CT等放射性检查；术后早期避免大声喊叫及长时间说话，保护喉返神经及声带。\n4. 用药注意：优甲乐患者钙剂、铁剂、铝碳酸镁及豆制品、高纤维食物间隔4小时以上服用，以免影响吸收。\n【随诊要求】\n1. 术后患者：术后1个月复诊复查甲功、血钙、PTH及颈部超声；此后每3~6个月复查甲功，每6~12个月复查颈部超声、甲状腺球蛋白（Tg）及抗Tg抗体，并按复发风险分层定期随访；行放射性碘131治疗者遵核医学科安排随访。\n2. 良性结节观察者：每6~12个月复查甲状腺超声，若结节短期内明显增大（6个月内体积增大≥50%或两条径线增加≥20%）、新发声音嘶哑、吞咽困难、呼吸不畅或触及颈部淋巴结肿大，应及时就诊评估。\n3. 用药期间出现心悸、手抖、多汗、失眠等甲亢表现或乏力、怕冷、浮肿等甲减表现，及时复诊调整剂量。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":621,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4d4200abed78f94192e2fe81b2bb047da51027a5cfaadafcb929b1bafa013564","pinyin":"jiazhuangxianzhongliu","initials":"jzxzl","setting":"out","caseName":"门诊病历486","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历486",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-374f436575ced88794a7","key":"v1-c9ccc21dfe2a3058|templates-374f436575ced88794a7","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"龋病","category":"门诊病历模板","raw":{"name":"龋病","category":"门诊病历模板","case":{"case_name":"门诊病历487","templates":{"主诉":"牙齿冷热刺激痛伴食物嵌塞6月","现病史":"患者于6个月前（渐进，病程数月数年）发现龋洞（牙体呈黑色、有缺损及洞形，探诊可探及），近1个月出现：冷热刺激痛（早期龋达牙本质时，冷热及甜酸刺激可致一过性疼痛，刺激去除后缓解（提示可复性牙髓反应，见于浅龋及中龋））、食物嵌塞痛（嵌塞压迫时疼痛）、自发痛（龋达牙髓时出现，表现为牙髓炎的持续性自发痛及夜间痛，见牙髓炎，深龋者需警惕）、牙痛（持续性、夜间加重要考虑牙髓炎）、口臭；需注意有无氟化物防护（饮水加氟、含氟牙膏，可预防）、口腔卫生（刷牙，每日2次，使用牙线）、甜食（含糖食物及进食频率，为龋齿主因，细菌（变形链球菌）分解糖产酸致脱矿、龋坏）、既往牙科治疗（充填后边缘可发生继发龋）、放射治疗（头颈部放疗致口干，可发生猛性龋）、口干（干燥综合征或药物所致，龋风险高）、儿童（奶瓶龋，含奶瓶入睡或夜奶可致上前牙龋，重要，需预防）、牙齿位置（磨牙窝沟（最常见，为窝沟龋）、邻面（隐蔽，需X线发现）、牙颈（根面龋，老年牙龈萎缩者多见））；按分度分为浅龋（仅累及釉质，无症状）、中龋（达牙本质浅层，有刺激痛）、深龋（达牙本质深层，接近牙髓，刺激痛明显，可累及牙髓）。今日来我院口腔科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P74次/分，R18次/分，BP116/72mmHg。口腔（患牙（牙位为右下第一磨牙）、龋洞（部位（邻面）、大小及深度（以探针探诊，龋洞内为软化牙本质，探痛（中龋及深龋敏感）、穿髓点（深龋可探及，疼痛）、颜色（呈黄褐色）、冷热诊（浅龋无反应；中龋及深龋有刺激痛，可复性者去除刺激后缓解；深龋近髓者疼痛明显）、叩诊（无痛提示牙髓未受累；疼痛提示牙髓或根尖病变，参见相应章节）、松动（无）、牙龈（红肿提示食物嵌塞所致龈乳头炎）、牙周（牙石）、对颌牙（咬合情况）、全口（检查其他龋齿，评估口腔卫生）。","辅助检查":"【必做】口腔检查（探诊加冷热诊，用于诊断）；【影像】X线（根尖片或咬合翼片（可发现邻面龋（隐蔽、早期者需X线发现，重要）、判断龋坏深度（是否近髓或穿髓，为治疗决策依据）、继发龋（充填体下方，需X线）、评估牙髓及根尖（牙髓炎、根尖周炎）））；【其他】龋活跃性检测（儿童及高龋风险者用于预防评估，较少用）、口腔卫生评估。","初步诊断":"1. 龋病（右下第一磨牙，中龋，部位为邻面，需评估继发龋及牙髓受累）\n（注：治疗（去除龋坏加充填修复，防止进展，早治是关键，浅龋可再矿化）：①浅龋及早期龋（釉质龋或白垩斑，行再矿化治疗（氟化物（涂氟、含氟牙膏，可再矿化并抑制进展）、窝沟封闭（儿童用于预防窝沟龋，重要）），并观察）；②充填治疗（适用于中龋及深龋（未穿髓）：去龋（去除龋坏组织，保留健康牙体，制备洞形）、充填（复合树脂（美观，适用于前牙及后牙，为现代首选）或银汞、玻璃离子（用于后牙及根面，现已少用）、垫底（深龋近髓者用氢氧化钙垫底，保护牙髓，防刺激）、充填后（调整咬合、抛光））；就诊于牙体牙髓科或口腔科，行充填以恢复功能，防止发展为深龋及牙髓炎）；③深龋近髓或穿髓（行牙髓治疗（见牙髓炎，可行盖髓或根管治疗））；④预防（为核心，防龋措施：口腔卫生（正确刷牙（Bass法，每日2次，每次2分钟，使用含氟牙膏（氟化物可防龋，重要）、牙线（清洁邻面，每日使用）、定期口腔检查（每6~12个月，早发现早治疗，并检查充填体有无继发龋）、饮食（控制糖摄入（减少甜食，尤其注意进食频率及黏性糖，避免两餐间进食）、氟化物（饮水加氟、涂氟，儿童每年进行）、窝沟封闭（儿童磨牙，6~8岁第一恒磨牙封闭，预防效果重要）、儿童奶瓶龋的预防（不含奶瓶入睡，夜奶后清洁口腔））；⑤随访（充填后观察症状（刺激痛消失；短期不适可观察，持续者复诊（检查咬合高点、调磨、充填体边缘及继发龋）、定期检查（充填体及邻面，必要时X线复查继发龋））；本病由口腔科诊治，早期充填，防止累及牙髓，以预防为主，含氟及窝沟封闭、定期检查，重要。","处理方案":"【药物治疗】\n1. 氟化物类：含氟保护漆（如多乐氟、氟保护漆）局部涂布患牙及邻面，每3-6个月1次；日常使用含氟牙膏（氟浓度1000-1500ppm），每日早晚各刷牙1次，每次不少于2分钟。\n2. 再矿化制剂：酪蛋白磷酸肽-无定形磷酸钙（CPP-ACP，如GC护牙素/Tooth Mousse）涂布于牙面及窝洞周围，每日1次，睡前刷牙后使用，用于早期龋（白垩斑）再矿化及预防继发龋。\n3. 含氟含漱液：0.05%氟化钠含漱液，每次10ml含漱1分钟，每日1次，含漱后30分钟内不进食、不饮水；对活动性龋风险较高者可使用0.12%氯己定含漱液10ml含漱30秒，每日2次，连续不超过2周。\n【一般治疗及生活指导】\n1. 尽早完成充填治疗：浅龋可行保守再矿化治疗或树脂充填；中深龋应去除龋坏组织后行树脂/玻璃离子充填修复，深龋近髓者需完善垫底、盖髓或根管治疗，避免延误导致牙髓炎。\n2. 饮食控制：减少蔗糖及其他游离糖摄入频率，避免粘性含糖食物（如糖果、饼干）和碳酸饮料，两餐间少吃零食，进食后立即清水漱口。\n3. 口腔卫生维护：采用Bass（巴氏）刷牙法有效清洁牙面、牙龈沟及窝沟，配合使用牙线或牙间隙刷清洁邻面，每3-6个月行洁治（洗牙）1次，去除菌斑与牙石。\n4. 定期防龋检查：每6-12个月进行口腔检查，高危患者每3-6个月复查，及时处理早期龋及充填物边缘渗漏。\n【随诊要求】\n1. 充填或治疗后如出现冷热刺激痛、自发痛、夜间痛、咬合痛或充填体脱落、折断，应及时复诊。\n2. 每6-12个月定期口腔检查；接受涂氟、再矿化治疗者每3-6个月复诊评估龋病进展及防治效果。\n3. 如发现充填物边缘着色、邻面塞食物或牙体再次变色缺损，提示继发龋，应随时复诊进行X线检查及修补。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":622,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2d200e9f318c247049d96f38f352f29911eafe6046ec7b789f78757c2fba265b","pinyin":"qubing","initials":"qb","setting":"out","caseName":"门诊病历487","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历487",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-abdb17c144d7e1c61ffc","key":"v1-c9ccc21dfe2a3058|templates-abdb17c144d7e1c61ffc","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"牙髓炎","category":"门诊病历模板","raw":{"name":"牙髓炎","category":"门诊病历模板","case":{"case_name":"门诊病历488","templates":{"主诉":"牙痛3天","现病史":"患者于3天前出现牙痛：自发性阵发性疼痛（无刺激时发作、夜间加重、平卧时更痛，为牙髓炎特征）、冷热刺激诱发或加重（早期为冷刺激痛，化脓期则热痛冷缓解）、疼痛不能明确定位（为牵涉痛，上牙可放射至耳颞部，下牙放射至下颌，定位模糊）；有无深龋洞、充填体、牙体隐裂或外伤史及近期补牙史；疼痛呈持续性自发痛（属不可逆性，需根管治疗，与可逆性的一过性刺激痛鉴别，重要）；有夜间痛醒，影响睡眠。今日来我院口腔科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P78次/分，R18次/分，BP118/74mmHg。患牙（牙位为左下第一磨牙）可见深龋洞，探诊（龋洞探痛，可探及穿髓点），叩诊（无明显叩痛，早期牙髓炎叩诊多正常，根尖周炎则叩痛明显，可鉴别），冷热诊（温度测验：不可逆性者激发痛持续，热痛明显；可逆性者为一过性痛），电活力测验（评估牙髓活力），牙龈及根尖区（无肿胀，根尖周炎时可见肿胀）。","辅助检查":"【必做】临床检查为主（探诊、冷热诊、叩诊、电活力测试，为诊断核心）；【影像】根尖X线片（判断龋坏深度（近髓或穿髓）、根尖周正常，可与根尖周炎鉴别）、咬合翼片（检查邻面龋）；【其他】必要时行曲面断层。","初步诊断":"1. 牙髓炎（左下第一磨牙，不可逆性，急性）\n（注：可逆性（一过性刺激痛）者行去龋充填加间接盖髓（氢氧化钙）以保髓；不可逆性（自发痛持续）者行根管治疗（开髓引流减压止痛，根管预备、消毒、充填，全冠修复以防劈裂）；急性疼痛者急诊开髓（最有效的止痛方法）；抗生素一般不需要（牙髓炎非感染扩散，除非伴根尖周炎或蜂窝织炎，可用阿莫西林加甲硝唑）；无法保留（残根或破坏大）者拔除后修复；预防应定期检查并及时治疗龋齿。）","处理方案":"【药物治疗】\n1. 抗感染：阿莫西林胶囊0.5g tid×5天（青霉素过敏者改用克林霉素胶囊0.3g qid×5天），联合甲硝唑片0.2g tid×5天（或奥硝唑片0.5g bid×5天）覆盖口腔厌氧菌。\n2. 镇痛：布洛芬缓释胶囊0.3g bid×3天（餐后服，活动性消化道溃疡者禁用），或洛索洛芬钠片60mg tid×3天。\n3. 局部含漱：复方氯己定含漱液10ml含漱1分钟，bid×5天，保持口腔清洁、减轻炎症。\n\n【一般治疗及生活指导】\n1. 患侧暂勿咀嚼，进温凉软食，避免过冷、过热、过甜及辛辣刺激诱发疼痛。\n2. 保持口腔卫生，餐后温水漱口，使用软毛牙刷轻柔清洁，避免患牙叩击、剔牙等刺激。\n3. 急性牙髓炎药物治疗仅能缓解症状、控制感染，不能根治，应尽快于口腔科行开髓引流及根管治疗。\n4. 疼痛剧烈时可局部冷敷面颊部（每次15分钟，间隔1小时以上）以减轻肿胀与疼痛。\n\n【随诊要求】\n1. 药物治疗3天后复诊，评估疼痛、叩痛及全身症状改善情况，必要时调整抗菌方案。\n2. 症状缓解后尽早（1周内）于口腔科完成开髓引流和根管治疗，避免转为根尖周炎。\n3. 若疼痛持续不缓解，或出现面部肿胀、发热、张口受限等，需立即复诊或急诊处理。\n4. 根管治疗完成后按医嘱定期复查（通常3~6个月），评估根尖周愈合情况并完成永久性牙体修复。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":623,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0c670113798ae5a0abb407183ceb1d3690ec40d76cab64b63d4a92aff37defc1","pinyin":"yasuiyan","initials":"ysy","setting":"out","caseName":"门诊病历488","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历488",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-95c5171008d6011b6c0a","key":"v1-c9ccc21dfe2a3058|templates-95c5171008d6011b6c0a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"根尖周炎","category":"门诊病历模板","raw":{"name":"根尖周炎","category":"门诊病历模板","case":{"case_name":"门诊病历489","templates":{"主诉":"牙痛伴牙龈肿胀3天","现病史":"患者于3天前出现患牙持续胀痛（咬合时剧痛，不敢咬合、牙齿有浮起伸长感（根尖渗出所致）、持续性钝痛，定位明确，可指出患牙为右下第一磨牙）、叩痛明显；有无牙龈肿胀（根尖区前庭沟变浅、有波动感提示根尖周脓肿）、面部肿胀（颊面部蜂窝织炎，可扩散）、发热、龋病史或牙髓炎治疗史（未治疗为最常见来源）、牙外伤或隐裂史；无夜间加重（夜间加重多见于牙髓炎，可鉴别）。今日来我院口腔科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.6℃，P84次/分，R18次/分，BP120/76mmHg。患牙叩痛（垂直及侧方叩诊均明显）、松动度（Ⅰ度）、根尖区牙龈充血肿胀（前庭沟变浅隆起、有波动感提示脓肿）、牙体深龋或充填体（提示牙髓来源）、温度诊无反应（牙髓多已坏死）、区域淋巴结（肿大，提示扩散）、面颊部肿胀（需评估）。","辅助检查":"【必做】叩诊（为关键）及临床检查、根尖X线片（根尖周透射影提示慢性骨破坏；早期可正常，急性期以临床表现为准）；【其他】脓肿穿刺（于波动处穿刺排脓）、CBCT（复杂根管或需明确病变范围时，必要时）。","初步诊断":"1. 急性化脓性根尖周炎（右下第一磨牙，即根尖周脓肿）\n（注：根管治疗为根本：急性期行开髓引流（减压）加脓肿切开引流（于波动处）加调磨减咬合加全身抗生素（伴面部肿胀、发热者用阿莫西林克拉维酸加甲硝唑，以抗厌氧菌为主）；炎症控制后行根管治疗（清理、成形、消毒、充填）；根管治疗失败或病变不消退者行根管再治疗或根尖手术；无法保留者拔除加根尖刮治；并发症为颌面部间隙感染（肿胀扩散，需住院静脉用抗生素加切开引流，可致纵隔感染或败血症，属急诊）；治疗后随访X线（观察根尖病变愈合，6~12个月复查）。）","处理方案":"【药物治疗】\n1. 青霉素类+硝基咪唑类联合抗感染：阿莫西林胶囊0.5g tid×5-7天，联合甲硝唑片0.4g tid×5-7天（青霉素过敏者改用克林霉素胶囊0.3g qid×5-7天，或头孢呋辛酯片0.25g bid×5-7天；甲硝唑与酒精同服可引起双硫仑样反应，服药期间禁酒）。\n2. 解热镇痛：布洛芬缓释胶囊0.3g bid，疼痛明显时服用（或对乙酰氨基酚片0.5g prn，日不超过2g），用于急性根尖周炎疼痛控制，餐后服用。\n3. 急性化脓期如伴发热、面部肿胀明显：可静脉给药或加用头孢类，必要时转口腔科急诊行开髓引流、切开排脓，药物疗程延长至7-10天。\n【一般治疗及生活指导】\n1. 尽快于口腔科行根管治疗（开髓引流、根管预备消毒及根管充填）为根治手段，药物治疗仅为辅助控制感染；急性期脓肿形成者需行牙槽脓肿切开引流。\n2. 患牙避免咀嚼及受力，进食温凉软食，忌辛辣、过烫及硬性食物，以免加重炎症及疼痛。\n3. 保持口腔清洁，每日早晚刷牙、饭后温盐水（或0.05%氯己定含漱液）漱口，注意患牙周围清洁。\n4. 急性期注意休息，避免劳累及熬夜，保持充足睡眠以增强抵抗力；如出现面部进行性肿胀、张口受限、发热等应尽早就医，警惕间隙感染。\n【随诊要求】\n1. 急性疼痛、肿胀明显者3天后复诊评估疗效；用药5-7天后复诊，复查症状体征，必要时复查血常规、调整抗感染方案。\n2. 根管治疗需按疗程定期复诊，一般需2-4次（开髓引流、根管预备消毒、根管充填），请遵医嘱按时完成全部根管治疗，勿中途中断。\n3. 根管治疗完成后1周复诊，拍X线根尖片评估根充质量；术后3-6个月及1年复查根尖周愈合情况，若出现患牙疼痛、咬合不适或肿胀随时复诊。\n4. 根管治疗后建议行全冠修复保护患牙，修复前避免使用患侧咀嚼过硬食物。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":624,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ed6f886cb494d14184999bcfd71dae11e7bff35969adbf41b78686b5e82807a8","pinyin":"genjianzhouyan","initials":"gjzy","setting":"out","caseName":"门诊病历489","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历489",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-55c2f1d6d1c90b840780","key":"v1-c9ccc21dfe2a3058|templates-55c2f1d6d1c90b840780","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"牙周脓肿","category":"门诊病历模板","raw":{"name":"牙周脓肿","category":"门诊病历模板","case":{"case_name":"门诊病历490","templates":{"主诉":"牙龈肿痛、溢脓3天","现病史":"患者（牙周炎基础：深牙周袋（大于5~6mm）致慢性牙周炎急性发作，脓液积存于牙周袋内、引流不畅而形成脓肿，为最常见原因；亦可因食物嵌塞（牙周袋内）、牙周治疗（刮治后残留）、异物（鱼刺或牙签刺入）、全身因素（如糖尿病（本例既往否认，血糖控制差者易反复发作，重要）、免疫功能异常））于3天前出现：牙龈红肿（牙周袋区域局限性肿胀）、疼痛（呈跳痛，进行性加重，有咬合痛（牙齿有浮起感、伸长感，咬合时先接触对颌牙而疼痛）、牙齿松动（急性加重，因脓液积聚于牙周膜）、脓液（挤压牙周袋可见溢脓）、口臭、发热（可有低热）、淋巴结（颌下肿大）；需注意鉴别：根尖周脓肿（牙髓坏死，有龋或充填体，叩痛明显，X线示根尖阴影）与牙周脓肿（牙髓多存活，牙周袋深，骨吸收呈水平型，两者区别重要，治疗不同）、牙龈脓肿（位于龈乳头，表浅，无牙周袋，与牙周脓肿的深袋区分）、牙周-牙髓联合病变（两者并存）；既往情况（牙周炎（诊断及刮治史，有无出血、牙周袋）、糖尿病（控制情况，重要）、吸烟（可加重牙周破坏）、口腔卫生）。今日来我院口腔科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.4℃，P82次/分，R18次/分，BP118/74mmHg。牙周（患牙（牙位为左下第一磨牙）、牙龈（局限性红肿（牙周袋口隆起）、压痛、有波动感（脓肿））、牙周袋（探诊（深袋（大于5~6mm）、溢脓（挤压可见脓液）、探诊出血）、牙髓（活力正常，重要，可与根尖周脓肿鉴别，牙周脓肿者牙髓多存活、无深龋）、牙松动（Ⅱ度）、叩诊（疼痛，有咬合痛及浮起感）、X线（牙槽骨呈水平吸收（牙周炎）、根尖正常（无根尖阴影，可鉴别））、邻牙（检查牙周情况）、口腔卫生（牙石、菌斑）、全身（评估有无糖尿病（本例否认），必要时查血糖）。","辅助检查":"【必做】牙周检查（探诊、溢脓、松动，为核心）、牙髓活力测试（用于鉴别，牙周脓肿者牙髓正常）、X线（根尖片或曲面断层：牙槽骨吸收（牙周炎，呈水平或垂直型）、根尖有无阴影（与根尖周脓肿鉴别，重要）、牙周袋深度）；【其他】血糖（糖尿病与牙周脓肿相互影响，为反复发作的重要因素，应检查，重要）、脓液培养（用于反复发作或难治者，查牙周病原菌，非常规）。","初步诊断":"1. 牙周脓肿（左下第一磨牙，深牙周袋（7mm）急性感染，伴牙周炎，需评估糖尿病，牙髓活力正常（与根尖周脓肿鉴别））\n（注：治疗（引流加抗感染加牙周治疗）：①脓肿引流（为关键，应立即处理：通过牙周袋引流（用探针轻柔扩张袋口，引流脓液）、生理盐水冲洗（冲洗牙周袋，清除脓液）、牙周袋内上药（碘甘油或米诺环素软膏，局部用药）；脓肿表浅者可于牙龈表面切开（在波动处纵行切开，引流）；②咬合调整（调磨浮起牙，减轻咬合创伤）；③抗生素（全身用药指征为脓肿伴明显肿胀、发热、淋巴结肿大或糖尿病者，可口服阿莫西林克拉维酸0.625g tid或阿莫西林加甲硝唑（针对牙周厌氧菌，重要），连用5~7天）；④牙周治疗（急性期后（红肿消退1周后）行牙周系统治疗（龈上洁治加龈下刮治（根面平整，清除牙周袋内菌斑牙石，为治本措施）、评估牙周袋（深袋（大于5~6mm）刮治后复查，仍深者可行牙周手术（翻瓣术）评估））；⑤全身治疗（糖尿病者控制血糖（牙周脓肿与血糖相互影响，控制血糖重要，且牙周治疗可改善血糖，呈双向关系）、戒烟（对牙周治疗关键））；⑥随访（急性期3~5天复查（观察肿胀消退及溢脓停止）、牙周（刮治后4~6周复查牙周袋深度）、反复发生牙周脓肿者需评估牙周系统治疗依从性、糖尿病控制情况及深袋，必要时手术）；本病由口腔科及牙周科诊治，以引流、抗生素及牙周系统治疗为主，需控制血糖、戒烟，防复发，重要。","处理方案":"【药物治疗】\n1. 阿莫西林胶囊 0.5g po tid×5天（青霉素过敏者禁用，可改克林霉素胶囊0.3g qid×5天）；\n2. 甲硝唑片 0.2g po tid×7天（厌氧菌覆盖，与阿莫西林联合抗菌）；\n3. 0.05%氯己定含漱液 10ml 含漱1分钟 tid（餐后含漱，含漱后半小时内勿饮水进食）；\n4. 疼痛明显者：布洛芬缓释胶囊 0.3g po bid×3天（餐后服用）。\n（以上剂量为门诊成人常规用量，已行脓肿切开引流者仍应足疗程抗感染。）\n\n【一般治疗及生活指导】\n1. 患侧暂勿咀嚼，进食温凉软食，避免辛辣、过烫及粗糙食物刺激局部；\n2. 保持口腔清洁：餐后软毛牙刷竖刷清洁，暂避免用力刷患牙及使用牙线/冲牙器刺激脓肿区，待脓肿消退后再恢复牙间隙清洁；\n3. 适当休息，避免熬夜及过度劳累，戒烟戒酒；\n4. 术后24小时内局部冷敷（每2小时敷15分钟），减少肿胀；勿自行挤压脓肿，以防感染扩散。\n\n【随诊要求】\n1. 用药后3~5天复诊，评估脓肿消退、引流情况及全身症状改善程度，必要时调整抗菌药物；\n2. 脓腔消退、急性炎症控制后1~2周行牙周系统治疗（龈上洁治、龈下刮治及根面平整），去除病因；\n3. 治疗期间若出现发热、面部肿胀加重、张口受限或疼痛加剧，需立即复诊；并存深牙周袋及松动明显者，建议行影像学检查评估骨破坏程度，必要时转牙周专科门诊进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":625,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"21ff71fa8e6ab6f55bcfe772e48b15a8a66ef9adbbccdff482f159a95461ad16","pinyin":"yazhounongzhong","initials":"yznz","setting":"out","caseName":"门诊病历490","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历490",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c6664134599882098ad8","key":"v1-c9ccc21dfe2a3058|templates-c6664134599882098ad8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"智齿冠周炎","category":"门诊病历模板","raw":{"name":"智齿冠周炎","category":"门诊病历模板","case":{"case_name":"门诊病历491","templates":{"主诉":"牙龈肿痛伴张口受限3天","现病史":"患者（青年18~30岁，智齿萌出或阻生）于3天前出现右下智齿周围牙龈肿痛（龈瓣红肿覆盖牙冠，形成盲袋并食物嵌塞，为冠周炎表现）、张口受限（咀嚼肌炎症，翼内肌受累）、吞咽痛（波及咽部）、颊部肿胀、发热，有无反复发作史（慢性盲袋，可反复急性发作）、同侧淋巴结肿大、口臭（盲袋脓性分泌物）、X线智齿阻生情况（是否建议过拔除）、诱因（熬夜劳累、抵抗力下降）：无反复发作史。今日来我院口腔科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.8℃，P88次/分，R20次/分，BP118/76mmHg。张口度（受限程度）、下颌第三磨牙区龈瓣红肿覆盖牙冠（部分萌出、盲袋深，可探及食物残渣或脓性分泌物，挤压溢脓）、颊侧前庭沟肿胀、同侧颌下淋巴结肿大压痛、面颊肿胀（扩散评估）。","辅助检查":"【必做】临床检查为主；【影像】X线曲面断层（判断智齿阻生方向为近中、水平或垂直，以及其与下牙槽神经管的关系，评估拔除风险）；【其他】血常规（发热时了解白细胞）、脓肿穿刺、CT（疑深部间隙感染扩散时，必要时）。","初步诊断":"1. 智齿冠周炎（右下第三磨牙，急性，伴间隙感染待排）\n（注：急性期局部处理为主：冠周盲袋冲洗（3%过氧化氢与生理盐水交替，清除残渣脓液，每日1~2次）加盲袋碘甘油；全身抗生素（发热肿胀时用阿莫西林克拉维酸加甲硝唑，覆盖厌氧菌，连用5~7天）；对症（布洛芬、氯己定含漱、张口训练）；脓肿时切开引流；间隙感染（面颊肿胀扩散、张口受限明显）时住院静脉抗生素加切开引流，按急诊处理；炎症消退后1~2周拔除阻生智齿（根治，防复发，术前X线评估，告知下唇麻木风险）。）","处理方案":"【药物治疗】\n1. 阿莫西林克拉维酸钾片0.625g po bid×5~7天，联合甲硝唑片0.4g po tid×5~7天（覆盖口腔厌氧菌）；青霉素过敏者改用头孢呋辛酯片0.25g po bid×5天联合甲硝唑片0.4g po tid×5天。\n2. 疼痛明显时口服布洛芬缓释胶囊0.3g po bid，餐后服用，按需连用≤3天。\n3. 局部治疗：3%过氧化氢溶液与生理盐水交替冲洗智齿冠周盲袋，每日1~2次，冲洗后盲袋内涂布碘甘油，以抗菌消炎、通畅引流。\n【一般治疗及生活指导】\n1. 饮食：进温凉流质或半流质饮食，忌辛辣、过烫、过硬及黏性食物，急性期避免患侧咀嚼。\n2. 口腔卫生：三餐后及睡前用0.12%~0.2%氯己定含漱液含漱1分钟，每日3~4次；使用软毛牙刷轻柔清洁，避免刺激肿胀牙龈。\n3. 休息与活动：急性期注意休息，保证充足睡眠，避免熬夜、劳累及剧烈运动，以免抵抗力下降加重感染。\n4. 禁忌：急性期戒烟、戒酒；切勿用手或硬物自行挑刺、挤压肿胀区域，防止感染向咽旁及颌下间隙扩散。\n【随诊要求】\n1. 用药3天后复诊，评估肿痛、张口受限等症状缓解情况，必要时调整抗菌药物方案。\n2. 若出现高热（≥38.5℃）、张口受限进行性加重、颌下或面颊部肿胀、吞咽困难等间隙感染征兆，应立即返院就诊。\n3. 急性炎症消退后1~2周复诊，评估患牙：智齿位置正常、咬合关系良好且反复发作次数少者，可考虑龈瓣切除术保留；位置异常或反复发作者，建议择期拔除智齿以根治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":626,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"28a43b972abd9a4d4b5859d58e65626261986f79d515e9ff36111732ca6502f7","pinyin":"zhichiguanzhouyan","initials":"zcgzy","setting":"out","caseName":"门诊病历491","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历491",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6ec5270b2de0c62230cd","key":"v1-c9ccc21dfe2a3058|templates-6ec5270b2de0c62230cd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"口腔黏膜溃疡","category":"门诊病历模板","raw":{"name":"口腔黏膜溃疡","category":"门诊病历模板","case":{"case_name":"门诊病历492","templates":{"主诉":"口腔溃疡伴乏力1周","现病史":"患者1周前无明显诱因出现口腔黏膜溃疡相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以口腔溃疡伴乏力1周为主诉，反复或持续不愈的口腔溃疡需排除全身性疾病所致，完善血常规检查排除感染、贫血及血液系统疾病所致黏膜损害；查便常规加潜血试验以了解消化道有无出血，排除炎症性肠病及消化道肿瘤所致营养吸收障碍性口腔溃疡；完善肝功能检查以评估肝脏合成功能及营养代谢状态，排除肝病所致维生素缺乏及黏膜修复障碍；查淀粉酶以排除胰腺病变所致消化吸收不良；行脂肪酶检查进一步排除胰腺疾病，鉴别消化系统病因所致溃疡；完善凝血功能检查以评估凝血状态，为可能的口腔活检等有创操作提供安全保障；行腹部超声检查了解腹腔脏器情况，排除肝胆胰脾病变；查胃镜以明确有无食管、胃部病变所致反流性及营养性口腔黏膜损害，肠镜必要时完善以排除炎症性肠病；行腹部CT检查进一步明确腹腔脏器有无占位性病变；完善幽门螺杆菌检测（C13或C14呼气试验）以明确有无幽门螺杆菌感染，指导根除治疗及黏膜病变的病因治疗。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 口腔黏膜溃疡\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 局部抗菌含漱：复方氯己定含漱液10ml含漱，每次含漱1～2分钟，每日3～4次（餐后及睡前），含漱后30分钟内不饮水、不进食，疗程7天。\n2. 局部抗炎促愈：曲安奈德口腔软膏适量薄涂于溃疡面，每日2次（早晚各1次），连续使用不超过7天。\n3. 局部止痛：2%利多卡因凝胶适量涂布溃疡面，每日3次，于餐前15分钟使用以减轻进食疼痛，必要时睡前加用1次。\n4. 营养支持：复合维生素B片（含维生素B2）1～2片口服，每日3次，疗程7～14天；维生素C 0.1g口服，每日3次，疗程7天。\n\n【一般治疗及生活指导】\n1. 休息：保证充足睡眠，避免熬夜、精神紧张及过度劳累，注意劳逸结合、减轻压力，以免诱发溃疡复发。\n2. 饮食：进食温凉、清淡、细软易消化食物，多饮水，忌辛辣、过烫、过酸、粗糙坚硬及油炸食物，戒烟酒，少饮浓茶、咖啡等刺激性饮品。\n3. 口腔护理：使用软毛牙刷轻柔刷牙，避免刷牙及进食时损伤口腔黏膜；保持口腔清洁，餐后温水漱口；避免反复舔舐、撕咬溃疡处。\n4. 活动：可正常活动，避免剧烈运动致疲劳，规律作息有助于黏膜修复。\n\n【随诊要求】\n1. 一般口腔溃疡7～14天可自行愈合；若单个溃疡超过2周未愈合、面积增大、疼痛加剧，或伴发热、颌下淋巴结肿大等，应及时复诊，必要时行病理活检排除其他病变。\n2. 反复频繁发作（每年≥3次）者，建议复诊于口腔科或口腔黏膜科，进一步评估贫血、微量元素缺乏、免疫功能异常等全身因素。\n3. 用药期间若出现局部过敏、刺激加重或明显不良反应，随时复诊调整用药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":627,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"70c02d8f3e755e01d4e894a55dfa8e937b1f991bbfe421611bb061ccf2cc8496","pinyin":"kouqiangnianmokuiyang","initials":"kqnmky","setting":"out","caseName":"门诊病历492","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历492",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c4e9dac99485d36c97c0","key":"v1-c9ccc21dfe2a3058|templates-c4e9dac99485d36c97c0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"口腔念珠菌病","category":"门诊病历模板","raw":{"name":"口腔念珠菌病","category":"门诊病历模板","case":{"case_name":"门诊病历493","templates":{"主诉":"口腔黏膜白斑伴灼痛1周","现病史":"患者于3天前出现口腔黏膜白色凝乳样假膜（假膜型，多见于颊、舌、腭，可拭去，拭去后遗留潮红糜烂面，婴幼儿及免疫低下者多见）或红斑萎缩（红斑型，位于义齿承托区，即义齿性口炎，戴活动义齿者多见）、口角皲裂（念珠菌性口角炎），伴灼痛（进食刺激时明显）、味觉异常、口干口臭，有无诱因（婴幼儿鹅口疮、长期广谱抗生素、吸入或全身激素、糖尿病、HIV或免疫抑制、活动义齿未清洗、干燥综合征、贫血）：无特殊诱因。今日来我院口腔科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.2℃，P80次/分，R18次/分，BP118/76mmHg。口腔黏膜颊舌腭见白色凝乳样假膜（可拭去，拭去后潮红糜烂）或义齿承托区充血红斑（义齿性口炎）、口角皲裂糜烂，假膜刮取物送检，舌萎缩或毛舌，口腔干燥，义齿清洁状况评估。","辅助检查":"【必做】假膜刮取物KOH涂片（查假菌丝及孢子，可确诊，快速）；【其他】真菌培养（明确菌种，以白念珠菌为主，光滑念珠菌及克柔念珠菌可耐药）、血糖（糖尿病筛查，反复鹅口疮者必查）、HIV检测（顽固病例或有危险因素者）、血常规（查贫血及中性粒细胞减少）、义齿面涂片。","初步诊断":"1. 口腔念珠菌病（假膜型，诱因待查）\n（注：局部抗真菌首选：制霉菌素混悬液含漱吞咽（每日4次，连用7~14天）或克霉唑含片或咪康唑口颊片；广泛顽固或免疫低下者口服氟康唑（首日200mg，继以100~200mg每日1次，连用7~14天，监测肝功能）；义齿性口炎须义齿彻底清洗（制霉菌素浸泡）并夜间不戴（关键）；去除诱因（停用抗生素、吸入激素后漱口、控制糖尿病、补充维生素B12及叶酸铁剂）；口角炎予制霉菌素加抗炎软膏；免疫低下者系统治疗，合并HIV者抗反转录病毒治疗（感染科协作）；超过2周不愈者复查培养，评估耐药及免疫状态。）","处理方案":"【药物治疗】\n1. 抗真菌药物（首选局部用药）：制霉菌素混悬液（10万U/ml）含漱或涂布患处，每次1～2ml，每日4次（qid），含漱后尽量延长药液在口腔内停留时间（含漱5分钟），疗程7～14天；亦可用制霉菌素片50万U（1片）研碎后蘸少许水涂布患处，每日3次。\n2. 碱性含漱液：2%～4%碳酸氢钠溶液（小苏打水）含漱，每次约20ml，每日3～4次，使口腔呈碱性环境以抑制念珠菌生长，疗程同抗真菌药（7～14天）。\n3. 对局部用药疗效不佳或反复发作、累及咽部及消化道者：氟康唑胶囊100mg，每日1次口服（首日可顿服200mg），连用7～14天；用药期间注意肝肾功能监测。\n4. 对症及诱因处理：口腔黏膜红肿疼痛明显者可加用康复新液含漱（每次10ml，每日3次）促进黏膜修复；合并口角炎者局部涂擦克霉唑乳膏，每日2次，连用1～2周。\n\n【一般治疗及生活指导】\n1. 保持口腔清洁卫生：餐后及时漱口、刷牙，使用软毛牙刷，勤换牙刷，避免交叉感染；假牙（义齿）佩戴者每餐后取下刷洗，睡前取下浸泡于2%～4%碳酸氢钠溶液中，治疗期间每日浸泡。\n2. 饮食宜清淡、温软，多饮水，多吃富含B族维生素及优质蛋白的新鲜蔬果；忌辛辣、过烫、过甜及发酵类食物（如面包、蛋糕、馒头、含糖饮料），戒烟酒。\n3. 消除诱因：积极控制血糖（糖尿病患者严格监测并控制血糖达标）；正在使用广谱抗生素、糖皮质激素或免疫抑制剂者，医师指导下尽可能停用或调整；避免长期滥用抗生素及含激素的口腔喷剂。\n4. 加强营养与休息，保证充足睡眠，适度锻炼，提高机体抵抗力；婴幼儿患者注意奶瓶、奶嘴煮沸消毒，哺乳期母亲注意乳头清洁。\n\n【随诊要求】\n1. 用药后1周门诊复诊，评估口腔白色斑片消退情况及症状改善程度，决定是否继续或调整治疗。\n2. 疗程结束后若症状未完全缓解或短期内反复发作，应复诊行真菌涂片/培养及药敏检查，并完善血糖、血常规等检查，排查糖尿病、免疫缺陷等基础疾病。\n3. 经规范抗真菌治疗2周仍无好转者，请口腔科/皮肤科专科会诊，必要时行组织病理学检查排除其他口腔白斑性病变。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":628,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"25266c54aa76e154de32e6f4912ebc785499f1af73357152b52ab53d5574f4a4","pinyin":"kouqiangnianzhujunbing","initials":"kqnzjb","setting":"out","caseName":"门诊病历493","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历493",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-49c8d04024b6e220d8aa","key":"v1-c9ccc21dfe2a3058|templates-49c8d04024b6e220d8aa","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"口腔白斑","category":"门诊病历模板","raw":{"name":"口腔白斑","category":"门诊病历模板","case":{"case_name":"门诊病历494","templates":{"主诉":"口腔黏膜白斑伴乏力1周","现病史":"患者1周前无明显诱因出现口腔白斑相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以口腔黏膜白斑伴乏力1周为主诉，口腔白斑属癌前病变，需评估病变范围并排除恶性变，完善口腔检查以了解白斑的部位、大小、形态、表面质地及有无糜烂、硬结，评估恶变风险并确定活检部位；行牙周探诊以了解牙周袋深度及牙周炎症情况，排除牙周病变所致长期慢性刺激；查牙髓活力测试以了解牙髓状态，排除牙源性感染及残根残冠对黏膜的持续刺激；行根尖片检查以了解牙根尖周情况，排除根尖周病变及埋伏牙所致黏膜刺激；完善全景片以全面了解全口牙齿、牙槽骨及颌骨情况，明确有无残根、阻生牙等刺激因素；行CBCT检查以明确病变深度、范围及颌骨有无破坏，评估有无恶变及浸润，为活检及手术方案提供依据；完善血常规检查排除感染、贫血所致黏膜改变；查凝血功能以评估凝血状态，为有创操作（活检、手术切除）提供安全保障。\n\n（检查清单）\n【必做检查】\n口腔检查、牙周探诊、牙髓活力测试\n\n【影像学检查】\n根尖片、全景片、CBCT\n\n【其他检查】\n血常规、凝血功能（有创操作前）","初步诊断":"1. 口腔白斑\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 0.05%维A酸乳膏（维A酸软膏）局部涂布病损处，每日1～2次，睡前使用，连用4～8周，注意局部刺激、脱屑及色素沉着，不宜大面积长期使用，育龄期女性慎用。\n2. 维生素E胶丸 100mg 口服 每日3次，连用3个月。\n3. β-胡萝卜素软胶囊 30mg 口服 每日1次（或维生素A胶丸 2.5万U 口服 每日1次），连用3个月；长期大剂量使用需监测肝功能、血脂。\n4. 若病损表面疑合并念珠菌感染（涂片或真菌培养证实），加用制霉菌素片 50万U 含化，每日3次，连用7～14天。\n\n【一般治疗及生活指导】\n1. 立即戒烟、戒酒，戒除咀嚼槟榔习惯，此为白斑消退与防止恶变的基础措施，须长期坚持。\n2. 避免进食过烫、辛辣及粗糙刺激性食物，戒烟期间避免以含酒精漱口液刺激黏膜，多饮水，均衡饮食，适当补充新鲜蔬果。\n3. 及时去除口腔内不良刺激因素：调磨尖锐牙尖、拔除残根残冠及不良修复体，避免病损区反复摩擦刺激。\n4. 保持良好口腔卫生，正确刷牙、餐后漱口；唇部白斑注意防晒及润唇保护。\n\n【随诊要求】\n1. 每3～6个月复诊1次，记录并对比病损大小、范围及形态变化。\n2. 如病损出现糜烂、溃疡、硬结、疣状增生、疼痛或出血等变化，应立即就诊，必要时行活检病理检查以排除恶变。\n3. 非均质型、疣状型白斑及病理提示上皮不典型增生者，缩短复诊间隔至1～3个月，并根据患者具体情况制定个体化方案行手术切除、冷冻或激光治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":629,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ee533288ec4da22fe6354d0b685d1452c7c984fb7871894cefba26f09ccac379","pinyin":"kouqiangbaiban","initials":"kqbb","setting":"out","caseName":"门诊病历494","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历494",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-53669948baf2631d94b3","key":"v1-c9ccc21dfe2a3058|templates-53669948baf2631d94b3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"舌炎","category":"门诊病历模板","raw":{"name":"舌炎","category":"门诊病历模板","case":{"case_name":"门诊病历495","templates":{"主诉":"舌痛伴味觉减退1月","现病史":"患者于2周前出现舌部灼痛（进食辛辣热酸食物时加重）、舌面红肿光滑（舌乳头萎缩，呈镜面舌，为维生素B缺乏及贫血的特征性表现）、舌缘齿痕、裂纹、地图样红斑（游走性舌炎，良性）、味觉减退，有无营养缺乏（维生素B12缺乏见于恶性贫血，表现为光滑舌加贫血加周围神经病；叶酸、铁缺乏见于缺铁性舌炎伴口角炎；烟酸缺乏见于糙皮病，表现为舌炎加皮炎加腹泻）、干燥综合征（口干）、糖尿病（念珠菌性舌炎）、药物（抗生素或化疗）、局部刺激（锐利牙尖或义齿）、胃肠道吸收不良（乳糜泻）：无特殊。今日来我院口腔科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP116/74mmHg。舌体及舌背（舌乳头充血或萎缩光滑呈镜面舌、裂纹、地图样红斑、白色假膜提示念珠菌）、舌缘齿痕、舌腹（溃疡时警惕舌癌，舌缘单发溃疡超过3周不愈或伴硬结者应活检）、舌质颜色（苍白提示贫血，绛红提示烟酸缺乏）、口角及黏膜（口角炎或溃疡）、全身（贫血貌、皮肤）。","辅助检查":"【必做】血常规（贫血，区分大细胞或小细胞）、维生素B12、叶酸、铁蛋白、维生素B2及烟酸（疑缺乏时）；【其他】血糖（糖尿病）、抗SSA/SSB抗体（口干时查干燥综合征）、真菌镜检（念珠菌性）；【活检】舌缘溃疡超过3周不愈或伴硬结者，排除舌癌（老年人尤须重视）。","初步诊断":"1. 舌炎（营养缺乏性，病因待查）\n（注：病因治疗为核心，按化验结果补充（维生素B12缺乏者肌注甲钴胺，恶性贫血时口服无效；叶酸、铁剂、B族复合维生素）；念珠菌性者抗真菌（制霉菌素或氟康唑）；局部对症（利多卡因含漱止痛、温和漱口、软食、避免辛辣酸酒）；治疗基础病（糖尿病、干燥综合征可用人工唾液或毛果芸香碱）；去除局部刺激；补充后2~4周舌乳头恢复，注意随访；警惕舌癌，舌缘溃疡不愈伴硬结者应活检。）","处理方案":"【药物治疗】\n1. 补充B族维生素（营养缺乏性舌炎首选）：复合维生素B片2片 tid口服；维生素B2片10mg tid口服，疗程2～4周；伴舌乳头萎缩者加用甲钴胺片0.5mg tid、叶酸片5mg tid，连用4周。\n2. 局部抗炎含漱：复方氯己定含漱液10ml含漱tid，每次含漱1～2分钟后吐出，餐后使用，疗程5～7天。\n3. 念珠菌性舌炎（舌背白膜、拭去后见充血糜烂）：制霉菌素片50万U研碎涂布患处或含化tid，或2%碳酸氢钠溶液20ml含漱tid，疗程7～14天。\n4. 止痛（疼痛明显影响进食者）：复方苯佐卡因凝胶涂布舌面bid～tid，餐前15分钟使用。\n【一般治疗及生活指导】\n1. 饮食：进食温凉、清淡软食，忌过热、辛辣、过酸及粗糙坚硬食物，戒烟酒，多饮水。\n2. 口腔卫生：早晚及餐后用软毛牙刷清洁口腔，温淡盐水漱口，避免刺激性漱口液。\n3. 作息：规律作息，避免熬夜、劳累及精神紧张，保持情绪稳定。\n4. 禁忌：避免咬舌、刮舌等不良习惯，避免自行长期滥用抗生素及含漱液；去除残根、不良修复体等局部刺激因素。\n【随诊要求】\n1. 用药1周后复诊评估疼痛、充血、肿胀及糜烂改善情况；症状加重或2周未愈者及时复诊。\n2. 反复发作或萎缩性舌炎者建议查血常规、血清铁、叶酸、维生素B12水平及血糖，必要时转口腔黏膜科、血液科或消化内科进一步诊治。\n3. 舌部溃疡、结节或肿物经2周正规治疗不愈或进行性增大者，复诊行病理活检以排除恶变。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":630,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8d289d234e17bba036098b9eeee514dfdc4cd0f14d9b03bd120cd05659191187","pinyin":"sheyan","initials":"sy","setting":"out","caseName":"门诊病历495","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历495",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-cb010f4a34634ab56f07","key":"v1-c9ccc21dfe2a3058|templates-cb010f4a34634ab56f07","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"口角炎","category":"门诊病历模板","raw":{"name":"口角炎","category":"门诊病历模板","case":{"case_name":"门诊病历496","templates":{"主诉":"口角皲裂伴疼痛1周","现病史":"患者1周前无明显诱因出现口角炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以口角皲裂伴疼痛1周为主诉，口角皲裂糜烂伴疼痛多与感染、营养缺乏及免疫功能异常相关，完善血常规检查排除感染、贫血及血液系统疾病所致黏膜修复障碍；查尿常规以了解泌尿系统情况，排除糖尿病、肾脏疾病所致营养代谢异常及脱水；查便常规以了解消化吸收功能，排除慢性腹泻、肠道病变所致营养素吸收不良；完善肝肾功能检查以评估肝脏合成功能及肾脏排泄功能，排除肝肾功能不全所致维生素及微量元素代谢障碍，同时为药物治疗的安全性提供依据；查血糖以排除糖尿病所致口角炎反复不愈及易感染倾向；查血脂以了解脂质代谢水平，评估营养状态及心血管危险因素；查电解质以了解有无钠钾钙等电解质紊乱及锌缺乏相关表现，排除电解质失衡所致黏膜病变；行心电图检查以了解心脏基础状态，评估全身情况；行胸部X线片检查排除肺部感染、结核等全身性疾病所致口角及口周黏膜损害；行腹部超声检查了解肝胆胰脾情况，排除消化系统疾病所致营养吸收障碍及维生素缺乏；根据病情需要选择相应检查，可加查微量元素及血清铁、叶酸、维生素B12以明确有无营养素缺乏所致口角炎。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 口角炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 补充B族维生素（口角炎基础治疗）：维生素B2（核黄素）片 10mg po tid，联合复合维生素B片 2片 po tid，疗程1~2周；\n2. 局部抗真菌治疗（疑念珠菌感染，见口角浸渍发白、鳞屑）：克霉唑乳膏涂患处 bid，或盐酸特比萘芬乳膏涂患处 bid，疗程1~2周；\n3. 局部抗感染（合并细菌感染，见脓性分泌物、结痂）：莫匹罗星软膏涂患处 bid，疗程5~7天；\n4. 渗出糜烂期处理：3%硼酸溶液局部湿敷 bid，每次15~20分钟，待渗出减少后改用乳膏外用。\n\n【一般治疗及生活指导】\n1. 保持口角区清洁干燥，避免舔舐口角、撕扯痂皮，以防反复感染和皮损扩大；\n2. 均衡饮食，多食动物肝脏、蛋黄、豆类、绿叶蔬菜等富含B族维生素的食物，戒烟酒，忌辛辣刺激及过烫饮食；\n3. 避免口角长时间受风吹、日晒及寒冷刺激，干燥季节局部涂抹凡士林或润唇膏保湿；\n4. 纠正咬唇、吮指等不良习惯，毛巾、餐具专人专用并定期煮沸消毒，避免交叉感染。\n\n【随诊要求】\n治疗1周后复诊评估疗效；若2周后症状无明显缓解或反复发作，需行血常规、空腹血糖等检查，排查贫血、糖尿病、免疫缺陷等系统性疾病；治疗期间如出现糜烂扩大、化脓、发热或张口受限，应及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":631,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"94dfbabb2e9dc1ef885d0844c4f3629f1af89c1f73a9b93577aaea2ae2c04e01","pinyin":"koujueyan","initials":"kjy","setting":"out","caseName":"门诊病历496","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历496",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-63c5dfa45f3c43b74626","key":"v1-c9ccc21dfe2a3058|templates-63c5dfa45f3c43b74626","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"唇炎","category":"门诊病历模板","raw":{"name":"唇炎","category":"门诊病历模板","case":{"case_name":"门诊病历497","templates":{"主诉":"反复唇炎相关不适1周，加重1天。","现病史":"患者1周前无明显诱因出现唇炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者反复唇部不适1周、近日加重，伴轻度乏力，虽无明显发热，仍需完善血常规检查排除细菌或病毒感染、排除贫血及营养不良所致口唇改变；唇部症状可由全身性因素诱发，完善尿常规、便常规检查排除泌尿系感染与消化道慢性失血、吸收不良；患者本次拟予局部及口服药物治疗，药物需经肝肾代谢，完善肝肾功能检查排除肝肾功能不全并指导用药剂量；完善血糖检查排除糖尿病所致口唇干燥、念珠菌感染，完善血脂检查了解血脂水平以评估营养代谢状态；完善电解质检查排除电解质紊乱引起的口唇麻木、灼痛等感觉异常。查心电图了解心脏基础状态、排除心律失常等可致唇色改变的疾病，查胸部X线片排除肺部感染及结核等慢性消耗性疾病；查腹部超声了解肝胆胰脾情况、排除消化道疾病及营养吸收障碍所致唇炎；必要时完善过敏原检测明确有无接触性过敏因素，完善血清铁、叶酸、维生素B12检查排除营养性贫血所致口角炎、唇炎；若唇部糜烂、皲裂持续不愈超过2周，需完善局部组织病理活检明确有无癌变及特异性炎症，必要时请皮肤科、风湿免疫科会诊完善自身免疫抗体谱检查明确有无干燥综合征、红斑狼疮等系统性疾病。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 唇炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 局部糖皮质激素抗炎：丁酸氢化可的松乳膏（尤卓尔）适量涂于唇部，bid，连用5～7天，炎症消退后减为qd再巩固3～5天，总疗程不超过2周（注意避免长期使用致唇部萎缩及继发真菌感染）。\n2. 保湿屏障修复：凡士林软膏或维生素E乳膏，每日多次（至少4次）薄涂唇部及口周，餐后及睡前必涂，长期坚持使用。\n3. 伴念珠菌感染（唇部见白色膜状物、口角浸渍糜烂）时加用抗真菌药：克霉唑乳膏适量涂唇及口角，bid，连用7～10天。\n4. 口服补充：复合维生素B片2片 tid，连服2周；同时可加用葡萄糖酸锌口服液10ml qd×2周，促进黏膜修复。\n【一般治疗及生活指导】\n1. 纠正不良习惯：戒除舔唇、咬唇、撕剥唇部皮屑等动作，唇干时以润唇膏代替舔舐湿润。\n2. 饮食宜清淡、温凉软食，多饮水，避免辛辣、过烫、过酸及坚果、芒果、海鲜等易致敏食物，戒烟酒。\n3. 避免日光暴晒、寒冷干燥及风沙刺激，外出戴口罩或涂抹防晒润唇膏（SPF≥30）。\n4. 停用可疑致敏或刺激的唇膏、口红、牙膏、漱口水等口唇接触物，选用成分简单、无香精的护唇产品。\n【随诊要求】\n用药1周后复诊评估疗效及调整用药；若用药5～7天后症状无缓解或加重，或出现糜烂、渗液、结痂、感染等征象，应及时就诊；反复发作超过2次者建议皮肤科专科随诊，必要时行斑贴试验明确接触性过敏原。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":632,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"272fe996c9e674ccc8a901221f5af2d7f720ab0364b05d8344b58d783e61ad8e","pinyin":"chunyan","initials":"cy","setting":"out","caseName":"门诊病历497","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历497",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-63ec493d009c2a88de8c","key":"v1-c9ccc21dfe2a3058|templates-63ec493d009c2a88de8c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"颌骨骨髓炎","category":"门诊病历模板","raw":{"name":"颌骨骨髓炎","category":"门诊病历模板","case":{"case_name":"门诊病历498","templates":{"主诉":"颌骨疼痛伴面部肿胀1周","现病史":"患者1周前无明显诱因出现颌骨骨髓炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者颌骨疼痛伴面部肿胀1周、逐渐加重，首先完善口腔检查了解病灶牙及局部牙龈红肿、瘘管、松动情况；完善牙周探诊明确牙周袋深度及有无牙周来源感染，完善牙髓活力测试明确患牙牙髓是否坏死，以判定感染源；查根尖片了解根尖周骨质破坏情况，查全景片了解全口牙及颌骨整体情况，因根尖片与全景片为二维重叠影像，难以判断骨质破坏范围及死骨形成，故完善CBCT检查明确骨质破坏边界、有无死骨及病理性骨折、指导手术方案。患者颌面部肿胀伴感染，完善血常规检查明确白细胞及中性粒细胞水平、评估感染严重程度；因本病常需切开引流或病灶清除等有创操作，查凝血功能排除凝血障碍、评估出血风险；完善C反应蛋白、降钙素原检查了解炎症活动度及疗效，完善血糖检查排除糖尿病这一颌骨骨髓炎重要易感及复发因素，完善肝肾功能检查为抗感染用药选择及剂量调整提供依据；颌骨骨髓炎迁延不愈需与颌骨肿瘤、骨纤维异常增殖症鉴别，必要时完善颌骨MRI或组织病理活检明确病变性质。\n\n（检查清单）\n【必做检查】\n口腔检查、牙周探诊、牙髓活力测试\n\n【影像学检查】\n根尖片、全景片、CBCT\n\n【其他检查】\n血常规、凝血功能（有创操作前）","初步诊断":"1. 颌骨骨髓炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗感染治疗（首选）：阿莫西林克拉维酸钾片0.625g（阿莫西林500mg/克拉维酸125mg）口服 tid×7-14天，覆盖口腔需氧及厌氧菌；青霉素过敏者改用克林霉素胶囊0.3g qid口服×7-14天。\n2. 联合抗厌氧菌：甲硝唑片0.4g 口服 tid×7-14天，与上述药物联用增强抗厌氧菌效果。\n3. 对症镇痛：布洛芬缓释胶囊0.3g 口服 bid，疼痛明显时服用，症状缓解即停，连续使用不超过5天。\n\n【一般治疗及生活指导】\n1. 患侧颌骨制动，避免咀嚼硬物、坚果、骨刺及过烫食物，进食温凉软食或半流食，减轻患区负荷，防止病理性骨折。\n2. 保持口腔清洁，餐后及睡前使用复方氯己定含漱液含漱，每次10ml含漱1分钟，每日3-4次，避免病灶区机械刺激。\n3. 急性期注意休息，避免熬夜、劳累及剧烈活动；戒烟戒酒，忌辛辣刺激饮食，多饮水，保证营养摄入。\n4. 如有龋齿、残根、智齿冠周炎等牙源性感染病灶，建议尽早于口腔科处理病灶牙，去除感染源。\n\n【随诊要求】\n1. 用药3天后复诊评估疗效及有无药物不良反应；若出现面部肿胀加重、张口受限、发热或剧烈疼痛，随时急诊复诊。\n2. 完成疗程后1周复诊，复查血常规及炎性指标（CRP、ESR），必要时行曲面断层片或颌骨CT评估骨质破坏范围及死骨形成情况。\n3. 慢性颌骨骨髓炎患者需每1-3个月随访，持续6-12个月，观察有无死骨排出、瘘管反复溢脓等复发征象，必要时转口腔颌面外科评估手术（死骨摘除、病灶刮治）指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":633,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"45109829c09413134ba3b014aa498c3dbb79cb95726d78919fab8a9e592b72d2","pinyin":"hegugusuiyan","initials":"hggsy","setting":"out","caseName":"门诊病历498","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历498",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9e8b264ce6f1acbc135d","key":"v1-c9ccc21dfe2a3058|templates-9e8b264ce6f1acbc135d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"颌面部间隙感染","category":"门诊病历模板","raw":{"name":"颌面部间隙感染","category":"门诊病历模板","case":{"case_name":"门诊病历499","templates":{"主诉":"面部肿胀伴张口受限3天","现病史":"患者（牙源性感染最常见，占90%以上，多由根尖周炎或冠周炎引起，其中智齿冠周炎为下颌最常见的来源；感染穿破骨壁后进入筋膜间隙。腺源性感染多见于儿童，由淋巴结炎化脓穿破所致；此外还有损伤性及血源性感染，后者少见）于1周前（牙痛或智齿冠周炎后数天）出现：原发牙痛（患牙所致）、面部肿胀（依间隙部位而异：眶下间隙感染位于上颌牙、尖牙窝、眼睑下及鼻旁；颊间隙感染位于颊部、腮腺导管口，可形成脓肿；咬肌间隙感染多由下颌磨牙冠周炎引起，最常见，位于下颌角及腮腺咬肌区，位置深在，张口受限明显，为本间隙特征；翼下颌间隙感染位于下颌翼内肌内侧，亦致张口受限；颌下间隙感染位于下颌下缘及颌下腺区，可波及舌下；舌下间隙感染位于口底，致舌抬高；咽旁间隙感染可引起吞咽困难及呼吸困难，较为危险；口底多间隙感染即口底蜂窝织炎，多为双侧，呈牛颈样广泛肿胀，可致呼吸困难甚至窒息，最危险，属急症，又称路德维希咽峡炎，须高度重视）、全身症状（发热、寒战、乏力，重者脓毒症）、肿胀（局部红肿热痛，边界不清，脓肿形成时可有波动感，深部脓肿需穿刺或影像学检查）、张口受限（咬肌及翼内肌受累，呈间歇性加重）、吞咽困难（咽旁或口底受累）、呼吸困难（口底或咽旁受累，危及气道，属急症）、糖尿病（可使感染加重，须控制）、免疫状态。今日来我院口腔颌面外科或急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.8℃，P98次/分，R20次/分，BP125/78mmHg。面部（肿胀部位为右下颌角及咬肌区，范围较广，边界不清，局部红肿热痛，表浅处可及波动感，提示表浅脓肿）、张口度（明显受限）、口内（患牙为右下颌第三磨牙，呈冠周炎表现，叩痛阳性；前庭沟红肿，可及波动；口底无抬高、舌下无肿胀，舌体活动可；咽部无明显肿胀，咽旁间隙未受累，呼吸通畅，气道需持续评估）、颈部（颌下及颏下轻度肿胀，可及肿大淋巴结）、气道（呼吸平稳，口底及咽旁受累时可致窒息，须评估，属急症）、全身（发热，心率增快，注意脓毒症及血糖）。","辅助检查":"【必做】血常规（白细胞显著升高）、CRP、血糖（糖尿病可加重感染，控制血糖很重要）、血培养（疑脓毒症时）；【影像】X线曲面断层或根尖片（显示病灶牙的根尖病变）及颌骨片、CT增强（关键，可显示深部间隙脓肿定位，表现为环状强化及脓腔，明确范围及是否累及多间隙，如口底、咽旁乃至向下扩散至纵隔，并评估气道受压及下颌骨有无骨髓炎样骨质破坏，引流前定位很重要）、超声（表浅脓肿可查波动感）；【其他】脓液培养（切开引流时取标本，同时做需氧及厌氧培养加药敏）、穿刺（波动感明显或深部脓肿可抽脓确诊）。","初步诊断":"1. 颌面部间隙感染（右下颌咬肌间隙，牙源性，病灶牙为右下第三磨牙，脓肿形成待评估，无口底多间隙及咽旁受累，气道受压及脓毒症风险待评估，糖尿病待评估）\n（注：治疗以切开引流加抗感染加病灶牙处理为主，属口腔颌面外科急症，气道管理是关键：①气道评估为首要，口底、咽旁及多间隙肿胀可致呼吸困难及窒息风险，必要时插管或气管切开，转入ICU保持气道通畅，口底蜂窝织炎（路德维希咽峡炎）可致窒息，须积极抢救；②切开引流，脓肿必须引流，据CT或超声定位，切口依间隙选择口内或口外切口，颌下及咬肌间隙多取口外隐蔽切口，充分打开脓腔并贯通多间隙，留置引流条，每日冲洗，脓液送培养；③抗感染，静脉用广谱抗生素，牙源性感染以厌氧菌（革兰阴性厌氧菌为主）加链球菌及金黄色葡萄球菌为主，可用青霉素或阿莫西林克拉维酸加甲硝唑（覆盖厌氧菌，关键），重症可用哌拉西林他唑巴坦或美罗培南覆盖耐药菌，必要时考虑MRSA；疗程为静脉用药至退热及肿胀消退后改口服，总疗程7~14天，重症更长；④病灶牙处理，针对原发牙髓炎或冠周炎可开髓引流、根管治疗，残根则拔除，以控制感染源，拔牙时机在急性期引流后、脓肿控制时，可同期或炎症消退后依全身状况评估；⑤全身支持，补液、退热、营养支持，脓毒症者行器官支持并转ICU，控制糖尿病（重要，血糖与感染相互影响）；⑥并发症防治，脓毒症或败血症（血培养指导抗感染）、纵隔感染（向下扩散，CT查胸部并引流，请胸外科）、下颌骨骨髓炎（长期骨处理）、气道梗阻（窒息，属急症）；⑦随访，观察引流及拔管（脓尽后待肉芽生长）、每日换药，观察肿胀消退及张口度恢复，完成病灶牙根管或拔除以防复发，复查CT了解深部脓肿消退情况；口腔颌面外科强调早期引流、足量抗厌氧菌、病灶牙处理、气道监护、糖尿病控制，重症多间隙感染转ICU，均很重要。","处理方案":"【药物治疗】\n1. 青霉素类（首选）：阿莫西林胶囊 0.5g tid，口服，共5～7天；青霉素皮试阴性后使用，覆盖口腔链球菌等需氧菌。\n2. 硝基咪唑类（抗厌氧菌，联合用药）：甲硝唑片 0.4g tid，口服，共5～7天，与阿莫西林联用覆盖口腔厌氧菌；青霉素过敏者由医师评估换用头孢菌素或克林霉素。\n3. 非甾体抗炎药（对症）：布洛芬缓释胶囊 0.3g bid，疼痛明显时餐后口服，热退痛止即停，连用不超过3天。\n4. 局部含漱：复方氯己定含漱液 10ml 含漱3分钟 tid，餐后含漱，保持口腔清洁抑制局部菌群。\n\n【一般治疗及生活指导】\n1. 休息：急性期注意休息、保证充足睡眠，避免熬夜及过度劳累，以利于炎症消退。\n2. 饮食：进温凉流质或半流质饮食，保证营养与饮水；忌辛辣、过热、过硬及煎炸食物，戒烟戒酒，避免刺激加重肿胀疼痛。\n3. 活动与局部护理：避免剧烈活动和大声说话；严禁挤压、揉按肿胀区，禁止热敷（以免炎症扩散、脓肿破溃），可于肿胀处早期冷敷每次15～20分钟。\n4. 口腔卫生：保持口腔清洁，餐后淡盐水或含漱液漱口，及时治疗龋齿、牙周炎等病灶牙；监测体温，如肿胀范围扩大或伴张口受限加重及时就医。\n\n【随诊要求】\n1. 用药2～3天后复诊评估疗效，症状无缓解或肿胀加重者需复诊调整方案。\n2. 治疗期间如出现高热不退、肿胀迅速扩大、张口困难加重、吞咽或呼吸困难、声音嘶哑等，提示感染扩散或脓肿形成，须立即急诊就诊，必要时行切开引流或住院治疗。\n3. 牙源性间隙感染者在急性炎症控制后，应至口腔科进一步处理病灶牙（根管治疗或拔除），以防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":634,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4dc2058eeccd2cd004945565f4b08dca9ace0baf7491b30eae041b289685f9e3","pinyin":"hemianbujianxiganran","initials":"hmbjxgr","setting":"out","caseName":"门诊病历499","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历499",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a2cdc584e65b734a64f8","key":"v1-c9ccc21dfe2a3058|templates-a2cdc584e65b734a64f8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"颌面部淋巴结炎","category":"门诊病历模板","raw":{"name":"颌面部淋巴结炎","category":"门诊病历模板","case":{"case_name":"门诊病历500","templates":{"主诉":"颌下淋巴结肿痛1周","现病史":"患者1周前无明显诱因出现颌面部淋巴结炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者颌下淋巴结肿痛1周，需先寻找原发感染灶，完善口腔检查了解有无龋齿、牙周炎、根尖周炎及咽部、扁桃体炎症；完善牙周探诊明确牙周袋及牙石情况，完善牙髓活力测试明确有无牙髓坏死所致根尖周感染这一常见诱因；查根尖片了解根尖周骨质及牙体情况，查全景片了解全口牙及颌骨有无隐匿病灶；因颌面部解剖结构重叠、二维影像难以显示深部间隙，故完善CBCT检查明确肿大淋巴结与周围组织关系及有无脓肿形成。患者淋巴结肿痛伴轻度乏力，完善血常规检查明确白细胞及淋巴细胞分类、评估感染性质；因可能需要穿刺或切开引流等有创操作，查凝血功能排除凝血障碍、评估出血风险；完善C反应蛋白、降钙素原检查了解炎症程度；淋巴结肿大超过2周不消退需与淋巴结核、淋巴瘤鉴别，必要时完善颈部超声或颈部增强CT检查明确淋巴结形态、血流及有无坏死，完善结核菌素试验、T-SPOT检查排除结核，必要时行淋巴结穿刺细胞学或活检明确病理性质。\n\n（检查清单）\n【必做检查】\n口腔检查、牙周探诊、牙髓活力测试\n\n【影像学检查】\n根尖片、全景片、CBCT\n\n【其他检查】\n血常规、凝血功能（有创操作前）","初步诊断":"1. 颌面部淋巴结炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 首选β-内酰胺类抗生素：阿莫西林胶囊 0.5g po tid×5～7天；青霉素过敏者改用阿奇霉素片 0.5g po qd×3～5天。\n2. 疑口腔牙源性感染、伴厌氧菌感染时加用甲硝唑片 0.4g po tid×5～7天。\n3. 发热或疼痛明显者予对症处理：布洛芬缓释胶囊 0.3g po bid（餐后服用，按需，疗程≤3天）。\n\n【一般治疗及生活指导】\n1. 充分休息，避免熬夜及劳累，多饮水，保持大便通畅，增强机体免疫力，促进炎症消退。\n2. 清淡易消化饮食，忌辛辣、油腻、过烫及刺激性食物，戒烟戒酒，避免刺激口腔及颌面部病灶。\n3. 保持口腔及面部清洁，每日温水漱口，积极治疗龋齿、牙周炎、扁桃体炎等原发感染灶。\n4. 禁忌：严禁挤压、揉搓肿大淋巴结及周围组织，以防炎症扩散甚至引发败血症；急性期48小时内可局部冷敷减轻肿痛，勿过早热敷。\n\n【随诊要求】\n1. 用药3天后复诊：评估体温、肿块大小及疼痛变化；若症状无缓解或加重（持续高热、肿块迅速增大、疼痛加剧、皮肤发红伴波动感），应立即复诊，必要时转口腔颌面外科行切开引流术。\n2. 疗程结束后（5～7天）复诊：复查肿块消退情况，消退缓慢者可行颌面部B超及血常规检查，必要时适当延长抗生素疗程。\n3. 若淋巴结反复肿大、消退不完全或呈无痛性、质地坚硬肿大，需进一步检查（颌面部超声、血常规、结核菌素试验等）以排除结核性淋巴结炎及淋巴瘤等，必要时行淋巴结活检明确诊断。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":635,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"de69fee09063815814ce3c378c59b9105c5b005e1704f08dce2c096749b78f07","pinyin":"hemianbulinbajieyan","initials":"hmblbjy","setting":"out","caseName":"门诊病历500","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历500",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2e0a4dcc714dac006130","key":"v1-c9ccc21dfe2a3058|templates-2e0a4dcc714dac006130","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"涎腺炎","category":"门诊病历模板","raw":{"name":"涎腺炎","category":"门诊病历模板","case":{"case_name":"门诊病历501","templates":{"主诉":"腮腺肿痛伴发热1周","现病史":"患者1周前无明显诱因出现涎腺炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者腮腺肿痛伴发热1周，完善血常规检查明确白细胞及中性粒细胞水平、评估细菌感染程度；完善C反应蛋白、降钙素原检查了解炎症活动度及抗感染疗效；涎腺炎常与脱水、营养不良及全身消耗状态相关，完善尿常规、便常规检查排除泌尿系感染及消化道疾病；本次拟予抗感染及支持治疗，药物经肝肾代谢，完善肝肾功能检查排除肝肾功能不全、指导用药剂量；完善血糖检查排除糖尿病所致涎腺分泌功能减退及易感染状态，完善血脂检查了解营养代谢水平；完善电解质检查排除脱水及电解质紊乱，涎腺炎患者可因进食疼痛、饮水减少出现低钾低钠。因肿痛位于腮腺区，需与流行性腮腺炎、涎腺肿瘤及涎石病鉴别，查腮腺超声检查明确腺体大小、回声、导管扩张及有无脓肿形成；查心电图了解心脏基础状态、排除心律失常等发热诱因，查胸部X线片排除肺部感染及结核等慢性疾病，查腹部超声了解肝胆胰脾情况、排除腹部疾病所致发热；若考虑结石梗阻或深部脓肿，完善腮腺区CT或MRI检查明确导管内结石位置及病变范围。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 涎腺炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗菌药物（首选经验性覆盖金黄色葡萄球菌及口腔链球菌）：阿莫西林克拉维酸钾片0.457g（含阿莫西林0.4g/克拉维酸57mg）口服 tid×5~7天；青霉素过敏者改用克林霉素胶囊0.3g 口服 tid×5~7天。\n2. 止痛抗炎：布洛芬缓释胶囊0.3g 口服 bid×3~5天（餐后服用），缓解腺体肿痛；疼痛明显者可用对乙酰氨基酚片0.5g 口服，疼痛时服用。\n3. 促进唾液分泌（冲刷导管、排菌）：维生素C片0.2g 含服 tid×5~7天，并嘱咀嚼无糖口香糖或含服酸性糖果刺激唾液分泌。\n【一般治疗及生活指导】\n1. 急性期注意休息、避免劳累，每日饮水2000ml以上，保持口腔及腺体导管湿润，利于唾液冲刷引流。\n2. 饮食宜清淡、富含营养的流质或半流质，可适量食用酸性食物（柠檬水、山楂）刺激唾液分泌；忌辛辣、过甜、坚硬粗糙食物，戒烟戒酒。\n3. 保持口腔卫生，餐后漱口刷牙；肿胀期局部热敷每日3~4次、每次15~20分钟，疼痛缓解后沿导管走行自后向前轻按摩腺体（腮腺向耳前、颌下腺向口底方向），促进唾液排出。\n4. 禁忌：急性期勿用力挤压腺体以免炎症扩散；避免使用抑制唾液分泌的药物（阿托品类、抗组胺药、利尿剂、抗胆碱能药等）。\n【随诊要求】\n用药3天后复诊评估疼痛、肿胀缓解情况；若用药72小时症状无缓解或出现发热、腺体红肿扩大、导管口脓性分泌物，应及时复诊，完善血常规及唾液腺超声检查，警惕脓肿形成需外科引流或调整抗菌药物。症状缓解者建议1~2周门诊复查评估腺体恢复情况；反复发作或迁延不愈者需进一步行腮腺/颌下腺造影或超声排查导管结石、狭窄等病因。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":636,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4bcc1aa76d6ee139efd48cfdc465c4b769241caa40760f5c0bdccf387ed3c714","pinyin":"xianxianyan","initials":"xxy","setting":"out","caseName":"门诊病历501","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历501",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-61ff1096a388f96cfb9c","key":"v1-c9ccc21dfe2a3058|templates-61ff1096a388f96cfb9c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"涎石病","category":"门诊病历模板","raw":{"name":"涎石病","category":"门诊病历模板","case":{"case_name":"门诊病历502","templates":{"主诉":"进食时颌下肿痛1周","现病史":"患者1周前无明显诱因出现涎石病相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者进食时颌下肿痛1周，为典型的涎腺导管阻塞表现，需明确有无结石及其位置，首诊完善口腔检查了解导管开口有无红肿、溢脓及可否触及结石；完善牙周探诊明确牙周状况、排除牙周来源感染，完善牙髓活力测试排除牙源性疼痛，以免与涎石病所致进食性肿痛混淆。查下颌横断咬合片或根尖片了解导管走行区有无阳性结石，查全景片了解颌骨及涎腺区整体情况；因部分结石为阴性结石且二维影像存在重叠，故完善CBCT检查明确结石部位、大小、数目及与导管、腺体的关系，指导取石方式。患者肿痛反复发作、可继发感染并影响进食饮水，完善血常规检查明确有无继发细菌感染，完善C反应蛋白检查了解炎症程度；完善尿常规、便常规检查排除泌尿系感染及消化道疾病；完善肝肾功能检查为抗感染用药提供依据，完善血糖、血脂检查排除糖尿病及脂代谢异常所致腺体分泌改变与感染易感性；患者因进食疼痛饮水减少易致脱水，完善电解质检查排除电解质紊乱。查心电图了解心脏基础状态，查胸部X线片排除肺部感染及结核，查腹部超声排除腹部疾病所致不适；因可能需要内镜或手术取石等有创操作，查凝血功能排除凝血障碍、评估出血风险。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 涎石病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.抗感染（合并继发感染，腺体红肿热痛或伴发热时）：阿莫西林克拉维酸钾片0.457g（含阿莫西林0.4g/克拉维酸0.057g）po bid×5-7天；青霉素过敏者改用阿奇霉素片0.5g po qd×3天。\n2.促进唾液分泌、辅助排石：维生素C片0.2g po tid，餐前含化或配合酸性食物（柠檬、山楂）刺激唾液分泌，冲刷导管促结石排出。\n3.解痉镇痛：山莨菪碱片（654-2）5-10mg po tid，缓解导管痉挛及疼痛；疼痛明显者加用布洛芬缓释胶囊0.3g po bid，症状缓解后停用。\n【一般治疗及生活指导】\n1.多饮水（每日1500-2000ml），忌辛辣、过烫及粗糙食物，避免刺激腺体及加重导管损伤；戒烟酒。\n2.进食酸性食物（柠檬、山楂、酸梅）或含服维生素C片刺激唾液分泌，餐后及时漱口保持口腔清洁，防止逆行感染。\n3.局部按摩：沿导管走行方向自腺体向导管口轻轻按摩，每日3-4次，每次5-10分钟，促进唾液引流、利于排石；避免暴力挤压以防腺体损伤。\n4.如腺体出现红、肿、热、痛加重或发热，提示继发感染，应暂停刺激唾液分泌并尽快就诊。\n【随诊要求】\n1.药物治疗1周后复诊，评估疼痛、肿胀缓解情况；症状无缓解或反复发作，行涎腺彩超或涎腺X线造影，明确结石部位、大小及数目。\n2.保守治疗无效、结石直径>5mm或位于导管近腺门部者，建议转口腔颌面外科行导管切开取石或腺体切除术。\n3.结石排出或术后1-3个月复查，观察有无复发及腺体分泌功能恢复情况；出现腺体反复肿胀、疼痛或进食时明显肿痛者及时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":637,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"08f9b4b313b393d97cd4ed48c931a4e88d5e5a6607c3b57f944321449f5bc4a6","pinyin":"xianshibing","initials":"xsb","setting":"out","caseName":"门诊病历502","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历502",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a3239c24a33feb33763d","key":"v1-c9ccc21dfe2a3058|templates-a3239c24a33feb33763d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"颞下颌关节紊乱","category":"门诊病历模板","raw":{"name":"颞下颌关节紊乱","category":"门诊病历模板","case":{"case_name":"门诊病历503","templates":{"主诉":"颞下颌关节疼痛伴张口受限6月","现病史":"患者于3个月前开始出现关节区（耳前面颊）疼痛（张口咀嚼时疼痛）、张口受限（张口度减小）、关节弹响（张口闭口时咔嗒声，提示可复性盘前移位）或绞锁（张口受限，提示不可复性盘移位）、咀嚼肌酸痛（咬肌、颞肌紧张性疼痛）、头痛、耳鸣耳闷，有无诱因（精神紧张压力、夜磨牙致晨起咬肌酸痛、紧咬牙、不良咀嚼习惯、咬合紊乱、外伤或大张口、习惯性脱位史、类风湿关节炎）：无特殊诱因。今日来我院口腔科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P76次/分，R18次/分，BP118/74mmHg。张口度（小于3指，受限）、张口型（偏斜，提示髁突运动异常）、关节区及咀嚼肌压痛、关节弹响（听诊或触诊）、咀嚼痛、咬合关系（错颌或缺失牙）、牙齿磨损（夜磨牙证据）、耳前区（肿胀或脱位）。","辅助检查":"【必做】临床检查为主（诊断核心）；【影像】曲面断层（观察髁突形态，排除骨关节病）、MRI（评估关节盘位置，保守治疗无效时）、CT（骨关节病）；【其他】心理评估（压力焦虑）。","初步诊断":"1. 颞下颌关节紊乱病（关节盘可复性前移位，伴咀嚼肌紊乱）\n（注：多数保守治疗有效：患者教育加行为干预（软食、热敷、放松训练、避免大张口及单侧咀嚼，为核心）、物理治疗（理疗或肌功能训练）、咬合板（夜磨牙、紧咬牙者最常用的专业治疗）、咬合调整；药物（急性疼痛用NSAIDs如布洛芬或塞来昔布，肌肉痉挛用肌松剂乙哌立松）；关节腔注射（顽固病例用玻璃酸钠或糖皮质激素，限次）；关节镜或手术（保守治疗6个月无效者，极少采用）；治疗基础病（类风湿关节炎）；约80%患者经保守治疗缓解，注意随访调整。","处理方案":"【药物治疗】\n1. 非甾体抗炎药（NSAIDs，疼痛期首选）：布洛芬缓释胶囊 0.3g po bid 餐后服用×3～5天；或双氯芬酸钠缓释胶囊 75mg po qd 餐后×3～5天。疼痛缓解后即停用，避免长期使用。\n2. 中枢性肌肉松弛剂：盐酸乙哌立松片 50mg po tid 餐后×7天，缓解咀嚼肌痉挛与肌源性疼痛。\n3. 关节软骨保护剂：硫酸氨基葡萄糖胶囊 500mg（以硫酸氨基葡萄糖计）po tid 餐后×6～8周，用于关节盘及软骨退变、弹响伴磨损者。\n4. 外用制剂（局部症状为主时）：双氯芬酸二乙胺乳胶剂 涂于双侧颞下颌关节区，bid×7天，轻柔按摩至吸收。\n\n【一般治疗及生活指导】\n1. 饮食与咀嚼：进软食，避免啃咬硬物（坚果、硬糖、骨头、脆骨）、避免嚼口香糖及长时间偏侧咀嚼；进食细嚼慢咽，减小咀嚼幅度。\n2. 张口习惯：避免大张口（打哈欠时以手托住下颌、避免长时间张口进行牙科治疗），避免大笑、K歌等过度张口动作。\n3. 行为调整：避免紧咬牙关、夜磨牙（可至口腔科定制软性咬合板夜间佩戴）、避免长时间低头伏案及下颌前伸等不良姿势。\n4. 局部护理与心理调节：关节区湿热敷 15～20分钟 bid，配合轻揉按摩；保证充足睡眠，舒缓精神紧张与压力，避免熬夜疲劳。\n\n【随诊要求】\n1. 用药3～5天后若疼痛无缓解或加重，或出现张口受限进行性加重、关节弹响伴明显疼痛、绞锁/闭锁、脱位等，应及时复诊。\n2. 建议2周后复诊评估症状改善情况；症状反复或影像学可疑者，转口腔科颞下颌关节专科进一步诊治，必要时行CT/MRI检查及关节腔灌洗、关节镜治疗。\n3. 夜磨牙、紧咬牙明显者，建议口腔科定制咬合板；张口受限持续超过1周或完全不能张口者，立即复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":638,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"605ffbf5631011182ffcfd62571261e55c7cf6a93285792f1891a145a4886887","pinyin":"niexiaheguanjiewenluan","initials":"nxhgjwl","setting":"out","caseName":"门诊病历503","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历503",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e515ebc98da82629e758","key":"v1-c9ccc21dfe2a3058|templates-e515ebc98da82629e758","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"颞下颌关节脱位","category":"门诊病历模板","raw":{"name":"颞下颌关节脱位","category":"门诊病历模板","case":{"case_name":"门诊病历504","templates":{"主诉":"下颌不能闭口伴流涎2小时","现病史":"患者于6小时前（打哈欠后）出现下颌不能闭口（张口状态固定，下颌前伸偏斜，双侧脱位时下颌前伸）、面部变长、流涎（因不能闭口）、语言不清、吞咽困难、耳前关节区疼痛及凹陷（髁突脱出，关节窝空虚），有无习惯性脱位史（反复发作提示关节囊松弛）、外伤（颏部撞击需鉴别髁突骨折）、复位尝试：未行复位。今日来我院口腔科急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P88次/分，R19次/分，BP120/76mmHg。张口固定不能闭口（呈张口位）、下颌前伸或偏斜、咬合不能接触（开颌）、耳前触诊凹陷（髁突前脱位于关节结节前方）、压痛、颏部前突面型、流涎，外伤者可见颏部挫伤血肿（需评估髁突骨折）。","辅助检查":"【必做】临床诊断为主；【影像】曲面断层（确认脱位及复位后验证髁突位置，外伤者必查，以排除髁突骨折，张口型异常时用于脱位与骨折的鉴别）。","初步诊断":"1. 颞下颌关节脱位（双侧，急性）\n（注：以手法复位为主，行口内复位（拇指裹纱布置于磨牙颌面，向下压的同时向上后推，嘱患者放松配合），复位前热敷按摩以放松痉挛肌肉；复位困难者用局部麻醉或镇静；复位后限制下颌运动（颅颌弹力绷带固定1~2周、软食2~4周、避免大张口，打呵欠时托住下颌）；复发性脱位可保守治疗（咬合板、肌肉训练）或手术（顽固者行关节囊紧缩）；外伤伴髁突骨折者经X线确诊后行骨折固定或手术；复位后随访，观察闭口咬合恢复及复发情况。）","处理方案":"【药物治疗】\n1. 洛索洛芬钠片60mg po tid×5天：非甾体抗炎药，用于复位后颞下颌关节区及咀嚼肌疼痛、炎症反应；饭后服用，既往有消化道溃疡史者慎用。\n2. 盐酸乙哌立松片50mg po tid×7天：中枢性肌肉松弛剂，缓解复位后咀嚼肌痉挛与张力增高，减少再脱位倾向。\n3. 双氯芬酸二乙胺乳胶剂适量外用涂于双侧颞下颌关节区（耳屏前），bid×5天：局部镇痛抗炎，配合口服药增强疗效。\n4. 疼痛明显且上述药物效果不佳时，可加用塞来昔布胶囊200mg po qd×3~5天（选择性COX-2抑制剂，胃肠道刺激小）；合并焦虑紧张者根据患者具体情况制定个体化方案加用非处方镇静类药物，需评估后再用。\n\n【一般治疗及生活指导】\n1. 复位后当日以弹力绷带或颅颌绷带行颏部支持固定1~2周，限制下颌过度活动，防止再脱位；固定期间避免说话、进食时下颌大幅度运动。\n2. 饮食：术后1~2周进软食或半流质（粥、面条、蒸蛋、酸奶等），避免啃咬硬物（坚果、骨头、甘蔗）、韧性食物（牛肉干、口香糖）及过烫食物，2周内禁用患侧咀嚼。\n3. 避免大张口动作：打哈欠、大笑、打喷嚏时以手托住颏部保护；避免长时间张口（牙科治疗、唱歌、长时间大声说话），改掉单侧咀嚼、紧咬牙关、磨牙等不良习惯。\n4. 复位后1~2周内避免下颌前伸、侧方运动及过度开口训练，保持自然闭口休息位；局部可温热敷（每次15分钟，bid）促进软组织恢复。\n\n【随诊要求】\n1. 复位后1~2周复诊，评估咬合关系、张口度及下颌运动功能恢复情况，确认关节复位稳固、无再脱位。\n2. 若复位后反复出现张口后不能闭口（习惯性/复发性脱位）或伴关节区弹响、疼痛、张口受限，应及时返诊，必要时行影像学检查（锥形束CT、MRI）并转口腔颌面外科专科评估，考虑关节镜复位或手术治疗。\n3. 治疗期间如出现剧烈疼痛、面颊部肿胀、咬合错乱或再次脱位等异常，应随时急诊就诊，不可拖延。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":639,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"03c964f877eeda1c464d2f4e2d72ce65c7ab2658632660171a33e3883f2ad41b","pinyin":"niexiaheguanjietuowei","initials":"nxhgjtw","setting":"out","caseName":"门诊病历504","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历504",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-dd1db5656c6a0fe181ba","key":"v1-c9ccc21dfe2a3058|templates-dd1db5656c6a0fe181ba","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"颌面部外伤","category":"门诊病历模板","raw":{"name":"颌面部外伤","category":"门诊病历模板","case":{"case_name":"门诊病历505","templates":{"主诉":"面部肿痛伴皮肤裂伤2小时","现病史":"患者1周前无明显诱因出现颌面部外伤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者面部肿痛伴皮肤裂伤2小时，属急诊外伤，需优先排除危及生命的合并损伤。首先急诊完善口腔检查了解口腔黏膜裂伤、牙脱位、牙折断及咬合关系错乱情况，完善牙周探诊明确牙周组织损伤程度，完善牙髓活力测试明确外伤牙牙髓活力状态、为后续牙髓治疗提供依据；查根尖片了解牙根及根尖周骨质有无折断，查全景片了解上下颌骨整体情况及有无多发性骨折，查CBCT检查明确骨折线走行、移位程度、有无骨块陷入上颌窦或颞下颌关节，指导复位固定方案。患者皮肤裂伤需清创缝合，急诊完善血常规检查评估失血及感染情况，查凝血功能排除凝血障碍、评估手术出血风险；因外伤可能合并颅脑及颈椎损伤，若伴头痛、呕吐、意识改变或颈部疼痛，及时完善头颅CT及颈椎CT检查明确有无颅内出血、颅骨及颈椎骨折；完善肝肾功能、血糖检查为麻醉及抗感染用药提供依据。\n\n（检查清单）\n【必做检查】\n口腔检查、牙周探诊、牙髓活力测试\n\n【影像学检查】\n根尖片、全景片、CBCT\n\n【其他检查】\n血常规、凝血功能（有创操作前）","初步诊断":"1. 颌面部外伤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗感染：阿莫西林克拉维酸钾片0.457g（含阿莫西林0.4g）口服，每次1片，bid，连用5~7天（覆盖口腔需氧菌及厌氧菌）；青霉素过敏者改用克林霉素胶囊0.3g，tid，连用5天。若伤口深、污染重或涉及口腔黏膜，可联合甲硝唑片0.4g，tid×5天。\n2. 破伤风预防：伤后24小时内，破伤风抗毒素（TAT）1500IU肌注（皮试阴性后），或破伤风人免疫球蛋白250IU肌注；5年内已完成全程免疫且伤口清洁者可不注射。\n3. 镇痛消肿：布洛芬缓释胶囊0.3g口服，bid（餐后），疼痛缓解后即停，一般不超过3天；七叶皂苷钠片30mg口服，bid，连用7天，辅助减轻软组织肿胀。\n4. 口腔清洁（伤口涉及口腔或牙齿时）：复方氯己定含漱液10ml含漱，tid，每次1分钟，连用5天；餐后加漱1次。\n【一般治疗及生活指导】\n1. 休息与体位：伤后3天内减少说话、咀嚼等面部活动，避免剧烈运动及长时间低头；夜间睡眠适当垫高头部以减轻肿胀和出血。\n2. 饮食：伤后1周内进温凉流质或半流质饮食（粥、藕粉、蛋羹、烂面条），避免过烫、过硬、辛辣及黏性食物；合并牙外伤或颌骨骨折者，患侧勿咀嚼，用健侧或流质进食。\n3. 伤口护理：保持伤口敷料清洁干燥，按时复诊换药；面部缝线一般5~7天拆线，口腔内伤口7~10天拆线，拆线前伤口勿沾水、勿自行揭开敷料。\n4. 禁忌：伤后24小时内患处禁热敷、按摩及揉压（仅可间断冷敷，每次15~20分钟，每日3~4次）；禁烟酒；避免用力擤鼻、喷嚏及张口过大，防止伤口裂开及鼻出血加重。\n【随诊要求】\n1. 伤后48小时复诊换药，评估伤口愈合及有无感染；缝线伤口按时返院拆线（面部5~7天、口腔内7~10天）。\n2. 出现伤口红肿、渗液增多、流脓、发热或疼痛明显加剧等感染征象时，随时就诊。\n3. 疑有颌骨骨折、张口受限、咬合紊乱、复视或面部塌陷畸形者，及时转口腔颌面外科专科进一步检查（如X线片、CT）及处理。\n4. 伤口愈合后1个月复诊评估瘢痕情况，必要时转整形科行瘢痕防治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":640,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ee6d3c26ae7c4ee9252c972074a3d7a06920f81c841ec2f4d3514f08a2eb15c6","pinyin":"hemianbuwaishang","initials":"hmbws","setting":"out","caseName":"门诊病历505","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历505",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a45b0d237fc4721b369f","key":"v1-c9ccc21dfe2a3058|templates-a45b0d237fc4721b369f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"牙外伤","category":"门诊病历模板","raw":{"name":"牙外伤","category":"门诊病历模板","case":{"case_name":"门诊病历506","templates":{"主诉":"牙痛伴牙齿松动4小时","现病史":"患者于2小时前因跌倒伤及上前牙（最常受累部位），出现冠折（需判断是否露髓，有无冷热刺激痛或出血点）、牙脱位（松动Ⅰ~Ⅲ度，可移位为嵌入、突出或侧向）、完全脱出（牙脱出牙槽窝，离体牙处理：保存于生理盐水或牛奶中，或含于口内，忌干燥，黄金30分钟至2小时内再植，牙周膜存活是关键）、牙槽骨骨折（邻牙联动松动）、牙龈撕裂出血、冷热敏感及咬合痛，有无意识丧失或头痛呕吐（伴颅脑外伤，撞击重者需排查）、乳牙外伤（儿童需保护恒牙胚，处理原则不同）：无意识丧失。今日来我院口腔科急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P82次/分，R18次/分，BP115/72mmHg。患牙冠折（观察断面及露髓点，探痛）、松动度、移位方向（有咬合干扰）、缺失（牙槽窝空虚，可见血凝块，记录离体牙保存情况）、牙槽突压痛及活动（提示骨骨折，邻牙联动）、牙龈撕裂出血、口腔软组织伤、面部肿胀擦伤。","辅助检查":"【必做】根尖X线片（观察根折，可多角度拍摄；牙脱位时牙周膜间隙变化，嵌入时消失；牙槽骨骨折线；离体牙及邻牙情况）；【影像】全景片或CBCT（疑牙槽骨或颌骨骨折时，必要时）；【其他】牙髓活力测试（外伤后需随访监测，牙髓坏死可延迟发生，应定期复查1、3、6、12个月的牙髓活力、根吸收及钙化情况）。","初步诊断":"1. 牙外伤（上前牙冠折，伴牙脱位）\n（注：完全脱位者须争分夺秒再植（离体牙手持牙冠，勿触根面，用生理盐水或牛奶冲洗，勿刮根面，原位植入，黄金30分钟~2小时），弹性固定2~4周，再植后1~2周行根管治疗以防根吸收，并用抗生素；不全脱位者手法复位加弹性固定（2~4周），嵌入牙可观察自行再萌（年轻恒牙）或手术复位；冠折未露髓者树脂修复或断片再粘；露髓者，年轻恒牙行活髓切断以保髓（牙根未发育完成，关键），否则根管治疗后桩冠修复；根折者复位固定或观察（根尖1/3），根颈1/3预后差需拔除；牙槽骨骨折者复位加颌间固定；软组织清创缝合；外伤牙需长期随访（牙髓坏死变色者行根管治疗，根外吸收者定期X线复查1、3、6、12个月）；预防可用运动护齿器。）","处理方案":"【药物治疗】\n1. 预防感染：阿莫西林胶囊0.5g tid×5天（青霉素过敏者改用头孢呋辛酯片0.25g bid×5天）；伴牙龈撕裂、软组织损伤或牙槽骨骨折者疗程延长至7天。\n2. 镇痛：布洛芬缓释胶囊0.3g bid，疼痛时口服，疗程≤3天；或对乙酰氨基酚片0.5g prn，每日不超过4次。\n3. 口腔清洁：复方氯己定含漱液10ml含漱2分钟 tid×5天，保持口腔清洁、预防创口感染；外伤后24小时内轻柔含漱，勿用力鼓漱以防再出血。\n4. 促进牙周愈合：维生素C片0.2g tid×1周，辅助脱位牙复位后牙周组织修复。\n【一般治疗及生活指导】\n1. 饮食：伤后1-2周进温凉软食或流质，避免用患牙侧咀嚼，忌过冷、过热及坚硬、黏性食物刺激患牙。\n2. 口腔卫生：轻柔刷牙，避开患牙及牙周固定夹板，餐后以含漱液漱口；切勿用手摇动、触碰患牙或自行调整固定装置。\n3. 活动：2周内避免剧烈运动及对抗性体育活动，防止再次撞击患牙；牙折露髓或行根管治疗者，治疗期间避免患牙咬硬物。\n4. 禁忌：禁止用患牙撕咬硬物、嗑瓜子、开瓶盖；完全脱位牙切勿干燥保存，应置于牛奶、生理盐水或含于口腔前庭内尽快就诊再植。\n【随诊要求】\n1. 牙震荡、轻度移位：2周后复诊行牙髓活力测试，其后1、3、6个月复诊并拍X线片，观察牙髓活力及根尖周变化。\n2. 牙脱位（部分/完全/嵌入性脱位）复位固定后：固定4-8周，固定期间每2周复查1次；拆除固定后于3、6、12个月复诊，评估牙髓活力、牙根吸收及牙周愈合情况。\n3. 牙折露髓或牙髓坏死者：1周内行根管治疗，按根管治疗疗程（一般3-4次、2-4周）定期复诊；外伤后出现牙冠变色、自发痛、咬合痛或松动加重者随时复诊。\n4. 年轻恒牙外伤：需长期随访至牙根发育完成，每3-6个月行X线片及牙髓活力监测，警惕牙髓坏死、牙根内/外吸收及牙髓腔闭锁。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":641,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ee445325c1fc7d3227b4bcb7042b19989b103ad085b2b83f99bf54f349fcc330","pinyin":"yawaishang","initials":"yws","setting":"out","caseName":"门诊病历506","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历506",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1ace95b01b251f72588d","key":"v1-c9ccc21dfe2a3058|templates-1ace95b01b251f72588d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"牙槽脓肿","category":"门诊病历模板","raw":{"name":"牙槽脓肿","category":"门诊病历模板","case":{"case_name":"门诊病历507","templates":{"主诉":"右下后牙持续性胀痛伴面颊肿胀3天。","现病史":"患者3天前自觉右下后牙持续性胀痛，咬合时加重，自服布洛芬（0.3g）疼痛可暂时缓解；1天前疼痛加剧，牙龈及面颊部肿胀，张口受限，伴发热（未测体温）、口臭，无吞咽困难、无呼吸困难。曾于外院口腔科就诊（具体诊治不详）。今日来我院门诊就诊。发病以来精神欠佳，进食减少，睡眠欠佳，大小便正常。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 37.6℃，P 88次/分，R 19次/分，BP 122/80mmHg。神志清楚，急性病容。右侧面颊部轻度肿胀，皮温略高，无明显波动感。张口度约2.0cm（轻度受限）。口内检查：右下第一磨牙（46）龋坏，叩痛（++），松动Ⅰ度，对应颊侧前庭沟丰满、压痛明显，可及波动感，挤压有少量脓性分泌物溢出；右下颌下淋巴结肿大，约1.5cm×1.0cm，质软，轻压痛，活动可。","辅助检查":"【必做】血常规（白细胞及中性粒细胞比例升高提示感染）；【影像学】根尖X线片或口腔曲面断层片（可见根尖周骨质破坏、龋坏及根尖周阴影，明确病灶牙）；【其他】脓液细菌培养+药敏（脓肿切开引流时）。","初步诊断":"1. 牙槽脓肿（右下第一磨牙根尖周炎急性发作）\n（注：必要时请口腔科会诊，明确病灶牙及治疗方案。）","处理方案":"【药物治疗】\n1. 抗感染治疗：阿莫西林胶囊0.5g口服，每日3次（tid），疗程5天；联合甲硝唑片0.4g口服，每日3次（tid），疗程5天，覆盖需氧菌与厌氧菌。青霉素过敏者改用克林霉素胶囊0.3g口服，每日4次（qid），疗程5天。\n2. 镇痛治疗：布洛芬缓释胶囊0.3g口服，每日2次（bid），疼痛明显时服用，疗程不超过3天；或洛索洛芬钠片60mg口服，每日3次（tid），餐后服用。\n3. 局部用药：0.05%氯己定含漱液10ml含漱，每日2~3次，每次含漱1分钟；已行切开引流者，每日用生理盐水及甲硝唑注射液交替冲洗脓腔至引流通畅。\n\n【一般治疗及生活指导】\n1. 患侧避免咀嚼，进温凉软食或半流质饮食，禁烟酒，忌辛辣、过烫及过硬食物，减少局部刺激。\n2. 保持口腔卫生，使用软毛牙刷轻刷牙，避免刺激患牙区；饭后用温盐水或氯己定含漱液漱口。\n3. 急性期注意休息，避免劳累、熬夜；勿自行按压、挤压或挑破脓肿区域，防止感染沿筋膜间隙扩散。\n4. 脓肿成熟（有明显波动感）者应及时就医行切开引流，并尽快行患牙根管治疗或拔除，去除感染源，根治病因。\n\n【随诊要求】\n1. 用药3天后复诊，评估疼痛、肿胀缓解情况；若用药48小时症状无缓解或加重，或出现发热、张口受限、面部肿胀扩大、呼吸不畅等，立即复诊或急诊处理。\n2. 已行脓肿切开引流者，次日复诊换药，此后视引流情况每1~2天换药一次，直至引流通畅、脓腔闭合。\n3. 症状缓解后1~2周内至口腔科完成患牙根管治疗或拔除术，并摄根尖片或曲面断层片评估根尖周骨质破坏情况。\n4. 若为牙源性感染且反复发作，建议行血糖等全身检查，排除糖尿病等易感因素。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":642,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e61f57fa2b92fdae545ba7c7cd7067fa12811b0b447120c17c17c1523507a916","pinyin":"yacaonongzhong","initials":"ycnz","setting":"out","caseName":"门诊病历507","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历507",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-abb5cc2556a474a264ad","key":"v1-c9ccc21dfe2a3058|templates-abb5cc2556a474a264ad","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"口腔颌面部囊肿","category":"门诊病历模板","raw":{"name":"口腔颌面部囊肿","category":"门诊病历模板","case":{"case_name":"门诊病历508","templates":{"主诉":"发现左下颌骨隆起性肿物6个月，无明显疼痛。","现病史":"患者6个月前无意中发现左下颌骨区缓慢隆起性肿物，无疼痛、无红肿、无发热，肿物缓慢增大，近1个月自觉下颌轻度胀感，咬合无明显异常，无面部麻木、无张口受限。未行任何治疗。今日来我院门诊就诊。发病以来精神、食欲、睡眠可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 76次/分，R 17次/分，BP 118/76mmHg。神志清楚，查体合作。面部基本对称，左下颌骨体部可触及约3cm×2cm骨性隆起，质硬，边界清楚，无压痛，表面皮肤颜色、温度正常，无破溃。口内检查：左下颌磨牙区颊侧前庭沟隆起，表面黏膜正常，无充血，相应区域牙齿无松动、无叩痛，牙髓活力正常。双侧颌下、颈部淋巴结未触及肿大。","辅助检查":"【必做】口腔曲面断层片（全景片）或下颌骨CT：可见颌骨内边界清楚的类圆形低密度影，可呈单房或多房，周边有硬化边缘，牙根可有吸收或推移；【其他】穿刺抽吸（可抽出囊液，用于鉴别囊性病变性质）。","初步诊断":"1. 下颌骨囊肿（性质待病理）\n（注：颌骨囊肿种类较多（根尖囊肿、含牙囊肿、牙源性角化囊肿等），确诊需病理检查，建议口腔颌面外科进一步诊治。）","处理方案":"【药物治疗】\n1. 青霉素类抗生素（抗需氧菌，控制囊肿继发感染）：阿莫西林胶囊 0.5g 口服，每日3次，连用5～7天；青霉素过敏者改用头孢呋辛酯片 0.25g 口服，每日2次，连用5～7天。\n2. 硝基咪唑类抗生素（抗厌氧菌，与青霉素类联用覆盖口腔混合菌群）：甲硝唑片 0.4g 口服，每日3次，连用5～7天。\n3. 口腔局部消毒剂（维持口腔卫生、预防创口感染）：复方氯己定含漱液 10ml 含漱1分钟，每日3次，餐后使用，含漱后30分钟内不饮水、不进食。\n4. 非甾体抗炎药（术后或急性炎症期镇痛，必要时）：布洛芬缓释胶囊 0.3g 口服，每日2次，疼痛时短期使用，不超过3天。\n\n【一般治疗及生活指导】\n1. 口腔颌面部囊肿以手术彻底摘除（完整刮除囊壁）为根治手段，确诊后应择期行囊肿摘除术并送病理检查；伴有急性感染者先控制感染后再行手术。\n2. 饮食：进食温凉软食或半流质，避免过烫、过硬及辛辣刺激食物，患侧避免咀嚼硬物，防止囊壁破裂继发感染及大型囊肿区域病理性骨折。\n3. 口腔卫生与生活：保持口腔清洁、餐后漱口，术后24小时内避免刷牙漱口，之后轻柔刷牙；戒烟戒酒，避免剧烈运动、劳累及熬夜。\n4. 禁忌：禁止自行挤压、针刺或挑破肿物，禁止局部热敷或非医嘱按摩理疗，以免感染扩散或囊液外溢。\n\n【随诊要求】\n1. 术后7～10天复诊拆线，并取回病理检查报告供医师判读。\n2. 术后3～6个月复查颌面X线或锥形束CT，评估骨腔愈合及骨质重建情况；含牙囊肿、牙源性角化囊肿等复发风险高者，建议每6个月～1年影像学随访2～3年。\n3. 若出现术区红肿胀痛、发热、溢脓、口内瘘口或肿物再次隆起，应及时返院就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":643,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1a2dc9e1099ee648f4e172401945741fc5724d1504e5e54c0ee01c57fc9e8b30","pinyin":"kouqianghemianbunangzhong","initials":"kqhmbnz","setting":"out","caseName":"门诊病历508","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历508",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-05f6065311ca5080b750","key":"v1-c9ccc21dfe2a3058|templates-05f6065311ca5080b750","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"恐惧症","category":"门诊病历模板","raw":{"name":"恐惧症","category":"门诊病历模板","case":{"case_name":"门诊病历509","templates":{"主诉":"反复恐惧伴心悸1周","现病史":"患者1周前无明显诱因出现恐惧症相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者反复恐惧伴心悸1周，恐惧、心悸既可为精神心理症状，也可由躯体疾病诱发，故须先完善检查排除器质性疾病。完善血常规检查排除贫血所致心悸、乏力；完善血糖检查排除低血糖发作引起的紧张、心慌、出汗等类似惊恐表现；完善电解质检查排除低钾、低钙等电解质紊乱所致心悸及肢体感觉异常。查心电图检查了解心律及有无心肌缺血，必要时完善动态心电图及心脏彩超检查明确有无心律失常、心脏结构异常所致的心悸；查甲状腺功能检查排除甲状腺功能亢进这一引起心悸、烦躁、易激惹的常见躯体病因。患者情绪症状明显、长期睡眠受影响，完善肝肾功能检查为抗焦虑药物选择及剂量调整提供依据、排除肝肾功能不全；完善血脂检查了解血脂水平、评估代谢状态及药物选择；完善尿常规、便常规检查排除泌尿系及消化道感染、慢性失血等躯体疾病；查胸部X线片排除肺部疾病所致胸闷气短，查腹部超声了解肝胆胰脾情况、排除腹部疾病所致躯体不适。同时完善焦虑自评量表、抑郁自评量表及必要时的心理评估，明确症状严重程度、与其他精神障碍鉴别，必要时请精神心理科会诊。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 恐惧症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 选择性5-羟色胺再摄取抑制剂（SSRI，首选）：帕罗西汀片20mg qd 口服，晨服，2-4周起效，疗程12-24周，症状缓解后维持治疗6-12个月后遵医嘱缓慢减量停药。\n2. 5-羟色胺与去甲肾上腺素再摄取抑制剂（SNRI）：文拉法辛缓释胶囊75mg qd 口服，早餐后顿服，用于SSRI疗效不佳或不耐受者，疗程同SSRI。\n3. 苯二氮䓬类（短期按需）：劳拉西泮片0.5mg bid-tid 口服，用于急性焦虑发作或预期性焦虑明显者，仅短期使用，疗程不超过2-4周，防药物依赖。\n4. 社交恐惧情境用药：普萘洛尔片10-20mg 于暴露于恐惧情境前30-60分钟口服，单次按需使用，减轻心慌、手抖、出汗等躯体症状（心率<60次/分、哮喘者禁用）。\n【一般治疗及生活指导】\n1. 认知行为治疗（CBT）为本病一线心理治疗，建议每周1次，行系统脱敏、暴露疗法及认知重建，配合呼吸放松、渐进式肌肉放松训练，每日1-2次。\n2. 生活规律，保证充足睡眠，避免熬夜；忌浓茶、咖啡、酒精及含兴奋剂饮料，以免诱发或加重焦虑。\n3. 鼓励在家人陪伴下循序渐进接触恐惧情境（分级暴露），避免过度回避及\"安全行为\"强化恐惧；记录恐惧发作诱因与频次。\n4. 适当有氧运动（每周至少150分钟，如快走、慢跑、游泳），有助于缓解紧张情绪、改善睡眠。\n【随诊要求】\n1. 用药后2-4周复诊，评估疗效及药物不良反应；SSRI起效较慢，需坚持足量足疗程，不可自行停药或加量。\n2. 治疗期间每4周复诊一次，评估恐惧回避程度、惊恐发作频率及社会功能改善情况，据此调整剂量。\n3. 停药医师指导下每2-4周缓慢减量，防撤药反应；若出现头晕、恶心、激越等不良反应或症状加重，及时复诊。\n4. 足量足疗程治疗4-8周无效、合并严重抑郁或出现自杀意念者，转精神专科进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":644,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a6fb47eed4f9b25e0464446d60efaea5bdbf3f4d2f5f3bae05b133173775dc1b","pinyin":"kongjuzheng","initials":"kjz","setting":"out","caseName":"门诊病历509","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历509",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-429e3c0d9a89cee9341a","key":"v1-c9ccc21dfe2a3058|templates-429e3c0d9a89cee9341a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"惊恐障碍","category":"门诊病历模板","raw":{"name":"惊恐障碍","category":"门诊病历模板","case":{"case_name":"门诊病历510","templates":{"主诉":"反复突发恐惧伴心悸6月","现病史":"患者于6个月前开始反复出现惊恐发作（突发，10分钟内达高峰，数分钟至20分钟缓解，伴强烈恐惧，有濒死感即怕要死了、失控感即怕发疯，并伴心悸心慌、气促窒息感、胸闷胸痛、头晕、出汗震颤、恶心、麻木感、现实解体），发作间期对再次发作持续担忧（预期性焦虑，怕在公共场所发作，形成广场恐惧，回避单独外出、乘公交及密闭空间，严重时不敢出门），发作突发且无明确诱因（区别于特定恐惧），有无甲亢、心律失常或冠心病（心源性，首发及老年者需先排除，查心电图并请心内科评估）、低血糖、嗜铬细胞瘤、咖啡因或兴奋剂过量、抑郁共病及自杀风险：无上述诱因。今日来我院精神科或心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P92次/分（发作时可增快），R20次/分，BP118/76mmHg。表情焦虑紧张、双手细颤、出汗，心肺听诊（排除器质性）、甲状腺（肿大提示甲亢）。","辅助检查":"【必做】甲状腺功能（甲亢可致心悸焦虑，必查）、心电图（排除心律失常或缺血，必要时行动态心电图及心脏超声）、血糖；【其他】电解质、嗜铬细胞瘤筛查（阵发性发作伴血压波动时，必要时）、焦虑抑郁量表及自杀评估。","初步诊断":"1. 惊恐障碍（伴广场恐惧，须先排除躯体疾病）\n（注：认知行为疗法为一线心理治疗（认知重建，纠正对心悸等躯体感觉的灾难化解释；暴露治疗，广场情境逐步暴露；呼吸放松训练，用于发作时自我管理）；药物以SSRI为一线（帕罗西汀20mg每日1次，或舍曲林、艾司西酞普兰，起始低量以防初期激活，4~8周起效，疗程6~12个月，为防复发须渐减）、苯二氮卓类短期使用（少于2~4周，如阿普唑仑，防依赖，仅作桥接或用于严重发作）；发作急诊时，先以心电图排除心梗后安抚，并短期用劳拉西泮，避免反复急诊（配合教育）；共病抑郁者评估自杀风险（必须询问）；限咖啡因及酒精，规律有氧运动，做好睡眠管理；由精神科专科负责复发预防。）","处理方案":"【药物治疗】\n1. 首选SSRI类抗抑郁药（一线用药）：舍曲林片（左洛复）50mg qd口服，起始剂量25mg qd，1周后加至50mg qd，若疗效不足2周后可加至100mg qd；起效需2-4周，总疗程6-12个月，症状缓解后继续维持治疗至少6个月，不可擅自停药。\n2. 急性惊恐发作期短期联合苯二氮䓬类：阿普唑仑片0.4mg bid口服，发作先兆时可临时加服0.4mg，每日总量不超过1.6mg；连续使用不超过4周，症状控制后逐渐减量，避免长期依赖。\n3. 若SSRI疗效不佳或不能耐受，换用SNRI类：文拉法辛缓释胶囊75mg qd口服（早餐后顿服），2周后疗效不足可加至150mg qd，疗程6-12个月。\n\n【一般治疗及生活指导】\n1. 休息：保证规律作息，每晚睡眠7-8小时，避免熬夜及过度劳累；发作时立即采取缓慢腹式深呼吸（吸气4秒-屏气7秒-呼气8秒）、渐进性肌肉放松等放松训练以缓解症状。\n2. 饮食：忌咖啡、浓茶、可乐、酒精等兴奋性饮料及高糖食品，避免暴饮暴食，可适量进食富含B族维生素及色氨酸食物（如香蕉、燕麦、坚果）。\n3. 活动：坚持规律有氧运动（快走、慢跑、游泳、瑜伽），每周3-5次、每次30分钟，运动有助于降低惊恐发作频率和程度。\n4. 禁忌：避免自行增减剂量或突然停药；服用镇静药物期间避免驾驶、高空作业及操作精密机械；避免反复过度关注自身躯体感受，减少\"恐病\"行为。\n\n【随诊要求】\n1. 开始服药后2周复诊，评估药物疗效及不良反应（恶心、口干、嗜睡、性功能障碍等）。\n2. 治疗初期每月复诊1次，症状稳定后每1-3个月复诊1次，评估惊恐发作频率、回避行为及生活质量改善情况。\n3. 减药、停药医师指导下缓慢进行（每1-2周递减1次剂量），停药期间每2周复诊1次；若惊恐发作明显增多、出现持续失眠或自杀意念，应立即就诊或急诊就医。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":645,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4ac8772930ab9e1f20827a7052b13e863b98c26ece4bc21146974f3257a951c7","pinyin":"jingkongzhangai","initials":"jkza","setting":"out","caseName":"门诊病历510","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历510",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c525202d70f70222e537","key":"v1-c9ccc21dfe2a3058|templates-c525202d70f70222e537","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"广泛性焦虑障碍","category":"门诊病历模板","raw":{"name":"广泛性焦虑障碍","category":"门诊病历模板","case":{"case_name":"门诊病历511","templates":{"主诉":"反复担忧紧张伴失眠6月","现病史":"患者于6个月前开始对生活琐事（健康、家庭、工作、经济）过度担忧（难以自控）、紧张不安，伴坐立不安、易疲劳、注意力不集中、易激惹、肌肉紧张（颈肩痛、头痛）、睡眠障碍（入睡困难、易醒），有无躯体化表现（心悸、紧张性胃痛腹泻、尿频出汗，但无惊恐发作，且不局限于特定情境），有无抑郁共病、酒精或镇静药自我用药、甲亢（焦虑伴心悸消瘦，须鉴别，必查）、咖啡因过量、物质戒断、绝经期：无特殊。今日来我院精神科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P84次/分（可增快），R18次/分，BP120/78mmHg。表情紧张忧虑、坐立不安、双手细颤、出汗、颈肩肌肉紧张、心肺听诊正常、甲状腺无肿大。","辅助检查":"【必做】甲状腺功能（鉴别甲亢，必查）、心电图、血糖；【其他】焦虑抑郁量表（评估严重度及随访）、自杀风险评估（共病抑郁者必问）、肝肾功能（用药前基线）。","初步诊断":"1. 广泛性焦虑障碍（中度，共病失眠待评估）\n（注：药物以SSRI或SNRI为一线（帕罗西汀、艾司西酞普兰、文拉法辛，起始低量，4~8周起效，疗程6~12个月，防复发须渐减），苯二氮卓类仅短期使用（少于4周，防依赖，老年人防跌倒）；丁螺环酮为非苯二氮卓类，无依赖性，起效慢；心理治疗以认知行为疗法为一线（纠正灾难化思维、渐进性肌肉放松或正念、担忧管理并设固定担忧时间）、睡眠管理（睡眠卫生，必要时短程助眠）；有氧运动（每周≥3次，有抗焦虑证据）、限制咖啡因及酒精；共病抑郁及物质滥用须一并处理；精神科随访，2~4周评估起效并调整用药，维持期防复发，开展健康教育（本病慢性但可控制，以管理为主）。）","处理方案":"【药物治疗】\n1. 一线首选选择性5-羟色胺再摄取抑制剂（SSRI）：艾司西酞普兰片10mg qd晨服，起始5mg qd×3-5天，耐受后加至10mg qd，急性期疗程至少12周，维持期6-12个月。\n2. 若SSRI疗效不佳或不耐受，换用5-羟色胺和去甲肾上腺素再摄取抑制剂（SNRI）：文拉法辛缓释胶囊75mg qd晨服起始，1-2周后加量至150mg qd；或度洛西汀肠溶胶囊60mg qd，疗程同前。\n3. 急性期焦虑症状明显（如惊恐发作、严重失眠）可短期辅助苯二氮䓬类：劳拉西泮片0.5mg bid或睡前0.5-1mg，仅用2-4周，症状缓解后渐减停，避免长期使用以防依赖。\n【一般治疗及生活指导】\n1. 保持规律作息，保证每晚7-8小时睡眠，避免熬夜和昼夜颠倒；进行规律有氧运动（快走、慢跑、瑜伽、游泳等），每周至少3次、每次30分钟以上，有助于降低焦虑水平。\n2. 避免咖啡、浓茶、酒精、尼古丁及含兴奋成分的饮品，防止诱发心悸、紧张、失眠等症状。\n3. 学习并每日练习放松技术（腹式呼吸、渐进式肌肉放松、正念冥想）10-15分钟；建议接受认知行为治疗（CBT）等心理治疗，与家人保持沟通，必要时寻求心理支持。\n4. 合理安排工作与休息，减少应激源，避免过度劳累及长时间使用手机、电脑；规律进餐，均衡营养，不宜空腹长时间工作。\n【随诊要求】\n1. 开始服药后2周复诊，评估疗效及不良反应（恶心、头晕、嗜睡、乏力、性功能障碍等），据此调整剂量。\n2. 急性期每2-4周复诊1次，症状缓解（HAMA评分较基线下降≥50%）后进入维持期，每4-8周复诊；总疗程至少6-12个月，停药医师指导下数周至数月内缓慢减量，不可骤停以防撤药反应和复发。\n3. 复诊时重点评估情绪、睡眠、躯体症状及社会功能恢复情况，并监测自杀意念（尤其青少年及治疗初2-4周）；老年或合并躯体疾病患者注意药物相互作用，定期复查肝肾功能、心电图。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":646,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8caf7a11f94541fad7dd0ae98c8ca7bc3a217f0fb14a02bcc39f04858e9ce860","pinyin":"guangfanxingjiaolvzhangai","initials":"gfxjlza","setting":"out","caseName":"门诊病历511","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历511",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-858cc0690f55e10e1e4d","key":"v1-c9ccc21dfe2a3058|templates-858cc0690f55e10e1e4d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"社交焦虑障碍","category":"门诊病历模板","raw":{"name":"社交焦虑障碍","category":"门诊病历模板","case":{"case_name":"门诊病历512","templates":{"主诉":"社交时恐惧伴脸红手抖1年","现病史":"患者于青少年期起病，出现：在社交情境（当众讲话、聚会、与陌生人交谈、被注视时进食或书写）中显著恐惧焦虑（怕说错话被嘲笑、怕脸红手抖出汗被注意，核心是怕负面评价）、躯体症状（脸红、出汗、手抖、心慌、口干、说话结巴，焦虑明显时出现）、回避行为（回避社交场合、学校或工作，影响学业职业社交，造成功能损害）、预期性焦虑（事前数天即担忧，痛苦明显）；有无广泛性焦虑或抑郁共病、物质使用（以酒精缓解社交焦虑者常见，有依赖风险）、自杀意念（需评估）、自幼害羞性格（与之区别，社交焦虑为过度且致功能损害）、表演型（仅在演讲等表现情境）与广泛型（多数社交情境）之分、童年被嘲笑或羞辱史、父母过度保护或批评：无特殊。今日来我院精神科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P88次/分（焦虑时可快），R18次/分，BP118/74mmHg。表情紧张、出汗、手抖（会谈时可观察到）、回避眼神、言语（紧张，需评估）、甲状腺（排除甲亢所致心慌手抖）、心肺、神经系统（常规）。","辅助检查":"【必做】临床访谈评估（核心，含社交焦虑量表LSAS评估严重度及随访、SCID结构式访谈）、抑郁量表（PHQ-9，评估共病）、自杀风险评估（重要，共病抑郁时）、物质使用评估；【排除】甲状腺功能（甲亢可致焦虑心悸，须鉴别，重要）、咖啡因过量、物质戒断。","初步诊断":"1. 社交焦虑障碍（社交恐惧症，广泛型，严重度中等，伴回避及功能损害，共病抑郁及物质使用待评估）\n（注：治疗以心理治疗为一线，加CBT（认知重建，纠正对负面评价的灾难化预期；暴露治疗，逐级社交情境暴露，为核心；社交技能训练）、SSRI药物（帕罗西汀、舍曲林、艾司西酞普兰为一线，须用足剂量8~12周，疗程6~12个月，防复发）、SNRI（文拉法辛）、β受体阻滞剂（普萘洛尔，用于表演型，演出前按需服用，缓解手抖心慌）、苯二氮卓类（短期或按需，防依赖，不作一线）、共病抑郁者同时治疗（SSRI可同时覆盖）、物质滥用者须处理、心理教育（本病可治，应主动做暴露练习，勿回避，因回避会强化恐惧）、随访（用LSAS于2~4周评估起效并调整，维持治疗防复发，促进功能恢复）。","处理方案":"【药物治疗】\n1. 选择性5-羟色胺再摄取抑制剂（SSRIs，一线首选）：帕罗西汀片20mg qd早餐后顿服，2-4周起效，足量足疗程维持6-12个月；亦可选用艾司西酞普兰片10mg qd口服，疗效欠佳时可渐加至20mg qd。\n2. 备选SSRI：舍曲林片50mg qd口服，疗效欠佳时可渐加至100-200mg qd，疗程同前。\n3. 急性期或等待SSRIs起效期的短期焦虑控制：阿普唑仑片0.4mg bid-tid口服，短期按需使用，避免长期依赖。\n4. 表现型社交焦虑（演讲、会议发言、面试等特定情境）：普萘洛尔片10-20mg，于暴露情境前1小时单次口服，控制心悸、震颤等躯体症状。\n\n【一般治疗及生活指导】\n1. 规律作息，保证每日7-8小时睡眠，坚持每周3-5次、每次30分钟的有氧运动（如快走、慢跑），有助于缓解焦虑。\n2. 避免咖啡因、浓茶、酒精及吸烟等可诱发或加重焦虑的刺激物。\n3. 进行渐进式社交暴露训练：从低焦虑情境（如与熟人交谈、超市购物）逐步过渡至高焦虑情境（如当众发言），并配合认知调整，避免因回避行为强化恐惧。\n4. 家属应给予理解与支持，鼓励患者参加社交活动，避免责备或强迫其面对难以耐受的场合。\n\n【随诊要求】\n1. 用药初期每2-4周复诊，评估疗效、耐受性及药物不良反应（SSRIs需重点关注胃肠道反应、性功能影响及停药反应）。\n2. 病情稳定后每1-3个月复诊，维持治疗至少6-12个月，遵医嘱缓慢减量，切勿自行停药或加量。\n3. 如出现情绪恶化、明显冲动、自伤观念或严重药物不良反应，请及时提前就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":647,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2f469613bcadedd523d21e7cfa32edcea4f74e3e8b9cc40bfb26bfe33bda19c8","pinyin":"shejiaojiaolvzhangai","initials":"sjjlza","setting":"out","caseName":"门诊病历512","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历512",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1476cfb8ca2ce684e440","key":"v1-c9ccc21dfe2a3058|templates-1476cfb8ca2ce684e440","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"创伤后应激障碍","category":"门诊病历模板","raw":{"name":"创伤后应激障碍","category":"门诊病历模板","case":{"case_name":"门诊病历513","templates":{"主诉":"创伤后闪回伴回避6月","现病史":"患者曾经历严重创伤事件（事故、灾害、暴力、性侵、战争、亲人骤亡，可为直接经历或目睹），创伤后出现：闯入性再体验（反复闪回、身临其境、噩梦、闯入性痛苦记忆、创伤线索引发明显生理反应）、回避（回避与创伤相关的记忆、谈论、场所及人物）、认知与情绪的负性改变（创伤相关记忆缺失、负性信念如认为世界危险或过度自责、负性情绪、兴趣减退、疏离与情感麻木）、警觉性增高（易激惹、过度警觉、惊跳增强、注意力差、睡眠差）；症状持续>1个月（急性<3个月，慢性>3个月），显著影响社会功能。有无抑郁共病（抑郁共病率高，自杀风险评估为必问内容）、物质滥用（可因酒精自我缓解而成瘾）、躯体症状、惊恐共病及既往创伤史：无。今日来我院精神科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P82次/分（可增快），R18次/分，BP120/76mmHg。表情紧张或情绪平淡（情感麻木）、对创伤话题回避（眼神躲闪）、警觉惊跳，谈创伤时出汗等自主神经反应；躯体检查常规（排除躯体疾病）。","辅助检查":"【必做】精神评估为主（创伤史采集须注意敏感性，不强行追问；PTSD四维度评估（PCL-5量表，用于严重度评估及随访）；诊断性访谈按DSM-5标准）；【共病】抑郁量表、自杀风险评估（必做，重要）、物质使用评估、睡眠评估。","初步诊断":"1. 创伤后应激障碍（慢性，病程>3个月，无延迟起病；需共病抑郁及物质使用评估）\n（注：创伤聚焦心理治疗为一线（创伤聚焦认知行为疗法，通过长期暴露处理创伤记忆；认知加工疗法，纠正负性信念；眼动脱敏再加工，国际指南推荐，每周1次共12~16周，疗效显著且复发少）；药物辅助治疗：SSRI（舍曲林或帕罗西汀，FDA批准，改善闯入、回避及警觉症状，4~8周起效，疗程6~12个月）、SNRI（文拉法辛，二线）、睡眠用药（曲唑酮或哌唑嗪，哌唑嗪为α1受体阻滞剂，对创伤噩梦有效）、苯二氮䓬类不推荐长期使用（可加重PTSD）；共病处理（抑郁用SSRI覆盖、物质滥用先处理、自杀风险者制定安全计划或住院）；稳定化治疗及社会支持（放松训练、正念、睡眠管理，家庭及患者教育）；创伤后早期予心理急救，识别急性应激障碍，早期干预以防进展；精神科或心理科专科系统治疗，重视复发预防。）","处理方案":"【药物治疗】\n根据病情紧急处理，具体用药根据诊断和生命体征决定。\n\n【一般治疗及生活指导】\n卧床休息，密切监测生命体征，保持呼吸道通畅，建立静脉通路。\n\n【随诊要求】\n根据病情决定是否住院或留观，如症状加重立即就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":648,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9e3445ca3c8d551298a736482aee3e47aa39c4ae34d70b783a8575a50fcbb6fb","pinyin":"chuangshanghouyingjizhangai","initials":"cshyjza","setting":"out","caseName":"门诊病历513","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历513",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-27ab8b6287e094f47298","key":"v1-c9ccc21dfe2a3058|templates-27ab8b6287e094f47298","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"适应障碍","category":"门诊病历模板","raw":{"name":"适应障碍","category":"门诊病历模板","case":{"case_name":"门诊病历514","templates":{"主诉":"情绪低落伴失眠1周","现病史":"患者1周前无明显诱因出现适应障碍相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者情绪低落伴失眠1周，起病有明显心理社会应激背景，但仍须先完善检查排除躯体疾病所致情绪障碍。完善血常规检查排除贫血所致乏力、情绪低落；完善血糖检查排除低血糖或糖代谢异常引起的情绪波动、乏力；完善电解质检查排除电解质紊乱所致乏力及精神症状。查甲状腺功能检查排除甲状腺功能减退所致情绪低落、反应迟钝、嗜睡，排除甲状腺功能亢进所致失眠、烦躁；查心电图检查了解心律及有无心肌缺血，排除心脏疾病所致躯体不适与继发情绪问题。患者情绪及睡眠障碍需药物治疗，完善肝肾功能检查排除肝肾功能不全、为镇静催眠及抗抑郁药物剂量调整提供依据；完善血脂检查了解血脂水平、评估代谢状态；完善尿常规、便常规检查排除泌尿系及消化道疾病；查胸部X线片排除肺部感染及结核等慢性消耗性疾病所致乏力、情绪改变，查腹部超声了解肝胆胰脾情况、排除腹部器质性疾病。同时完善抑郁自评量表、焦虑自评量表及睡眠质量评估，明确情绪与睡眠障碍程度，必要时请精神心理科会诊进一步评估、与其他精神障碍鉴别。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 适应障碍\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗焦虑（一线）：坦度螺酮片10mg po tid×4周；或劳拉西泮片0.5mg po bid，症状缓解后逐渐减量，总疗程不超过2-4周，避免长期使用苯二氮䓬类。\n2. 抗抑郁（伴明显抑郁情绪）：舍曲林片50mg po qd（早餐后服），连用2周评估疗效，疗效不佳可渐增至100mg qd，总疗程至少6-8周，勿突然停药。\n3. 改善睡眠（伴入睡困难）：曲唑酮片25-50mg po qn，睡前服用，疗程2-4周，根据睡眠改善情况调整或停用。\n4. 症状轻微者首选心理治疗，暂不启动药物；药物仅用于症状明显影响日常功能时，且应小剂量起始、缓慢加减。\n\n【一般治疗及生活指导】\n1. 心理支持：鼓励倾诉应激事件感受，避免压抑情绪；可配合认知行为治疗或支持性心理治疗，每周1次。\n2. 作息规律：保证每日7-8小时睡眠，固定就寝及起床时间；白天避免长时间卧床，午睡不超过30分钟。\n3. 适度活动：每日进行30分钟中等强度有氧运动（快走、慢跑、瑜伽等），有助于缓解紧张焦虑情绪。\n4. 禁忌：服药期间禁酒及含咖啡因饮品（咖啡、浓茶、功能饮料），避免驾驶及高空作业（尤其使用苯二氮䓬类期间），避免反复接触引发应激的事件场景。\n\n【随诊要求】\n1. 用药后2周复诊，评估症状改善程度及药物耐受性（如头晕、嗜睡、胃肠不适等不良反应）。\n2. 每4周复诊1次，连续随访8-12周，评估情绪、睡眠及社会功能恢复情况，根据病情调整药物剂量或减停。\n3. 若出现症状加重、持续失眠、食欲显著减退、消极观念或自伤行为，需立即就医或至心理/精神科急诊，不可等待预约复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":649,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cfcdf0e4d3fcf3e9001bf0b52f148a7ddf7f5271207ef5572dfb7bb8d3314a8e","pinyin":"shiyingzhangai","initials":"syza","setting":"out","caseName":"门诊病历514","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历514",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-108471b423dbbdc4d033","key":"v1-c9ccc21dfe2a3058|templates-108471b423dbbdc4d033","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"躯体形式障碍","category":"门诊病历模板","raw":{"name":"躯体形式障碍","category":"门诊病历模板","case":{"case_name":"门诊病历515","templates":{"主诉":"反复多部位躯体不适2年，加重伴情绪低落1个月。","现病史":"患者2年前无明显诱因渐出现多种躯体不适，表现为头痛、头晕、心悸、胸闷、上腹不适、肢体麻木等，症状多变、部位不固定，反复于多家医院就诊，先后行头颅CT、心电图、心脏彩超、胃镜、腹部超声等多项检查均未见明显器质性异常，相关专科治疗后症状无明显缓解。1个月来上述症状加重，伴情绪低落、兴趣减退、睡眠差（入睡困难、早醒）、乏力，担心自己患有不治之症，反复要求检查，影响工作及生活。发病以来食欲欠佳，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 78次/分，R 18次/分，BP 118/76mmHg。神志清楚，接触合作，表情焦虑，言语流畅。全身系统查体未见与主诉相符的阳性体征：心肺听诊未闻及异常，腹部平软无压痛，神经系统检查无阳性体征，四肢肌力肌张力正常，病理征阴性。","辅助检查":"【必做】结合既往检查情况，一般无需反复重复检查；可完善血常规、甲状腺功能、心电图、血糖等以排除常见器质性疾病（如患者近期未查）；【原则】避免无指征地反复进行侵入性或有辐射检查，检查应以排除器质性疾病为限，重点在于医患沟通与心理评估。","初步诊断":"1. 躯体形式障碍\n（注：诊断需建立在充分排除器质性疾病基础上，必要时请精神科/心理科会诊评估。）","处理方案":"【药物治疗】\n1. 选择性5-羟色胺再摄取抑制剂（SSRIs）为一线首选：舍曲林片 50mg qd（早餐后口服），首周25mg qd起始，1周后加至50mg qd，疗效不佳者2-4周后加至100mg qd，疗程8-12周，症状缓解后继续巩固治疗6-12个月；\n2. 5-羟色胺与去甲肾上腺素再摄取抑制剂（SNRIs）：度洛西汀肠溶胶囊 30mg qd起始，1周后加至60mg qd，疗程8-12周（适用于伴明显疼痛、SSRI疗效不佳或不耐受者）；\n3. 抗焦虑辅助用药：坦度螺酮片 10mg tid口服；睡眠差者短期联用劳拉西泮片 0.5mg qn（睡前服），连续使用不超过2-4周，避免依赖；\n4. 合并抑郁症状明显者，可联合米氮平片 15mg qn起始，根据患者具体情况制定个体化方案增至30mg qn，注意监测体重及嗜睡反应。\n\n【一般治疗及生活指导】\n1. 规律作息，保证每晚7-8小时睡眠，避免熬夜、过度劳累及精神紧张；\n2. 坚持适度有氧运动（快走、慢跑、太极拳等）每周3-5次、每次30-40分钟，转移对躯体不适的过度关注；\n3. 饮食清淡均衡，忌浓茶、咖啡、酒精及辛辣刺激食物；避免反复自行检查身体、频繁网络检索症状及不必要的重复就医、过度检查；\n4. 配合心理治疗（认知行为治疗、正念治疗等），家属避免过度关切或否定患者不适主诉，营造宽松、支持的家庭氛围。\n\n【随诊要求】\n1. 2周后复诊，评估疗效及药物不良反应（恶心、头晕、嗜睡、口干等）并调整剂量；病情稳定后每4周复诊1次；\n2. 疗程中出现情绪恶化、自伤自杀观念、药物明显不耐受或新发严重躯体症状者，应及时就诊或电话联系医师，不可拖延；\n3. 症状缓解后遵医嘱巩固治疗6-12个月，停药医师指导下每1-2周缓慢减量，严禁自行停药或骤停；每3个月复查肝肾功能及血常规。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":650,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0e9c973d321e1c199105eb78898e60eadc5bf3cde55e0716824d5ce4444b349a","pinyin":"qutixingshizhangai","initials":"qtxsza","setting":"out","caseName":"门诊病历515","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历515",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d3f281c3953b432572f8","key":"v1-c9ccc21dfe2a3058|templates-d3f281c3953b432572f8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"癔症","category":"门诊病历模板","raw":{"name":"癔症","category":"门诊病历模板","case":{"case_name":"门诊病历516","templates":{"主诉":"反复癔症相关不适1周，加重1天。","现病史":"患者1周前无明显诱因出现癔症相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者反复癔症相关不适1周、加重1天，伴轻度乏力，首先完善血常规检查排除感染、贫血所致躯体症状；查尿常规、便常规排除泌尿系感染、消化道隐血等器质性病变；患者否认高血压、糖尿病、冠心病等慢性病史，但症状需与代谢性及内分泌疾病鉴别，完善肝肾功能检查排除肝肾功能不全，查血糖排除低血糖反应、查血脂了解血脂水平并评估动脉硬化危险因素，完善电解质检查排除低钾、低钙等电解质紊乱所致肢体麻木无力；患者日间困倦乏力、发作性症状需排除心脑供血异常，完善心电图检查排除心律失常、心肌缺血，查胸部X线片排除肺部感染及占位性病变；患者进食睡眠尚可、体重无明显变化，完善腹部超声了解腹部脏器有无器质性病变；因症状具有发作性、暗示性特点，必要时完善头颅CT或MRI检查排除颅内器质性病变，并与癫痫发作相鉴别，必要时行脑电图检查明确有无异常放电；上述检查结果回报后结合病史、体征综合判断，必要时请神经内科、精神科会诊协助明确诊断。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 癔症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】以心理治疗为主、药物为辅，药物治疗仅用于缓解伴随症状：\n1. 抗焦虑药（伴紧张、焦虑、失眠者）：地西泮片 2.5mg po tid，短期使用（一般不超过2-4周），症状缓解后逐渐减量停药，避免长期使用产生依赖性。\n2. 选择性5-羟色胺再摄取抑制剂（伴明显抑郁、焦虑情绪者）：帕罗西汀片 20mg po qd（早餐后顿服），疗程4-8周，症状改善后维持治疗并缓慢减量，注意监测撤药反应。\n3. 自主神经调节药（伴头晕、心悸、出汗等自主神经功能紊乱症状者）：谷维素片 10mg po tid，连用1-2个月，作为辅助治疗。\n\n【一般治疗及生活指导】\n1. 保证充足睡眠与规律作息，避免熬夜、过度劳累及长时间精神高度紧张。\n2. 鼓励适当舒缓活动，如散步、太极拳、瑜伽等，劳逸结合；避免观看恐怖、惊险、刺激性影视及参与激烈情绪冲突场合。\n3. 家属应给予理解与支持，避免过度关注患者症状、反复询问或指责，减少暗示性强化；患者本人应避免情绪激动，学会倾诉与放松技巧（如深呼吸、冥想）。\n4. 发作期间避免单独活动及从事危险操作（如驾车、高空作业），防止意外伤害。\n\n【随诊要求】\n1. 用药后1-2周复诊，评估症状缓解程度及药物耐受情况，调整治疗方案。\n2. 遵医嘱规律服药，不可自行增减剂量或突然停药；地西泮等苯二氮䓬类停药需遵医嘱缓慢减量。\n3. 若症状反复发作、持续加重或出现明显抑郁、自伤自杀观念，应及时复诊或立即就医。\n4. 症状缓解后建议每1-3个月随访1次，评估心理状态及社会功能恢复情况，巩固疗效、预防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":651,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"652bf02fa03f4af5207d0446e5d5347bb9533f7f1970a78afb38734247bcc550","pinyin":"yizheng","initials":"yz","setting":"out","caseName":"门诊病历516","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历516",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2cbfe5f62c911eb6635e","key":"v1-c9ccc21dfe2a3058|templates-2cbfe5f62c911eb6635e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"分裂情感性障碍","category":"门诊病历模板","raw":{"name":"分裂情感性障碍","category":"门诊病历模板","case":{"case_name":"门诊病历519","templates":{"主诉":"情绪低落伴幻觉妄想1周","现病史":"患者1周前无明显诱因出现分裂情感性障碍相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者情绪低落伴幻觉妄想1周，为排除器质性疾病所致精神障碍，入院后完善血常规检查排除感染、贫血所致精神症状；查尿常规、便常规排除泌尿系感染、消化道疾病等躯体因素；完善肝肾功能检查排除肝肾功能不全，同时为抗精神病药物、心境稳定剂的安全使用提供基线依据；查血糖排除低血糖所致意识与情绪异常，查血脂了解血脂水平并评估代谢综合征风险，完善电解质检查排除低钠、低钾等电解质紊乱所致精神行为异常；患者需与甲状腺功能异常所致情绪障碍鉴别，完善甲状腺功能检查明确有无甲亢或甲减；完善心电图检查排除心律失常及QT间期延长，为用药安全提供依据；查胸部X线片排除肺部感染及占位，完善腹部超声了解腹部脏器情况；患者首次发病、症状以幻觉妄想为主，完善头颅CT或MRI检查排除颅内占位、脑血管病变等器质性病因；必要时行脑电图检查排除癫痫性精神障碍，并行心理测评量表评估情绪与精神病性症状严重程度，指导后续治疗。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 分裂情感性障碍\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 第二代抗精神病药（首选）：奥氮平片起始5mg qn（睡前服），根据疗效及耐受性每3-7天渐加至10-20mg/d；或利培酮片起始1mg bid，渐加至2-4mg/d（分1-2次服，最大6mg/d）。急性期足量足疗程≥4-8周后评估疗效，症状缓解后维持治疗至少6-12个月，减停药患者医生指导下缓慢进行。\n2. 抑郁型（以抑郁症状为主）：联合抗抑郁药，如舍曲林片50mg qd晨服，1-2周无效者可渐加至100-150mg/d（最大200mg/d），与抗精神病药联用至少4-6周评估疗效，注意监测躁狂转相可能。\n3. 双相型（以躁狂或混合相为主）：联合心境稳定剂，如丙戊酸钠缓释片250mg bid起始，渐加至500-1500mg/d，监测血药浓度维持在50-100μg/mL；或碳酸锂片0.25g bid起始，渐加至有效量（血锂浓度0.6-1.2mmol/L），定期监测血锂及甲状腺、肾功能。\n\n【一般治疗及生活指导】\n1. 规律作息：保证每晚7-9小时睡眠，固定起床与入睡时间，避免熬夜及昼夜颠倒；日间午休不超过30分钟，避免过度兴奋活动。\n2. 饮食与活动：均衡营养饮食，忌浓茶、咖啡、酒精及含酒精饮料；每日进行散步、快走、太极拳等中等强度活动30分钟左右，避免剧烈及竞技性活动。\n3. 服药与安全管理：严格遵医嘱规律服药，不得自行增减剂量或突然停药（骤停可致复发或撤药反应）；药品由家属保管并监督服药，防止漏服或过量；治疗初期及剂量调整期避免驾驶、高空及危险机械作业，独居者由家属加强看护。\n4. 病情监测：家属注意观察睡眠、情绪及言行变化，若出现冲动、自伤、自杀或伤人等迹象，立即联系主治医生或就近精神专科急诊就诊。\n\n【随诊要求】\n1. 急性期每1-2周复诊1次，评估疗效及药物不良反应（锥体外系症状、体重、血糖、血脂、催乳素、心电图等）；病情稳定后延长至每2-4周复诊。\n2. 维持期每1-3个月复诊1次，每3-6个月复查血常规、肝肾功能、血糖、血脂、催乳素及心电图；服用丙戊酸钠者定期监测血药浓度及血常规，服用锂盐者定期监测血锂浓度、甲状腺功能及肾功能。\n3. 复诊时携带门诊病历及用药清单，如实反馈睡眠、情绪、幻觉妄想及日常生活功能情况；若出现失眠、多疑、情绪明显波动等复发征兆，应提前复诊或电话咨询主治医生。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":652,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6d863f53ed2b187e90ad91669309263b72b1e906379995834f642672c7287e50","pinyin":"fenlieqingganxingzhangai","initials":"flqgxza","setting":"out","caseName":"门诊病历519","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历519",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d58ef7240a5405045671","key":"v1-c9ccc21dfe2a3058|templates-d58ef7240a5405045671","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性短暂性精神病性障碍","category":"门诊病历模板","raw":{"name":"急性短暂性精神病性障碍","category":"门诊病历模板","case":{"case_name":"门诊病历521","templates":{"主诉":"幻觉妄想伴行为异常1周","现病史":"患者1周前无明显诱因出现急性短暂性精神病性障碍相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"【必做检查】\n血常规、肝肾功能、甲状腺功能、血糖、电解质\n\n【影像学检查】\n心电图、头颅CT/MRI（排除器质性病变）\n\n【其他检查】\n心理评估量表（PHQ-9、GAD-7、PANSS等）、药物浓度监测\n","初步诊断":"1. 急性短暂性精神病性障碍\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 首选第二代抗精神病药物：奥氮平片5mg qn起始，3-5天内渐增至10-15mg/d，分1-2次口服，急性期治疗4-6周，症状缓解后继续巩固治疗4-6个月（门诊成人常规剂量，根据耐受性及疗效调整）。\n2. 替代方案：利培酮片1mg bid起始，渐增至2-4mg/d（每日总量不超过6mg），分2次口服；急性期疗程及巩固期同上。\n3. 伴明显失眠、焦虑或激越者：劳拉西泮片0.5-1mg qn口服，或阿普唑仑片0.4mg qn口服，短期使用1-2周，症状缓解后逐渐减量停药，避免长期使用产生依赖。\n4. 若治疗中出现锥体外系反应（静坐不能、肌张力增高等）：苯海索片2mg bid口服对症处理，症状消失后减停（不主张常规预防性使用）。\n\n【一般治疗及生活指导】\n1. 休息：急性期建议暂时停止工作学习，保证每日7-8小时睡眠，规律作息，避免熬夜、劳累及精神刺激；卧室环境安静、光线柔和。\n2. 饮食：清淡均衡饮食，保证营养，戒烟戒酒，避免浓茶、咖啡等兴奋性饮品；部分药物可引起食欲增加，注意控制体重。\n3. 活动与监护：症状明显期由家属24小时看护，避免独处，妥善保管利器、刀具、绳索及药物；白天可安排散步、听音乐等适度活动，避免剧烈运动及参与争执。\n4. 心理与家庭支持：家属以耐心倾听、安抚为主，避免指责、争辩；督促按时按量服药，观察服药后有无吞咽药物及藏药行为。\n\n【随诊要求】\n1. 急性期每1-2周复诊1次，评估精神症状改善程度、药物不良反应及服药依从性；症状明显缓解后改为每月复诊1次，持续随访至少6-12个月。\n2. 复诊时复查血常规、肝肾功能、血糖、血脂、电解质及心电图，长期用药者监测体重、泌乳素水平。\n3. 出现以下情况应立即就诊或联系精神专科住院治疗：冲动伤人、自伤自杀言行、拒食拒药、持续失眠或症状突然加重。\n4. 症状缓解后不可自行停药或减量，停药、减量方案须经医生评估后逐步调整，以防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":653,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"91e1d90bc81ceb883d440de9c340c3233127b943e5dc44b31949bd4e4339a329","pinyin":"jixingduanzanxingjingshenbingxingzhangai","initials":"jxdzxjsbxza","setting":"out","caseName":"门诊病历521","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历521",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6466b3b4bf5e74ea2e3b","key":"v1-c9ccc21dfe2a3058|templates-6466b3b4bf5e74ea2e3b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"进食障碍","category":"门诊病历模板","raw":{"name":"进食障碍","category":"门诊病历模板","case":{"case_name":"门诊病历522","templates":{"主诉":"反复贪食伴呕吐1周","现病史":"患者1周前无明显诱因出现进食障碍相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者反复贪食伴呕吐1周，伴轻度乏力，首先完善血常规检查排除感染、贫血所致乏力；查尿常规、便常规排除泌尿系感染、消化道疾病；反复呕吐易致水电解质紊乱及代谢性碱中毒，急诊完善电解质检查排除低钾、低氯等紊乱，完善肝肾功能检查排除肝肾功能不全，并评估营养状态及代谢紊乱程度；查血糖排除低血糖所致乏力、情绪波动，查血脂了解血脂水平；患者长期进食行为异常、体重可受影响，完善心电图检查排除低钾所致心律失常及QT间期延长，必要时查心肌酶；查胸部X线片排除肺部感染，因反复呕吐存在误吸风险；完善腹部超声了解腹部脏器有无器质性病变，排除消化道疾病所致呕吐；患者需与甲状腺功能亢进、糖尿病等内分泌代谢病所致进食异常鉴别，完善甲状腺功能检查；必要时行上消化道钡餐或胃镜检查明确有无食管炎、贲门黏膜撕裂等呕吐并发症；同时行心理测评量表评估进食行为及情绪状态，必要时请精神科、营养科会诊。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 进食障碍\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 氟西汀胶囊（选择性5-HT再摄取抑制剂，SSRI）：起始20mg qd早餐后口服，1周后渐增至40-60mg qd，疗程至少3-6个月；为贪食症一线用药，亦用于厌食症合并抑郁、焦虑者，改善暴食-清除行为及情绪症状。\n2. 奥氮平片（非典型抗精神病药）：2.5mg qn起始，1周后增至5mg qn，必要时可加至10mg qn；用于厌食症患者减轻对体重增加的恐惧与强迫观念、改善睡眠并促进体重恢复。\n3. 复合维生素B片2片 tid＋碳酸钙D3片1片 qd口服：用于营养支持及纠正维生素、钙缺乏，与进食计划同步进行。\n【一般治疗及生活指导】\n1. 饮食指导：每日三餐规律进食、定时定量，保证热量摄入（成人厌食症恢复期初始1200-1500kcal/d，每周递增300kcal），均衡搭配主食、优质蛋白及蔬果；禁止催吐、滥用泻药、利尿剂及减肥药。\n2. 体重管理：每周固定时间监测体重1次，厌食症目标每周增重0.5-1kg，贪食症目标稳定体重；避免晨起空腹反复称重，减少体重数字带来的焦虑。\n3. 活动指导：暂停患者度及补偿性运动（长跑、健身等），改为散步、瑜伽等低强度活动，每日不超过30分钟，避免餐后立即运动。\n4. 心理行为：保持规律作息、充足睡眠；配合认知行为治疗或家庭治疗；家属避免在餐桌上指责催促进食，营造放松的进餐环境。\n【随诊要求】\n1. 每1-2周门诊复诊1次，评估进食行为、体重变化、情绪状态及药物耐受性，病情稳定后逐渐延长至每月1次。\n2. 定期复查血常规、电解质（钾、钠、氯）、肝肾功能、血糖及心电图；首次用药及调整剂量后2周复查，此后每月复查1次。\n3. 出现心悸、乏力、四肢麻木、晕厥或明显水肿提示电解质紊乱可能，需立即急诊就医处理。\n4. 抗抑郁/抗精神病药物需足量足疗程治疗6-12个月，症状缓解后遵医嘱缓慢减量，不可自行停药或增减剂量。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":654,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"eb490b0ad80aaa2e3e49e9fdd37bed952d2313e43287cdba6ce395527f9a8061","pinyin":"jinshizhangai","initials":"jsza","setting":"out","caseName":"门诊病历522","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历522",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-01d5618e608945a811f9","key":"v1-c9ccc21dfe2a3058|templates-01d5618e608945a811f9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"神经性厌食","category":"门诊病历模板","raw":{"name":"神经性厌食","category":"门诊病历模板","case":{"case_name":"门诊病历523","templates":{"主诉":"限制进食伴体重下降8月","现病史":"患者（青少年年轻女性多见）于8个月前开始限制进食（限制型，以节食及过度运动为主）、体重进行性下降（明显低于正常下限，BMI<17.5或低于期望体重15%以上）、强烈恐惧体重增加（即使极度消瘦仍觉得自己胖，存在体像障碍，为本病核心）、对体重体型存在先占观念，伴闭经（女性，停经>3个月）、低体温畏寒、心动过缓、便秘、乏力头晕、皮肤干燥脱发及毳毛、情绪抑郁易怒、拒食行为（藏匿或丢弃食物）及家庭冲突。有无并发症（低钾，与催吐导泻有关，可致心律失常甚至猝死，为最严重并发症；心律失常、QT间期延长、低血压、骨质疏松、贫血、再喂养综合征风险）、自杀风险评估及既往治疗史：无特殊。今日来我院精神科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T35.8℃，P52次/分（心动过缓），R16次/分，BP86/56mmHg（偏低）。身高165cm，体重41kg，BMI 15.1（<17.5）。皮下脂肪消失、恶病质、皮肤干燥脱发及毳毛、肢端发绀发冷、腮腺肿大（催吐所致）、牙齿酸蚀（催吐所致胃酸腐蚀前牙内侧）、低体温、肌力减弱；精神状态行抑郁评估。","辅助检查":"【必做】电解质（血钾，催吐及滥用泻药可致低钾，危及生命，为关键指标；同时查钠、钙、镁、磷）、血糖、肝肾功能、甲状腺功能（可见低T3综合征）、性激素（雌二醇降低，与闭经相关）、血常规、心电图（QT间期延长及心律失常，心源性猝死风险，为关键检查）、骨密度（慢性病程者）；【其他】白蛋白（营养评估）、再喂养综合征风险评估（开始营养支持前，重点监测血磷，重要）、抑郁量表及进食障碍量表。","初步诊断":"1. 神经性厌食（限制型，BMI 15.1，中度）\n（注：多学科治疗（营养恢复为基石＋心理治疗，严重者住院）：营养恢复（首要目标为恢复体重；住院指征为BMI<15~16、心动过缓<40~50次/分、低血压、低钾、心律失常；再喂养综合征监测（低磷，需补磷补钾，心电图监护，缓慢加量以防心力衰竭）；门诊每周增重0.5kg）；心理治疗（认知行为疗法增强版，青少年可采用家庭治疗，父母参与喂食为核心；动机访谈用于处理体像障碍）；药物（氟西汀，适用于暴食清除型或共病抑郁者，营养恢复后效果较好，不单独依赖）；并发症处理（骨质疏松予钙剂、维生素D，恢复体重后月经可恢复；电解质紊乱纠正；心律失常处理）；抑郁及自杀风险评估；随访（每周测体重，月经恢复以体重恢复至90%理想体重为目标，重视复发预防；本病程长，死亡率在精神疾病中最高之一，需精神科、儿科及营养科多学科长期管理。））","处理方案":"【药物治疗】\n1. 选择性5-羟色胺再摄取抑制剂（SSRIs）：氟西汀胶囊20mg qd早餐后口服，2-4周起效，疗程至少6个月（用于合并抑郁、焦虑或强迫症状者，需在营养状况改善后使用效果更佳；监测恶心、失眠、激越等不良反应）。\n2. 非典型抗精神病药：奥氮平片2.5mg qn起始，1-2周后可加至5mg qn，疗程3-6个月（可减轻进食相关焦虑及对体重体型的过度关注，有助于体重恢复；需监测嗜睡、血糖、血脂及体重变化）。\n3. 促胃肠动力药：莫沙必利片5mg tid餐前30分钟口服，疗程2-4周（改善胃排空延迟所致腹胀、早饱、恶心）。\n4. 营养补充剂：碳酸钙D3片（每片含钙600mg/维生素D3 200IU）1片 qd，复合维生素B片1-2片 tid，连用3-6个月（纠正钙及维生素D缺乏，预防骨质疏松）。\n【一般治疗及生活指导】\n1. 营养重建：在营养师指导下制定个体化复食方案，初始每日1200-1500kcal，每周递增300-500kcal，逐步恢复至BMI≥18.5；少量多餐（每日5-6餐），以高营养密度、易消化食物为主，纠正\"恐食\"心理，鼓励记录进食日记。\n2. 活动限制：复食早期限制剧烈运动及长时间活动，每日中低强度活动控制在30分钟以内，避免运动消耗抵消能量摄入；恢复期逐步增加活动量。\n3. 心理行为干预：采用认知行为治疗或家庭治疗，纠正对体重、体型的歪曲认知；家属避免就餐时催促、责备，营造放松的就餐环境；配合行为矫正（完成进食目标给予奖励），严重者转诊精神心理科。\n4. 禁忌：严禁催吐、导泻、滥用利尿剂及减肥药；避免饮用浓茶、咖啡等加重胃排空延迟的饮品；复食期间禁止突然大量进食，防止再喂养综合征（低磷、低钾、心律失常）。\n【随诊要求】\n每周复诊1次，病情稳定后每2-4周复诊1次：每次监测体重（晨起空腹、同条件称重）、血压、心率、BMI，每月复查血常规、电解质（钾、钠、磷）、肝肾功能、血糖、血脂及心电图；治疗6-8周评估疗效，若体重持续下降、出现严重低钾低钠血症、心律失常、晕厥或自杀意念，立即复诊或收住院治疗；体重恢复后仍需坚持随访至少1-2年，预防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":655,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"21be1a60f3e65be5aff8b3ada9b26f3d2c4ed8211d4aceed9b7e312e27865794","pinyin":"shenjingxingyanshi","initials":"sjxys","setting":"out","caseName":"门诊病历523","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历523",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8ad1411b81dd0660eb9e","key":"v1-c9ccc21dfe2a3058|templates-8ad1411b81dd0660eb9e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"神经性贪食","category":"门诊病历模板","raw":{"name":"神经性贪食","category":"门诊病历模板","case":{"case_name":"门诊病历524","templates":{"主诉":"反复贪食伴呕吐1周","现病史":"患者1周前无明显诱因出现神经性贪食相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者反复贪食伴呕吐1周，伴轻度乏力，为评估反复呕吐所致代谢紊乱及营养状态，完善生化全项检查了解肝肾功能、电解质及代谢指标，重点排除低钾、低氯等电解质紊乱；查血常规排除感染、贫血所致乏力，完善凝血功能检查为必要时的有创操作及穿刺提供安全保障；查血糖排除低血糖及糖代谢异常所致进食行为改变，查血脂了解血脂水平并评估代谢综合征风险，完善同型半胱氨酸检查评估血管损伤及营养代谢状况；患者贪食发作需与颅内病变所致下丘脑摄食中枢功能异常鉴别，完善头颅CT/MRI检查明确有无颅内器质性病变；完善颈动脉超声、经颅多普勒检查了解颅内外血流情况，排除脑供血不足所致头晕乏力；完善心电图检查排除低钾所致心律失常及心肌缺血，查心脏超声排查心腔内栓子来源；因反复呕吐存在误吸及颅内感染风险，必要时行腰椎穿刺检查明确脑脊液情况；同时行心理测评量表评估进食行为，必要时请精神科、营养科会诊指导治疗。\n\n（检查清单）\n【必做检查】\n血常规、生化全项、凝血功能、血糖、血脂、同型半胱氨酸\n\n【影像学检查】\n头颅CT/MRI、颈动脉超声、经颅多普勒\n\n【其他检查】\n心电图、心脏超声（排查栓子来源）、腰椎穿刺（必要时）","初步诊断":"1. 神经性贪食\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 氟西汀胶囊20mg qd晨服，2-4周后疗效不足可加量至40-60mg qd（最大80mg/d），疗程3-6个月；为治疗神经性贪食的首选药物，可显著减少暴食及清除行为。\n2. 舍曲林片50mg qd晨服，2周后视疗效加量至100-150mg qd，疗程3-6个月；适用于不能耐受氟西汀者。\n3. 托吡酯片25mg qd起始，每周递增25mg，目标剂量100-200mg/d分2次口服；用于SSRI疗效不佳或伴明显冲动控制差者，注意监测血电解质及体重变化。\n4. 伴明显焦虑、抑郁或睡眠障碍者，可短期联合劳拉西泮0.5-1mg睡前口服（不超过2周）或阿普唑仑0.4mg tid，避免长期依赖。\n【一般治疗及生活指导】\n1. 规律三餐、定时定量，避免长时间空腹或过度节食诱发暴食；严禁催吐、导泻及滥用利尿剂/泻药，以防低钾血症、心律失常及代谢紊乱。\n2. 记录饮食日记（进食内容、量、诱因及情绪），识别并主动回避诱发暴食的情境、食物及压力事件。\n3. 坚持规律有氧运动（如快走、慢跑30分钟/次，每周3-5次），但禁止以过度运动作为清除体重的代偿手段；保证充足睡眠，避免熬夜。\n4. 注意口腔护理，餐后温水漱口（勿用牙刷刺激咽喉诱发呕吐），定期口腔科检查，防治牙釉质腐蚀及龋齿。\n【随诊要求】\n1. 急性期每1-2周复诊，评估暴食/清除行为频率、体重变化及情绪状态；病情稳定后每2-4周复诊1次。\n2. 每1-3个月复查血电解质（尤其血钾）、肝肾功能及心电图，警惕低钾血症所致心律失常；出现心慌、乏力、晕厥及时就诊。\n3. 疗程满3-6个月系统评估疗效，减药或停药医师指导下缓慢进行，禁止骤停；如出现明显抑郁、自伤观念或暴食频率急剧增加，需立即复诊或急诊处理。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":656,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0e075f5336b623348c06a6a075f00fcd179e6444de407bfd1d03798d8648314b","pinyin":"shenjingxingtanshi","initials":"sjxts","setting":"out","caseName":"门诊病历524","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历524",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5093d2804931b720c3a3","key":"v1-c9ccc21dfe2a3058|templates-5093d2804931b720c3a3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"睡眠障碍","category":"门诊病历模板","raw":{"name":"睡眠障碍","category":"门诊病历模板","case":{"case_name":"门诊病历525","templates":{"主诉":"入睡困难伴夜间易醒3月","现病史":"患者于3个月前出现睡眠问题：以失眠为主要表现，包括入睡困难（入睡潜伏期>30分钟）、睡眠维持困难（夜间易醒且再入睡困难）、早醒（比预期时间早醒，为抑郁的常见线索）、日间功能受损（疲劳、注意力下降、情绪差、嗜睡），频率≥3晚/周、持续≥3个月，符合慢性失眠。诱因包括应激及生活事件、焦虑抑郁（为最常见共病，早醒常提示抑郁，须评估，重要）、不良睡眠习惯（午后摄入咖啡因及浓茶、吸烟，饮酒后虽易入睡但可致早醒，睡前使用屏幕或手机，作息不规律或昼夜颠倒，白天睡眠过多）、躯体因素（疼痛、夜尿，与前列腺疾病或利尿药有关，心力衰竭可致端坐呼吸，甲亢、COPD夜间缺氧，不宁腿综合征、睡眠呼吸暂停）、药物因素（激素、支气管扩张剂、抗抑郁药激活作用）、倒班及跨时区旅行。需同时了解有无睡眠过多（嗜睡可见于嗜睡症，也见于睡眠呼吸暂停、发作性睡病或抑郁）、打鼾及呼吸暂停（提示阻塞性睡眠呼吸暂停，必要时行睡眠监测）、发作性睡病（白天不可抗拒的睡眠伴猝倒）、不宁腿（夜间下肢不适、活动后缓解）、夜惊、梦游、噩梦，以及情绪压力、作息、咖啡及酒精使用情况。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP120/76mmHg。BMI（肥胖提示阻塞性睡眠呼吸暂停）、口腔（扁桃体肥大提示阻塞性睡眠呼吸暂停）、颈围、心肺、下肢（水肿提示心力衰竭）、甲状腺、神经系统（不宁腿者可有感觉运动异常）、精神状态（情绪，行焦虑抑郁评估）、嗜睡程度（Epworth评分）。","辅助检查":"【必做】睡眠日记（记录2周，为核心项目，包括睡时、醒时、觉醒次数及日间功能）、失眠量表（PSQI）及Epworth嗜睡量表、抑郁焦虑量表（PHQ-9、GAD-7，用于共病筛查，重要）；【排除】甲状腺功能、血糖（低血糖可致夜醒）、铁蛋白（不宁腿）、多导睡眠图（疑阻塞性睡眠呼吸暂停、周期性肢体运动或发作性睡病时，必要时加做多次睡眠潜伏期试验）、动态监测（阻塞性睡眠呼吸暂停筛查）；【其他】基础疾病评估（心力衰竭、COPD、疼痛等，需相应处理）。","初步诊断":"1. 睡眠障碍（慢性失眠症，以入睡困难及睡眠维持困难为主，共病焦虑抑郁可能，伴日间功能受损）\n（注：治疗以失眠为重点，CBT-I为一线（睡眠卫生（规律作息、限制咖啡及酒精、睡前放松，卧室保持安静、黑暗、凉爽）、刺激控制（床仅用于睡眠，20分钟未入睡即起床，勿在床上清醒躺卧）、睡眠限制（减少卧床时间以提高睡眠效率）、认知重建（纠正对睡眠的灾难化认知）、放松训练），为核心措施，优于药物治疗）；药物治疗（短期使用：苯二氮䓬受体激动剂（唑吡坦、艾司佐匹克隆，短期<4周，防依赖，老年人防跌倒）、褪黑素受体激动剂（雷美替胺，适用于入睡困难）、食欲素受体拮抗剂（苏沃雷生）、抗抑郁药（曲唑酮、米氮平，低剂量用于共病抑郁或失眠者助眠）、褪黑素（适用于节律紊乱者）；勿自行长期使用苯二氮䓬类（可致依赖及戒断））；共病处理（抑郁者予抗抑郁治疗，失眠常随之改善；阻塞性睡眠呼吸暂停予CPAP；疼痛及夜尿者处理原发病）；老年患者以非药物措施优先，注意防跌倒；随访（记录睡眠日记，CBT-I疗程6~8周评估疗效，药物逐渐减停，防复发，长期坚持睡眠卫生）。）","处理方案":"【药物治疗】\n1.非苯二氮卓类镇静催眠药（首选）：唑吡坦片10mg，睡前口服qn，仅用于入睡困难者，疗程1-2周按需服用；或右佐匹克隆片2mg qn，疗程2-4周，不良反应较苯二氮卓类少。\n2.褪黑素受体激动剂：雷美替胺片8mg，睡前qn，适用于入睡困难及需长期维持用药者，无成瘾性。\n3.苯二氮卓类：艾司唑仑片1-2mg，睡前qn，用于入睡困难或维持睡眠，连用不超过4周，停药需逐渐减量，防反跳性失眠及药物依赖。\n4.伴焦虑抑郁情绪者：曲唑酮片25-50mg qn（从小剂量起始），或联合SSRI类（如艾司西酞普兰10mg qd晨服），需情绪症状同步治疗。\n\n【一般治疗及生活指导】\n1.睡眠卫生教育：固定作息，按时起床（节假日亦如此）；午睡不超过30分钟且不晚于15:00；睡前4-6小时避免咖啡、浓茶、酒精及吸烟。\n2.环境与行为（刺激控制法）：卧室保持安静、黑暗、室温18-22℃；仅在有睡意时上床，卧床约20分钟仍无法入睡即离床，待有睡意再回床；睡前1小时停止使用手机、电脑等电子产品。\n3.活动与放松：日间规律有氧运动（如快走30分钟/日），但睡前3小时避免剧烈运动；睡前可进行腹式呼吸或渐进性肌肉放松训练10-15分钟。\n4.禁忌：避免白天长时间卧床补觉；不自行长期服用市售或网购安眠药；服药后立即卧床、勿再起身活动，用药期间禁酒，防跌倒。\n\n【随诊要求】\n1.首次用药后1-2周复诊，评估疗效、日间功能及不良反应，必要时调整剂量或换药。\n2.连续用药者每2-4周复诊1次；苯二氮卓类总疗程不超过4周，减量停药医师指导下逐步进行，防反跳性失眠与依赖。\n3.若出现日间嗜睡、头晕、步态不稳、记忆减退或情绪异常加重，及时复诊；打鼾明显、肥胖或疑合并睡眠呼吸暂停者，建议完善多导睡眠监测（PSG）后复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":657,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"29d8dba13bf94cd951b50b8b8a684db00d2841acc66d72921fbe10f7b50369c9","pinyin":"shuimianzhangai","initials":"smza","setting":"out","caseName":"门诊病历525","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历525",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7af97eb4881c3d058145","key":"v1-c9ccc21dfe2a3058|templates-7af97eb4881c3d058145","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"嗜睡症","category":"门诊病历模板","raw":{"name":"嗜睡症","category":"门诊病历模板","case":{"case_name":"门诊病历526","templates":{"主诉":"日间过度困倦伴乏力1周","现病史":"患者1周前无明显诱因出现嗜睡症相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者日间过度困倦伴乏力1周，首先完善血常规检查排除感染、贫血所致乏力困倦；查尿常规、便常规排除泌尿系感染、消化道疾病等躯体因素；完善肝肾功能检查排除肝肾功能不全所致代谢性脑病，查血糖排除低血糖所致日间嗜睡，查血脂了解血脂水平并评估脑血管病危险因素，完善电解质检查排除低钠、低钾等电解质紊乱所致意识与精神状态异常；患者日间嗜睡需与甲状腺功能减退所致精神萎靡鉴别，完善甲状腺功能检查；完善心电图检查排除心律失常、心肌缺血所致脑供血不足，查胸部X线片排除肺部感染、睡眠呼吸暂停相关肺部改变，完善腹部超声了解腹部脏器情况；患者需排除颅内病变及发作性睡病，完善头颅CT或MRI检查明确有无颅内占位、脑血管病变；建议行多导睡眠监测明确睡眠结构及有无睡眠呼吸暂停，必要时行多次睡眠潜伏期试验；并完善Epworth嗜睡量表评估嗜睡程度，指导后续治疗方案。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 嗜睡症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中枢兴奋剂：莫达非尼（首选），成人常规剂量100mg晨起顿服，疗效不足时可增至200mg，每日1次，连用4周评估疗效；或哌甲酯缓释片18mg晨服，可增至36mg，每日1次。\n2. 伴猝倒者：文拉法辛缓释胶囊75mg每日1次晨服；或氯米帕明25mg每晚1次起始，视耐受情况调整。\n3. 夜间睡眠严重片段化者：可短期辅以右佐匹克隆1-3mg睡前服用，连用不超过2周，避免长期依赖。\n【一般治疗及生活指导】\n1. 保持规律作息，固定就寝及起床时间，保证成人夜间睡眠7-8小时，避免熬夜及昼夜颠倒；白天安排1次20-30分钟短时小睡（以午后为宜）以缓解困倦。\n2. 戒酒，避免或慎用镇静催眠药、抗组胺类抗过敏药、苯二氮䓬类等加重嗜睡的药物。\n3. 坚持适度有氧运动（如快走、慢跑，每日30分钟左右），避免久坐及长时间连续驾驶；睡前避免饮浓茶、咖啡及使用电子产品。\n4. 症状控制前避免从事驾车、高空作业、操作精密或危险机械等工作，必要时调整岗位，防止意外伤害。\n【随诊要求】\n用药后2-4周复诊，评估疗效及血压、心率、情绪等不良反应；症状改善稳定后每1-3个月复诊1次。若出现猝倒、睡眠瘫痪、入睡前幻觉，或日间嗜睡加重、伴打鼾及呼吸暂停，应及时复诊；必要时转诊神经内科或睡眠医学门诊，完善多导睡眠监测（PSG）及多次小睡潜伏期试验（MSLT）明确病因。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":658,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"610da0b12d40265f2477f1a78668f0c3f528b3edce96e7be8030b955f27815de","pinyin":"shishuizheng","initials":"ssz","setting":"out","caseName":"门诊病历526","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历526",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ba64ce91082094f23800","key":"v1-c9ccc21dfe2a3058|templates-ba64ce91082094f23800","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"性功能障碍","category":"门诊病历模板","raw":{"name":"性功能障碍","category":"门诊病历模板","case":{"case_name":"门诊病历527","templates":{"主诉":"勃起困难伴乏力1周","现病史":"患者1周前无明显诱因出现性功能障碍相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者勃起困难伴乏力1周，首先完善血常规检查排除感染、贫血所致乏力；完善肝肾功能检查排除肝肾功能不全，同时为后续药物治疗提供代谢基线，完善电解质检查排除电解质紊乱所致神经肌肉功能异常；患者勃起功能障碍常与内分泌及代谢异常相关，完善血糖、血脂检查排除糖尿病、血脂异常所致血管内皮损伤，完善性激素检查了解睾酮水平，完善甲状腺功能检查排除甲状腺功能异常所致性功能减退；完善心电图检查评估心脏情况，为必要时应用PDE5抑制剂提供安全依据；完善X线片、CT、MRI检查根据原发病选择相应部位，如腰骶椎MRI排除腰椎间盘突出、椎管狭窄所致神经源性勃起功能障碍，头颅MRI排除垂体及颅内病变；完善阴茎海绵体多普勒超声了解阴茎血流及血管性病因，行肌电图检查评估盆底及阴部神经传导功能；完善康复评定量表（Fugl-Meyer、Barthel指数、Berg平衡量表等）评估肢体运动、日常生活能力及平衡功能，指导康复方案制定。\n\n（检查清单）\n【必做检查】\n血常规、肝肾功能、电解质\n\n【影像学检查】\nX线片、CT、MRI（根据原发病）\n\n【其他检查】\n康复评定量表（Fugl-Meyer、Barthel指数、Berg平衡量表等）、肌电图","初步诊断":"1. 性功能障碍\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 首选PDE5抑制剂：西地那非片50mg，性生活前约1小时按需口服，每日最多1次；或他达拉非片10mg按需口服（每日最多1次），亦可他达拉非5mg每日1次规律服药。\n2. 若合并早泄：盐酸达泊西汀片30mg，性生活前1~3小时按需口服，24小时内最多1次。\n3. 若血清总睾酮低下（<10.4nmol/L）：十一酸睾酮胶丸80mg bid随餐口服，疗程3~6个月后评估疗效。\n\n【一般治疗及生活指导】\n1. 生活方式干预：规律作息、保证充足睡眠，每周≥150分钟中等强度有氧运动（快走、游泳等），控制体重，避免久坐。\n2. 戒烟限酒，减少高脂高糖饮食，均衡营养，适当增加富含锌及优质蛋白食物（瘦肉、鱼类、坚果等）。\n3. 心理及行为指导：与伴侣充分沟通，减轻性焦虑；配合盆底肌训练（凯格尔运动），每日2~3组。\n4. 基础疾病管理：严格控制血压、血糖、血脂；必要时在医师指导下调整可能影响性功能的降压药（如β受体阻滞剂、噻嗪类利尿剂）。\n\n【随诊要求】\n1. 用药后2~4周复诊，评估勃起功能改善（IIEF-5评分）及药物耐受性；规律用药者每3个月复评1次。\n2. 定期复查性激素六项、空腹血糖、血脂、肝肾功能及前列腺特异性抗原（PSA）。\n3. 若出现持续胸痛、心悸等心血管症状，或连续2次按需用药无效，及时复诊调整治疗方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":659,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bf3431d24553c788225de522f1ed11fb21031c445b9a240d83975f4cabd90533","pinyin":"xinggongnengzhangai","initials":"xgnza","setting":"out","caseName":"门诊病历527","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历527",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2d00ae154f11cb8d27f4","key":"v1-c9ccc21dfe2a3058|templates-2d00ae154f11cb8d27f4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"性欲减退","category":"门诊病历模板","raw":{"name":"性欲减退","category":"门诊病历模板","case":{"case_name":"门诊病历528","templates":{"主诉":"缺乏性兴趣伴乏力1周","现病史":"患者1周前无明显诱因出现性欲减退相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者缺乏性兴趣伴乏力1周，首先完善血常规检查排除感染、贫血所致乏力；查尿常规、便常规排除泌尿系感染、消化道疾病等慢性消耗性疾病；完善肝肾功能检查排除肝肾功能不全所致内分泌及代谢紊乱，查血糖排除糖尿病所致血管神经病变，查血脂了解血脂水平并评估动脉硬化风险，完善电解质检查排除电解质紊乱所致全身乏力；患者性欲减退常与内分泌功能异常相关，完善性激素检查了解睾酮、雌二醇及促性腺激素水平，完善甲状腺功能检查排除甲减所致性欲下降及情绪低落；完善心电图检查排除心律失常、心肌缺血，查胸部X线片排除肺部感染及占位，完善腹部超声了解腹部脏器情况，重点排除肾上腺、盆腔器质性病变；患者需与抑郁障碍所致性欲减退鉴别，可行心理测评量表评估情绪状态；必要时完善头颅MRI检查排除垂体病变所致性腺功能减退，综合结果明确病因后指导治疗。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 性欲减退\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 睾酮替代治疗：十一酸睾酮胶丸40mg po bid，餐后服，疗程3～6个月，适用于确诊性腺功能减退或血清睾酮低下者；治疗期间监测血清睾酮水平及血常规（红细胞压积），女性需在妇科/内分泌科指导下小剂量使用。\n2. 氟班色林片100mg po qn（睡前服），适用于绝经前女性性欲减退，疗程至少8周评估疗效，无效则停用；用药期间禁酒。\n3. 溴隐亭片1.25mg po bid起始，每2周递增至2.5mg bid，疗程视血清泌乳素水平恢复情况而定，适用于高泌乳素血症所致性欲减退。\n4. 安非他酮缓释片150mg po qd（晨服），疗程4～8周，适用于抑郁情绪相关性欲减退者（对性功能影响较小，不宜与SSRI联用者慎用）。\n【一般治疗及生活指导】\n1. 心理疏导与夫妻同治：接受性心理/性教育咨询，减轻焦虑与压力，加强伴侣间沟通与情感交流，纠正错误性观念。\n2. 规律作息，保证每晚7～8小时睡眠，避免熬夜、过度劳累及久坐，坚持每周≥150分钟中等强度有氧运动（如快走、游泳、骑行）。\n3. 均衡营养、戒烟限酒、控制体重，避免滥用镇静催眠药及对性功能有影响的药物（如β受体阻滞剂、噻嗪类利尿剂、部分抗抑郁药等）。\n4. 积极治疗原发病：控制糖尿病、高血压，规范治疗甲状腺功能减退、慢性肾病、贫血及营养不良等基础疾病。\n【随诊要求】\n用药后2～4周复诊，评估性欲改善程度及药物不良反应；睾酮治疗者每1～3个月监测血清睾酮、红细胞压积及肝功能，男性加测血清PSA；溴隐亭治疗者定期复查泌乳素并监测血压；氟班色林治疗者疗程满8周必须复诊判定疗效，无效即停药调整方案；症状持续不缓解、加重或出现明显不良反应时随时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":660,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"711589bec3a28446791d981e72347cc8180bff63ee29215aa91f443a5fa30322","pinyin":"xingyujiantui","initials":"xyjt","setting":"out","caseName":"门诊病历528","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历528",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-926af389130e6ad33bf5","key":"v1-c9ccc21dfe2a3058|templates-926af389130e6ad33bf5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"早泄","category":"门诊病历模板","raw":{"name":"早泄","category":"门诊病历模板","case":{"case_name":"门诊病历529","templates":{"主诉":"射精过快6月","现病史":"患者于半年前出现：射精潜伏期短（插入后<1分钟，属原发性即终生性）、缺乏射精控制感、伴明显痛苦及人际困扰。分型：原发性（从首次性交即存在，终生性，多与神经生理及遗传因素、射精阈值低相关）。诱因及心理因素（焦虑，尤其是表现焦虑形成恶性循环，较为常见；关系冲突、压力、性经验少）、共病（勃起功能障碍，治疗勃起功能障碍可改善早泄，重要；焦虑抑郁）、药物（抗抑郁药SSRI可推迟射精，需评估用药史）、内分泌（甲亢可致早泄，需筛查）、前列腺炎（可有下尿路症状）、物质（戒断或使用）、性频率。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP118/74mmHg。外生殖器（包皮及龟头，注意包茎及龟头炎；阴茎、睾丸）、前列腺（直肠指诊，注意前列腺炎）、第二性征、神经（会阴感觉，异常少见）、甲状腺。","辅助检查":"【必做】性功能评估（自报阴道内射精潜伏期、诊断性访谈以明确分型）；【排除】甲状腺功能（甲亢可致早泄，重要）、血糖（糖尿病神经病变可致勃起功能障碍及早泄）、性激素（睾酮降低可致性欲下降及勃起功能障碍）、前列腺液（前列腺炎可有尿路症状）、抑郁焦虑量表（共病筛查）、勃起功能IIEF评分（共病勃起功能障碍评估）。","初步诊断":"1. 早泄（原发性即终生性；阴道内射精潜伏期<1分钟；控制感差并伴明显痛苦；需评估共病（勃起功能障碍、焦虑抑郁、甲亢、前列腺炎））\n（注：治疗以行为治疗联合药物为主，并按分型处理：行为治疗（动-停技术、挤捏技术以提高射精阈值、延长射精时间；性技巧训练以分散注意力）、心理治疗（针对表现焦虑行认知行为治疗及认知重建）、药物（达泊西汀，属SSRI，按需30~60mg，性交前1~3小时服用，为一线用药，已批准用于早泄，可延迟射精；SSRI长期方案（帕罗西汀，每日服用，可延迟射精，注意性欲下降等副作用）、局部麻醉（利多卡因乳膏或喷剂，降低龟头敏感度以延迟射精，注意会影响女方感觉，性交前使用后需洗去））、共病处理（勃起功能障碍者先治勃起功能障碍，用PDE5抑制剂，改善后早泄多随之改善；甲亢者治疗甲亢；前列腺炎者抗炎治疗）、心理支持（进行教育，说明正常变异性，降低焦虑）；随访（评估阴道内射精潜伏期及控制感、疗效，据情调整用药，注意停药后复发并制定维持策略）。）","处理方案":"【药物治疗】\n1. 盐酸达泊西汀片30mg，性生活前1~3小时口服，按需服用，24小时内最多1次；若疗效欠佳可遵医嘱增至60mg。4周（约8次）为1个疗程，首诊以30mg起始。\n2. 复方利多卡因乳膏（利多卡因+丙胺卡因）：性生活前15~30分钟取少量均匀涂于龟头、冠状沟及系带处，轻轻按摩，性交前将残留药膏洗净，以降低龟头敏感性、延长射精潜伏期。\n3. 若合并勃起功能障碍：西地那非片50mg或他达拉非片10mg，性生活前30~60分钟口服，每日最多1次，需先评估心血管风险。\n4. 若伴明显焦虑或上述方案效果不佳：舍曲林片50mg qd口服，连用4~8周（属超说明书用药，需充分知情同意），注意胃肠道反应及嗜睡、乏力等不良反应。\n【一般治疗及生活指导】\n1. 心理疏导与性教育：正确认识早泄，解除焦虑紧张情绪，鼓励夫妻同治；进行认知行为训练（动-停技术、挤捏技术）及盆底肌训练（凯格尔运动），提高射精控制能力。\n2. 规律作息，避免熬夜、过度劳累及久坐，坚持适度有氧运动（快走、游泳、慢跑），保持良好体能和情绪状态。\n3. 戒烟限酒，避免辛辣刺激性食物及浓茶、咖啡过量摄入；保持规律适度的性生活，避免频繁手淫或长期禁欲后仓促性交。\n4. 加强伴侣沟通与配合，营造轻松和谐的性生活氛围，不以射精时间作为唯一评价指标。\n【随诊要求】\n1. 用药4周后门诊复诊，评估疗效（射精潜伏期IELT、早泄诊断工具PEDT评分）及不良反应（恶心、头晕、腹泻、嗜睡等），必要时调整剂量或更换方案。\n2. 每日服药者每月复诊1次，监测耐受性及性功能变化；若出现晕厥、体位性低血压、皮疹等严重不良反应，立即停药并急诊就诊。\n3. 复诊时评估是否合并勃起功能障碍、慢性前列腺炎等基础疾病，必要时联合相应治疗；症状稳定3个月后可根据患者具体情况制定个体化方案减量或停药观察，避免突然停药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":661,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"aa2409e01e189e9699947cd3bd2b638bc29b95c236a35bfd5de9f04844b0c67f","pinyin":"zaoxie","initials":"zx","setting":"out","caseName":"门诊病历529","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历529",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4a6c3fa15543aa6385d3","key":"v1-c9ccc21dfe2a3058|templates-4a6c3fa15543aa6385d3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"性高潮障碍","category":"门诊病历模板","raw":{"name":"性高潮障碍","category":"门诊病历模板","case":{"case_name":"门诊病历530","templates":{"主诉":"难以达到性高潮1周","现病史":"患者1周前无明显诱因出现性高潮障碍相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者难以达到性高潮1周，首先完善血常规检查排除感染、贫血所致乏力及全身状态下降；查尿常规、便常规排除泌尿系感染、消化道疾病等躯体因素；完善肝肾功能检查排除肝肾功能不全所致内分泌代谢异常，并为他日用药提供基线；查血糖排除糖尿病所致周围神经及血管病变影响性反应，查血脂了解血脂水平并评估血管内皮功能，完善电解质检查排除电解质紊乱所致神经肌肉传导异常；患者性高潮障碍需与内分泌功能减退鉴别，完善性激素检查了解睾酮等性激素水平，完善甲状腺功能检查排除甲状腺功能异常；完善心电图检查评估心血管情况，查胸部X线片排除肺部感染及占位，完善腹部超声了解腹部脏器及盆腔情况；完善盆底肌电图检查评估阴部神经及盆底肌功能，排除神经源性因素；患者需与抑郁障碍、焦虑障碍及药物因素所致性功能障碍鉴别，行心理测评量表评估情绪与性功能状态，必要时请妇科或男科、心理科会诊制定治疗方案。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 性高潮障碍\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 安非他酮缓释片（悦亭）150mg，每日1次，晨起口服，疗程4～8周：为性高潮障碍（含抗抑郁药SSRI所致者）的一线尝试药物，可改善性唤起与性高潮功能，起效后维持治疗并按疗效复评。\n2. 替勃龙片（利维爱）2.5mg，每日1次口服，疗程3～6个月：适用于绝经后女性伴性欲减退及性高潮障碍者，需排除乳腺、子宫等雌激素依赖性病变后使用，用药期间定期复评。\n3. 雌三醇软膏（欧维婷）0.5～1g，每晚睡前阴道内涂布，连用2周后改为每周1～2次维持：用于伴阴道萎缩干涩、性交不适者，改善局部条件以利于性高潮获得；活动性阴道出血、雌激素依赖肿瘤者禁用。\n\n【一般治疗及生活指导】\n1. 行为与心理治疗为核心：建议进行盆底肌训练（凯格尔运动，每日3组、每组10～15次收缩，每次收缩持续5～10秒）、性感集中训练及自我刺激练习，每周至少3次；同时加强伴侣沟通，双方共同参与治疗。\n2. 规律作息与运动：保证每晚7～8小时睡眠，避免熬夜及长期精神紧张；坚持每周≥150分钟中等强度有氧运动（快走、游泳、瑜伽等）；戒烟限酒，避免在过度疲劳或压力大时安排性生活。\n3. 药物与饮食注意：避免自行使用抑制性欲或影响性功能的药物（如部分降压药、镇静催眠药、H2受体拮抗剂等），必要时在医师指导下调整原用药；均衡饮食，适当增加富含锌、维生素B族及优质蛋白的食物，控制高脂高糖摄入。\n\n【随诊要求】\n1. 用药4周后复诊，评估疗效及不良反应（恶心、失眠、情绪波动、体重变化、阴道异常出血等），复查女性性功能指数（FSFI）评分；\n2. 替勃龙等激素相关治疗者每3～6个月复查乳腺超声、妇科超声及肝功能；绝经前女性如出现月经紊乱及时就诊；\n3. 疗效不佳或症状加重者，转诊妇科、心理科/性医学专科联合评估，必要时调整治疗方案；治疗期间如出现胸痛、头痛、情绪低落加重等及时就医。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":662,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"83bb0b0d54479945a67f2b1af69a37f29fe10c64d1ec382087202a5216e731e7","pinyin":"xinggaochaozhangai","initials":"xgcza","setting":"out","caseName":"门诊病历530","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历530",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-44476b60c5cd1c760496","key":"v1-c9ccc21dfe2a3058|templates-44476b60c5cd1c760496","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"儿童孤独症","category":"门诊病历模板","raw":{"name":"儿童孤独症","category":"门诊病历模板","case":{"case_name":"门诊病历531","templates":{"主诉":"社交障碍伴言语发育落后1周","现病史":"患者1周前无明显诱因出现儿童孤独症相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"患儿系第1胎第1产，足月顺产，出生体重3.2kg，无窒息抢救史。母乳喂养，按时添加辅食，预防接种按国家计划进行。生长发育同同龄儿童。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 100/65 mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患儿以社交障碍伴言语发育落后为主要表现，病程1周且呈进行性加重，查血常规了解有无贫血、感染等影响神经系统发育的基础疾病；查CRP、降钙素原排除细菌感染及全身炎症性疾病所致的行为倒退，因感染后免疫激活可导致发育倒退，需与孤独症退行型鉴别；查尿常规排除泌尿系感染、尿路畸形及代谢异常，查便常规排除肠道寄生虫感染及慢性腹泻所致营养吸收障碍，因肠道菌群与营养状态同神经发育密切相关；患儿伴轻度乏力，查心肌酶谱排除心肌损伤及心肌炎所致的精神行为异常，查电解质排除低钠、低钙等电解质紊乱引起的乏力和行为改变，查血糖排除低血糖发作所致注意力不集中与情绪行为异常；患儿起病隐匿，查病原学检测明确有无巨细胞病毒、弓形虫、梅毒螺旋体等先天性或慢性感染，上述病原感染是儿童发育落后与行为异常的重要可治性病因，需重点排除；查胸部X线片排除肺结核、肺部感染等慢性疾病；查腹部超声排除腹部占位、肝脾肿大及肠套叠等器质性病变；因孤独症无特异性实验室指标，诊断以行为评估为核心，故上述检查的意义在于排除听力障碍、铅中毒、甲状腺功能减退、遗传代谢病等可治性病因，并须完善听力评估、脑电图及发育量表评定以明确共患癫痫与发育水平，必要时请儿童保健科、神经内科及精神科会诊协诊。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原、尿常规、便常规\n\n【影像学检查】\n胸部X线片、腹部超声\n\n【其他检查】\n心肌酶谱、电解质、血糖、病原学检测","初步诊断":"1. 儿童孤独症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 利培酮口服溶液/片（如维思通）：孤独症伴易激惹、攻击冲动、自伤等行为症状的首选治疗药物。起始剂量0.25mg，每日2次口服；每1～2周根据疗效与耐受性递增0.25mg，常规维持量0.5～1.5mg/日，分2次服用，每日总量一般不超过2mg；连续用药3～6个月后评估疗效，症状稳定后维持巩固，减量或停药需在医师指导下缓慢进行，不可骤停。用药期间每1～3个月监测体重、身高、血糖、血脂、催乳素水平及锥体外系反应。\n2. 阿立哌唑片（如安律凡）：用于利培酮疗效不佳或不能耐受者的替代治疗，改善易激惹与攻击行为。起始剂量2mg，每日1次口服；每1～2周加量2mg，常规有效剂量5～10mg/日，每日1次顿服；疗程3～6个月，定期评估疗效及静坐不能、嗜睡、体重增加等不良反应。\n3. 托莫西汀胶囊：用于合并注意缺陷多动障碍（ADHD）症状者，改善注意缺陷与冲动。起始剂量0.5mg/(kg·d)，早餐后顿服或分2次口服，1周后渐增至1.2mg/(kg·d)，单日总量不超过1.4mg/kg或100mg；连续服用至少4～8周后评估疗效。用药期间监测心率、血压、食欲及肝功能。\n4. 褪黑素：用于合并睡眠障碍（入睡困难、睡眠维持差）者，睡前30～60分钟口服3～6mg，连续使用2～4周评估疗效；需在医师指导下根据年龄与反应调整剂量，不可与中枢镇静药物随意联用。\n\n【一般治疗及生活指导】\n1. 核心治疗为行为与教育干预：尽早并长期坚持患者行为分析（ABA）、结构化教学（TEACCH）、社交技能训练及言语、作业、感觉统合等综合康复训练，每日训练不少于3小时、每周累计不少于20小时；家长须参加系统培训，将训练融入日常生活，营造结构化、可预测的居家环境，减少患儿因环境突变产生的焦虑与行为问题。\n2. 亲子互动与沟通：多进行面对面目光交流、游戏互动及绘本共读，对患儿的任何交流尝试（目光、手势、发音、指认）即时给予积极回应，避免呵斥、体罚与冷处理；将日常洗漱、进食、穿衣等生活环节作为训练契机，逐步引导患儿表达需求并强化正向行为。\n3. 饮食与生活作息：均衡营养、规律三餐，少食含人工色素、高糖及过度加工食品，观察有无食物不耐受或过敏表现；保证规律作息与充足睡眠，睡前1小时避免剧烈活动及屏幕暴露（2岁以下避免使用电子屏幕，2岁以上每日累计不超过1小时）。\n4. 安全防护与户外活动：加强家庭环境安全管理，做好防走失、防自伤、防意外伤害措施；每日安排适当户外活动与感觉统合训练，增强体质；规律接种疫苗、注意手卫生，预防呼吸道感染；尽量维持稳定的日程安排，需改变时提前告知并辅以图片或手势提示。\n\n【随诊要求】\n1. 服用利培酮、阿立哌唑、托莫西汀等药物者每1～3个月复诊1次，评估疗效与不良反应，监测体重、身高、血糖、血脂、催乳素及锥体外系症状，并定期复查血常规、肝肾功能；服药期间出现抽搐、频繁呕吐、意识改变或静坐不能、肌张力异常等应及时就诊。\n2. 每3～6个月复评行为症状、睡眠及进食情况，动态调整药物剂量与康复训练方案，不可自行增减或停用药物。\n3. 每6～12个月行孤独症相关发育评估（如CARS、ADOS、ABC量表）及智力、适应行为评估，客观评价训练效果并及时调整干预目标与康复计划。\n4. 学龄前至学龄期做好与幼儿园、学校的沟通衔接，落实融合教育或特教支持；家长培训及家庭干预督导建议每1～3个月开展1次，持续监测患儿社交、语言及生活自理能力改善情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":663,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f8c66e24aa03313aa25b28e6e9ffaab1dbc5774cd582049dda4e59623bf9e402","pinyin":"ertongguduzheng","initials":"etgdz","setting":"out","caseName":"门诊病历531","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历531",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-898d895d5aec874712ae","key":"v1-c9ccc21dfe2a3058|templates-898d895d5aec874712ae","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"注意缺陷多动障碍","category":"门诊病历模板","raw":{"name":"注意缺陷多动障碍","category":"门诊病历模板","case":{"case_name":"门诊病历532","templates":{"主诉":"注意力不集中伴多动6月","现病史":"患儿于学龄期（<12岁起病，常于学龄期诊断）出现：注意力不集中（上课走神、作业马虎粗心出错、丢三落四、听讲困难即听而不闻、难以组织任务、易分心）、多动（坐不住、身体扭动、小动作多、话多、不能安静玩耍、跑跳攀爬）、冲动（插嘴、抢答、难以等待轮流、干扰他人、不顾危险）。分型为混合型（注意缺陷为主型、多动冲动为主型或混合型）。诊断要点：起病<12岁、症状存在于≥2种场合（学校及家庭）、伴功能损害（学业下降甚至留级、社交方面同伴排斥、亲子冲突及家庭压力）、共病（对立违抗或品行障碍、学习障碍（阅读及计算）、焦虑抑郁、抽动障碍、睡眠问题）；成人ADHD可表现为注意缺陷持续、组织及时间管理差、冲动，影响职业及人际，多数由儿童期延续而来，易漏诊，须评估；智力正常（与发育迟滞相区别，需行韦氏智力评估）；家族史（ADHD有明显遗传倾向，须筛查父母，重要）；孕期及围产期因素（早产、低出生体重、母亲吸烟饮酒）；评估采用行为量表（Conners、SNAP，父母及教师问卷，重要）。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P88次/分，R20次/分，BP100/64mmHg。一般发育、神经系统（软体征，协调笨拙，多为非特异性）、视力及听力（须排除视力听力障碍所致注意力差，重要）、多动观察（会谈过程中坐不住）、生长发育。","辅助检查":"【必做】行为量表（Conners、SNAP-Ⅳ、Vanderbilt，父母及教师填写，为核心，需多场合评估）、发育及智力评估（韦氏，排除智力障碍并评估学习能力）、ADHD诊断访谈（按DSM-5，评估症状、场合及功能）；【共病】学习障碍（评估学业及阅读、数学能力）、抽动及焦虑抑郁量表（共病筛查，重要）、睡眠评估；【排除】甲状腺功能（甲亢可致多动）、贫血及缺铁、血铅、癫痫（失神发作可表现为注意力问题，疑及时行脑电图）、听力视力、药物因素、睡眠不足。","初步诊断":"1. 注意缺陷多动障碍（ADHD，混合型；起病<12岁，多场合存在功能损害；需评估共病（对立违抗、学习障碍、焦虑）并行成人ADHD筛查）\n（注：治疗以综合干预为主，6岁以下以行为干预为主，6岁以上采用药物联合行为治疗：行为干预及家长培训（正面强化、结构化常规、及时表扬、自然后果，家长管理培训为核心，重要）、教育支持（学校调整，如安排前排座位、任务分解）、药物治疗（6岁以上中重度者：一线为哌甲酯缓释剂（中枢兴奋剂，首选，改善注意、多动及冲动，疗效好）、托莫西汀（非兴奋剂，选择性去甲肾上腺素再摄取抑制剂，适用于合并抽动或焦虑者，无滥用风险，起效慢，2~4周）、可乐定（用于共病抽动或睡眠问题，为辅助用药）；剂量个体化，监测食欲下降、体重及生长、失眠及心血管指标（血压、心率））；共病治疗（对立违抗行家长培训、学习障碍行特殊教育、焦虑予SSRI或CBT）；随访（用量表评估疗效，调整药物，每3~6个月监测身高体重，定期监测血压心率）；成人ADHD予药物（长效哌甲酯或托莫西汀）及心理干预（组织与时间管理训练）与支持。））","处理方案":"【药物治疗】\n1. 盐酸哌甲酯缓释片（专注达）18mg qd 晨起口服，根据疗效与耐受性每1-2周递增剂量，成人常规剂量18-54mg qd，每日晨服1次，避免下午及晚间服药以免影响睡眠；疗程一般3-6个月后行疗效评估，用药期间监测血压、心率及食欲。\n2. 盐酸托莫西汀胶囊 40mg qd 晨服或分早晚两次口服，1-2周后可增至80mg qd，最大日剂量100mg；需连续用药4-6周方显效，坚持8-12周评估疗效，适用于伴焦虑或对兴奋剂不耐受者，服药期间注意监测心率与血压。\n3. 若合并明显焦虑、抑郁情绪：舍曲林片 50mg qd 晨服，与上述药物联用，2-4周起效，持续8-12周评估情绪及注意力改善情况。\n【一般治疗及生活指导】\n1. 行为与认知心理治疗：接受认知行为治疗或执行功能训练（如时间管理、任务分解、清单化安排），改善冲动与组织能力，药物治疗与心理干预联合效果最佳。\n2. 保持规律作息：固定起床与就寝时间，保证每晚7-8小时睡眠，避免熬夜与睡前使用电子产品；睡眠不足可显著加重注意力及冲动症状。\n3. 规律有氧运动：每周至少150分钟中等强度运动（如快走、慢跑、游泳、球类），有助于改善注意集中与冲动控制；避免饮酒，限制咖啡、浓茶等含咖啡因饮品，尤其午后禁饮以免加重睡眠问题。\n4. 注意安全：服药初期或剂量调整期注意力波动，避免酒后驾驶、疲劳驾驶及高风险操作；工作学习环境尽量减少干扰源（远离手机、安静区域、单任务作业）。\n【随诊要求】\n1. 剂量调整期每2-4周复诊1次，评估疗效与不良反应（食欲下降、失眠、心悸、血压升高、口干），监测血压、心率及体重。\n2. 每3个月复诊评估症状量表（成人ADHD自评量表ASRS或ADHD症状评定量表）及功能改善情况，据评分调整维持方案。\n3. 长期用药者每年复查心电图、肝肾功能与血压；用药期间出现心悸、胸闷、胸痛、晕厥或情绪恶化时立即就诊，不可自行增减或骤停药物。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":664,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"95e0d98b7d79b5a0447fa484e172433dadd79c12af677b671007781c88bf4d12","pinyin":"zhuyiquexianduodongzhangai","initials":"zyqxddza","setting":"out","caseName":"门诊病历532","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历532",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4d8a13c1cae97e23d41c","key":"v1-c9ccc21dfe2a3058|templates-4d8a13c1cae97e23d41c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"抽动障碍","category":"门诊病历模板","raw":{"name":"抽动障碍","category":"门诊病历模板","case":{"case_name":"门诊病历533","templates":{"主诉":"不自主眨眼、清嗓3月","现病史":"患儿于学龄前期（4~7岁起病多见，男孩较多）出现：运动抽动（简单抽动如眨眼，为最常见首发症状，另有皱眉、耸鼻、咧嘴、摇头、耸肩、清嗓；复杂抽动如触摸、蹦跳、模仿动作）、发声抽动（简单发声如清嗓、吸鼻、咕噜声、犬吠样；复杂发声如词句，秽语约见于10%的患者，属Tourette综合征表现）。分型：Tourette综合征（运动抽动与发声抽动均持续>1年，多在18岁前起病）、慢性运动或发声抽动障碍（单一类型持续>1年）、短暂抽动障碍（<1年，最常见，多自限）。抽动具有波动性，时好时坏，应激、疲劳、兴奋及感染时加重，专注或睡眠时减轻；抽动前多有前驱冲动（局部不适感，抽动后可缓解），可短暂抑制。共病包括ADHD（最常见，约50%，即注意缺陷多动障碍）、强迫症（强迫观念及行为）、焦虑抑郁、睡眠障碍、自伤。需评估功能影响（社交方面被嘲笑、学习方面课堂受影响、家庭影响）、既往用药（抗精神病药，须评估）、家族史（抽动有遗传倾向，家族史重要）；多数患者成年后抽动减轻，青春期后部分可完全消失。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P90次/分，R20次/分，BP100/64mmHg。观察（会谈中观察抽动的种类及频率并记录、评估可否短暂抑制）、神经系统（除外舞蹈症（风湿性，表现为不自主动作）、肌阵挛、癫痫及药物反应（抗精神病药所致迟发性运动障碍））、发声（清嗓需与咽喉炎区别）、共病观察（多动，注意ADHD）、锥体外系检查（排除其他原因）。","辅助检查":"【必做】临床观察及访谈（诊断以观察和病史为主；采用YGTSS耶鲁抽动严重程度量表评估严重度并随访）；【共病】ADHD量表、强迫量表、焦虑抑郁量表（筛查，重要）；【排除】抗链球菌溶血素O（ASO，用于评估链球菌感染相关性自身免疫性神经精神障碍，该病骤发起病、多见于儿童、较为少见，需评估）、甲状腺功能、脑电图（疑癫痫时）、头颅MRI（有神经体征时，除外基底节病变，不作常规检查）。","初步诊断":"1. 抽动障碍（短暂性（病程<1年）；需明确运动及发声抽动类型、严重度（YGTSS）、共病（ADHD、强迫症）及功能影响评估）\n（注：治疗上轻中度以观察及心理干预为主，重度方用药：心理教育（告知本病多为良性、多数可减轻，勿惩罚、勿过度关注，因关注可强化抽动）、习惯逆转训练（HRT，识别前驱冲动并训练替代反应，为核心行为治疗，有效）、共病处理（ADHD需治疗，注意中枢兴奋剂可加重抽动，宜选托莫西汀或可乐定；强迫症予SSRI联合CBT）、药物（中重度且影响功能者：一线为α2受体激动剂（可乐定、胍法辛，可减轻抽动并兼治ADHD，从小剂量起始）、抗精神病药（氟哌啶醇、阿立哌唑，作用强效，但可有锥体外系及代谢副作用，为二线，用于中重度者））、随访（用YGTSS评估疗效并调整药物，监测副作用；青春期后抽动多减轻，药物逐渐减量，勿骤停；成人持续者继续药物及心理支持；社交方面予心理支持，开展学校宣教，帮助老师同学理解，重要）。）","处理方案":"【药物治疗】\n1. 盐酸可乐定片（α2受体激动剂，一线首选）：成人起始剂量0.05mg bid，每3~5天递增0.025~0.05mg，常用维持量0.1~0.2mg/d分2~3次口服，最大日剂量不超过0.4mg；服药前及加量期间监测血压、心率，停药须缓慢减量，避免骤然停药致反跳。\n2. 盐酸硫必利片（多巴胺D2受体阻滞剂）：成人起始0.05g bid，每3~5天渐增至0.1g bid~tid，常用剂量0.2~0.3g/d分2~3次口服；注意嗜睡、乏力、头晕等不良反应，不与中枢抑制药合用，用药期间监测肝功能。\n3. 阿立哌唑片（D2受体部分激动剂，疗效不佳或副作用不耐受时选用）：成人起始5mg qd早餐后口服，每2~4周据疗效及耐受性加量5mg，常用维持量10~15mg/d，最大不超过30mg/d；注意静坐不能、体重增加等不良反应。\n\n【一般治疗及生活指导】\n1. 保证规律作息，避免熬夜、过度疲劳及长时间使用电子产品、观看视频，睡眠不足和疲劳可诱发或加重抽动。\n2. 均衡饮食，避免浓茶、咖啡、可乐、功能性饮料等含咖啡因饮品及辛辣刺激、过甜食物；不需特殊忌口，不主张盲目忌口或服用保健品。\n3. 适当参加慢跑、游泳、球类等有氧运动，避免精神紧张、过度兴奋及竞技性应激；患者及家属应正确认识本病，避免责备、训斥或过度关注抽动动作，减少心理压力。\n4. 注意保暖预防感冒、咽喉部感染等诱发因素，保持情绪稳定，合理安排学习与工作强度。\n\n【随诊要求】\n用药后2~4周复诊评估疗效及不良反应（血压、心率、嗜睡、体重、肝功能等）并调整剂量；症状控制稳定后每1~3个月定期复诊。症状明显缓解后可遵医嘱逐步减量维持治疗3~6个月以上，停药医师指导下缓慢减量，不可骤停。若出现抽动明显加重、新发运动障碍、意识改变或药物不良反应，应及时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":665,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f9b74dcde983607f98bf0b13f57a1f0dbd4c1eeaac36c44982a2f5f2b1549804","pinyin":"choudongzhangai","initials":"cdza","setting":"out","caseName":"门诊病历533","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历533",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-38c5ca5380727611a4c1","key":"v1-c9ccc21dfe2a3058|templates-38c5ca5380727611a4c1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"品行障碍","category":"门诊病历模板","raw":{"name":"品行障碍","category":"门诊病历模板","case":{"case_name":"门诊病历534","templates":{"主诉":"攻击行为伴逃学1周","现病史":"患者1周前无明显诱因出现品行障碍相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患儿以攻击行为伴逃学为主要表现，首诊须先排除器质性与物质相关病因，查血常规排除贫血、感染及慢性疾病所致情绪行为异常；查尿常规排除泌尿系感染及尿液毒品筛查所需的代谢异常，为有无精神活性物质滥用的鉴别提供依据；查便常规排除肠道寄生虫感染及慢性消化系统疾病；患儿如采用药物干预，多数精神科用药需经肝脏代谢、肾脏排泄，查肝肾功能排除肝肾功能不全，指导用药选择与剂量调整；查血糖排除低血糖或糖代谢异常所致易激惹与冲动行为；查血脂了解血脂水平，评估代谢状态并指导后续用药监测；查电解质排除低钠、低钾、低钙等电解质紊乱所致情绪不稳与冲动行为；查心电图排除心律失常及QT间期延长，为后续选用精神科药物提供安全基线；查胸部X线片排除肺结核及肺部感染，查腹部超声排除腹部器质性病变及肝脾异常；因品行障碍的诊断须在排除躯体疾病、物质滥用及心境障碍的基础上建立，故根据病情需要选择相应检查，必要时加做甲状腺功能、头颅MRI及脑电图以明确有无中枢神经系统病变，并完善智力测验、注意力评估及家庭社会因素评定，必要时请精神科、心理科会诊协诊以明确诊断。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 品行障碍\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 控制冲动攻击行为（首选第二代抗精神病药）：利培酮片起始0.5mg qn，据疗效及耐受性每3～5天递增，常用量1～2mg/d（分1～2次口服），疗程4～8周，冲动攻击缓解后维持最低有效量。\n2. 稳定情绪、减轻易激惹（心境稳定剂）：丙戊酸钠缓释片0.5g bid口服，必要时加至0.75～1.0g bid，疗程3～6个月；用药期间监测血药浓度（50～100μg/mL）及肝功能。\n3. 共病注意缺陷多动障碍者：盐酸哌甲酯缓释片18mg qd晨服，可每周加量至36～54mg qd，疗程3～6个月，傍晚后勿服以免影响睡眠。\n4. 共病抑郁/焦虑者：舍曲林片50mg qd晨服，1～2周后视反应加至100～200mg qd，疗程至少6个月，联合认知行为治疗。\n【一般治疗及生活指导】\n1. 以心理行为治疗为核心：参加认知行为治疗、父母管理训练及家庭治疗，设立明确一致的家庭规则，奖惩及时且对事不对人，杜绝体罚与暴力示范。\n2. 规律作息，保证充足睡眠与适度户外活动，鼓励参与体育运动、集体活动及兴趣培养，减少与不良同伴接触及沉迷电子产品。\n3. 饮食清淡均衡，忌烟酒及咖啡浓茶等兴奋性饮品，避免熬夜、独处及接触暴力影视/游戏内容。\n4. 禁忌：未经评估禁止自行服用镇静催眠药或兴奋剂；若出现自伤、伤人或破坏行为时立即就医评估。\n【随诊要求】\n1. 每2～4周门诊复诊1次，评估冲动攻击行为频率、情绪稳定性、药物依从性及锥体外系反应、嗜睡、体重增加等不良反应。\n2. 服用抗精神病药及心境稳定剂期间，每1～3个月复查血常规、肝功能、肾功能、心电图及体重；服用锂盐者定期监测血锂浓度，丙戊酸钠者监测血药浓度。\n3. 症状稳定后维持治疗至少6～12个月，减量医师指导下缓慢进行，防止复发；出现严重冲动、自伤或暴力行为时应随时急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":666,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2aeeb9b9ee231919f1184f7c6058122f020d234ca39f8130a36883f9142856af","pinyin":"pinxingzhangai","initials":"pxza","setting":"out","caseName":"门诊病历534","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历534",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-346755effdfa92b29288","key":"v1-c9ccc21dfe2a3058|templates-346755effdfa92b29288","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"对立违抗障碍","category":"门诊病历模板","raw":{"name":"对立违抗障碍","category":"门诊病历模板","case":{"case_name":"门诊病历535","templates":{"主诉":"易怒伴对抗行为1周","现病史":"患者1周前无明显诱因出现对立违抗障碍相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患儿以易怒伴对抗行为为主要表现，诊断前须先排除器质性疾病与物质因素所致的行为改变，查血常规排除贫血、感染等躯体疾病所致情绪易激惹；查尿常规排除泌尿系感染，并作为毒物及药物筛查的基础；查便常规排除肠道寄生虫感染及慢性消化道疾病；患儿情绪不稳若需药物干预，相关药物多经肝肾代谢，查肝肾功能排除肝肾功能不全，指导用药方案与剂量；查血糖排除低血糖发作所致烦躁、冲动及对立行为；查血脂了解血脂水平，评估代谢状况并指导用药期间监测；查电解质排除电解质紊乱所致情绪与行为异常；查心电图排除心律失常及QT间期延长，为精神科药物使用提供心脏安全基线；查胸部X线片排除肺结核、肺部感染等慢性疾病，查腹部超声排除腹部器质性病变；因对立违抗障碍属行为与情绪障碍，缺乏特异性实验室指标，诊断依赖症状学标准，故上述检查的核心目的是排除躯体疾病、物质滥用及心境障碍等继发因素，根据病情需要选择相应检查，必要时完善甲状腺功能、头颅MRI、脑电图及智力与注意力评估，并行家庭养育方式评估，必要时请精神科、心理科及儿科会诊协诊以明确诊断。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 对立违抗障碍\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n对立违抗障碍首选治疗为心理行为干预（家长管理训练、认知行为治疗），药物仅作为辅助，用于共病障碍或严重攻击冲动症状，且患者行为干预联合：\n1. 伴明显攻击、冲动、暴怒发作者（控制对立违抗核心症状）：阿立哌唑片（安律凡）5mg qd起始，餐后服用，根据疗效与耐受性每1-2周加量5mg，常用维持量10-15mg qd，疗程3-6个月，症状稳定后缓慢减量评估，不可骤停。\n2. 伴显著焦虑、抑郁情绪或情绪不稳者：舍曲林片（左洛复）50mg qd起始，1周后加至100mg qd，常用范围50-200mg qd，疗程6-12个月，早晨或晚间固定时间服用，避免睡前给药。\n3. 共病注意缺陷多动障碍（ADHD）且以注意力不集中、冲动为主者：盐酸哌甲酯缓释片（专注达）18mg qd晨服起始，每周可加量18mg，常用维持量36-54mg qd，疗程≥6个月，午后再给第二剂可能影响夜间睡眠，需定期评估。\n用药期间监测：体重、血压、催乳素、血糖血脂及锥体外系反应（EPS）；舍曲林与哌甲酯联合使用时警惕5-羟色胺综合征及心血管不良反应。\n\n【一般治疗及生活指导】\n1. 家长管理训练为核心：家长学习一致、明确、具体的行为规则，奖惩一致，避免体罚、当众羞辱和过度妥协；采用\"忽根据患者具体情况制定个体化方案—暂停—表扬\"策根据患者具体情况制定个体化方案（忽根据患者具体情况制定个体化方案轻度不良行为、冲突升级时冷静暂停10-15分钟、及时强化亲社会行为），每周固定家庭会议沟通。\n2. 规律作息与健康生活方式：保证充足睡眠（学龄儿童9-11小时/晚、青少年8-10小时/晚、成人7-9小时），规律三餐，限制高糖饮食、咖啡因及碳酸饮料，电子屏幕时间每日≤1-2小时，每日户外活动或体育锻炼30-60分钟。\n3. 情绪与冲动管理训练：指导患者识别愤怒前兆信号（心跳加快、握拳、呼吸急促），练习深呼吸、倒数、离开现场转移注意力等放松技巧；在学校/职场建立行为契约与正向激励，明确后果并执行。\n4. 家庭与社交环境优化：减少家庭冲突、暴力及忽视暴露，父母保持情绪稳定、言行一致、以身作则；鼓励参加规则明确的集体运动或社团活动，发展社交技能与同伴关系。\n\n【随诊要求】\n1. 初始治疗及药物调整期每2-4周复诊1次，评估症状严重度（可使用SNAP-IV量表或对立违抗症状筛查）、药物疗效与不良反应（体重、EPS、嗜睡、血糖血脂、催乳素、心电图）。\n2. 病情稳定后每4-8周复诊1次，随访服药依从性、行为干预执行情况及家庭功能。\n3. 每3-6个月复查血常规、肝肾功能、血糖血脂；长期服用抗精神病药者定期监测催乳素水平，青春期前儿童每6个月评估身高体重生长曲线。\n4. 出现自伤、伤人、破坏财物、自杀意念或攻击行为加重等紧急情况时，随时立即就诊或至精神科急诊；停药医师指导下缓慢减停，禁止自行骤停。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":667,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"086b04fbd05bc7abb941108629ce3e7e9e3b142e7ac8e018bc26ca6bc16deae5","pinyin":"duiliweikangzhangai","initials":"dlwkza","setting":"out","caseName":"门诊病历535","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历535",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d9cf13b464105f29191a","key":"v1-c9ccc21dfe2a3058|templates-d9cf13b464105f29191a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"精神发育迟滞","category":"门诊病历模板","raw":{"name":"精神发育迟滞","category":"门诊病历模板","case":{"case_name":"门诊病历536","templates":{"主诉":"智力低下伴学习困难1周","现病史":"患者1周前无明显诱因出现精神发育迟滞相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"【必做检查】\n血常规、肝肾功能、甲状腺功能、血糖、电解质\n\n【影像学检查】\n心电图、头颅CT/MRI（排除器质性病变）\n\n【其他检查】\n心理评估量表（PHQ-9、GAD-7、PANSS等）、药物浓度监测\n","初步诊断":"1. 精神发育迟滞\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.脑代谢改善、促智治疗：吡拉西坦片（脑复康）0.8g 口服 每日3次，疗程3～6个月，可根据患者具体情况制定个体化方案换用奥拉西坦胶囊0.8g 每日2～3次，或胞磷胆碱钠片0.2g 每日3次，注意监测肝肾功能。\n2.合并冲动、攻击或自伤行为：利培酮片0.5mg 口服 每日2次起始，每3～5日缓慢加量，常规维持剂量1～2mg/d，分2次服用，注意观察锥体外系反应及嗜睡、体重增加等不良反应。\n3.合并明显注意缺陷、多动症状：哌甲酯缓释片18mg 晨服 每日1次，如疗效欠佳可每1～2周调整剂量，最大不超过54mg/d，午后及晚间不服用以防失眠。\n4.合并明显焦虑、抑郁情绪：舍曲林片50mg 晨服 每日1次，必要时2～4周后加至100mg/d，注意早期激越、胃肠道反应，禁与单胺氧化酶抑制剂合用。\n【一般治疗及生活指导】\n1.坚持个体化智能康复训练：进行语言、认知、记忆力及日常生活技能训练，循序渐进、长期坚持，配合作业疗法与社会适应能力训练。\n2.保证均衡营养与规律作息，适当进行力所能及的活动和劳动，避免熬夜、过度劳累；注意口腔卫生及个人清洁，预防呼吸道及皮肤感染。\n3.加强安全照护：避免单独外出或独处，远离水火电、锐器、高处等危险环境，外出佩戴联系信息卡，防止走失、跌倒及意外伤害。\n4.家庭与社会心理支持：以耐心、鼓励、关爱对待患者，避免斥责、歧视和溺爱，鼓励参与力所能及的社交及集体活动，家庭成员共同参与康复计划。\n【随诊要求】\n用药期间每1～3个月复诊1次，评估精神行为症状改善情况及药物疗效与不良反应；服用抗精神病药者定期复查血常规、肝肾功能、血糖、血脂及心电图，服用丙戊酸类药物者监测血药浓度；接受康复训练者每3～6个月进行智力水平及社会适应能力量表评估，及时调整康复训练方案；如出现严重冲动、攻击、自伤行为或新发癫痫发作、意识障碍等，立即就诊或急诊处理。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":668,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"375f839897b61fc8101b84293a604308f26931fc61a432acd2a88ac47a9d648b","pinyin":"jingshenfayuchizhi","initials":"jsfycz","setting":"out","caseName":"门诊病历536","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历536",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9fb8af7d4af6e9ee6754","key":"v1-c9ccc21dfe2a3058|templates-9fb8af7d4af6e9ee6754","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"阿尔茨海默病","category":"门诊病历模板","raw":{"name":"阿尔茨海默病","category":"门诊病历模板","case":{"case_name":"门诊病历537","templates":{"主诉":"进行性记忆减退伴认知下降2年","现病史":"患者（老年，年龄>65岁，发病率随年龄增长，85岁以上约1/3患病；女性略多）于2年前隐匿起病、渐进加重（病程数年）出现：记忆障碍（以近期记忆受损最先出现，表现为忘近期事、丢三落四、反复问同一问题、物品放置后找不到；远期记忆早期保留，后期亦受损）、认知障碍（语言方面找词困难、命名障碍、言语空洞；视空间方面迷路、不认路，在熟悉环境中走失，此点重要；执行功能方面计划及解决问题能力差；计算方面算不清账；判断力减退）、精神行为症状（人格改变如淡漠或多疑、固执；情绪方面抑郁、焦虑、易激惹；行为方面游走、重复动作、收集行为，夜间出现日落综合征；幻觉妄想如被害、被盗、被弃，较常见于中期；睡眠紊乱如昼夜颠倒；激越攻击致护理困难）、日常生活能力下降（渐进加重，从做饭、理财、家务、出行到穿衣洗漱、进食如厕，晚期完全依赖、卧床）。需鉴别：血管性痴呆（有卒中史、局灶体征、阶梯样进展，与AD相区别，处理上重视二级预防，重要）、路易体痴呆（认知波动＋视幻觉＋帕金森综合征，区别于AD）、额颞叶痴呆（行为人格改变突出且出现早，记忆相对保留，区别于AD）、甲减及维生素B12缺乏（属可逆性痴呆，须筛查，重要且可治）、正常压力脑积水（步态障碍＋尿失禁＋痴呆，可逆，可分流手术，须筛查）、抑郁（假性痴呆，可治）、药物（中枢抗胆碱能药物）。家族史（少数AD为家族性，早发<65岁，与淀粉样前体蛋白及早老素基因相关，需遗传咨询）、发病年龄及进展速度。今日来我院神经内科或老年科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP130/80mmHg。神经系统（一般正常，早期无局灶体征，AD为皮质性痴呆，晚期可出现肌强直、震颤、步态异常）、认知评估（简明精神状态检查MMSE，评估定向、记忆、计算、语言，用于痴呆筛查及程度判断；蒙特利尔认知评估MoCA，较敏感，用于轻度认知障碍筛查；并细查记忆、执行及语言）、精神检查（情绪、行为、幻觉）、日常生活能力（评估工具性日常生活能力）、步态（AD早期正常；异常提示血管性痴呆、路易体痴呆或正常压力脑积水）、帕金森体征（震颤、僵直，见于路易体痴呆或晚期AD）、体重（晚期可下降）。","辅助检查":"【必做】认知量表（简明精神状态检查及蒙特利尔认知评估，为核心，用于评估及随访）；【排除可逆病因】甲状腺功能（甲减可致可逆性痴呆，必查，重要）、维生素B12（缺乏可致可逆性痴呆，须筛查）、血常规、电解质、血糖、肝肾功能、梅毒血清学（神经梅毒少见但可治）、HIV（高危者）；【影像】头颅CT或MRI（为核心检查：脑萎缩（海马及内侧颞叶萎缩为AD特征，MRI显示较好）、脑白质病变及梗死（排除血管性痴呆）、脑积水（排除正常压力脑积水，该病可治，重要），并排除可手术的病变）；【生物标志物】脑脊液（淀粉样蛋白42降低、tau升高，支持AD病理，用于疑难、早发或临床试验）、淀粉样PET（显示Aβ沉积，用于确诊早发或疑难病例）、氟脱氧葡萄糖PET（颞顶叶低代谢，支持AD）；【基因】早发或家族性者检测淀粉样前体蛋白及早老素1、2基因，载脂蛋白E，并行遗传咨询；【其他】神经心理全套评估用于鉴别诊断、抑郁量表（排除抑郁所致假性痴呆，重要）。","初步诊断":"1. 阿尔茨海默病（晚发型，临床分期为轻度痴呆；可逆性病因已排除；生物标志物待查）\n（注：治疗为综合管理（药物＋非药物＋照护），以延缓进展，目前无法根治，管理为核心：①认知药物（胆碱酯酶抑制剂为一线：多奈哌齐5~10mg qd（起始5mg，4~6周后加量，用于轻中度）、卡巴拉汀或加兰他敏，可改善认知、维持功能、延缓进展，不能根治，疗效有限但具临床意义，早期患者效果好；美金刚（N-甲基-D-天冬氨酸受体拮抗剂）用于中重度，可单用或联合多奈哌齐；中重度可联合多奈哌齐与美金刚）；②精神行为症状（非药物措施首选：行为干预（安抚、改善环境、规律作息、避免对抗）、音乐及活动疗法、照护者培训，重要；药物仅用于症状严重者：激越、攻击或精神病性症状可用抗精神病药（利培酮或奥氮平，小剂量、短期使用；有黑框警告，老年痴呆患者使用抗精神病药死亡率升高、卒中风险增加，须慎用并权衡，非药物优先，重要）；抑郁用SSRI（舍曲林或西酞普兰）；焦虑用SSRI，短效苯二氮䓬类须慎用（防跌倒及依赖）；失眠用褪黑素或曲唑酮，避免苯二氮䓬类）；③非药物及照护（认知训练及刺激（益智活动）、运动（注意步态、防跌倒）、营养（地中海饮食有益脑健康）、社会参与；安全方面防走失（手环、GPS）、防跌倒（环境改造）、认知受损者禁止驾驶（安全，重要）；照护者支持（减轻负担、培训、喘息服务，重要））；④随访（每6~12个月用简明精神状态检查及蒙特利尔认知评估评估进展；药物方面胆碱酯酶抑制剂注意胃肠反应及心动过缓，美金刚注意耐受性；观察精神行为症状变化并处理；关注跌倒及走失等安全事件；晚期关注吞咽、营养，讨论鼻饲或胃造瘘，防治肺炎及褥疮，重视临终关怀；定期评估并支持照护者）；由神经内科、老年科及精神科协作，做到早期诊断、药物延缓、行为管理、照护支持及多学科长期管理。）","处理方案":"【药物治疗】\n1. 盐酸多奈哌齐片 5mg qn 口服（睡前服），为一线胆碱酯酶抑制剂；服用4-6周后如耐受良好可增至10mg qd，长期维持，缓释片5mg qd起始。\n2. 盐酸美金刚片 起始5mg qd口服，每周递增5mg，第4周加至10mg bid（20mg/d）维持，餐后服用；中重度肾功能不全者减量（5mg bid或10mg qd）。\n3. 重酒石酸卡巴拉汀胶囊 1.5mg bid口服（与食物同服），2周后可增至3mg bid，最大6mg bid；用于多奈哌齐不耐受或疗效不佳者的替代或联合（与多奈哌齐二选一为主）。\n4. 合并明显抑郁或精神行为症状（BPSD）者，可加用选择性5-HT再摄取抑制剂（如舍曲林片50mg qd晨服），症状明显时请精神科会诊，慎用抗精神病药（小剂量短期，注意锥体外系及跌倒风险）。\n\n【一般治疗及生活指导】\n1. 保持规律作息，保证每日7-8小时睡眠，避免熬夜、过劳及情绪波动；白天适当午休，夜间睡前避免咖啡、浓茶。\n2. 均衡饮食，推荐地中海饮食（多食鱼类、坚果、橄榄油、新鲜蔬果），控制盐与糖摄入，戒烟限酒，保证充足饮水防止脱水。\n3. 坚持每日认知训练（读报、计算、拼图、回忆往事）及社交活动，鼓励散步、太极拳等低强度活动，活动时家属陪同以防跌倒。\n4. 加强安全照护：佩戴防走失定位手环，随身携带写明姓名、地址、家属电话的卡片；避免独自外出、独自使用燃气及锐器；避免使用含抗胆碱能成分的药物（如苯海索、颠茄类及部分含抗组胺成分感冒药）。\n\n【随诊要求】\n1. 开始服药后2-4周复诊，评估药物耐受性及不良反应（恶心、腹泻、食欲减退、心动过缓等），必要时复查心电图。\n2. 此后每3-6个月复诊1次，定期行MMSE、MoCA等认知功能量表及日常生活能力（ADL）评估，监测血压、心率及肝肾功能，评估治疗反应并调整方案。\n3. 若出现精神行为症状加重、幻觉妄想、跌倒、意识改变、进食困难或病情快速进展，应立即就诊；长期卧床者注意防治压疮、肺部感染及深静脉血栓。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":669,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"509ff71dc9727cfb53b940f753c357837a120a85a7e40c5c306edea29e15541b","pinyin":"aercihaimobing","initials":"aechmb","setting":"out","caseName":"门诊病历537","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历537",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]}]);